pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize small unusable dead space (gaps too small for typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits (exact or near-exact).
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Pressure from number of open bins: prefer consolidating into fewer bins.
    score += open_bins_count as f64 * 0.5;

    // Prefer bins with residual below mean residual (pack fuller bins first).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 10.0;
    }

    // Mild preference for opening a new bin when many bins are already very full.
    if bin_residual == bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to fit even the
    // smallest plausible item are "dead". Penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0; // unusable sliver
    } else if post_residual == 0 {
        score -= 30.0; // perfect fit: fully consumed bin
    }

    // Penalize gaps too small for the lookahead item (k=2 lookahead synergy).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.35 * (next_item_size - post_residual) as f64;
    }
    // Reward gaps that exactly accommodate the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    }

    // Reward tight fits relative to bin capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Open-bin pressure: discourage spreading across many bins unless fit is tight.
    let pressure = open_bins_count as f64 / (1.0 + (total_items as f64).max(1.0).ln());
    score += 1.5 * pressure * (1.0 - tightness);

    // Last-chance bonus: if this is the only fitting bin, prefer using it
    // (avoiding a new bin) unless the fit creates dead space.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0 + 0.2 * item_size as f64;
        if post_residual > 0 && post_residual < 10 {
            score += 55.0; // but never if it strands a sliver
        }
    }

    // New-bin candidate handling: an empty bin is attractive when the current
    // item would leave a large awkward gap elsewhere, or open-bin pressure is low.
    if bin_residual == bin_capacity {
        let gap_penalty = if post_residual > 0 && post_residual < 10 { 0.0 } else { 0.0 };
        let _ = gap_penalty;
        // Base cost of opening a bin, discounted early in the stream and
        // when the item is large (large items fit best in fresh bins).
        let mut new_bin_score = 25.0
            - 6.0 * (step_index as f64 / total_items.max(1) as f64)
            - 0.15 * item_size as f64;
        // Prefer new bin if all existing fits would strand dead space.
        if post_residual == bin_capacity - item_size && item_size >= 50 {
            new_bin_score -= 15.0;
        }
        // If other bins fit but would leave slivers, opening fresh is better.
        if fitting_bins_count > 0 && mean_residual > 0.0 && (mean_residual - item_size as f64) < 10.0 {
            new_bin_score -= 20.0;
        }
        score = score.min(new_bin_score);
    }

    // Mean-residual coupling: prefer bins whose residual is below average
    // (concentrate waste into few bins rather than spreading it).
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftovers are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 40.0;
    }
    // Dead space in the awkward mid-range (11..=20) is also penalized.
    if post_residual >= 10 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 8.0;
    }

    // Reward tight fits (small post_residual relative to item).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 25.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: strong reward to use it rather than open a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: prefer opening a fresh bin only when the
    // item would leave a large, reusable gap in existing bins or fits badly.
    if bin_residual == bin_capacity {
        // Neutral baseline for a fresh bin, modulated by stream progress.
        score = 45.0 + (post_residual as f64) * 0.5;
        // Late in the stream, slightly favor closing out with existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        // If the next item is large, a fresh bin is more attractive.
        if next_item_size > 60 {
            score -= 20.0;
        }
    } else if post_residual > 0 && post_residual < next_item_size && next_item_size > 0 {
        // This bin's leftover can't hold the lookahead item; mild penalty.
        score += 6.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        // Placing here enables a near-perfect follow-up placement.
        score -= 15.0;
    }

    // Prefer bins below mean residual (filling emptier bins first keeps
    // tight bins available for small items).
    score += (mean_residual - bin_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post * post / cap; // quadratic pressure: big leftovers hurt more

    if post_residual == 0 {
        score -= 1000.0; // perfect fit dominates
    } else {
        // Harmony of the leftover space
        if post % 10 == 0 { score -= 12.0; }
        if post % 20 == 0 { score -= 8.0; }
        if post % 25 == 0 { score -= 8.0; }
        if post % 50 == 0 { score -= 6.0; }
        if post_residual < 10 {
            score += 330.0 / post; // dead sliver: strong penalty
        } else if post_residual < 12 {
            // borrowed from best: mid sliver band graded
            score += 90.0 + (12 - post_residual) as f64 * 6.0;
        } else if post_residual <= 20 {
            score += 6.0; // marginal
        } else if post_residual < 40 {
            score -= 4.0; // useful band
        } else {
            score -= 9.0; // large leftover is still usable
        }
        // dead-space band under 25% of capacity
        if post < 0.25 * cap {
            score += 30.0 * (1.0 - post / (0.25 * cap));
        }
        // reward small usable residuals more aggressively
        if post_residual >= 5 && post_residual < 12 {
            score -= 3.0 * (12 - post_residual) as f64;
        }
        // gradual small-residual penalty ramp
        if post_residual < 30 && post_residual >= 12 {
            score += 7.5 * (30 - post_residual) as f64 / 18.0;
        }
        // scale-based usable leftover credit
        score -= 15.0 * (post / cap);
        // penalize deep dead space generally
        let dead = post / cap;
        if dead > 0.45 {
            score += 14.0 * (dead - 0.45);
        }
        // tiny residual that next item cannot use: waste signal
        if post_residual > 0 && post_residual < 8 && next_item_size > post_residual {
            score += 26.0;
        }
        if post_residual > 0 && post_residual < 16 && next_item_size > post_residual && (mean_residual as u32) > post_residual {
            score += 9.0 * (16 - post_residual) as f64 / 8.0;
        }
    }

    // Lookahead: reward if next item chains into the leftover
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let chain_tight = 1.0 - (post - nxt) / cap;
            score -= 52.0 * chain_tight;
            if post_residual == next_item_size { score -= 68.0; } // exact chain fill
            if post_residual % next_item_size == 0 { score -= 18.0; } // harmonic chain
            if (post_residual - next_item_size) % 10 == 0 { score -= 6.0; }
            let gap = post - nxt;
            if gap >= 1.0 && gap <= 4.0 { score -= 12.0; } // near-perfect chain
            if post >= nxt + mean_residual { score -= 10.0; }
            if gap <= mean_residual * 0.5 { score -= 8.0; }
            if gap < 6.0 { score -= 18.0; }
            if (post_residual as f64 - nxt) as u32 == mean_residual as u32 { score -= 9.0; }
            if post_residual <= 25 && nxt > post_residual as f64 * 0.6 {
                score -= 13.0 * (1.0 - post_residual as f64 / 25.0);
            }
            // mid-range chain bonus scaled by dead-space ratio
            if gap <= 12.0 && gap <= mean_residual * 1.2 {
                score -= 7.0 * (1.0 - gap / 12.0);
            }
            if gap <= 2.0 && post > 0.4 * cap { score -= 9.0; }
            if gap <= 2.0 && post / cap > 0.5 { score -= 6.0; }
            if gap <= 3.0 && fitting_bins_count <= 2 { score -= 10.0; }
            if post_residual <= mean_residual as u32 { score -= 6.0; }
        } else {
            // next item won't fit here
            if post_residual > 0 && post_residual < 10 { score += 60.0; }
            if nxt - post <= 2.0 && fitting_bins_count > 1 { score += 15.0; }
            if nxt - post > 20.0 && post_residual < 20 { score += 12.0; }
            if post_residual < next_item_size / 2 {
                score += 6.0 * (1.0 - post_residual as f64 / (next_item_size / 2).max(1) as f64);
            }
            if post_residual > 0 && post_residual < item_size && open_bins_count > 3 { score += 8.0; }
            // near-miss penalty scaled by how close next item is
            if post_residual > 0 && nxt - post <= 10.0 {
                score += 4.0 * (1.0 - (nxt - post) / 10.0);
            }
            // penalize large dead space when next item overshoots badly
            let dead = post / cap;
            if dead > 0.35 && post_residual as f64 > mean_residual * 1.5 && fitting_bins_count > 3 {
                score += 10.0 * (dead - 0.35);
            }
            // residual just under next item (wasted near-fit)
            if post_residual >= (next_item_size * 3 / 4) && post_residual < next_item_size {
                score += 5.0 * (post_residual as f64 - next_item_size as f64 * 0.75) / (next_item_size as f64 * 0.25).max(1.0);
            }
            // deep dead space with few fitting bins: strong penalty
            if dead > 0.5 && fitting_bins_count <= 2 {
                score += 14.0 * (dead - 0.5);
            }
            // near-miss within half mean residual
            if post_residual > 0 && (nxt - post) < 0.5 * mean_residual.max(1.0) {
                score += 4.0;
            }
            // deep dead space with many open bins: extra pressure
            if dead > 0.55 && open_bins_count > 4 {
                score += 16.0 * (dead - 0.55);
            }
        }
    } else {
        score += post * 2.2;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let new_bin_bonus = 40.0 * (1.0 - progress);
        score -= new_bin_bonus; // early: bins cheap; late: consolidate
        if mean_residual < item_size as f64 && open_bins_count > 2 {
            score += 10.0;
        }
        // many open bins with slack: prefer consolidating instead of new bin
        if open_bins_count > 5 && mean_residual > 0.4 * cap {
            score += 12.0;
        }
        // late stream: opening new bins is expensive, tighten further
        if progress > 0.5 {
            score += 18.0 * (progress - 0.5);
        }
        if open_bins_count > 3 && progress > 0.6 {
            score += 8.0;
        }
        // if some open bin already fits next item, opening is less attractive
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
        if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
            score += 14.0;
        }
        if next_item_size > 0 && next_item_size as f64 <= bin_residual as f64 && open_bins_count > 1 {
            score += 6.0;
        }
        // penalize new bin when many open bins have deep slack
        let dead = post / cap;
        if dead > 0.5 && open_bins_count > 2 {
            score += 20.0 * (dead - 0.5);
        }
        // new bin that exactly fits next item is attractive
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 12.0;
        }
    } else {
        // tightness pressure toward fuller bins
        let tightness = 1.0 - (bin_residual as f64 / cap);
        score -= 10.0 * tightness;
        // many fitting bins means this choice matters less; slight penalty for sloppy fits
        if fitting_bins_count > 4 && post_residual > 30 {
            score += 3.0;
        }
        // penalize leaving dead space when next item is much larger than residual
        if post_residual > 0 && next_item_size as f64 > post && post_residual as f64 > mean_residual * 1.5 && fitting_bins_count > 3 {
            score += 8.0;
        }
        // near-miss within a couple units of next item with several options
        if post_residual > 0 && next_item_size as f64 > post && (next_item_size as f64 - post) <= 4.0 && fitting_bins_count > 2 {
            let dead = post / cap;
            if dead > 0.3 {
                score += 11.0 * (dead - 0.3);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Baseline: prefer tight fits (small post_residual), but scale by progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect match: next item exactly fills the residual -> huge reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0 + 80.0 * progress;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportional to how snugly it fits afterwards.
            let two_step_residual = (post_residual - next_item_size) as f64;
            score -= 40.0 - 0.35 * two_step_residual;
        } else {
            // Next item won't fit here: penalize leftover that is likely dead space,
            // especially when the leftover is small (unusable).
            let gap = (next_item_size - post_residual) as f64;
            if post_residual < 10 {
                score += 60.0; // tiny dead space, very undesirable
            } else {
                score += 0.15 * gap;
            }
        }
    }

    // Reward bins that are already well-used (small residual relative to mean).
    score += 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    score += 2.0 * open_bins_count as f64;

    // Late in the stream, tighten placements further.
    score *= 1.0 + 0.5 * progress;

    // New-bin candidate: neutral-ish baseline so it only wins when fits are bad.
    if bin_residual == bin_capacity {
        score = 55.0 + 20.0 * progress - 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
