pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are unusable
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward bins whose residual closely matches the item (tight fit)
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= (1.0 - tightness) * 15.0;

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize leaving a gap just below the next item (near-miss dead space)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few, encourage consolidation
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        score = 55.0 + open_bins_count as f64 * 0.5;
