            if dead > 0.35 && post_residual as f64 > mean_residual * 1.5 && fitting_bins_count > 3 {
                score += 10.0 * (dead - 0.35);
            }
            if post_residual >= (next_item_size * 3 / 4) && post_residual < next_item_size {
                score += 5.0 * (post_residual as f64 - next_item_size as f64 * 0.75) / (next_item_size as f64 * 0.25).max(1.0);
            }
            if dead > 0.5 && fitting_bins_count <= 2 {
                score += 14.0 * (dead - 0.5);
            }
            if post_residual > 0 && (nxt - post) < 0.5 * mean_residual.max(1.0) {
                score += 4.0;
            }
            if post_residual > 0 && (nxt - post) as u32 <= 4 && fitting_bins_count > 2 {
                score += 11.0 * (post / cap - 0.3).max(0.0);
            }
        }
    } else {
        score += post * 2.2;
    }

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let new_bin_bonus = 40.0 * (1.0 - progress);
        score -= new_bin_bonus;
        if mean_residual < item_size as f64 && open_bins_count > 2 {
            score += 10.0;
        }
        if open_bins_count > 5 && mean_residual > 0.4 * cap {
            score += 12.0;
        }
        if progress > 0.5 {
            score += 18.0 * (progress - 0.5);
        }
        if open_bins_count > 3 && progress > 0.6 {
            score += 8.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
        if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
            score += 14.0;
        }
        if next_item_size > 0 && next_item_size as f64 <= bin_residual as f64 && open_bins_count > 1 {
            score += 6.0;
        }
        if open_bins_count > 2 && mean_residual > 0.5 * cap {
            score += 20.0 * (mean_residual / cap - 0.5);
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 12.0;
        }
        // NEW: prefer consolidation late when an open bin leaves a residual close to next item
        if progress > 0.4 && next_item_size > 0 && fitting_bins_count > 0 {
            let near = (mean_residual - next_item_size as f64).abs();
            if near <= 5.0 { score += 10.0; }
        }
    } else {
        let tightness = 1.0 - (bin_residual as f64 / cap);
        score -= 10.0 * tightness;
        if fitting_bins_count > 4 && post_residual > 30 {
            score += 3.0;
        }
        if post_residual > 0 && next_item_size as f64 > post && post_residual as f64 > mean_residual * 1.5 && fitting_bins_count > 3 {
            score += 8.0;
        }
        // NEW: strong consolidation pressure when many bins compete and this fit is tight
        if fitting_bins_count > 3 && post_residual < 15 {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: coarse residue classes mod 10
    let item_class = item_size % 10;
    let next_class = next_item_size % 10;

    // Perfect fit bonus: post_residual in small harmonic classes
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual % 10 == 0 {
        // post_residual itself lands on a harmonic boundary — likely reusable
        score -= 50.0;
    }

    // Complementary pairing: if next item exactly fills post_residual
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 500.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // next item fits here: mild reward scaled by how snugly
        let snug = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - snug / bin_capacity as f64);
    } else if next_item_size > 0 {
        // next item does NOT fit after placement: penalize dead space creation
        let waste = next_item_size - post_residual;
        score += 20.0 + waste as f64 * 0.5;
    }

    // Class-match coupling: same harmonic class items tend to tile together
    if next_item_size > 0 && item_class == next_class {
        score -= 15.0;
    }

    // Integer-division thresholds on post_residual: dead-zone penalties
    if post_residual > 0 && post_residual < 10 {
        score += 150.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize slightly unless current bins are crowded
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 80.0 - 40.0 * progress - 2.0 * crowd;
        // open new bin if mean residual is very tight
        if mean_residual < item_size as f64 * 0.5 {
            score -= 60.0;
        }
    }

    // Deviation from mean residual: prefer bins below mean (tighter bins)
    score += (bin_residual as f64 - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are tiny (unusable gaps)
    // are heavily penalized beyond their raw value.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward placements that leave room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Leaves a gap the next item cannot use -> dead space risk.
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: penalize spreading across many bins slightly.
    score += 0.4 * open_bins_count as f64;

    // Prefer bins tighter than average (best-fit flavor).
    score += (post_residual as f64 - mean_residual) * 0.5;

    // New-bin candidate: default moderate score; open a new bin only when
    // current item is large and would leave a bad gap in any existing bin.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 55.0 + 20.0 * progress;
        if item_size > 50 && fitting_bins_count > 0 {
            // large item: opening fresh bin is often fine
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 8.0; // new bin can host both items
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if no realistic item (size >= 1, but practically < 10 rare) fits well.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny sliver -> wasted space
    } else if post_residual < 20 {
        score += 12.0; // near-dead zone
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit: strongly rewarded
    }

    // Reward tight fits generally: shrink score toward zero for small post_residual.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.15;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: with many open bins, avoid spreading; prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.8 + 0.6 * progress);

    // Lookahead: if the next item fits exactly into the post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            score += 6.0; // next item can't use this residual anyway
        }
    }

    // New-bin candidate handling: an empty bin has neutral post_residual = capacity.
    // Make it moderately attractive only when existing fits are poor.
    if bin_residual == bin_capacity {
        // Baseline: empty bin score should sit above good fits but below dead-space fits.
        score = 55.0 + open_bins_count as f64 * 0.5;
        if post_residual >= next_item_size && next_item_size > 0 {
            score -= 10.0; // fresh bin can host the next item too
        }
    }

    // Mean residual coupling: if mean residual across bins is high, prefer consolidation
    // into bins below the mean (this bin's residual below mean => good target).
    if bin_residual != bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear coupling of post-residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - norm_pr) * (1.0 - norm_pr);
    score -= 40.0 * poly * (0.5 + 0.5 * progress);

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - (pr / cap);
    score -= 12.0 * tightness * tightness * (1.0 + progress);

    // Penalize small dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 8.0 * (nxt - pr) * (0.5 + progress);
        } else {
            // smooth reward when lookahead fits in the post residual
            let slack = (pr - nxt) / cap;
            score -= 6.0 * (1.0 - slack) * (1.0 - slack);
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    // Pull toward mean residual: prefer bins near average fill state
    score += 0.3 * (pr - mean_residual).abs();

    // New-bin candidate: penalize unless post_residual is very large (poor fits elsewhere)
    if bin_residual == bin_capacity {
        score += 15.0 - 10.0 * norm_pr;
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    }

    // Penalize large post_residual only mildly (still usable space),
    // but reward when the lookahead item can fit the leftover gap.
    if next_item_size > 0 && post_residual >= next_item_size as f64 {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += (next_item_size - post_residual as u32) as f64 * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: fewer open bins -> prefer packing into existing bins.
    score += open_bins_count as f64 * 1.5;

    // Slight preference for tighter (smaller residual) bins early on.
    score += (bin_residual as f64) * 0.05;

    // New-bin candidate: make it unattractive unless residual pressure is high.
    if bin_residual == bin_capacity {
        score += 55.0 + open_bins_count as f64 * -0.8 + (mean_residual / 10.0);
    }

    // Late-stream nudge: tighten packing as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps heavily (dead space 1..=15)
    if post_residual > 0 && post_residual <= 15 {
        score += 40.0 * (16.0 - post_residual as f64);
    }

    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Dead space relative to capacity: penalize residuals that can't fit typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item would NOT fit post-residual but would fit another bin, mild penalty
    if next_item_size > post_residual && next_item_size > 0 {
        score += 4.0;
    }

    // Mean residual coupling: prefer bins below mean residual (filling emptier bins less)
    score -= (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate: neutral-ish baseline with slight pressure so it's chosen
    // only when existing bins score poorly (dead space).
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual as fraction of capacity
    let tight = post_residual as f64 / cap;
    score += tight * 20.0;

    // Reward filling the bin deeply (item large relative to residual)
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 15.0;

    // Lookahead: if next item fits exactly-ish in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let waste = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - waste / cap);
        } else {
            // next item won't fit here: penalize leaving awkward gaps
            let gap = post_residual as f64;
            if gap > 0.0 && gap < next_item_size as f64 {
                score += gap * 0.3;
            }
        }
    } else {
        // last item: minimize leftover hard
        score += post_residual as f64 * 2.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Many open bins: prefer consolidating into emptier bins to close them
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 3 {
        let below_mean = (mean_residual - bin_residual as f64) / cap;
        score -= below_mean * 10.0 * (open_bins_count as f64).ln();
    }

    // Early stream: be less greedy, keep flexibility (penalize very small residuals less)
    let flexibility = 1.0 - progress;
    if post_residual > 0 && post_residual < 10 {
        score -= flexibility * 8.0; // tiny dead space tolerated early? no—reward closing
    }

    // New-bin candidate: only open new bin if no open bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base cost of opening a new bin
        let mut new_cost = 35.0 + post_residual as f64;
        // cheaper to open a new bin when few bins open and stream is early
        new_cost -= progress * 15.0;
        new_cost -= (open_bins_count as f64) * 2.0;
        // if this bin would be the only fitting bin, opening new bin is wasteful
        if fitting_bins_count <= 1 {
            new_cost += 60.0;
        }
        // if next item is large and current bins are full-ish, new bin attractive
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            new_cost -= 10.0;
        }
        score += new_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let residual = bin_residual as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post * post / cap;

    // Perfect / near-perfect fit rewards.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 330.0 / post;
    } else if post_residual < 12 {
        score += 90.0 + (12 - post_residual) as f64 * 6.0;
    } else {
        score -= 15.0 * (post / cap);
        if post_residual >= 40 {
            score -= 9.0;
        }
        if post_residual < 30 {
            score += 7.5 * (30 - post_residual) as f64 / 18.0;
        }
    }

    // Tightness coupling.
    let fill_ratio = item / residual.max(1.0);
    score -= 24.0 * fill_ratio;

    // Fragmentation penalty for small residuals.
    if post > 0.0 && post < 0.25 * cap {
        score += 30.0 * (1.0 - post / (0.25 * cap));
    }

    // Lookahead chain-fit bonus (combined with fine residual anticipation).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let chain_tight = 1.0 - (post - nxt) / cap;
            score -= 52.0 * chain_tight;
            if post == nxt {
                score -= 68.0;
            }
            if post - nxt < 6.0 {
                score -= 18.0;
            }
            if post >= nxt + mean_residual {
                score -= 10.0;
            }
            if (post - nxt) as u32 == mean_residual as u32 {
                score -= 9.0;
            }
            if post >= nxt && (post - nxt) <= mean_residual * 0.5 {
                score -= 8.0;
            }
            if post - nxt >= 1.0 && post - nxt <= 4.0 {
                score -= 12.0;
            }
            // NEW: two-step lookahead — after placing next item, gap should stay reusable.
            let gap_after_next = post - nxt;
            if gap_after_next > 0.0 && gap_after_next < mean_residual {
                score += 10.0 * (1.0 - gap_after_next / mean_residual.max(1.0));
            }
            if gap_after_next >= mean_residual {
                score -= 6.0;
            }
        } else if post + 10.0 >= nxt {
            score += 6.0;
        } else {
            score += 0.06 * (nxt - post);
        }
        if nxt > post && (nxt - post) as u32 <= 2 && fitting_bins_count > 1 {
            score += 15.0;
        }
        if nxt > post && (nxt - post) as u32 > 20 && post_residual > 0 && post_residual < 20 {
            score += 12.0;
        }
    } else {
        score += post * 2.2;
    }

    // Dead-space penalty: residual too small for the next item.
    if post_residual > 0 && post_residual < 8 && next_item_size > post_residual {
        score += 26.0;
    }
    if post_residual > 0 && post_residual < 16 && next_item_size > post_residual && (mean_residual as u32) > post_residual {
        score += 9.0 * (16 - post_residual) as f64 / 8.0;
    }

    // Semi-fit lookahead.
    if post_residual > 0 && next_item_size as f64 <= post && next_item_size as f64 > post_residual as f64 * 0.6 && post_residual <= 25 {
        score -= 13.0 * (1.0 - post_residual as f64 / 25.0);
    }
    if post_residual > 0 && post_residual < item_size && next_item_size as f64 > post && open_bins_count > 3 {
        score += 8.0;
    }
    if post_residual > 0 && next_item_size as f64 > post && post_residual < (next_item_size / 2) {
        score += 6.0 * (1.0 - post_residual as f64 / (next_item_size / 2).max(1) as f64);
    }
    if post_residual > 0 && post_residual % 10 == 0 && next_item_size as f64 <= post {
        score -= 5.0;
    }
    let dead = post / cap;
    if post_residual > 0 && next_item_size as f64 > post && dead > 0.35 && (post_residual as f64) > mean_residual * 1.5 && fitting_bins_count > 3 {
        score += 10.0 * (dead - 0.35);
    }
    if post_residual > 0 && next_item_size as f64 <= post && (post - next_item_size as f64) <= 2.0 && dead > 0.4 {
        score -= 9.0;
    }
    if fitting_bins_count > 4 && bin_residual != bin_capacity && post_residual > 30 {
        score += 3.0;
    }

    // Last-chance pressure.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    } else if fitting_bins_count <= 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Consolidation pressure.
    score += (open_bins_count as f64) * 1.5;

    // Mean-residual coupling.
    if residual < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score += 120.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 100.0 * progress;
        score += 10.0 * (open_bins_count as f64);
        if fitting_bins_count > 1 {
            score += 100.0 * (fitting_bins_count as f64 - 1.0);
        }
        score += 0.5 * mean_residual;
        if item_size < (bin_capacity / 2) {
            score += 12.0;
            if next_item_size > 0 && (next_item_size as f64) <= post {
                score += 20.0;
            }
        }
        // Huge items deserve fresh bins when residuals are small.
