pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space relative to capacity (non-linear).
        let dead_frac = post_residual as f64 / bin_capacity as f64;
        score += 50.0 * dead_frac * dead_frac;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let lookahead_waste = post_residual - next_item_size;
        score -= 80.0;
        score -= 2.0 * (next_item_size as f64);
        score += 0.5 * (lookahead_waste as f64);
        if lookahead_waste == 0 {
            score -= 300.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize leaving residual that's too small to be useful.
        if post_residual < 10 {
            score += 60.0;
        }
        // Reward residuals close to but below next item size only mildly.
        score += 10.0;
    }

    // Compare residual against mean residual: prefer bins with less residual (tighter bins)
    // but avoid over-penalizing when this bin is the only fitting one.
    let mean_diff = (bin_residual as f64) - mean_residual;
    score += 0.3 * mean_diff;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // If many bins fit the item, prefer tighter ones (post_residual already does this),
    // add slight penalty proportional to open bins to encourage consolidation.
    score += 0.05 * open_bins_count as f64;

    // Early in stream, be more willing to open new bins (less penalty for new bin),
    // later in stream, favor filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_bonus = 40.0 * (1.0 - progress);
    if bin_residual == bin_capacity {
        score -= new_bin_bonus;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo small integers
    let r = post_residual;
    let mod12 = (r % 12) as f64;
    let mod8 = (r % 8) as f64;
    let mod5 = (r % 5) as f64;

    // Dead-space penalty: residuals that cannot host common item sizes
    // (sizes 1..100 unknown distribution -> penalize small odd residuals)
    if r > 0 && r < 10 {
        score += 40.0; // nearly unusable sliver
    } else if r < 20 {
        score += 12.0;
    }

    // Harmonic bonus: post_residual divisible by common class sizes (5,8,10,12,20,25)
    if r % 10 == 0 {
        score -= 8.0;
    } else if r % 5 == 0 {
        score -= 4.0;
    } else if r % 20 == 0 {
        score -= 10.0;
    }
    // Odd residuals are poor candidates for future integer items
    if r % 2 == 1 && r > 0 {
        score += 3.0 + mod5 * 0.5;
    }

    // Coupling with lookahead item: reward residuals that can host next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item fits here too -> strong reward
            score -= 6.0 + (next_item_size as f64) * 0.1;
            // extra reward if post_residual - next_item_size is a "harmonic" value
            let rr = post_residual - next_item_size;
            if rr % 10 == 0 { score -= 4.0; }
        } else if next_item_size <= bin_residual {
            // next item fits bin only if we don't take it? penalize blocking
            score += 2.0;
        }
    } else {
        // last item: just minimize waste
        score -= 5.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * 1.5;
    }

    // New-bin candidate handling: empty bin should only win when open bins are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / (bin_capacity as f64);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // prefer new bin when open bins have low mean residual (fragmented)
        if mean_residual < 25.0 || open_bins_count == 0 {
            score -= 20.0 + 10.0 * (1.0 - fragmentation);
        } else {
