    // late in the stream, packing density matters more.
    score -= 3.0 * (1.0 - progress) * (bin_residual as f64 / bin_capacity as f64);
    score += 2.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: opening a new bin is attractive only if current bin
    // fit is poor (large post_residual) or the item nearly fills the new bin.
    if bin_residual == bin_capacity {
