pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on (progress ~ 0): mildly prefer tight fits but tolerate larger residuals.
    // Later (progress ~ 1): strongly penalize large residuals to squeeze remaining space.
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) + norm_pr * (0.5 - 0.4 * progress);

    // Smooth reward for near-perfect fits (small post_residual), amplified late in stream.
    let tight_fit_bonus = -2.0 * (1.0 - norm_pr).powi(3) * (1.0 + progress);

    // Penalize opening new bins when existing bins fit, more so late in the stream.
    let new_bin_penalty = if bin_residual == bin_capacity && fitting_bins_count > 0 {
        1.5 + 2.0 * progress
    } else {
        0.0
    };

    // Lookahead: reward bins whose post-residual can still hold the next item.
    let lookahead = if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        -0.5 * (1.0 + progress)
    } else if next_item_size > 0 {
        0.3 * progress
    } else {
        0.0
    };

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    let last_chance = if fitting_bins_count == 1 && bin_residual != bin_capacity {
        -1.0
    } else {
        0.0
    };

    // Slight preference for bins deviating from mean residual (consolidation effect).
    let mean_pull = -0.1 * (mean_residual - pr) / cap;

    let mut score = pr + poly * cap + tight_fit_bonus + new_bin_penalty + lookahead + last_chance + mean_pull;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual: classify leftover space ---
    // Class 0: perfect fit (post_residual == 0) -> strongest reward
    // Class 1: post_residual in a "reusable" band (>= 20, divisible-friendly)
    // Class 2: small dead space (1..20) -> penalize heavily
    let post = post_residual;
    if post == 0 {
        score -= 60.0; // perfect fit: close the bin ideally
    } else if post <= 10 {
        // dead space too small for most items (items >= 1, but tiny slivers waste)
        score += (11 - post) as f64 * 3.0;
    } else {
        // Reusable band: reward residuals that are multiples of common sizes
        let mult_bonus = if post % 10 == 0 {
            8.0
        } else if post % 5 == 0 {
            5.0
        } else if post % 25 == 0 {
            6.0
        } else {
            0.0
        };
        score -= mult_bonus;
    }

    // Integer-division threshold: how many "typical" chunks of size 20 fit in leftover
    let chunks = post / 20;
    score -= chunks as f64 * 2.5;

    // --- Lookahead coupling (k=2) ---
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 45.0; // next item exactly fills this bin
        } else if next_item_size <= post {
            // next item fits here: bonus scaled by how snugly
            let slack = (post - next_item_size) as f64;
            score -= 15.0 - slack.min(30.0) * 0.25;
        } else {
            // next item cannot use this bin's leftover: penalize big leftovers less
            score += ((next_item_size - post) as f64).min(40.0) * 0.3;
        }
    } else {
        // last item: strongly prefer filling any bin completely
        score -= 20.0;
    }

    // --- Last-chance bin: avoid opening a new bin when this is the only fit ---
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive if open bins are nearly full on average
        let pressure = mean_residual / bin_capacity as f64;
        score = 100.0 - pressure * 30.0;
        // discourage opening bins late in the stream when many are open
        score += open_bins_count as f64 * 1.5;
        // discourage when next item is large (keep current bins for it)
        if next_item_size > 50 {
            score += 10.0;
        }
    }

    // --- Stream progression: early on, be picky; late, just fill ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0; // late stream: urgency to fill existing bins

    // Slight preference for bins tighter than the mean residual (compactness)
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold the smallest item are waste.
    // Smallest item is 1, but treat gaps below ~15 as near-dead, with a hard
    // spike for gaps in the "unusable" band (1..=12).
    if post_residual > 0 && post_residual <= 12 {
        score += 40.0 + (13 - post_residual) as f64 * 4.0; // tiny gap = pure waste
    } else if post_residual > 12 && post_residual < 20 {
        score += 10.0; // risky zone
    }

    // Reward tight fits strongly: post_residual near 0 is ideal.
    if post_residual == 0 {
        score -= 60.0; // perfect packing
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Lookahead: if next item fits exactly in the post_residual, this is a great chain.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            let gap_after_next = post_residual - next_item_size;
            if gap_after_next <= 12 {
                score -= 15.0; // two items leave only dead space -> good
            }
        } else if post_residual > 0 && post_residual < next_item_size {
            // next item can't use this gap; if gap is dead anyway, less bad
            if post_residual <= 12 {
                score += 5.0;
            } else {
                score += 8.0; // blocks a usable gap
            }
        }
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (penalize opening new bins indirectly by raising all scores uniformly
    // is neutral; instead reward using bins when count is high).
    let pressure = (open_bins_count as f64).ln().max(0.0) * 3.0;
    score -= pressure;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer bins with low residual overall (fill emptier-first intuition
    // reversed: keep large residuals for large future items).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // New-bin candidate: neutral baseline; only attractive when no open bin
    // offers a decent fit. Penalize it mildly so tight fits win.
    if bin_residual == bin_capacity {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward placements where the next item fits exactly into the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-chain
        } else if next_item_size <= post_residual {
            // Reward proportionally to how well the next item fills the remainder.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * fill;
            // Extra bonus if after the next item the bin is nearly full.
            let rem2 = post_residual - next_item_size;
            if rem2 <= 5 {
                score -= 25.0;
            }
        } else {
            // Next item cannot follow into this bin: penalize large dead space.
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 20.0 * waste;
        }
    }

    // Penalize bins whose residual is far below the mean (they are already fragmented);
    // prefer consuming bins that are below-mean residual (tight packing there is cheap).
    let dev = mean_residual - post_residual as f64;
    score += 0.15 * dev;

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize leaving residuals that are too small to ever be useful (dead space),
    // but reward near-zero residuals (bin fully consumed).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    } else if post_residual == 0 {
        score -= 20.0;
    }

    // Early in the stream, be more willing to open/spread across bins (score new bins better);
    // late in the stream, squeeze into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable early, penalized later.
        score += 25.0 * (1.0 - progress);
        // But if no open bin fits well, a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 35.0;
        }
    }

    // Mild penalty for accumulating too many open bins.
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream: early on, be conservative; later, fill aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: reward near-perfect packing.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize small dead space that likely cannot be reused (post_residual too small for typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - progress); // early stream: small leftovers are costly
    }

    // Lookahead coupling: reward if next item fits into post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 30.0;
        } else {
            // Next item won't fit here; penalize slightly more if this bin was the only option.
            score += 10.0 * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Global state: many open bins -> prefer filling existing ones (penalize new-bin candidate).
    score += open_bins_count as f64 * 2.0 * (bin_residual as f64 / bin_capacity as f64);

    // Mean residual deviation: prefer bins whose residual is below mean (already partially filled).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // New-bin candidate handling: empty bin gets a baseline cost, decreasing as stream progresses
    // (later, consolidating is more valuable than spreading).
    if bin_residual == bin_capacity {
        score += 55.0 - 35.0 * progress;
        // But if no open bin fits well, allow opening: soften when fit is terrible.
        if fit_ratio < 0.5 {
            score -= 20.0 * (0.5 - fit_ratio) * 2.0;
        }
    }

    // Time-horizon term: as the end approaches, minimize absolute leftover hard.
    score += (1.0 - progress) * 0.1 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early stream: prefer tight fits (penalize large residual quadratically).
    // Late stream: residual waste matters more since bins are less likely refilled.
    let tightness = pr_norm * pr_norm;
    score += 40.0 * tightness * (0.5 + 2.0 * progress);

    // Smooth reward for near-perfect fits via polynomial valley around pr_norm ~ 0.
    score -= 25.0 * (-pr_norm * 6.0).exp();

    // Last-chance bin: strong smooth bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 - progress * 0.5);
    }

    // Lookahead coupling: smooth reward if next item fits in post_residual.
    if next_item_size > 0 {
        let fits_next = if (post_residual as u32) >= next_item_size { 1.0 } else { 0.0 };
        let next_norm = next_item_size as f64 / cap;
        score -= 30.0 * fits_next * (1.0 - pr_norm) * (0.5 + next_norm);
    } else {
        // Last item: penalize any residual linearly-extra.
        score += 10.0 * pr_norm;
    }

    // Penalize bins far from mean residual (smooth dispersion term).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Many open bins: gently discourage spreading; smooth in open_bins_count.
    let obn = open_bins_count as f64;
    score += 2.0 * pr_norm * (obn / (obn + 5.0));

    // New-bin candidate: make it moderately attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        score += 15.0 - 10.0 * tightness - 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit -> extremely strong reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of the leftover space: classify post_residual by
    // integer division into "usable" classes. Small leftovers (dead space)
    // are penalized; leftovers that can still host typical items are fine.
    let cap = bin_capacity as f64;

    // Class thresholds via integer division on post_residual
    let cls = post_residual / 10; // 0..10 harmonic class
    match cls {
        0 => score -= 50.0,               // post_residual < 10: near-perfect packing
        1 => score += 5.0,                // 10-19: small but usable
        2 | 3 => score += 15.0,           // 20-39: medium leftover
        4 | 5 => score += 25.0,           // 40-59: half-full-ish, still flexible
        _ => score += 40.0,               // 60+: wasteful placement of a small item
    }

    // Reward when post_residual is a good host for the lookahead item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 - slack * 0.4; // prefer just-fits-for-next combos
    } else if next_item_size > 0 {
        // next item cannot fit here; penalize proportionally
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a new bin is wasteful unless
    // nothing decent fits elsewhere. Base penalty:
    if bin_residual == bin_capacity {
        score += 200.0;
        // but if few fitting bins exist, opening fresh may be right
        if fitting_bins_count == 0 {
            score -= 250.0;
        } else if fitting_bins_count == 1 {
            score -= 100.0;
        }
        // late in the stream, prefer closing out existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 50.0;
    }

    // Coupling with mean residual: prefer bins close to the mean fill state
    // (keeps residual distribution balanced, preserving flexibility)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Fraction-of-capacity tightness bonus (harmonic fraction logic)
    let fill_frac = (bin_capacity - post_residual) as f64 / cap;
    score -= fill_frac * fill_frac * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space penalty: gaps too small to ever be useful are quadratically punished.
    // With unknown distributions, treat residuals < 10 as near-dead (min observed size class).
    if post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 10.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits: small post_residual relative to capacity is good (already via base),
    // but boost the reward for near-perfect packing.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Open-bin pressure: discourage spreading across many open bins; encourage closing bins out.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoiding wasted capacity in the current bin).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward;
    // if it doesn't fit at all, mild penalty for leaving a gap the future can't use.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            score += 5.0;
        }
    }

    // New-bin candidate calibration: an empty new bin has post_residual == bin_capacity;
    // make it attractive only when existing bins would leave large dead space.
    if bin_residual == bin_capacity {
        score -= 10.0;
        score += mean_residual * 0.3;
    }

    // Progress-based tightening: as the stream advances, prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward exact or near-exact match with next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64 - next).abs() < 0.5 {
            score -= 60.0; // perfect chain: item + next item fill bin
        } else if post_residual >= next_item_size {
            let slack = post_residual as f64 - next;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize proportionally to leftover dead space
            let overflow = next - post_residual as f64;
            score += 10.0 + 0.5 * overflow;
        }
    } else {
        // Last item: prefer minimal post residual strongly.
        score -= 30.0;
    }

    // Relative-to-mean coupling: bins with residual far from mean are less attractive
    // unless they are near-perfect fits.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Tightness reward: low post_residual relative to capacity is good.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness * tightness;

    // Last-chance bin: strongly favor using the only bin that fits to avoid opening new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin, unless current fit is terrible
    // and a fresh bin matches next item better.
    if bin_residual == bin_capacity {
        let base_penalty = 45.0;
        let escape_bonus = if next_item_size > 0
            && post_residual >= next_item_size
            && (bin_residual as f64 - item_size as f64) > 0.0
        {
            0.0
        } else {
            0.0
        };
        // If no open bin fits well (post residual large), reduce penalty.
        let poor_fit = if post_residual > bin_capacity / 2 { 25.0 } else { 0.0 };
        score += base_penalty - poor_fit + escape_bonus;
    }

    // Mild stream-progress effect: late in stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) with a non-linear coupling.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize creating tiny unusable dead space (< smallest possible item).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual == 0 {
        // Perfect fill is excellent.
        score -= 40.0;
    }

    // Lookahead: penalize if the next item cannot fit into the post residual
    // (creates a blocking placement), reward if it fits snugly.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 6.0 + 0.05 * next_item_size as f64;
        } else {
            let slack_after_next = post_residual - next_item_size;
            score -= 4.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Global state: when many bins are open, discourage spreading items
    // into fresh bins; encourage consolidation into existing ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to how many bins could fit.
        score += 35.0 + 3.0 * fitting_bins_count as f64;
        // Early in the stream new bins are cheap; later they are expensive.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    } else {
        // Slight preference for bins with residuals near the mean (balanced use).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.03 * dev;
        // Many open bins: favor filling the fullest bins first.
        score -= 0.10 * (bin_residual as f64 / bin_capacity as f64) * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear coupling: post_residual weighted by progress polynomial
    let pr = post_residual as f64;
    let coupling = pr * (1.0 + 2.0 * progress * progress + 3.0 * progress * progress * progress);
    score += 0.5 * coupling;

    // Penalize post_residual relative to capacity (dead space), smoothly
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    score += 10.0 * norm_pr * norm_pr * (1.0 + progress);

    // Reward tight fits: post_residual small relative to item size
    let it = item_size as f64;
    if it > 0.0 {
        score -= 8.0 * (it / (pr + it)) * (1.0 + progress * progress);
    }

    // Last-chance bonus: only one fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Smooth penalty for spreading across many open bins vs mean residual
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Lookahead: if next item fits in post_residual, reward this placement
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let fits_next = if nxt <= pr { 1.0 } else { 0.0 };
        score -= 6.0 * fits_next * (1.0 + progress);
        // penalize leaving residual that barely misses next item
        let miss = if nxt > pr && nxt - pr <= 10.0 { 1.0 } else { 0.0 };
        score += 4.0 * miss;
    }

    // New-bin candidate: opening a new bin should only win when current fit is terrible
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress) + 5.0 * norm_pr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit).
    let fit_ratio = item_size as f64 / bin_capacity as f64;
    score -= fit_ratio * 30.0;

    // Harmonic class of post_residual: dead space is residual < next_item_size.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Unusable sliver: penalize proportionally, harsher for tiny slivers.
        let sliver = post_residual as f64;
        score += 40.0 + (next_item_size - post_residual) as f64 * 0.8;
        // Tiny slivers (<=10) are near-wasted capacity.
        if post_residual <= 10 {
            score += 25.0;
        }
        let _ = sliver;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Residual reusable by lookahead: reward, scaled by how well next item fills it.
        let reuse = next_item_size as f64 / post_residual as f64;
        score -= 25.0 * reuse.min(1.0);
    }

    // Integer-division threshold classes on post_residual (harmonic buckets).
    let bucket = post_residual / 25; // 0,1,2,3
    match bucket {
        0 => score += 15.0,  // 0..24: near-full, dead space risk unless exact
        1 => score -= 5.0,   // 25..49: mid usable
        2 => score -= 10.0,  // 50..74: good for medium items
        _ => score -= 3.0,   // 75..99: keep loose bins flexible
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., item barely fits anywhere or many bins already open with low mean residual).
    if bin_residual == bin_capacity {
        let crowded = (open_bins_count as f64) * 1.5;
        let poor_fits = if fitting_bins_count == 0 { 0.0 } else {
            (bin_residual - item_size) as f64
        };
        score = 100.0 - fit_ratio * 20.0 - poor_fits * 0.3 + crowded - mean_residual * 0.2;
        // Late in stream, prefer closing out open bins rather than opening new.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 30.0;
    }

    // Prefer filling bins below mean residual (reduces fragmentation variance).
    score -= (mean_residual - post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in the "unusable gap" band
    // (too small to hold any plausible item) is heavily penalized.
    // Gap is unusable if smaller than the smallest plausible item (10),
    // and especially toxic in the 1..=9 band.
    if post_residual == 0 {
        // Perfect fit: strongly reward (subtract).
        score -= 60.0;
    } else if post_residual < 10 {
        // Dead space: unusable for any future item. Severe penalty.
        score += 45.0 + (10 - post_residual) as f64 * 4.0;
    } else {
        // Usable residual: mild bonus scaled by how much useful space remains,
        // favoring residuals that can still host typical items (10..80).
        let usable = post_residual as f64 / bin_capacity as f64;
        score -= 12.0 * usable;
        // Extra reward if the residual can still fit a mid/large item.
        if post_residual >= 40 {
            score -= 6.0;
        }
    }

    // Tightness coupling: reward filling a large fraction of the bin.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill_ratio;

    // Lookahead: if the next item fits into the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item almost fits (within 10), slight penalty for blocking chain fits.
    if next_item_size > 0 && post_residual < next_item_size && post_residual + 10 >= next_item_size {
        score += 5.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: penalize placements that keep many bins open with
    // scattered residuals; encourage consolidation when bins are numerous.
    score += (open_bins_count as f64) * 1.5;

    // Consolidation bonus: prefer bins whose residual is below the mean
    // (i.e., already well-filled bins) to concentrate items.
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // New-bin candidate handling: an empty bin starts with a mild handicap
    // so it only wins when open bins are poor fits (large post_residual / dead space).
    if bin_residual == bin_capacity {
        score += 18.0;
        // But if no open bin fits well, the handicap is overcome naturally
        // by the dead-space penalties above. Slight relief late in the stream
        // when consolidation opportunities have dried up.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: perfect match between post_residual and next_item_size
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 100.0; // exact two-item fill of the bin
        } else if post_residual >= next_item_size {
            // next item fits here; reward tight residual coupling
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use this residual; penalize proportionally to waste
            let waste = (next_item_size - post_residual) as f64;
            score += 5.0 * (waste / 100.0);
        }
    }

    // Relative to mean residual: prefer bins whose residual is tighter than average
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize unless current bins are very fragmented
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        if fragmentation < 0.25 || (next_item_size > 0 && next_item_size > mean_residual) {
            score -= 20.0; // open a new bin when existing space is unusable
        } else {
            score += 40.0; // discourage spreading out
        }
    }

    // Progress-based mild pressure to consolidate early
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.2 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let residual = bin_residual as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer tight fits (low post residual), scaled non-linearly.
    let mut score = post * post / cap;

    // Reward near-perfect packing: exact or near-exact fit gets strong discount.
    if post == 0 {
        score -= 1000.0;
    } else if post <= 5 {
        score -= 300.0 / post;
    }

    // Relative tightness within this bin.
    let fill_ratio = item / residual.max(1.0);
    score -= 50.0 * fill_ratio;

    // Penalize leaving dead space that few future items could use.
    // Small residuals (<10) are dead; moderate residuals (10..80) are reusable.
    if post > 0.0 && post < 10.0 {
        score += 80.0; // dead space penalty
    } else if post >= 10.0 && post <= 80.0 {
        score -= 20.0; // reusable gap bonus
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            // chain bonus, stronger when the chain is tight
            let chain_tight = 1.0 - (post - nxt) / cap;
            score -= 40.0 * chain_tight;
        } else {
            // next item won't fit here; slight penalty proportional to gap
            score += 0.05 * (nxt - post);
        }
    } else {
        // Last item: any leftover is pure waste; maximize final fill.
        score += post * 2.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate logic: opening a new bin is only attractive when
    // the current item fits very poorly everywhere or bins are scarce.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base cost of opening a bin
        score += 120.0;
        // cheaper to open bins early in the stream / when few are open
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 200.0 * progress;
        score += 10.0 * (open_bins_count as f64);
        // if many bins already fit the item, opening a new one is wasteful
        if fitting_bins_count > 1 {
            score += 100.0 * (fitting_bins_count as f64 - 1.0) as f64;
        }
        // if mean residual across open bins is large, prefer existing bins
        score += 0.5 * mean_residual;
        // exception: huge items relative to typical residual deserve fresh bins
        if item > 0.8 * cap && mean_residual < item * 0.9 {
            score -= 200.0;
        }
    } else {
        // Mild bonus for consolidating into bins whose residual is above mean
        // (keeps a set of uniform bins for future flexibility).
        if residual > mean_residual {
            score -= 5.0;
        }
    }

    // Global balance: discourage over-concentrating on one bin when many are open
    // with large residuals (spread load to keep options open).
    if !is_new_bin && open_bins_count > 3 && residual > 2.0 * mean_residual {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items as f64;
