    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = (mean_residual / bin_capacity as f64) * (open_bins_count as f64).sqrt();
        // If mean residual across open bins is small, opening is fine; else discourage.
        score += 30.0 + 120.0 * pressure * (1.0 - 0.5 * progress);
        // If the item is large relative to capacity, opening fresh is more attractive.
        score -= 20.0 * (item_size as f64 / bin_capacity as f64);
    }

    // Mild penalty for leaving very small dead space (unusable slivers),
    // unless it is exactly zero (already rewarded).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Slight preference for tighter (fuller) bins overall.
    score -= 5.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);

    score
}

