            score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
        // Slightly favor bins whose residual is already small (tight packing).
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: make it attractive only when it leaves a versatile residual.
