        let versatility = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 4.0 * versatility;
        // If no open bin fits well (post_residual tiny everywhere), opening a bin is fine.
        if fitting_bins_count == 0 {
            score -= 10.0;
        }
    }

    // Mild preference to fill bins when stream is late (fewer wasted partial bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

