                score -= 18.0;
            }
            if post >= nxt + mean_residual {
                score -= 10.0;
            }
            if (post - nxt) as u32 == mean_residual as u32 {
                score -= 9.0;
            }
            if (post - nxt) <= mean_residual * 0.5 {
                score -= 8.0;
            }
            if post - nxt >= 1.0 && post - nxt <= 4.0 {
                score -= 12.0;
            }
            // Two-step anticipation: residual after chaining still reusable.
            let chained = post - nxt;
            if chained >= mean_residual * 0.8 && chained <= mean_residual * 1.6 {
                score -= 7.0;
            }
        } else if post + 10.0 >= nxt {
            score += 6.0;
        } else {
            score += 0.06 * (nxt - post);
        }
        if nxt > post && (nxt - post) as u32 <= 2 && fitting_bins_count > 1 {
            score += 15.0;
        }
        if nxt > post && (nxt - post) as u32 > 20 && post_residual > 0 && post_residual < 20 {
            score += 12.0;
        }
    } else {
        score += post * 2.2;
    }

    // Dead-space penalty: residual too small for the next item.
    if post_residual > 0 && post_residual < 8 && next_item_size > post_residual {
        score += 26.0;
    }
    if post_residual > 0 && post_residual < 16 && next_item_size > post_residual && (mean_residual as u32) > post_residual {
        score += 9.0 * (16 - post_residual) as f64 / 8.0;
    }

    // Semi-fit lookahead.
    if post_residual > 0 && nxt <= post && nxt > post_residual as f64 * 0.6 && post_residual <= 25 {
        score -= 13.0 * (1.0 - post_residual as f64 / 25.0);
    }
    if post_residual > 0 && post_residual < item_size && nxt > post && open_bins_count > 3 {
        score += 8.0;
    }
    if post_residual > 0 && nxt > post && post_residual < (next_item_size / 2) {
        score += 6.0 * (1.0 - post_residual as f64 / (next_item_size / 2).max(1) as f64);
    }
    if post_residual > 0 && post_residual % 10 == 0 && nxt <= post {
        score -= 5.0;
    }
    let dead = post / cap;
    if post_residual > 0 && nxt > post && dead > 0.35 && post_residual as f64 > mean_residual * 1.5 && fitting_bins_count > 3 {
        score += 10.0 * (dead - 0.35);
    }
    if post_residual > 0 && nxt <= post && (post - nxt) <= 2.0 && dead > 0.4 {
        score -= 9.0;
    }
    if fitting_bins_count > 4 && bin_residual != bin_capacity && post_residual > 30 {
        score += 3.0;
    }

    // Last-chance pressure.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    } else if fitting_bins_count <= 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Consolidation pressure.
    score += (open_bins_count as f64) * 1.5;

    // Mean-residual coupling.
    if residual < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score += 120.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 100.0 * progress;
        score += 10.0 * (open_bins_count as f64);
        if fitting_bins_count > 1 {
            score += 100.0 * (fitting_bins_count as f64 - 1.0);
        }
        score += 0.5 * mean_residual;
        if item_size < (bin_capacity / 2) {
            score += 12.0;
            if next_item_size > 0 && nxt <= post {
                score += 20.0;
            }
        }
        if item > 0.8 * cap && mean_residual < item * 0.9 {
            score -= 200.0;
        }
        if item > 0.5 * cap && next_item_size > 0 && nxt > mean_residual {
            score -= 120.0;
        }
        // Anticipation: prefer fresh bin when item + next item pair perfectly.
        if next_item_size > 0 && item + nxt as u32 <= bin_capacity && (bin_capacity - item as u32 - next_item_size) <= 3 {
            score -= 40.0;
        }
    } else if open_bins_count > 3 && residual > 2.0 * mean_residual {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize dead space into
    // capacity-fraction buckets. Residuals in the lowest class (tiny scraps)
    // are punished hard; large residuals are mild.
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 8.0).floor() as i32; // 0..7 harmonic class
    let class_penalty: f64 = match class {
        0 => 60.0,           // unusable scrap (< 12.5%)
        1 => 25.0,
        2 => 10.0,
        3 => 0.0,
        4 => -5.0,           // half-full-ish bins are reusable
        5 => -8.0,
        6 => -4.0,
        _ => -2.0,
    };
    score += class_penalty;

    // Perfect/near-perfect fit reward
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 100.0;
    }

    // Modulo coupling: does next_item_size land on the residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0; // exact chain fit
        } else if next_item_size < post_residual {
            // residual after hypothetically placing next item
            let chain = post_residual - next_item_size;
            if chain <= 10 {
                score -= 40.0;
            }
            // integer-division harmonic: residual divisible by next item
            if next_item_size > 0 && post_residual % next_item_size == 0 {
                score -= 30.0;
            }
        } else {
            // next item cannot fit here; residual is terminal for lookahead
            score += 15.0;
            // but if residual is small scrap, that's actually fine
            if post_residual < next_item_size && post_residual <= 15 {
                score -= 35.0;
            }
        }
    }

    // Last-chance bin bonus: if this is the only bin that fits, avoid opening new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate logic: fresh bin (residual == capacity).
    if bin_residual == bin_capacity {
        // Prefer new bin when item is large or current bins are fragmented
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let pressure = open_bins_count as f64 / (1.0 + step_index as f64);
        if item_size >= 50 || fitting_bins_count == 0 {
            score -= 30.0;
        }
        if fragmentation > 30.0 {
            score += 20.0; // don't proliferate bins when fragmentation high
        }
        if pressure > 0.5 {
            score += 10.0;
        }
        // If next item is large and this item is small, new bin is wasteful
        if next_item_size > 60 && item_size < 30 {
            score += 25.0;
        }
    }

    // Mild global phase signal
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let residual = bin_residual as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post * post / cap;

    // Perfect / near-perfect fit rewards.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 330.0 / post;
    } else if post_residual < 12 {
        score += 90.0 + (12 - post_residual) as f64 * 6.0;
    } else {
        score -= 15.0 * (post / cap);
        if post_residual >= 40 {
            score -= 9.0;
        }
        // Dead-space ramp: residuals just under 30 are hard to reuse.
        if post_residual < 30 {
            score += 7.5 * (30 - post_residual) as f64 / 18.0;
