    // relative to the running mean residual (keeps residuals reusable).
    if post_residual > 0 && (post_residual as f64 - mean_residual).abs() <= 3.0 {
        score -= 7.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item
    // (min item size 1, but practically small gaps are waste) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0; // unusable gap => strong penalty
    }

    // Reward near-perfect fits (post_residual very small but not penalized zone handled above).
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    }

    // Coupling with open-bin pressure: prefer reusing bins when many are open,
    // prefer opening a fresh bin when few are open and fit is poor.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(0.0) / 10.0);
    score += pressure * 2.0;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 40.0; // leaves a perfect slot for the next item
        } else {
            score -= 10.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item cannot use leftover -> leftover likely dead space
        score += post_residual as f64 * 0.5;
    }

    // New-bin candidate handling: an empty bin is attractive early (few open bins)
    // or when its score would otherwise beat a poor fit; make it moderately costly
    // so it only wins when open bins are scarce or fits are bad.
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (open_bins_count as f64 + 1.0);
        score += 15.0 - scarcity * 30.0 + progress * 10.0;
        // if no open bin can fit at all, new bin must win
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    score
}

