            let slack = (post_residual - next_item_size) as f64;
            // small slack after lookahead placement is good
            score -= (20.0 * (1.0 - slack / bin_capacity as f64)).max(-15.0);
        } else {
            let deficit = (next_item_size - post_residual) as f64;
            // dead space that next item cannot use
            score += 0.5 * deficit;
