    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Compare residual against mean residual: bins tighter than average are better targets
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Slight preference for filling fuller bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: penalize mildly so we only open when open bins are truly bad
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post-residual.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tight * tight;

    // Penalize dead space that cannot plausibly fit the next item (lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Bin can still host the next item: reward leftover capacity relative to next item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (slack / bin_capacity as f64);
        } else {
            // Dead space relative to next item: penalize proportionally.
            let dead = (post_residual as f64) / (next_item_size as f64);
            score += 10.0 * dead;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when open bins
    // are crowded or the item fits poorly everywhere.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity >= item_size;
    if is_new_bin {
        // Base cost of opening a new bin grows with stream progress (commitment effect)
        // and with the number of already-open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + 20.0 * progress + 1.5 * open_bins_count as f64;
        // If open bins are nearly empty on average, opening a new bin is wasteful.
        if mean_residual > item_size as f64 * 1.5 {
            score += 15.0;
        }
        // If next item is small, a fresh bin can absorb both items well: soften the cost.
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 12.0;
        }
    } else {
        // Reward placing into bins whose residual is close to the item (best-fit coupling).
        let fit_gap = (bin_residual - item_size) as f64;
        score -= 8.0 * (1.0 - fit_gap / bin_capacity as f64).powi(3);
