        score -= 0.5 * (open_bins_count as f64).ln().max(0.0);
        // Prefer bins below the mean residual (use up emptier bins first).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        } else {
            score += 3.0;
        }
    }

    // Early-stream exploration: slightly favor trying fresh bins early to diversify residuals.
    if step_index < total_items / 10 {
        if is_new_bin {
            score -= 5.0;
        }
    }

    // Late-stream pressure: avoid opening new bins near the end.
    if step_index as f64 > 0.9 * total_items as f64 && is_new_bin {
        score += 40.0;
