pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base: prefer tight fits (low post residual), with non-linear shaping.
    let mut score = pr * (1.0 + 0.5 * progress);

    // Quadratic dead-space penalty: small residuals (but nonzero) are wasted space.
    let norm_pr = pr / cap;
    score += 40.0 * norm_pr * norm_pr * (1.0 - norm_pr);

    // Cubic coupling with stream progress: early on, tolerate loose packing;
    // late in the stream, penalize residual waste more aggressively.
    score += 30.0 * progress * progress * progress * norm_pr;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward if the next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size > post_residual {
            // Penalize residuals that block the next item.
            score += 8.0 * (next_item_size as f64 - pr) / cap;
        } else {
            score += 0.05 * (pr - next_item_size as f64);
        }
    }

    // Mean residual coupling: penalize bins deviating from the mean residual
    // (encourages homogeneous residual classes for future merging).
    score += 0.3 * (pr - mean_residual).abs() * (0.5 + progress);

    // New-bin candidate handling: slightly discourage opening a new bin
    // unless the item is large relative to remaining capacity elsewhere.
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * (1.0 - progress);
        if item_size > bin_capacity / 2 {
            score -= 4.0;
        }
    }

    score
}

