    if next_item_size > 0 && next_item_size <= post {
        if post % next_item_size == 0 { harmony_bonus += 18.0; }
        else if (post - next_item_size) % 10 == 0 { harmony_bonus += 6.0; }
    }
    // Penalize if next item would NOT fit here (we'd strand space anyway)
    if next_item_size > post && post > 0 && post < 10 {
        harmony_bonus -= 10.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        harmony_bonus += 15.0;
