if bin_residual == bin_capacity && post_residual > 0 && fitting_bins_count > 0 { score += 14.0 + 0.05 * post_residual as f64 ; } score }

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post_residual non-linearly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tight * tight;

    // Penalize large dead space, especially when it can't fit the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 12.0 + 0.3 * (post_residual as f64);
        } else {
            // Reward bins that can also host the lookahead item (chained fit).
            let chain_left = post_residual - next_item_size;
            score -= 8.0 * (1.0 - chain_left as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large
    // relative to current mean residual (i.e., existing bins fit poorly).
    if bin_residual == bin_capacity {
        let early = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = (fitting_bins_count == 0) as i32 as f64;
        score += 55.0 - 25.0 * early - 20.0 * poor_fit;
        // Large items justify fresh bins more readily.
        score -= 0.15 * item_size as f64;
        // Many open bins with high mean residual: prefer reusing them.
        score += 0.05 * open_bins_count as f64 + 0.1 * mean_residual;
    }

    // Time horizon: late in stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 15.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mild penalty for bins far below mean residual (keeps bin residuals uniform).
    let dev = mean_residual - bin_residual as f64;
    score += 0.08 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let residual = bin_residual as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post * post / cap;

    // Perfect / near-perfect fit rewards.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 330.0 / post;
    } else if post_residual < 12 {
        score += 90.0 + (12 - post_residual) as f64 * 6.0;
    } else {
        score -= 15.0 * (post / cap);
        if post_residual >= 40 {
            score -= 9.0;
        }
        // Dead-space ramp: residuals just under 30 are hard to reuse.
        if post_residual < 30 {
            score += 7.5 * (30 - post_residual) as f64 / 18.0;
        }
    }

    // Tightness coupling.
    let fill_ratio = item / residual.max(1.0);
    score -= 24.0 * fill_ratio;

    // Fragmentation penalty for small residuals.
    if post > 0.0 && post < 0.25 * cap {
        score += 30.0 * (1.0 - post / (0.25 * cap));
    }

    // Lookahead chain-fit bonus.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let chain_tight = 1.0 - (post - nxt) / cap;
            score -= 52.0 * chain_tight;
            if post == nxt {
                score -= 68.0;
            }
            if post - nxt < 6.0 {
                score -= 18.0;
            }
            if post >= nxt + mean_residual {
                score -= 10.0;
            }
            if (post - nxt) as u32 == mean_residual as u32 {
                score -= 9.0;
            }
            if post >= nxt && (post - nxt) <= mean_residual * 0.5 {
                score -= 8.0;
            }
            if post - nxt >= 1.0 && post - nxt <= 4.0 {
                score -= 12.0;
            }
        } else if post + 10.0 >= nxt {
            score += 6.0;
        } else {
            score += 0.06 * (nxt - post);
        }
        // Next item nearly fits: penalize leaving a barely-too-small gap.
        if nxt > post && (nxt - post) as u32 <= 2 && fitting_bins_count > 1 {
            score += 15.0;
        }
        if nxt > post && (nxt - post) as u32 > 20 && post_residual > 0 && post_residual < 20 {
            score += 12.0;
        }
    } else {
        score += post * 2.2;
    }

    // Dead-space penalty: residual too small for the next item.
    if post_residual > 0 && post_residual < 8 && next_item_size > post_residual {
        score += 26.0;
    }
    if post_residual > 0 && post_residual < 16 && next_item_size > post_residual && (mean_residual as u32) > post_residual {
        score += 9.0 * (16 - post_residual) as f64 / 8.0;
    }

    // Semi-fit lookahead: next item fits within a fraction of the post residual.
    if post_residual > 0 && next_item_size as f64 <= post && next_item_size as f64 > post_residual as f64 * 0.6 && post_residual <= 25 {
        score -= 13.0 * (1.0 - post_residual as f64 / 25.0);
    }
    // Residual too small for item and next item won't fit either: discourage.
    if post_residual > 0 && post_residual < item_size && next_item_size as f64 > post && open_bins_count > 3 {
        score += 8.0;
    }
    if post_residual > 0 && next_item_size as f64 > post && post_residual < (next_item_size / 2) {
        score += 6.0 * (1.0 - post_residual as f64 / (next_item_size / 2).max(1) as f64);
    }
    if post_residual > 0 && post_residual % 10 == 0 && next_item_size as f64 <= post {
        score -= 5.0;
    }
    let dead = post / cap;
    if post_residual > 0 && next_item_size as f64 > post && dead > 0.35 && (post_residual as f64) > mean_residual * 1.5 && fitting_bins_count > 3 {
        score += 10.0 * (dead - 0.35);
    }
    if post_residual > 0 && next_item_size as f64 <= post && (post - next_item_size as f64) <= 2.0 && dead > 0.4 {
        score -= 9.0;
    }
    if fitting_bins_count > 4 && bin_residual != bin_capacity && post_residual > 30 {
        score += 3.0;
    }

    // NEW: two-step lookahead — prefer residuals that can host item then next item exactly.
    if next_item_size > 0 && post_residual >= item_size + next_item_size {
        score -= 14.0;
    }
    // NEW: penalize creating residuals in the "awkward zone" (just below typical item sizes).
    if post_residual > 0 && post_residual < next_item_size && post_residual >= (next_item_size as f64 * 0.8) as u32 {
        score += 10.0;
    }

    // Last-chance pressure.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    } else if fitting_bins_count <= 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Consolidation pressure.
    score += (open_bins_count as f64) * 1.5;

    // Mean-residual coupling.
    if residual < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score += 120.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 100.0 * progress;
        score += 10.0 * (open_bins_count as f64);
        if fitting_bins_count > 1 {
            score += 100.0 * (fitting_bins_count as f64 - 1.0);
        }
        score += 0.5 * mean_residual;
        if item_size < (bin_capacity / 2) {
            score += 12.0;
            if next_item_size > 0 && (next_item_size as f64) <= post {
                score += 20.0;
            }
        }
        // Huge items deserve fresh bins when residuals are small.
        if item > 0.8 * cap && mean_residual < item * 0.9 {
            score -= 200.0;
        }
        // Medium-large items late in stream when no open bin fits the next item.
        if item > 0.5 * cap && next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 120.0;
        }
        // NEW: fresh bin for large item when all fitting residuals are tiny.
        if item > 0.6 * cap && fitting_bins_count > 0 && mean_residual < item * 0.5 {
            score -= 60.0;
        }
    } else if open_bins_count > 3 && residual > 2.0 * mean_residual {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let pr_norm = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let progress_term = 0.5 + 0.5 * progress;
    let mut score = pr * (1.0 + 0.8 * progress_term);

    // Penalize dead space quadratically, more so early in the stream
    score += 30.0 * pr_norm * pr_norm * (1.0 - progress);

    // Reward tight fits (small post_residual) via smooth negative coupling
    score -= 20.0 * (1.0 - pr_norm) * fit_ratio * fit_ratio;

    // Lookahead: reward bins whose post-residual fits the next item, smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= 12.0 * (1.0 - slack * slack);
        } else {
            score += 8.0 * ((pr - nx).abs() / cap);
        }
    }

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mild penalty for spreading across many open bins late in stream
    score += 0.15 * open_bins_count as f64 * progress;

    // Anchor against new-bin opening: empty bin candidate gets high residual,
    // so keep base score positive-biased for near-empty residuals
    if pr_norm > 0.95 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "small" residue classes are near-perfectly packed -> reward them.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // fraction of capacity wasted after placement

    // Class boundaries via integer division thresholds on post_residual.
    let class = post_residual / 10; // 0..=10 harmonic classes
    match class {
        0 => score -= 60.0,              // near-perfect fit (residual < 10)
        1 => score -= 40.0,              // excellent
        2 => score -= 25.0,              // good
        3 => score -= 12.0,
        4 => score -= 5.0,
        7 => score += 15.0,              // ~70-80 leftover: risky dead space
        8 => score += 25.0,
        9 => score += 35.0,
        _ => {}
    }

    // Modulo arithmetic: residuals divisible by small item sizes are reusable.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 8.0; // perfectly divisible residual, matches common sizes
        } else if post_residual % 5 == 0 {
            score -= 4.0;
        }
    }

    // Lookahead coupling: reward if next item fits the post-residual exactly
    // or nearly (harmonic chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0; // perfect chain
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 30.0;
            } else if slack <= 25 {
                score -= 10.0;
            } else {
                score += 5.0; // next item leaves big hole again
            }
        } else {
            // next item won't fit here; small residuals are fine to strand
            if post_residual > 30 {
                score += 12.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // current open bins are badly fragmented.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fragmentation = if open_bins_count > 0 {
            (mean_residual / cap).max(0.0)
        } else {
            0.0
        };
        // High mean residual => open bins are empty-ish, prefer them.
        score += 30.0 + 50.0 * fragmentation;
        // Early in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
        // If item is huge, fresh bin is natural.
        if item_size >= 60 {
            score -= 25.0;
        }
    }

    // Prefer filling emptier bins when many bins are open (bin consolidation).
    if open_bins_count > 3 {
        score += 0.15 * open_bins_count as f64 * (bin_residual as f64 / cap);
    }

    // Mild penalty proportional to waste fraction.
    score += 20.0 * frac * frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
