        score -= 330.0 / post;
    } else if post_residual < 12 {
        score += 85.0 + (12 - post_residual) as f64 * 5.5;
    } else {
        score -= 13.0 * (post / cap);
        if post_residual >= 40 { score -= 9.0; }
        if post_residual < 30 { score += 7.0 * (30 - post_residual) as f64 / 18.0; }
    }

    // Penalize small dead space generally
    if post > 0.0 && post < 0.25 * cap {
        score += 30.0 * (1.0 - post / (0.25 * cap));
    }

    // Lookahead: chain fit with next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let chain_tight = 1.0 - (post - nxt) / cap;
            score -= 52.0 * chain_tight;
            if post == nxt { score -= 68.0; }
            let slack = post - nxt;
            if slack <= 2.0 { score -= 14.0; }
            else if slack <= 4.0 { score -= 12.0; }
            else if slack <= 6.0 { score -= 9.0; }
            if slack >= 1.0 && slack <= mean_residual * 0.5 { score -= 8.0; }
            if post >= nxt + mean_residual { score -= 10.0; }
        } else if post + 10.0 >= nxt {
            score += 6.0;
        } else {
            score += 0.06 * (nxt - post);
        }
        // Next item would strand this residual
        if nxt > post && post_residual > 0 && post_residual < 20 {
            score += 11.0;
        }
        if nxt > post && (nxt - post) as u32 <= 2 && fitting_bins_count > 1 {
            score += 15.0;
        }
        if nxt > post && (nxt - post) as u32 > 20 && post_residual > 0 && post_residual < 20 {
            score += 12.0;
        }
        if nxt > post && post_residual > 0 && post_residual < (next_item_size / 2).max(1) {
            score += 6.0 * (1.0 - post_residual as f64 / (next_item_size / 2).max(1) as f64);
        }
    } else {
        score += post * 2.2;
    }

    // Sliver penalty when next item cannot use it
    if post_residual > 0 && post_residual < 8 && next_item_size > post_residual {
        score += 26.0;
    }
    if post_residual > 0 && post_residual < 16 && next_item_size as f64 > post && (mean_residual as u32) > post_residual {
        score += 9.0 * (16 - post_residual) as f64 / 8.0;
    }

    // Last-chance bin: strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Many open bins: keep big residuals from hogging preference
    if fitting_bins_count > 4 && bin_residual != bin_capacity && post_residual > 30 {
        score += 3.0;
    }

    // Mean-residual relative comparison
    score -= 0.25 * (mean_residual - post);

    // Progress-aware fullness preference
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 8.0 * progress * (post / cap);

    // Dead-space ratio lookahead: strand risk when bin is already >40% empty
    let dead = post / cap;
    if post_residual > 0 && next_item_size as f64 > post && dead > 0.35 && (post_residual as f64) > mean_residual * 1.5 && fitting_bins_count > 3 {
        score += 10.0 * (dead - 0.35);
    }
    if post_residual > 0 && next_item_size as f64 <= post && (post - next_item_size as f64) <= 2.0 && dead > 0.4 {
        score -= 9.0;
    }
    if post_residual > 0 && post_residual < item_size && next_item_size as f64 > post && open_bins_count > 3 {
        score += 8.0;
    }

    // New-bin candidate: only open when open bins are truly poor
    if bin_residual == bin_capacity {
        score += 18.0;
        // Late stream with many open bins: opening new bins is fine
        if open_bins_count > 6 && progress > 0.5 {
            score -= 6.0;
        }
        // Never open a new bin when an exact or near-exact fit exists
        if post_residual == 0 || (post_residual <= 2 && fitting_bins_count > 0) {
            score += 400.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    // Quadratic residual penalty dominates: strongly prefer tight fits
    let mut score = post * post / cap;

