        score -= 100.0;
    }

    // Reward tight fits relative to bin capacity (waste ratio).
    score -= (item_size as f64 / bin_capacity as f64) * 30.0;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: baseline attractiveness, reduced when many bins
    // are already open (consolidation pressure) or when the next item
    // would fit better into this bin's post_residual.
    if bin_residual == bin_capacity {
        score = 50.0 + post_residual as f64;
        score += (open_bins_count as f64).min(20.0) * 1.5;
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 15.0; // existing bin could host the next item too
        }
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 20.0;
        } else if slack < 25.0 {
            score -= 6.0;
        }
    }

    // Open-bin pressure: mildly discourage spreading across many bins.
    score += (open_bins_count as f64 / 50.0) * 3.0;

    // Late in the stream, prefer closing bins tightly (avoid many tiny residuals).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.7 && post_residual > 0 {
        score += post_residual as f64 * 0.3 * progress;
    }

    // Deviation from mean residual: prefer bins whose residual is close to item need.
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post * post / cap;

    // Exact fill is ideal
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 330.0 / post;
    } else if post_residual < 12 {
        score += 90.0 + (12 - post_residual) as f64 * 6.0;
    } else {
        score -= 15.0 * (post / cap);
        if post_residual >= 40 { score -= 9.0; }
        if post_residual < 30 { score += 7.5 * (30 - post_residual) as f64 / 18.0; }
    }

    // Penalize small dead space generally
    if post > 0.0 && post < 0.25 * cap {
        score += 30.0 * (1.0 - post / (0.25 * cap));
    }

    // Lookahead: chain fit with next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let chain_tight = 1.0 - (post - nxt) / cap;
            score -= 52.0 * chain_tight;
            if post == nxt { score -= 68.0; }
            if post >= nxt + mean_residual { score -= 10.0; }
            if post >= nxt && (post - nxt) <= mean_residual * 0.5 { score -= 8.0; }
            let slack = post - nxt;
            if slack >= 1.0 && slack <= 4.0 { score -= 12.0; }
            if nxt <= post && slack < 6.0 { score -= 18.0; }
            if slack as u32 == mean_residual as u32 { score -= 9.0; }
        } else if post + 10.0 >= nxt {
            score += 6.0;
        } else {
            score += 0.06 * (nxt - post);
        }
        // Next item barely misses this bin: residual likely stranded
        if nxt > post && (nxt - post) as u32 <= 2 && fitting_bins_count > 1 {
            score += 15.0;
        }
        if nxt > post && (nxt - post) as u32 > 20 && post_residual > 0 && post_residual < 20 {
            score += 12.0;
        }
        if nxt > post && post_residual > 0 && post_residual < (next_item_size / 2).max(1) {
            score += 6.0 * (1.0 - post_residual as f64 / (next_item_size / 2).max(1) as f64);
        }
    } else {
        score += post * 2.2;
    }

    // Sliver penalty when next item cannot use it
    if post_residual > 0 && post_residual < 8 && next_item_size > post_residual {
        score += 26.0;
    }
    if post_residual > 0 && post_residual < 16 && next_item_size > post_residual && (mean_residual as u32) > post_residual {
        score += 9.0 * (16 - post_residual) as f64 / 8.0;
    }

    // Many open bins: keep big residuals from hogging preference
    if fitting_bins_count > 4 && bin_residual != bin_capacity && post_residual > 30 {
        score += 3.0;
    }

    // Dead-space-aware lookahead coupling
    let dead = post / cap;
    if post_residual > 0 && next_item_size as f64 <= post && next_item_size as f64 > post_residual as f64 * 0.6 && post_residual <= 25 {
        score -= 13.0 * (1.0 - post_residual as f64 / 25.0);
    }
    if post_residual > 0 && post_residual < item_size && next_item_size as f64 > post && open_bins_count > 3 {
        score += 8.0;
    }
    if post_residual > 0 && next_item_size as f64 > post && dead > 0.35 && post_residual as f64 > mean_residual * 1.5 && fitting_bins_count > 3 {
        score += 10.0 * (dead - 0.35);
    }
    if post_residual > 0 && next_item_size as f64 <= post && (post - next_item_size as f64) <= 2.0 && dead > 0.4 {
        score -= 9.0;
    }

    // Last-chance bin: strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Mean-residual relative comparison
    score -= 0.25 * (mean_residual - post);

    // Progress-aware fullness preference
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 8.0 * progress * (post / cap);

    // New-bin candidate: only open when open bins are truly poor
    if bin_residual == bin_capacity {
        score += 18.0;
        if open_bins_count > 6 && progress > 0.5 {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but weight waste relative to mean residual.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mean = if mean_residual.is_finite() { mean_residual } else { cap };

    // 2-step lookahead: exact match of post_residual with next_item_size is ideal.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post - nxt).abs();
        // Perfect chaining bonus: next item exactly fills this bin.
        if diff < 0.5 {
            score -= 60.0;
        } else if post >= nxt {
            // Next item fits here: reward proportionally to closeness of match.
            let rel = diff / cap;
            score -= 40.0 * (1.0 - rel.min(1.0));
            // Extra reward if the pair nearly exhausts the bin.
            if post - nxt as u32 <= 10 {
                score -= 15.0;
            }
        } else {
            // Next item would NOT fit here: penalize dead space below next size.
            let gap = nxt - post;
            score += 20.0 + 0.5 * gap;
            // Small leftovers (<10) are nearly dead space; harsh penalty.
            if post < 10.0 {
                score += 25.0;
            }
        }
    }

    // Compare post_residual against mean residual: leaving more than average
    // waste is bad, leaving less is good.
    score += 0.3 * (post - mean);

    // Last chance: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when open bins are congested or
    // the item is huge and nothing tight exists. Neutral otherwise.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let congestion = open_bins_count as f64 / (1.0 + progress * 4.0);
        score += 45.0 + congestion * 10.0;
        // Late in the stream, avoid proliferating bins.
        score += 30.0 * progress;
        // If item is small, opening a fresh bin wastes capacity.
        if (item_size as f64) < 0.35 * cap {
            score += 20.0;
        }
    }

    // Mild preference for bins that become exactly half or fully packed.
    if post == 0 {
        score -= 50.0;
    } else if post == 50 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large waste fraction nonlinearly.
    let waste_frac = post_residual as f64 / cap;
    score += waste_frac * waste_frac * 8.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: reward if next item fits the post residual.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 6.0;
        } else {
            // Dead space relative to next item's needs.
            let gap = next_item_size as f64 - post_residual as f64;
            score += gap * 0.35;
        }
        // Bonus for leaving exactly the space the next item needs.
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Global state: many open bins with high mean residual -> prefer consolidation
    // into existing bins rather than spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 2 {
        score += (mean_residual / cap) * (open_bins_count as f64).ln() * 2.0 * (1.0 - progress * 0.5);
    }

    // Penalize opening a new bin when it's not needed, more so early in the stream.
    if bin_residual == bin_capacity {
        let new_bin_penalty = 20.0 + 25.0 * (1.0 - progress);
        // Allow new bin when existing fit is terrible and mean residual is low.
        let escape = (post_residual as f64 / cap) * 10.0 + (mean_residual / cap) * 5.0;
        score += new_bin_penalty - escape;
    }

    // Mild time-horizon shaping: be greedier (prefer tight fits) as stream ends.
    score -= progress * (bin_residual as f64 - item_size as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: waste left behind, with non-linear penalty for mid-range dead space
    let mut score = pr as f64;
    score += cap * (x * (1.0 - x) * 4.0) * (0.5 + 0.5 * t) * 2.0;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate larger residuals; late, tighten packing
    let progress_weight = 1.0 + 2.0 * t * t;
    score += x * x * cap * progress_weight * 0.5;

    // Reward tight fits (small post residual) more strongly as stream advances
    score -= (1.0 - x).powi(3) * cap * (0.3 + 0.7 * t);

    // Lookahead: if next item fits into post residual, reward this bin
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let snug = 1.0 - ((pr - nx) / cap);
            score -= snug * snug * (10.0 + 20.0 * t);
        } else {
            score += 5.0 + 10.0 * t;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 25.0 * t;
    }

    // Slight dispersion penalty relative to mean residual (prefer balanced bins)
    score += (pr - mean_residual) * 0.15;

    // Mild preference to fill existing bins over opening new ones early
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let residual = bin_residual as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post * post / cap;

    // Perfect / near-perfect fit rewards.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 330.0 / post;
    } else if post_residual < 12 {
        score += 90.0 + (12 - post_residual) as f64 * 6.0;
    } else {
        score -= 15.0 * (post / cap);
        if post_residual >= 40 {
            score -= 9.0;
        }
        // Dead-space ramp: residuals just under 30 are hard to reuse.
        if post_residual < 30 {
            score += 7.5 * (30 - post_residual) as f64 / 18.0;
        }
    }

    // Tightness coupling.
    let fill_ratio = item / residual.max(1.0);
    score -= 24.0 * fill_ratio;

    // Fragmentation penalty for small residuals.
    if post > 0.0 && post < 0.25 * cap {
        score += 30.0 * (1.0 - post / (0.25 * cap));
    }

    // Lookahead chain-fit bonus.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let chain_tight = 1.0 - (post - nxt) / cap;
            score -= 52.0 * chain_tight;
            if post == nxt {
                score -= 68.0;
            }
            if post - nxt < 6.0 {
                score -= 18.0;
            }
            if post >= nxt + mean_residual {
                score -= 10.0;
            }
            if (post - nxt) as u32 == mean_residual as u32 {
                score -= 9.0;
            }
            if post >= nxt && (post - nxt) <= mean_residual * 0.5 {
                score -= 8.0;
            }
            if post - nxt >= 1.0 && post - nxt <= 4.0 {
                score -= 12.0;
            }
            // Two-step lookahead: after placing next item, residual stays reusable.
            let post2 = post - nxt;
            if post2 >= next_item_size as f64 && next_item_size > 0 {
                score -= 6.0;
            }
        } else if post + 10.0 >= nxt {
            score += 6.0;
        } else {
            score += 0.06 * (nxt - post);
        }
        // Next item nearly fits: penalize leaving a barely-too-small gap.
        if nxt > post && (nxt - post) as u32 <= 2 && fitting_bins_count > 1 {
            score += 15.0;
        }
        if nxt > post && (nxt - post) as u32 > 20 && post_residual > 0 && post_residual < 20 {
            score += 12.0;
        }
    } else {
        score += post * 2.2;
    }

    // Dead-space penalty: residual too small for the next item.
    if post_residual > 0 && post_residual < 8 && next_item_size > post_residual {
        score += 26.0;
    }
    if post_residual > 0 && post_residual < 16 && next_item_size > post_residual && (mean_residual as u32) > post_residual {
        score += 9.0 * (16 - post_residual) as f64 / 8.0;
    }

    // Semi-fit lookahead: next item fits within a fraction of the post residual.
    if post_residual > 0 && next_item_size as f64 <= post && next_item_size as f64 > post_residual as f64 * 0.6 && post_residual <= 25 {
        score -= 13.0 * (1.0 - post_residual as f64 / 25.0);
    }
    // Residual too small for item and next item won't fit either: discourage.
    if post_residual > 0 && post_residual < item_size && next_item_size as f64 > post && open_bins_count > 3 {
        score += 8.0;
    }
    if post_residual > 0 && next_item_size as f64 > post && post_residual < (next_item_size / 2) {
        score += 6.0 * (1.0 - post_residual as f64 / (next_item_size / 2).max(1) as f64);
    }
    if post_residual > 0 && post_residual % 10 == 0 && next_item_size as f64 <= post {
        score -= 5.0;
    }
    let dead = post / cap;
    if post_residual > 0 && next_item_size as f64 > post && dead > 0.35 && (post_residual as f64) > mean_residual * 1.5 && fitting_bins_count > 3 {
        score += 10.0 * (dead - 0.35);
    }
    if post_residual > 0 && next_item_size as f64 <= post && (post - next_item_size as f64) <= 2.0 && dead > 0.4 {
        score -= 9.0;
    }
    if fitting_bins_count > 4 && bin_residual != bin_capacity && post_residual > 30 {
        score += 3.0;
    }

    // Last-chance pressure.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    } else if fitting_bins_count <= 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Consolidation pressure.
    score += (open_bins_count as f64) * 1.5;

    // Mean-residual coupling.
    if residual < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score += 120.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 100.0 * progress;
        score += 10.0 * (open_bins_count as f64);
        if fitting_bins_count > 1 {
            score += 100.0 * (fitting_bins_count as f64 - 1.0);
        }
        score += 0.5 * mean_residual;
        if item_size < (bin_capacity / 2) {
            score += 12.0;
            if next_item_size > 0 && (next_item_size as f64) <= post {
                score += 20.0;
            }
        }
        // Huge items deserve fresh bins when residuals are small.
        if item > 0.8 * cap && mean_residual < item * 0.9 {
            score -= 200.0;
        }
        // Medium-large items late in stream when no open bin fits the next item.
        if item > 0.5 * cap && next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 120.0;
        }
        // Fresh bin is attractive when the best open fit would strand a tiny gap.
        if fitting_bins_count > 1 {
            let gap = residual - item;
            if gap > 0.0 && gap < 10.0 && next_item_size as f64 > gap {
                score -= 60.0;
            }
        }
    } else if open_bins_count > 3 && residual > 2.0 * mean_residual {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: which capacity fraction band does the leftover live in? ---
    // Class the residual by integer division into harmonic bands of the capacity:
    //   band 0: post_residual == 0            (perfect fit -> huge reward)
    //   band 1: 1..=12                        (tiny sliver, likely dead space)
    //   band 2: 13..=25                       (small)
    //   band 3: 26..=50                       (medium, reusable)
    //   band 4: 51..=100                      (large, very reusable)
    let band = post_residual / 13; // 0..7 harmonic classes via integer division threshold
    match band {
        0 => {
            if post_residual == 0 {
                score -= 200.0; // perfect closure
            } else {
                score += 90.0; // sliver: 1..12 mostly dead space
            }
        }
        1 => { score += 25.0; }        // 13..25 small
        2 => { score -= 10.0; }        // 26..50 medium, decent
        _ => { score -= 30.0; }        // 51+ large leftover, very reusable
    }

    // --- Modulo coupling: does post_residual align with the NEXT item's harmonic class? ---
    // If next_item_size > 0, check whether next item fits exactly or nearly into the leftover.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 120.0; // next item closes this bin perfectly
            } else if gap <= 5 {
                score -= 60.0;  // near-perfect lookahead fit
            } else if gap <= 15 {
                score -= 20.0;  // decent lookahead fit
            } else {
                score += (gap as f64) * 0.35; // wasteful: big gap after next item
            }
        } else {
            // next item cannot use this leftover at all: penalize proportionally
            score += 15.0 + (next_item_size as f64 - post_residual as f64) * 0.25;
        }
    }

    // --- Last-chance dynamics ---
    if fitting_bins_count == 1 {
        // This is the only bin that fits: strongly favor using it over opening a new bin.
        score -= 70.0;
    } else if fitting_bins_count == 0 {
        // Should not happen for open bins, but guard.
        score += 50.0;
    }

    // --- New-bin candidate handling: bin_residual == bin_capacity (empty bin) ---
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin: discourage unless fits are poor.
        score = bin_capacity as f64 - 40.0; // baseline 60
        // Reward opening a new bin when current item leaves a bad residual elsewhere
        // (i.e., when item is small relative to capacity: fresh bin keeps flexibility).
        let fill_frac = item_size as f64 / bin_capacity as f64;
        if fill_frac < 0.35 {
            score -= 25.0; // small item into fresh bin is fine
        } else if fill_frac > 0.8 {
            score += 20.0; // big item: prefer an existing bin if any fits
        }
        // If many bins are open and mean residual is large, prefer reusing.
        score += (mean_residual / 10.0).min(30.0);
        // If next item is large and this item is small, fresh bin preserves room.
        if next_item_size > 60 && item_size < 40 {
            score -= 15.0;
        }
        // If this was the last chance among open bins, opening is less bad.
        if fitting_bins_count == 1 {
            score -= 55.0;
        }
    }

    // --- Mild stream-progression tie-breaker: later in stream, prefer tighter packing ---
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // --- Open-bins pressure: many open bins -> favor filling existing ones ---
    score += (open_bins_count as f64).ln().max(0.0) * 3.0;

    // --- Modulo texture on post_residual: multiples related to common item sizes ---
    // Residuals that are multiples of 10 align with the item grid (items 10..80 historically).
    if post_residual > 0 && post_residual % 10 == 0 {
        score -= 8.0;
    }
    // Residuals that are prime-like odd slivers (mod 2 == 1 and small) are dead weight.
    if post_residual % 2 == 1 && post_residual < 20 {
        score += 12.0;
    }

    score
}

