    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on wasted space, damped by stream progress
    let mut score = pr * (1.0 + 0.8 * norm_pr * (1.0 - progress));

    // Smooth polynomial coupling: waste penalized more as stream advances
    score += 12.0 * norm_pr.powi(2) * (0.3 + progress);

    // Reward tight fits with a smooth saturating term
    let tightness = 1.0 - norm_pr;
    score -= 15.0 * tightness.powi(3) * (1.0 + progress);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 * (0.5 + progress);
