    // Lookahead: reward residual that can host the next item (smooth overlap)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_gap = (pr - nx).abs();
        score -= 8.0 * (1.0 - fit_gap / cap).max(0.0);
    } else {
        // Final items: minimize residual aggressively
        score += 6.0 * norm_pr;
    }

    // Mild diversity pressure: many open bins -> prefer filling existing ones
    score += 0.4 * open_bins_count as f64 * norm_pr;

    // Mean residual coupling: penalize deviating far from mean residual state
    score += 0.05 * (pr - mean_residual).abs();

    // New-bin candidate penalty: opening fresh bins is costly unless residual is large
    if bin_residual == bin_capacity {
        score += 18.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

