    // are more "usable" for future items (items are multiples of 10 in classic streams).
    let r = post_residual;
    let class_mod = r % 10;
    let class_bonus = match class_mod {
        0 => -6.0,          // perfectly reusable residue
        1..=2 => -3.0,      // nearly perfect
        8..=9 => -2.0,      // nearly a full slot away
        3..=7 => 0.0,       // awkward middle residue
        _ => 0.0,
    };
