    if r <= 5 {
        score += 8.0;
    }
    // Large leftover residual is good (bin stays flexible).
    if r >= 40 {
        score -= 3.0;
    }

    // Lookahead coupling: does next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= r {
            // Perfect or near-perfect fill for the next item: strong reward.
            let tightness = (r - next_item_size) as f64;
            if tightness <= 5.0 {
                score -= 10.0;
            } else {
                score -= 4.0;
            }
        } else {
            // Next item cannot use this bin's residue: penalize small residues more.
            score += 2.0 + (next_item_size - r) as f64 * 0.05;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a new bin should only win when all
    // open bins give bad fits. Make the empty bin attractive only for large items.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base cost of a new bin grows with how many bins are already open.
        score += 15.0 + open_bins_count as f64 * 0.5;
        // Large items relative to capacity justify a fresh bin.
        let frac = item_size as f64 / bin_capacity as f64;
        if frac > 0.6 {
            score -= 10.0 * frac;
        }
        // Late in the stream, waste on a fresh bin is less amortized.
        score += progress * 3.0;
        // If next item would fit nicely in a fresh bin after this one, mild bonus.
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 2.0;
        }
    }

    // Tight fit reward: minimal waste placements get extra preference.
    if r == 0 {
        score -= 9.0;
    }

    // Mean residual context: if open bins are generally slack, prefer consuming
    // slack from this bin rather than fragmenting elsewhere.
    if mean_residual > 20.0 && r < mean_residual {
        score -= 1.5;
    }

    score
}

