pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress in stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fractional fill of the bin after placement
    let fill = 1.0 - (post_residual as f64 / bin_capacity as f64);

    // Reward tight fits strongly (non-linear)
    score -= 12.0 * fill * fill;

    // Penalize leaving dead space that nothing small can use later:
    // dead space is worse if post_residual is small-but-nonzero (awkward gap)
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size < post_residual {
            score -= 4.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty for wasting capacity
            score += 2.0 * (post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: maximize fill aggressively
        score -= 15.0 * fill;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Many open bins: prefer consolidating into bins with low residual
    if open_bins_count > 2 {
        let rel_mean = mean_residual / bin_capacity as f64;
        // favor bins whose residual is below average (tighter bins)
        let diff = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 5.0 * diff;
        // pressure to close bins when many are open
        score -= 3.0 * (open_bins_count as f64).ln() * (1.0 - rel_mean);
    }

    // Early in stream: allow spreading (penalize opening new bins less later).
    // New-bin candidate handling: residual == capacity means empty bin.
    if bin_residual == bin_capacity {
        // Opening a new bin is costly early, acceptable late or when item is huge
        let item_frac = item_size as f64 / bin_capacity as f64;
        let openness = 0.5 + 0.5 * progress;
        score += 25.0 * openness * (1.0 - item_frac);
        // If item is large (>70% capacity), new bin is fine
        if item_frac > 0.7 {
            score -= 12.0;
        }
        // If no existing bin fits well, opening new bin is natural
        if fitting_bins_count == 0 {
            score -= 15.0;
        }
    }

    // Mild global pressure: as stream progresses, reward high fill more
    score -= 6.0 * progress * fill;

    score
}

