pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr as f64;
    score += 18.0 * base * base * (0.5 + progress);
    score -= 12.0 * base * (1.0 - progress) * (1.0 - base);

    // Tight-fit reward, stronger late in the stream
    let tightness = 1.0 - base;
    score -= 10.0 * tightness * tightness * (0.4 + 0.6 * progress);

    // Penalize dead space relative to mean residual
    score += 0.15 * (pr as f64 - mean_residual).max(0.0);
    score -= 0.08 * (mean_residual - pr as f64).max(0.0);

    // Lookahead: favor residual that can host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr as f64 >= nx {
            score -= 8.0 * (1.0 - (pr as f64 - nx) / cap);
        } else {
            score += 6.0 * (nx - pr as f64) / cap;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (0.5 + progress);
    }

    // New-bin candidate: penalize mildly early, more when many bins open
    if bin_residual == bin_capacity {
        score += 10.0 + 1.5 * open_bins_count as f64 * (0.5 + progress);
    }

    score
}

