    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    } else if fitting_bins_count <= 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Consolidation pressure.
    score += (open_bins_count as f64) * 1.5;

    // Mean-residual coupling.
    if residual < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score += 120.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 100.0 * progress;
        score += 10.0 * (open_bins_count as f64);
        if fitting_bins_count > 1 {
            score += 100.0 * (fitting_bins_count as f64 - 1.0);
        }
        score += 0.5 * mean_residual;
        if item_size < (bin_capacity / 2) {
            score += 12.0;
            if next_item_size > 0 && (next_item_size as f64) <= post {
                score += 20.0;
            }
        }
        // Huge items deserve fresh bins when residuals are small.
        if item > 0.8 * cap && mean_residual < item * 0.9 {
            score -= 200.0;
        }
        // Medium-large items late in stream when no open bin fits the next item.
        if item > 0.5 * cap && next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 120.0;
        }
    } else if open_bins_count > 3 && residual > 2.0 * mean_residual {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 define "dead space bands".
    let residue_class = post_residual % 10;
    // Harmonic penalty: residual in awkward bands (1..9) is less reusable than multiples of 10.
    let band_penalty = match residue_class {
        0 => -8.0,                       // perfectly harmonic residual
        1 | 2 | 3 => 6.0,                // tiny slivers, nearly dead
        4 | 5 | 6 => 2.0,                // mid slivers
        _ => 0.0,                        // 7..9: can host small items (1..7 range)
    };
    score += band_penalty;

    // Integer-division threshold: how many size-10 units fit in post_residual.
    let units = post_residual / 10;
    score -= (units as f64) * 3.0;       // reward residuals that hold multiple unit slots

    // Lookahead coupling: if next item fits in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 - slack * 0.15;    // prefer snug chain fit
    } else if next_item_size > 0 {
        score += 4.0;                    // chain broken
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // tie-break among fitting bins toward tighter fit (already via post_residual)
        score += (fitting_bins_count as f64 - 1.0) * 0.5;
    }

    // New-bin candidate handling: empty bin (residual == capacity).
    if bin_residual == bin_capacity {
        // Prefer new bin only when no open bin gives a decent fit, or stream is early
        // and many items remain (amortize a fresh bin).
        let progress = step_index as f64 / total_items.max(1) as f64;
        let decent_fit_exists = fitting_bins_count > 0 && (post_residual as f64) <= mean_residual * 0.5;
        if decent_fit_exists {
            score += 20.0;               // keep using existing decent bins
        } else {
            score -= 5.0 + 10.0 * (1.0 - progress);
        }
        // Cap new-bin attractiveness so it never beats an exact fit.
        if post_residual == 0 { score = score.min(-30.0); }
    }

    // Penalize wasting a large-capacity bin on a tiny item when many bins are open.
    if item_size < bin_capacity / 4 && post_residual > bin_capacity / 2 && bin_residual != bin_capacity {
        score += 5.0;
    }

    // Mild preference for bins below mean residual (consolidate fullness).
    score += ((post_residual as f64) - mean_residual).max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post * post / cap;

    // Exact fill is ideal
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 330.0 / post;
    } else if post_residual < 12 {
        score += 90.0 + (12 - post_residual) as f64 * 6.0;
    } else {
        score -= 15.0 * (post / cap);
        if post_residual >= 40 { score -= 9.0; }
        if post_residual < 30 { score += 7.5 * (30 - post_residual) as f64 / 18.0; }
    }

    // Penalize small dead space generally
    if post > 0.0 && post < 0.25 * cap {
        score += 30.0 * (1.0 - post / (0.25 * cap));
    }

    let dead = post / cap;

    // Lookahead: chain fit with next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let chain_tight = 1.0 - (post - nxt) / cap;
            score -= 52.0 * chain_tight;
            if post == nxt { score -= 68.0; }
            let slack = post - nxt;
            if slack <= 2.0 { score -= 14.0; }
            else if slack <= 6.0 { score -= 18.0; }
            if slack >= 1.0 && slack <= mean_residual * 0.5 { score -= 8.0; }
            if (slack as u32) == mean_residual as u32 { score -= 9.0; }
            if slack >= 1.0 && slack < 12.0 { score -= 4.0; }
            if post >= nxt + mean_residual { score -= 10.0; }
            if nxt <= post && post - nxt < 6.0 { score -= 18.0; }
            if post_residual > 0 && post_residual % 10 == 0 { score -= 5.0; }
        } else if post + 10.0 >= nxt {
            score += 6.0;
            if (nxt - post) as u32 <= 2 && fitting_bins_count > 1 { score += 15.0; }
        } else {
            score += 0.06 * (nxt - post);
        }
        // Next item would strand this residual
        if nxt > post && post_residual > 0 && post_residual < 20 {
            score += 12.0;
        }
        if nxt > post && post_residual > 0 && post_residual < (next_item_size / 2).max(1) {
            score += 6.0 * (1.0 - post_residual as f64 / (next_item_size / 2).max(1) as f64);
        }
        if post_residual > 0 && post_residual < 16 && nxt > post && (mean_residual as u32) > post_residual {
            score += 9.0 * (16 - post_residual) as f64 / 8.0;
        }
        // Dead-space ratio penalty when next item strands a mid residual
        if nxt > post && dead > 0.35 && post as f64 > mean_residual * 1.5 && fitting_bins_count > 3 {
            score += 10.0 * (dead - 0.35);
        }
        // Near-exact two-item chain
        if nxt <= post && (post - nxt) <= 2.0 && dead > 0.4 {
            score -= 9.0;
        }
        // Residual partially usable by next item
        if post_residual > 0 && nxt <= post && nxt > post_residual as f64 * 0.6 && post_residual <= 25 {
            score -= 13.0 * (1.0 - post_residual as f64 / 25.0);
        }
        // Stranded sliver with many open bins
        if post_residual > 0 && post_residual < item_size && nxt > post && open_bins_count > 3 {
            score += 8.0;
        }
    } else {
        score += post * 2.2;
    }

    // Sliver penalty when next item cannot use it
    if post_residual > 0 && post_residual < 8 && next_item_size > post_residual {
        score += 26.0;
    }

    // Last-chance bin: strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Many open bins: keep big residuals from hogging preference
    if fitting_bins_count > 4 && bin_residual != bin_capacity && post_residual > 30 {
        score += 3.0;
    }

    // Mean-residual relative comparison
    score -= 0.25 * (mean_residual - post);

    // Progress-aware fullness preference
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 8.0 * progress * (post / cap);

    // New-bin candidate: only open when open bins are truly poor
    if bin_residual == bin_capacity {
        score += 18.0;
        if open_bins_count > 6 && progress > 0.5 {
            score -= 6.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 4 {
            score += 40.0;
        }
        if next_item_size > 0 && post_residual >= item_size + next_item_size {
            score += 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space penalty: residuals below the minimum item size (1..~10)
    // are unusable; punish them super-linearly.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Reward very tight fits (post_residual near zero but still valid).
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 3 {
        score -= 12.0;
    }

    // Perfect-fit style reward when the next item could exactly fill the gap.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // mild reward if next item still fits after this placement
        score -= 2.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item cannot use the leftover: penalize proportionally
        score += (next_item_size as f64 - post_residual as f64).min(15.0) * 0.8;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, favor filling existing ones
    // (penalize new-bin candidate implicitly via subtracting here).
    score -= (open_bins_count as f64).ln() * 4.0;

    // Prefer bins whose residual is already below average (compact bins),
    // keeping large-residual bins available for future big items.
    let diff = mean_residual - bin_residual as f64;
    score += diff * 0.3;

    // Early in the stream, be more willing to keep bins flexible;
    // later, prioritize closing bins out (reward larger consumption).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (item_size as f64) * 0.2;

    // New-bin candidate: make it moderately attractive only when the item
    // is large and no open bin is a good fit.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score += 8.0 - (item_size as f64) * 0.1;
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        let _ = waste;
    }

    score
}

