    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 80.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; mildly penalize blocking.
            score += 30.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    } else if fitting_bins_count > 1 {
        // More competition: prefer bins where this item wastes least.
        score += 5.0 * (fitting_bins_count as f64).ln();
    }

    // Time horizon: early in stream, keep bins flexible (penalize low residual);
    // late in stream, prioritize closing bins out (reward tight fits more).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 0.3 * post_residual as f64;
    score -= progress * 50.0 * fill;

    // Global state: many open bins with high mean residual -> encourage consolidation.
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 20.0;
    }
    // Few open bins -> opening a new bin is cheap-ish; penalize cramming into residual.
    if open_bins_count <= 2 && post_residual > 0 && post_residual < item_size {
        score += 25.0;
    }

    // New-bin candidate calibration: empty bin gets a moderate baseline so it wins
    // only when existing bins would create bad fits.
    if bin_residual == bin_capacity {
        score += 60.0 - 40.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post * post / cap;

    // Perfect fit: overwhelming reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 330.0 / post;
    } else if post_residual < 12 {
        score += 90.0 + (12 - post_residual) as f64 * 6.0;
    } else {
        score -= 15.0 * (post / cap);
        if post_residual >= 40 { score -= 9.0; }
        if post_residual < 30 { score += 7.5 * (30 - post_residual) as f64 / 18.0; }
    }

    // Harmonic divisibility of leftover space
    let mut harmony = 0.0;
    if post_residual % 10 == 0 { harmony += 5.0; }
    if post_residual % 25 == 0 { harmony += 4.0; }
    if post_residual % 50 == 0 { harmony += 3.0; }
    score -= harmony;

    // Dead-space band: very small leftover relative to capacity
    if post > 0.0 && post < 0.25 * cap {
        score += 30.0 * (1.0 - post / (0.25 * cap));
    }

    // Lookahead: chain the next item into this bin
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let chain_tight = 1.0 - (post - nxt) / cap;
            score -= 52.0 * chain_tight;
            if post == nxt { score -= 68.0; }
            if post >= nxt + mean_residual { score -= 10.0; }
            if (post - nxt) <= mean_residual * 0.5 { score -= 8.0; }
            if post - nxt >= 1.0 && post - nxt <= 4.0 { score -= 12.0; }
            if post - nxt < 6.0 { score -= 18.0; }
            if (post - nxt) as u32 == mean_residual as u32 { score -= 9.0; }
            if post_residual % 10 == 0 { score -= 5.0; }
        } else if post + 10.0 >= nxt {
            score += 6.0;
        } else {
            score += 0.06 * (nxt - post);
            // stranded space: next item is much larger than leftover
            if (nxt - post) as u32 > 20 && post_residual < 20 { score += 12.0; }
            if post_residual < (next_item_size / 2).max(1) {
                score += 6.0 * (1.0 - post_residual as f64 / (next_item_size / 2).max(1) as f64);
            }
            if post_residual < item_size && open_bins_count > 3 { score += 8.0; }
        }
        // near-miss: almost fits, with alternatives available
        if nxt > post && (nxt - post) as u32 <= 2 && fitting_bins_count > 1 { score += 15.0; }
    } else {
        score += post * 2.2;
    }

    // Tiny slivers that the next item cannot use
    if post_residual > 0 && post_residual < 8 && next_item_size > post_residual { score += 26.0; }
    if post_residual > 0 && post_residual < 16 && next_item_size > post_residual && (mean_residual as u32) > post_residual {
        score += 9.0 * (16 - post_residual) as f64 / 8.0;
    }
    if post_residual > 0 && post_residual < 25 && next_item_size as f64 <= post
        && next_item_size as f64 > post_residual as f64 * 0.6 {
        score -= 13.0 * (1.0 - post_residual as f64 / 25.0);
    }

    // Last-chance bin: strong consolidation pressure
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Mild spreading when many bins and large usable leftovers
    if fitting_bins_count > 4 && bin_residual != bin_capacity && post_residual > 30 { score += 3.0; }

    // High-dead-space bin with above-mean leftover: defer to other bins
    let dead = post / cap;
    if post_residual > 0 && next_item_size as f64 > post && dead > 0.35
        && (post_residual as f64) > mean_residual * 1.5 && fitting_bins_count > 3 {
        score += 10.0 * (dead - 0.35);
    }
    if post_residual > 0 && next_item_size as f64 <= post && (post - next_item_size as f64) <= 2.0 && dead > 0.4 {
        score -= 9.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        score -= 20.0; // base cost of opening a bin
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * (1.0 - progress);
        if mean_residual < item_size as f64 && open_bins_count > 2 {
            score += 10.0;
        }
    }

    // Tightness pressure toward fuller bins
    let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
