pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of the post residual: classify dead space by capacity fractions.
    // Classes: [0..10) excellent, [10..25) good, [25..50) mediocre, [50..cap] wasteful.
    let class: f64 = if post_residual == 0 {
        -30.0
    } else if post_residual < 10 {
        -20.0
    } else if post_residual < 25 {
        -8.0
    } else if post_residual < 50 {
        6.0
    } else {
        18.0
    };
    score += class;

    // Modulo-style harmonic bonus: post_residual congruent to small values mod 10
    // means the leftover pairs well with the smallest item class.
    let r10 = post_residual % 10;
    if r10 == 0 {
        score -= 4.0;
    } else if r10 <= 3 {
        score -= 2.0;
    }

    // Lookahead: reward bins whose leftover can host the next item exactly or snugly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size as u32) as f64;
        score -= 12.0 - 8.0 * (slack / cap);
        if post_residual == next_item_size {
            score -= 10.0; // perfect pairing, zero waste
        }
    } else if next_item_size > 0 {
        // Next item cannot fit here: penalize proportionally to how much dead space we create.
        score += 6.0 * (post / cap);
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Prefer bins tighter than the current mean residual (best-fit flavor).
    score += 0.35 * (mean_residual - bin_residual as f64);

    // New-bin candidate: only attractive when the item is large relative to capacity
    // (leaving a useful large residual) and few fitting bins exist.
    if bin_residual == bin_capacity {
        let frac = post / cap;
        score = 40.0 - 30.0 * frac;
        if fitting_bins_count == 0 {
            score -= 25.0; // forced new bin
        }
        if fitting_bins_count == 1 {
            score += 10.0; // an existing bin is last chance; prefer it
        }
    }

    // Late in the stream, consolidate: slightly favor existing bins over spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 3.0 * progress;
    }

    score
}

