    let mut score = post_residual as f64;

    // Sharpen best-fit: prefer bins whose pre-fit residual was tight relative to capacity.
    let tightness = bin_residual as f64 / bin_capacity as f64;
    score *= 1.0 + 0.02 * tightness;

    // Lookahead reward: if the next item can also fit here, this placement is doubly efficient.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 0.5 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space: leftover too small for the upcoming item.
        score += 3.0;
    }

    // Last-chance bonus: this is the only open bin that fits; avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Penalize the brand-new-bin candidate mildly, scaled by how many bins are already open.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.05 * open_bins_count as f64;
    }

    // Global-state coupling: penalize bins whose residual deviates upward from the mean
