pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets (eighths of the bin) and reward "clean" classes.
    let eighth = bin_capacity as f64 / 8.0;
    let class = (post_residual as f64 / eighth).floor() as i32; // 0..8
    let class_bonus = match class {
        0 => -30.0, // near-perfect fill: residual < 1/8 capacity
        1 => -18.0,
        2 => -8.0,
        3 => 4.0,   // awkward mid-range dead space
        4 => 6.0,
        5 => 2.0,
        6 => -6.0,  // half-full-ish: still versatile
        7 => -12.0,
        _ => -20.0, // empty-ish bin, plenty of room
    };
    score += class_bonus;

    // Fine harmonic structure: modulo-10 classes of post_residual.
    // Small residues (0,1,2 mod 10) are hard to reuse; penalize them.
    let m = post_residual % 10;
    let mod_pen = match m {
        0 => -10.0,
        1 => 12.0,
        2 => 10.0,
        3 => 6.0,
        4 => 3.0,
        5 => -4.0, // half-of-ten residuals pair well with mid items
        6 => 2.0,
        7 => 4.0,
        8 => 8.0,
        _ => 9.0,
    };
    score += mod_pen as f64;

    // Integer-division threshold coupling between post_residual and next item.
    if next_item_size > 0 {
        let fits_next = (post_residual >= next_item_size) as i32;
        let next_class = next_item_size / 20; // 0..=4 harmonic tier of next item
        if fits_next == 1 {
            // Reward bins that can also host the next item, scaled by its tier.
            score -= 10.0 + 4.0 * next_class as f64;
            // Extra reward when post_residual is an exact harmonic multiple
            // relative to the next item (tight two-item packing).
            if post_residual == next_item_size {
                score -= 25.0;
            } else if post_residual % next_item_size.max(1) <= 2 {
                score -= 8.0;
            }
        } else {
            // Next item cannot follow here: penalize proportionally to wasted class.
            score += 8.0 + 3.0 * next_class as f64;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate handling: an empty bin should only win when all open
    // bins would leave ugly residuals. Compare against mean residual.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened late in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_cost = 55.0 - 15.0 * progress;
        // If existing bins are crowded (low mean residual), opening is cheaper.
        new_bin_cost -= (mean_residual / bin_capacity as f64) * 20.0;
        // If few bins can fit the item, new bin is more attractive.
        if fitting_bins_count <= 1 {
            new_bin_cost -= 30.0;
        }
        score = new_bin_cost + item_size as f64 * 0.1;
    }

    // Global tightness coupling: prefer filling bins below the current mean
    // residual (targets the emptiest / most fragmented bins).
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Mild stream-phase modulation: early on, keep bins flexible (favor larger
    // post_residual slightly); late, pack aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (post_residual as f64) * 0.08;
    score -= progress * (post_residual as f64) * 0.05;

    score
}

