pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post * post / cap; // quadratic pressure: big leftovers hurt more

    if post_residual == 0 {
        score -= 1000.0; // perfect fit dominates
    } else {
        // Harmony of the leftover space
        if post % 10 == 0 { score -= 12.0; }
        if post % 20 == 0 { score -= 8.0; }
        if post % 25 == 0 { score -= 8.0; }
        if post % 50 == 0 { score -= 6.0; }
        if post_residual < 10 {
            score += 330.0 / post; // dead sliver: strong penalty
        } else if post_residual <= 20 {
            score += 6.0; // marginal
        } else if post_residual < 40 {
            score -= 4.0; // useful band
        } else {
            score -= 9.0; // large leftover is still usable
        }
        // dead-space band under 25% of capacity
        if post < 0.25 * cap {
            score += 30.0 * (1.0 - post / (0.25 * cap));
        }
    }

    // Lookahead: reward if next item chains into the leftover
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let chain_tight = 1.0 - (post - nxt) / cap;
            score -= 52.0 * chain_tight;
            if post_residual == next_item_size { score -= 68.0; } // exact chain fill
            if post_residual % next_item_size == 0 { score -= 18.0; } // harmonic chain
            if (post_residual - next_item_size) % 10 == 0 { score -= 6.0; }
            if post_residual - next_item_size <= 4 { score -= 12.0; } // near-perfect chain
            if post >= nxt + mean_residual { score -= 10.0; }
            if (post - nxt) <= mean_residual * 0.5 { score -= 8.0; }
        } else {
            // next item won't fit here
            if post_residual > 0 && post_residual < 10 { score += 26.0; }
            if nxt - post <= 2.0 && fitting_bins_count > 1 { score += 15.0; }
            if nxt - post > 20.0 && post_residual < 20 { score += 12.0; }
            if post_residual < next_item_size / 2 {
                score += 6.0 * (1.0 - post_residual as f64 / (next_item_size / 2).max(1) as f64);
            }
        }
    } else {
        score += post * 2.2;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        score -= 20.0; // base cost of opening a bin
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * (1.0 - progress); // early: bins cheap; late: consolidate
        if mean_residual < item_size as f64 && open_bins_count > 2 {
            score += 10.0;
        }
        // many open bins with slack: prefer consolidating instead of new bin
        if open_bins_count > 5 && mean_residual > 0.4 * cap {
            score += 12.0;
        }
    } else {
        // tightness pressure toward fuller bins
        let tightness = 1.0 - (bin_residual as f64 / cap);
        score -= 10.0 * tightness;
        // many fitting bins means this choice matters less; slight penalty for sloppy fits
        if fitting_bins_count > 4 && post_residual > 30 {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that no future item can use are worthless.
    // Any gap below the smallest plausible item (1) is fully dead; gaps below the lookahead
    // item are likely dead too. Penalize them harshly and non-linearly.
    if post_residual > 0 {
        if post_residual < next_item_size.max(1) {
            // Gap cannot fit the very next item: likely dead space.
            score += 18.0 + 0.35 * post_residual as f64;
        }
        // Perfect fit is the ideal outcome.
        if post_residual == 0 {
            score -= 25.0;
        }
    }

    // Coupling with bin pressure: many open bins -> prefer filling existing ones,
    // discourage opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 1.4 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // If this bin is the last one that can fit the item, strongly prefer it
    // to avoid opening a fresh bin for a poorly-fitting item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when existing
    // bins are crowded (mean residual low) or the item simply fits poorly elsewhere.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, scaled by how many bins are already open.
        score += 22.0 + 2.0 * open_bins_count as f64;
        // If open bins are nearly full on average, a new bin is legitimate.
        score -= 0.25 * mean_residual;
        // Late in the stream, keep bins tight; new bins become more expensive.
        score += 10.0 * progress;
    } else {
        // Reward using a bin whose residual closely matches the item (tight fit).
        let tightness = (bin_residual as f64 - item_size as f64).abs();
        score += 0.12 * tightness;
        // Reward bins whose residual is above the mean (use the roomier ones first,
        // keeping small residuals as dead-space traps? No: prefer balanced usage).
        score -= 0.05 * (bin_residual as f64 - mean_residual);
    }

    // Lookahead: if the next item fits exactly in the post-residual, this is a great chain.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 10.0;
    }
    // If next item would be blocked by this placement, add mild penalty.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post * post / cap;

    // Perfect fit: overwhelming reward so oracle picks it
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        // tiny slivers are dead space: penalize proportionally
        score -= 330.0 / post;
    } else if post_residual < 12 {
        score += 90.0 + (12 - post_residual) as f64 * 6.0;
    } else {
        score -= 15.0 * (post / cap);
        if post_residual >= 40 { score -= 9.0; }
        if post_residual < 30 { score += 7.5 * (30 - post_residual) as f64 / 18.0; }
    }

    // Penalize small leftover band relative to capacity
    if post > 0.0 && post < 0.25 * cap {
        score += 30.0 * (1.0 - post / (0.25 * cap));
    }

    // Lookahead: reward leaving space the next item can use
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let chain_tight = 1.0 - (post - nxt) / cap;
            score -= 52.0 * chain_tight;
            if post == nxt { score -= 68.0; }
            if post >= nxt + mean_residual { score -= 10.0; }
            if post - nxt >= 1.0 && post - nxt <= 4.0 { score -= 12.0; }
            if post - nxt < 6.0 { score -= 18.0; }
            if post_residual % 10 == 0 { score -= 5.0; }
        } else if post + 10.0 >= nxt {
            score += 6.0;
        } else {
            score += 0.06 * (nxt - post);
        }
        // next item nearly fits: mildly penalize near-miss fits
        if nxt > post && (nxt - post) as u32 <= 2 && fitting_bins_count > 1 {
            score += 15.0;
        }
        // stranded small residual that next item cannot use
        if nxt > post && (nxt - post) as u32 > 20 && post_residual > 0 && post_residual < 20 {
            score += 12.0;
        }
        // dead-space penalty when residual too small for next item
        if post_residual > 0 && post_residual < 8 && nxt > post_residual {
            score += 26.0;
        }
        if post_residual > 0 && post_residual < 16 && nxt > post && (mean_residual as u32) > post_residual {
            score += 9.0 * (16 - post_residual) as f64 / 8.0;
        }
        // next item would leave an exact harmonic remainder
        if nxt <= post && (post - nxt) as u32 == mean_residual as u32 {
            score -= 9.0;
        }
        // residual less than half of next item: wasted space
        if post_residual > 0 && nxt > post && post_residual < (next_item_size / 2).max(1) {
            score += 6.0 * (1.0 - post_residual as f64 / (next_item_size / 2).max(1) as f64);
        }
    } else {
        score += post * 2.2;
    }

    // Last-chance bin: use it before opening new
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: cost of opening, cheaper early in stream
    if bin_residual == bin_capacity {
        score -= 20.0;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * (1.0 - progress);
        if mean_residual < item_size as f64 && open_bins_count > 2 {
            score += 10.0;
        }
        // crowded field with large residuals: consolidation preferred
        if post_residual > 0 && next_item_size as f64 > post && open_bins_count > 3 {
            score += 8.0;
        }
    }

    // Mild pressure toward tighter bins
    let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 10.0 * tightness;

    // Many fitting bins and large post-residual: discourage hoarding space
    if fitting_bins_count > 4 && bin_residual != bin_capacity && post_residual > 30 {
        score += 3.0;
    }

    // Dead-space ratio penalty when residual far exceeds mean
    let dead = post / cap;
    if post_residual > 0 && next_item_size as f64 > post && dead > 0.35
        && (post_residual as f64) > mean_residual * 1.5 && fitting_bins_count > 3 {
        score += 10.0 * (dead - 0.35);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Aggressive 2-step lookahead: reward when the next item exactly fills the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        if gap < 0.5 {
            // Perfect chain: next item consumes this bin completely.
            score -= 60.0;
        } else {
            // Penalize mismatch scaled by relative dead-space risk.
            score += gap * 0.8;
            // Extra penalty if next item cannot fit at all (leaves stranded space).
            if nxt > post {
                score += 15.0 + (nxt - post) * 0.3;
            }
        }
    } else {
        // Last item: tightest fit wins.
        score -= 10.0;
    }

    // Compare post residual against mean residual: leaving less than average is good.
    score -= (mean_residual - post) * 0.25;

    // Last-chance bin: strongly prefer using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize creating small unusable slivers (dead space < 10).
    if post > 0.0 && post < 10.0 {
        score += 20.0;
    }

    // Late in the stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post * 0.1 * progress;
    score -= open_bins_count as f64 * 0.05;

    // New-bin candidate: neutral baseline, only chosen when open bins score poorly.
    if bin_residual == bin_capacity {
        score += 30.0 + post * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    // Quadratic residual core: strongly prefer small leftovers
    let mut score = post * post / cap;

    let post_u = post_residual;
    let mut harmony_bonus = 0.0;

    if post_u == 0 {
        harmony_bonus += 1000.0; // perfect fit dominates everything
    } else if post_u <= 5 {
        // tiny slivers: reward proportionally (dead space is nearly full)
        harmony_bonus += 330.0 / post as f64;
    } else if post_u < 12 {
        harmony_bonus -= 90.0 + (12 - post_u) as f64 * 6.0; // marginal band penalty
    } else {
        // usable band: mild reward scaled to how large the leftover is
        harmony_bonus += 15.0 * (post / cap);
        if post_u >= 40 { harmony_bonus += 9.0; }
        if post_u < 30 { harmony_bonus -= 7.5 * (30 - post_u) as f64 / 18.0; }
        if post_u % 10 == 0 { harmony_bonus += 5.0; }
        if post_u % 25 == 0 { harmony_bonus += 3.0; }
    }

    // Lookahead: next item fits into post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let chain_tight = 1.0 - (post - nxt) / cap;
            harmony_bonus += 52.0 * chain_tight;
            if post_u == next_item_size { harmony_bonus += 68.0; }
            if post as f64 >= nxt + mean_residual { harmony_bonus += 10.0; }
            let gap = post - nxt;
            if gap >= 1.0 && gap <= 4.0 { harmony_bonus += 12.0; }
            if gap < 6.0 { harmony_bonus += 18.0; }
            if gap as u32 == mean_residual as u32 { harmony_bonus += 9.0; }
        } else {
            // next item won't fit here
            if post + 10.0 >= nxt {
                harmony_bonus -= 6.0; // near miss: bin nearly saturated anyway
            } else {
                harmony_bonus -= 0.06 * (nxt - post);
            }
            if (nxt - post) as u32 <= 2 && fitting_bins_count > 1 { harmony_bonus -= 15.0; }
            if (nxt - post) as u32 > 20 && post_u > 0 && post_u < 20 { harmony_bonus -= 12.0; }
        }
    } else {
        harmony_bonus -= post * 2.2;
    }

    // Dead sliver that next item cannot use: penalize choosing this bin
    if post_u > 0 && post_u < 8 && next_item_size > post_u {
        harmony_bonus -= 26.0;
    }
    if post_u > 0 && post_u < 16 && next_item_size > post_u && (mean_residual as u32) > post_u {
        harmony_bonus -= 9.0 * (16 - post_u) as f64 / 8.0;
    }
    // Next item consumes most of a small leftover: excellent chaining
    if post_u > 0 && next_item_size as f64 <= post
        && next_item_size as f64 > post as f64 * 0.6 && post_u <= 25 {
        harmony_bonus += 13.0 * (1.0 - post as f64 / 25.0);
    }
    // Stranded space when many bins open and next item won't fit
    if post_u > 0 && post_u < item_size && next_item_size as f64 > post && open_bins_count > 3 {
        harmony_bonus -= 8.0;
    }
    if post_u > 0 && next_item_size as f64 > post && post_u < (next_item_size / 2) {
        harmony_bonus -= 6.0 * (1.0 - post_u as f64 / (next_item_size / 2).max(1) as f64);
    }
    // Fragmented state: leftover much larger than mean residual and next item skips it
    if post_u > 0 && next_item_size as f64 > post && (post / cap) > 0.35
        && post as f64 > mean_residual * 1.5 && fitting_bins_count > 3 {
        harmony_bonus -= 10.0 * ((post / cap) - 0.35);
    }
    // Near-perfect chain into a large leftover
    if next_item_size as f64 <= post && (post - next_item_size as f64) <= 2.0 && (post / cap) > 0.4 {
        harmony_bonus += 9.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        harmony_bonus += 15.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is bad
    if bin_residual == bin_capacity {
        harmony_bonus -= 20.0;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        harmony_bonus += 15.0 * (1.0 - progress);
        if mean_residual < item_size as f64 && open_bins_count > 2 {
            harmony_bonus += 10.0;
        }
    }

    // Mild pressure toward tighter bins overall
    let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 10.0 * tightness;

    score -= harmony_bonus;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post_residual non-linearly.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        let frac = post_residual as f64 / bin_capacity as f64;
        score += frac * frac * 40.0;
    }

    // Penalize very small dead space thresholds that likely waste space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits in post_residual, strong bonus.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 30.0 + 0.3 * next_item_size as f64;
        } else {
            // Dead space relative to next item's needs.
            score += 0.15 * (next_item_size as f64 - post_residual as f64).max(0.0);
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    let open_pressure = open_bins_count as f64 / (1.0 + total_items as f64).ln().max(1.0);
    if bin_residual < bin_capacity {
        score -= open_pressure * 8.0;
    }

    // Compare residual to mean residual: prefer bins tighter than average.
    score += 0.4 * (bin_residual as f64 - mean_residual);

    // Time horizon: early in stream, allow opening new bins (penalize tight bins less);
    // late in stream, squeeze everything into open bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // New bin candidate: attractive early, expensive later.
        score += 55.0 * progress - 20.0 * (1.0 - progress);
        // A new bin is fine if no open bin fits well.
        if fitting_bins_count == 0 {
            score -= 70.0;
        }
    } else {
        score -= 25.0 * progress;
    }

    // Mild reward for placing large items into already-open bins.
    score -= 0.05 * item_size as f64;

    score
}

