pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr_norm = pr / cap;
    let fit = item_size as f64 / cap;
    let nxt = next_item_size as f64 / cap;

    // base: prefer small post-residual (best fit), non-linearly
    let mut score = 10.0 * pr_norm.powf(1.8);

    // smooth progress coupling: tighter packing valued more later in stream
    score += 6.0 * pr_norm * pr_norm * (progress * (1.0 - progress) * 4.0 + 0.5);

    // reward leaving room for the lookahead item (smooth interaction)
    let room = (nxt - pr_norm).max(0.0);
    score -= 4.0 * (1.0 - room.min(1.0)).powi(2) * if next_item_size > 0 { 1.0 } else { 0.0 };

    // penalize near-empty usage of an existing bin (wasteful) smoothly
    score += 3.0 * fit * fit * (1.0 - pr_norm);

    // last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // new-bin candidate handling: only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        let crowd = (open_bins_count as f64).max(1.0);
        score = 12.0 + mean_residual / cap * 5.0 - 4.0 / crowd.sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let residual = bin_residual as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post * post / cap;

    // Perfect / near-perfect fit rewards.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 330.0 / post;
    } else if post_residual < 12 {
        score += 90.0 + (12 - post_residual) as f64 * 6.0;
    } else {
        score -= 15.0 * (post / cap);
        if post_residual >= 40 {
            score -= 9.0;
        }
        // Dead-space ramp: residuals just under 30 are hard to reuse.
        if post_residual < 30 {
            score += 7.5 * (30 - post_residual) as f64 / 18.0;
        }
    }

    // Tightness coupling.
    let fill_ratio = item / residual.max(1.0);
    score -= 24.0 * fill_ratio;

    // Fragmentation penalty for small residuals.
    if post > 0.0 && post < 0.25 * cap {
        score += 30.0 * (1.0 - post / (0.25 * cap));
    }

    // Lookahead chain-fit bonus.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let chain_tight = 1.0 - (post - nxt) / cap;
            score -= 52.0 * chain_tight;
            if post == nxt {
                score -= 68.0;
            }
            if post - nxt < 6.0 {
                score -= 18.0;
            }
            if post >= nxt + mean_residual {
                score -= 10.0;
            }
            if (post - nxt) as u32 == mean_residual as u32 {
                score -= 9.0;
            }
            if post >= nxt && (post - nxt) <= mean_residual * 0.5 {
                score -= 8.0;
            }
            if post - nxt >= 1.0 && post - nxt <= 4.0 {
                score -= 12.0;
            }
        } else if post + 10.0 >= nxt {
            score += 6.0;
        } else {
            score += 0.06 * (nxt - post);
        }
        // Next item nearly fits: penalize leaving a barely-too-small gap.
        if nxt > post && (nxt - post) as u32 <= 2 && fitting_bins_count > 1 {
            score += 15.0;
        }
        if nxt > post && (nxt - post) as u32 > 20 && post_residual > 0 && post_residual < 20 {
            score += 12.0;
        }
    } else {
        score += post * 2.2;
    }

    // Dead-space penalty: residual too small for the next item.
    if post_residual > 0 && post_residual < 8 && next_item_size > post_residual {
        score += 26.0;
    }
    if post_residual > 0 && post_residual < 16 && next_item_size > post_residual && (mean_residual as u32) > post_residual {
        score += 9.0 * (16 - post_residual) as f64 / 8.0;
    }

    // Semi-fit lookahead: next item fits within a fraction of the post residual.
    if post_residual > 0 && next_item_size as f64 <= post && next_item_size as f64 > post_residual as f64 * 0.6 && post_residual <= 25 {
        score -= 13.0 * (1.0 - post_residual as f64 / 25.0);
    }
    // Residual too small for item and next item won't fit either: discourage.
    if post_residual > 0 && post_residual < item_size && next_item_size as f64 > post && open_bins_count > 3 {
        score += 8.0;
    }
    if post_residual > 0 && next_item_size as f64 > post && post_residual < (next_item_size / 2) {
        score += 6.0 * (1.0 - post_residual as f64 / (next_item_size / 2).max(1) as f64);
    }
    if post_residual > 0 && post_residual % 10 == 0 && next_item_size as f64 <= post {
        score -= 5.0;
    }
    let dead = post / cap;
    if post_residual > 0 && next_item_size as f64 > post && dead > 0.35 && (post_residual as f64) > mean_residual * 1.5 && fitting_bins_count > 3 {
        score += 10.0 * (dead - 0.35);
    }
    if post_residual > 0 && next_item_size as f64 <= post && (post - next_item_size as f64) <= 2.0 && dead > 0.4 {
        score -= 9.0;
    }
    if fitting_bins_count > 4 && bin_residual != bin_capacity && post_residual > 30 {
        score += 3.0;
    }

    // Two-item lookahead: post residual can hold next item and leave a slot
    // still usable by a small follow-up — strong chain bonus.
    if post_residual > 0 && next_item_size > 0 {
        let after_next = post - next_item_size as f64;
        if after_next >= 1.0 && after_next < 10.0 {
            score -= 7.0;
        }
    }

    // Last-chance pressure.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    } else if fitting_bins_count <= 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Consolidation pressure.
    score += (open_bins_count as f64) * 1.5;

    // Mean-residual coupling.
    if residual < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score += 120.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 100.0 * progress;
        score += 10.0 * (open_bins_count as f64);
        if fitting_bins_count > 1 {
            score += 100.0 * (fitting_bins_count as f64 - 1.0);
        }
        score += 0.5 * mean_residual;
        if item_size < (bin_capacity / 2) {
            score += 12.0;
            if next_item_size > 0 && (next_item_size as f64) <= post {
                score += 20.0;
            }
        }
        // Huge items deserve fresh bins when residuals are small.
        if item > 0.8 * cap && mean_residual < item * 0.9 {
            score -= 200.0;
        }
        // Medium-large items late in stream when no open bin fits the next item.
        if item > 0.5 * cap && next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 120.0;
        }
        // Fresh-bin bonus when the item would leave a tiny unusable gap in
        // every open bin (poor-fit avoidance): allow opening a new bin.
        let best_gap = if fitting_bins_count > 0 { 1 } else { 0 };
        if best_gap == 0 && item <= 0.5 * cap && next_item_size > 0 && (next_item_size as f64) > mean_residual * 1.2 {
            score -= 60.0;
        }
    } else if open_bins_count > 3 && residual > 2.0 * mean_residual {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: multiples of 10 are "clean" residuals,
    // odd/prime-ish leftovers are dead-space prone.
    let pr = post_residual;
    let class_mod = pr % 10;
    score -= match class_mod {
        0 => 12.0,                     // perfectly harmonic residual
        5 => 4.0,                      // half-harmonic
        2 | 4 | 6 | 8 => 0.0,          // even, moderate
        _ => 6.0,                      // odd residue, likely dead space
    };

    // Integer-division thresholds: tiny unusable slivers are heavily penalized.
    if pr > 0 && pr < 10 {
        score += 30.0;
    }

    // Lookahead coupling: exact or near-exact match with next item is gold.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            let gap = pr - next_item_size;
            score -= 15.0 * (1.0 - gap as f64 / 50.0);
        } else {
            // next item cannot use this residual: slight penalty scaled by overflow
            let over = (next_item_size - pr) as f64;
            score += 2.0 * (over / 50.0).min(1.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: prefer opening a new bin only when the best
    // existing fit would leave a badly fragmented residual, or when few bins
    // are open (early stream, keep packing tight).
    if bin_residual == bin_capacity {
        // Neutral-ish baseline: harmonic discount so it wins over fragmented bins
        // but loses to bins that keep harmonic structure.
        score = 55.0 + class_mod as f64;
        if open_bins_count > 6 {
            score -= 8.0; // many bins open: consolidation preferred
        }
        if pr == 0 {
            score -= 5.0; // item exactly fills a fresh bin
        }
    }

    // Tightness reward: filling most of the bin is always good.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Stream progression: later in stream, prefer compacting into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (bin_residual < bin_capacity) as i32 as f64;

    // Mean residual coupling: if this bin is far below mean residual, it is
    // already fragmented; deprioritize it.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

