            score += 6.0 * (1.0 - post_residual as f64 / (next_item_size / 2).max(1) as f64);
        }
        if post_residual > 0 && post_residual < 16 && nxt > post && (mean_residual as u32) > post_residual {
            score += 9.0 * (16 - post_residual) as f64 / 8.0;
        }
        // Dead-space ratio penalty when next item strands a mid residual
        let dead = post / cap;
        if nxt > post && dead > 0.35 && post as f64 > mean_residual * 1.5 && fitting_bins_count > 3 {
            score += 10.0 * (dead - 0.35);
        }
        // Near-exact two-item chain: residual fits both item and next tightly
        if nxt <= post && (post - nxt) <= 2.0 && dead > 0.4 {
            score -= 9.0;
        }
        // Residual just below next item: near-miss penalty scaled
        if nxt > post && post_residual > 0 && post_residual <= 25 && nxt > post_residual as f64 * 0.6 {
            score += 13.0 * (1.0 - post_residual as f64 / 25.0);
        }
        // Residual a multiple of 10 is likely reusable
        if post_residual > 0 && post_residual % 10 == 0 && nxt <= post {
            score -= 5.0;
        }
    } else {
        score += post * 2.2;
    }

    // Sliver penalty when next item cannot use it
    if post_residual > 0 && post_residual < 8 && next_item_size > post_residual {
        score += 26.0;
    }

    // Last-chance bin: strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Many open bins: keep big residuals from hogging preference
    if fitting_bins_count > 4 && bin_residual != bin_capacity && post_residual > 30 {
        score += 3.0;
    }

    // Mean-residual relative comparison
    score -= 0.25 * (mean_residual - post);

    // Progress-aware fullness preference
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 8.0 * progress * (post / cap);

    // New-bin candidate: only open when open bins are truly poor
    if bin_residual == bin_capacity {
        score += 18.0;
        if open_bins_count > 6 && progress > 0.5 {
            score -= 6.0;
        }
        if open_bins_count > 3 && post_residual > 0 && next_item_size as f64 > post && post_residual < item_size {
            score += 8.0;
        }
        // Don't open a new bin when some open bin gives a near-exact fit
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size as u32 <= 4 {
            score += 40.0;
        }
        // Avoid opening new bins when an open bin can chain both current and next items
        if next_item_size > 0 && post_residual >= item_size + next_item_size {
            score += 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    // A residual that cannot fit even the smallest plausible item (<= 10)
    // is pure waste; a residual just below the next item is also suspect.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 25.0; // unusable dead space
        } else if next_item_size > 0 && post_residual < next_item_size {
            score += 8.0; // gap too small for the lookahead item
        } else {
            score -= 3.0; // gap remains usable
        }
    } else {
        score -= 12.0; // perfect fit: eliminate a bin entirely
    }

    // Reward filling bins tightly (large item relative to residual).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio;

    // Open-bin pressure: with many open bins, favor consolidating into
    // existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = open_bins_count as f64 / (1.0 + progress);
    score += 0.05 * bin_pressure;

    // New-bin candidate handling: opening a bin is only attractive when
    // no open bin fits well (last chance) or the item is large.
    if bin_residual == bin_capacity {
        let last_chance = fitting_bins_count == 1;
        let big_item = item_size >= 60;
        if last_chance || big_item {
            score -= 20.0; // allow opening a fresh bin
        } else {
            score += 30.0; // strongly prefer existing bins
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Mean-residual coupling: prefer bins whose residual is near the mean
    // (balanced packing) when mean residual is small.
    if mean_residual < 30.0 {
        score += (post_residual as f64 - mean_residual).abs() * 0.2;
    }

    score
}

