pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: post_residual close to 0 is great.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post-residual,
    // this placement is highly desirable (bin gets perfectly filled in two steps).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if post == next {
            score -= 35.0;
        } else if next <= post && post - next <= 10.0 {
            score -= (10.0 - (post - next)) * 2.0;
        } else if next > post {
            // Next item won't fit here; penalize proportionally to the wasted gap,
            // unless the residual is small enough to be near-dead anyway.
            let gap = next - post;
            if post >= 10.0 {
                score += gap * 0.6;
            } else {
                // Small residual is already near-dead space; mild penalty only.
                score += gap * 0.1;
            }
        }
    }

    // Penalize creating large dead space relative to mean residual across bins.
    let post_f = post_residual as f64;
    if post_f > mean_residual + 15.0 {
        score += (post_f - mean_residual - 15.0) * 0.8;
    } else if post_f < mean_residual - 15.0 {
        // Keeping this bin tighter than average is good (balance preservation).
        score -= (mean_residual - 15.0 - post_f) * 0.3;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 20.0;
        // If several open bins could fit, opening a new bin is wasteful.
        if fitting_bins_count > 2 {
            score += 25.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
        }
        // Early in the stream, opening bins is cheaper (few bins to manage).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 10.0;
        // If next item is large and current item is small, a fresh bin wastes capacity.
        if next_item_size > 0 && next_item_size as f64 > item_size as f64 * 1.5 {
            score += 15.0;
        }
    }

    // Mild preference to fill bins with larger residual (consolidation) when many bins open.
    if open_bins_count > 8 {
        score += (bin_residual as f64) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit), scaled.
    score = post_residual as f64 * 1.0;

    // Perfect fit bonus.
