        score -= 1000.0;
    }

    // Lookahead: reward if next item fits exactly in the post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_tightness = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - next_tightness / bin_capacity as f64);
