            if post_residual == next_item_size {
                score -= 250.0;
            }
        } else {
            // Penalize leaving dead space too small for the next item.
            score += 25.0;
        }
    }

    // Relative fit quality: fraction of bin consumed by this item.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 80.0 * fill_ratio;

    // Penalize creating residual that is small but nonzero (hard-to-use slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 90.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 30.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        // Neutral-ish baseline; encourage using open bins when mean residual is tight.
        score = 45.0 + mean_residual * 0.4;
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative, must open
        }
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 40.0 * (1.0 - progress);
    }

    // Global state: if many open bins with large mean residual, prefer consolidating
    // into bins with below-average residual (i.e., tighter bins).
    if bin_residual != bin_capacity && open_bins_count > 1 {
        let diff = bin_residual as f64 - mean_residual;
        score += 0.15 * diff;
    }

    score
}

