            if slack >= 1.0 && slack <= mean_residual * 0.5 { score -= 8.0; }
            if (slack as u32) == mean_residual as u32 { score -= 9.0; }
            if slack >= 1.0 && slack < 12.0 { score -= 4.0; }
        } else if post + 10.0 >= nxt {
            score += 6.0;
            if (nxt - post) as u32 <= 2 && fitting_bins_count > 1 { score += 15.0; }
        } else {
            score += 0.06 * (nxt - post);
        }
        // Next item would strand this residual
        if nxt > post && post_residual > 0 && post_residual < 20 {
            score += 12.0;
        }
        if nxt > post && post_residual > 0 && post_residual < (next_item_size / 2).max(1) {
            score += 6.0 * (1.0 - post_residual as f64 / (next_item_size / 2).max(1) as f64);
        }
        if post_residual > 0 && post_residual < 16 && nxt > post && (mean_residual as u32) > post_residual {
            score += 9.0 * (16 - post_residual) as f64 / 8.0;
        }
        // Dead-space ratio penalty when next item strands a mid residual
        let dead = post / cap;
        if nxt > post && dead > 0.35 && post as f64 > mean_residual * 1.5 && fitting_bins_count > 3 {
            score += 10.0 * (dead - 0.35);
        }
        // Near-exact two-item chain
        if nxt <= post && (post - nxt) <= 2.0 && dead > 0.4 {
            score -= 9.0;
        }
        // Borrowed from best: strand penalty for large gaps
        if nxt > post && (nxt - post) as u32 > 20 && post_residual > 0 && post_residual < 20 {
            score += 12.0;
        }
        // Borrowed: mid residual that next item nearly consumes
        if post_residual > 0 && nxt <= post && nxt > post_residual as f64 * 0.6 && post_residual <= 25 {
            score -= 13.0 * (1.0 - post_residual as f64 / 25.0);
        }
        // Borrowed: avoid stranding small residuals in crowded state
        if post_residual > 0 && post_residual < item_size && nxt > post && open_bins_count > 3 {
            score += 8.0;
        }
        // Borrowed: even residual bonus when chainable
        if post_residual > 0 && post_residual % 10 == 0 && nxt <= post {
            score -= 5.0;
        }
    } else {
        score += post * 2.2;
    }

    // Sliver penalty when next item cannot use it
    if post_residual > 0 && post_residual < 8 && next_item_size > post_residual {
        score += 26.0;
    }

    // Last-chance bin: strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Many open bins: keep big residuals from hogging preference
    if fitting_bins_count > 4 && bin_residual != bin_capacity && post_residual > 30 {
        score += 3.0;
    }

    // Mean-residual relative comparison
    score -= 0.25 * (mean_residual - post);

    // Progress-aware fullness preference
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 8.0 * progress * (post / cap);

    // New-bin candidate: only open when open bins are truly poor
    if bin_residual == bin_capacity {
        score += 18.0;
        if open_bins_count > 6 && progress > 0.5 {
            score -= 6.0;
        }
        // Don't open a new bin when some open bin gives a near-exact fit
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size as u32 <= 4 {
            score += 40.0;
        }
        // Avoid opening new bins when an open bin can chain both current and next items
        if next_item_size > 0 && post_residual >= item_size + next_item_size {
            score += 25.0;
        }
        // Borrowed: don't open when any open bin fits with small slack
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size as u32 <= mean_residual as u32 {
            score += 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-classes of capacity
    let pr = post_residual;
    let class = pr % 25; // quarter-capacity harmonic class
    let quarter = bin_capacity / 4;

    // Perfect-fit class: post_residual == 0 is ideal
    if pr == 0 {
        score -= 60.0;
    } else if pr <= 10 {
        // tiny dead space is nearly perfect
        score -= 25.0;
    } else if pr >= quarter && pr < 2 * quarter {
        // mid-range residual: worst class, hard to fill later
        score += 18.0;
    } else if pr >= 2 * quarter && pr < 3 * quarter {
        score += 4.0;
    }

    // Bonus if next item fits exactly in the post residual (pairing)
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here: slight penalty proportional to overflow gap
            score += 6.0 * ((next_item_size - pr) as f64 / cap);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when fit here is bad and many bins open
    if bin_residual == bin_capacity {
        let fit_quality = item_size as f64 / cap;
        // penalize opening a new bin generally, more when many bins are open
        score += 30.0 + 4.0 * open_bins_count as f64;
        // but if item is large and current bin would leave a bad mid-class residual, ease it
        if pr >= quarter && pr < 2 * quarter {
            score -= 40.0 * fit_quality;
        }
    }

    // Early in stream: be a bit more willing to spread (mild new-bin tolerance)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 5.0;

    // Coupling with mean residual: avoid dumping into bins that deviate badly
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // future item (min size 1, but practically small gaps waste space)
    // are heavily penalized. Small-but-nonzero gaps are the worst.
    if post_residual > 0 {
        // penalize tiny unusable gaps super-linearly
        let gap = post_residual as f64;
        if gap < 10.0 {
            score += (10.0 - gap) * 8.0; // dead space penalty
        }
    } else {
        // perfect fit: strong reward
        score -= 50.0;
    }

    // Reward leaving room for the lookahead item (good chain fit)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // leftover can't host the next item: mild penalty
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // prefer tight packing into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate handling: opening a new bin is only attractive
    // when the item fits very poorly anywhere else. Give the empty bin
    // a baseline cost so it wins only over bad fits.
    if bin_residual == bin_capacity {
        score += 25.0 + mean_residual * 0.3;
    } else {
        // reward bins whose residual is close to the item (tight fit)
        let tightness = (bin_residual as f64 - item_size as f64).abs();
        score += tightness * 0.1;
    }

    // Prefer bins with below-mean residual (consolidate fuller bins)
    if bin_residual != bin_capacity {
        score += (bin_residual as f64 - mean_residual) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
