            score -= 200.0;
        } else {
            // Smooth penalty growing with mismatch, scaled by next item size.
            let norm = diff / (next_item_size as f64 + 1.0);
            score += norm * 40.0;
            // If next item still fits after this placement, mild reward.
            if post_residual >= next_item_size {
                score -= 15.0;
            }
        }
    }

    // Relative-to-mean coupling: prefer bins whose residual is tighter than average.
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // Penalize creating small unusable dead space (< 10, assuming min item 1..100 -> use small threshold).
    if post_residual > 0 && post_residual < 5 {
        score += 60.0;
    }

    // Slight preference to fill fuller bins as the stream progresses.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score -= (bin_capacity - bin_residual) as f64 * (0.1 + 0.2 * progress);

    // Mild penalty for spreading across many open bins with a new bin.
    if bin_residual == bin_capacity {
        score += 25.0 + 5.0 * open_bins_count as f64;
