    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: bucket by capacity fractions ---
    // Dead-space classes: residual <= 10 is "perfect-ish", 11..=20 good,
    // mid-range (21..=50) is where waste lives, >50 keeps future options.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect closure
    } else if pr <= 10 {
        score -= 35.0;
    } else if pr <= 20 {
        score -= 18.0;
    } else if pr <= 50 {
        // penalize mid-range leftovers, especially "just below half"
        score += 12.0 + (50 - pr) as f64 * 0.3;
    } else {
        // large residual is reusable, but slightly worse than a tight fit
        score -= 4.0;
    }

    // --- Modulo arithmetic on post_residual: small mod classes are classic dead zones ---
    if pr > 0 && pr < bin_capacity {
        let m = pr % 10;
        if m == 1 || m == 2 || m == 9 {
            score += 6.0; // awkward slivers
        } else if m == 0 {
            score -= 5.0; // round residual, easy future fits
        }
    }

    // --- Lookahead coupling: does next_item_size fit the post_residual? ---
    if next_item_size > 0 {
        if next_item_size <= pr {
            // this bin can also host the next item: strong reward
            score -= 14.0;
            // harmonic class match: next item lands on a round class
            if pr % 10 == 0 || next_item_size % 10 == 0 {
                score -= 6.0;
            }
        } else {
            // post_residual unusable for next item: penalize proportionally
            score += (next_item_size - pr) as f64 * 0.25;
        }
    }

    // --- Last-chance logic: only this bin fits the item ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0; // strongly prefer using the last fitting bin
    }

    // --- Prefer bins tighter than the mean residual (best-fit flavor) ---
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= (mean_residual - res_f) * 0.2;
    } else {
        score += (res_f - mean_residual) * 0.1;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive if existing bins fit badly
        // (large post_residual elsewhere) or stream is late and bins are many.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 55.0 + item_size as f64 * 0.5 - progress * 10.0;
        if next_item_size > 0 && next_item_size > mean_residual {
            score -= 15.0; // no open bin likely fits next item either
        }
    }

    // --- Mild penalty for hoarding many open bins ---
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
