    let mut score = post_residual as f64;

    // Base preference: tighter fit (smaller post_residual) is already favored.

    // 2-step lookahead: reward bins where the NEXT item also fits the leftover.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain fit: strongly reward proportionally to how snugly next item fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot follow here: penalize proportional to wasted potential.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    }

    // Penalize dead space relative to mean residual across open bins.
    let post_f = post_residual as f64;
    if post_f > mean_residual {
        score += 0.25 * (post_f - mean_residual);
    } else {
        score -= 0.10 * (mean_residual - post_f);
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Prefer keeping the number of open bins low when few bins exist.
    if open_bins_count > 0 {
        score -= 2.0 / open_bins_count as f64;
    }

    // New-bin candidate: only attractive when item is huge relative to typical residuals.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        // Open a new bin only if existing bins are quite full (low mean residual).
        score += 40.0 * (1.0 - pressure);
        // Discourage opening bins early in the stream.
        score += 5.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin can chain the next item too
        }
    }

    // Mild reward for filling bins that were already mostly full.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fill_ratio.min(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post * post / cap;

    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 330.0 / post;
    } else if post_residual < 12 {
        score += 90.0 + (12 - post_residual) as f64 * 6.0;
    } else {
        score -= 15.0 * (post / cap);
        if post_residual >= 40 {
            score -= 9.0;
        }
        if post_residual < 30 {
            score += 7.5 * (30 - post_residual) as f64 / 18.0;
        }
    }

    // Sliver penalty: small nonzero residuals are hard to reuse.
    if post > 0.0 && post < 0.25 * cap {
        score += 30.0 * (1.0 - post / (0.25 * cap));
    }

    // Lookahead: reward chains where the next item fits.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let chain_tight = 1.0 - (post - nxt) / cap;
            score -= 52.0 * chain_tight;
            if post == nxt {
                score -= 68.0;
            }
            if post >= nxt + mean_residual {
                score -= 10.0;
            }
            if (post - nxt) <= mean_residual * 0.5 {
                score -= 8.0;
            }
            if post - nxt >= 1.0 && post - nxt <= 4.0 {
                score -= 12.0;
            }
        } else if post + 10.0 >= nxt {
            score += 6.0;
        } else {
            score += 0.06 * (nxt - post);
        }
        if nxt <= post && post - nxt < 6.0 {
            score -= 18.0;
        }
        if nxt > post && (nxt - post) as u32 <= 2 && fitting_bins_count > 1 {
            score += 15.0;
        }
        if nxt > post && (nxt - post) as u32 > 20 && post_residual > 0 && post_residual < 20 {
            score += 12.0;
        }
    } else {
        score += post * 2.2;
    }

    // Dead-space shaping relative to the next item.
    if post_residual > 0 && post_residual < 8 && next_item_size > post_residual {
        score += 26.0;
    }
    if post_residual > 0 && post_residual < 16 && next_item_size > post_residual && (mean_residual as u32) > post_residual {
        score += 9.0 * (16 - post_residual) as f64 / 8.0;
    }
    if post_residual > 0 && next_item_size as f64 <= post && next_item_size as f64 > post_residual as f64 * 0.6 && post_residual <= 25 {
        score -= 13.0 * (1.0 - post_residual as f64 / 25.0);
    }
    if post_residual > 0 && post_residual < item_size && next_item_size as f64 > post && open_bins_count > 3 {
        score += 8.0;
    }
    if post_residual > 0 && next_item_size as f64 > post && post_residual < (next_item_size / 2) {
        score += 6.0 * (1.0 - post_residual as f64 / (next_item_size / 2).max(1) as f64);
    }
    if post_residual > 0 && post_residual % 10 == 0 && next_item_size as f64 <= post {
        score -= 5.0;
    }
    let dead = post / cap;
    if post_residual > 0 && next_item_size as f64 > post && dead > 0.35 && post_residual as f64 > mean_residual * 1.5 && fitting_bins_count > 3 {
        score += 10.0 * (dead - 0.35);
    }
    if post_residual > 0 && next_item_size as f64 <= post && (post - next_item_size as f64) <= 2.0 && dead > 0.4 {
        score -= 9.0;
    }
    if post_residual > 0 && next_item_size as f64 <= post && (post - next_item_size as f64) <= 12.0 && (post - next_item_size as f64) <= mean_residual * 1.2 {
        score -= 7.0 * (1.0 - (post - next_item_size as f64) / 12.0);
    }
    if post_residual > 0 && next_item_size > post_residual && post_residual >= (next_item_size * 3 / 4) && post_residual < next_item_size {
        score += 5.0 * (post_residual as f64 - next_item_size as f64 * 0.75) / (next_item_size as f64 * 0.25).max(1.0);
    }

    // Last-chance: only fitting open bin — keep item out of a fresh bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate gating: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        score = 45.0 + mean_residual * 0.4;
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 40.0 * (1.0 - progress);
        // Late in the stream, avoid opening bins when decent fits exist.
        if progress > 0.7 && fitting_bins_count > 0 && mean_residual < item_size as f64 * 2.0 {
            score += 30.0;
        }
    }

    // Consolidation: prefer tighter-than-average bins when many are open.
    if bin_residual != bin_capacity && open_bins_count > 1 {
        let diff = bin_residual as f64 - mean_residual;
        score += 0.15 * diff;
        // Stronger pull toward the tightest bins when many bins compete.
        if open_bins_count > 6 && diff < 0.0 {
            score -= 4.0 * (-diff / cap);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where the item fills a large fraction of residual.
    let residual = bin_residual as f64;
    let fill_ratio = item_size as f64 / residual.max(1.0);
    score -= 40.0 * fill_ratio * fill_ratio;

    // Penalize dead space: small post-residuals that can't fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else {
        // Reward post-residuals that can fit the lookahead item (chaining fits).
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        } else if next_item_size > 0 {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 100.0;
    }

    // Penalize spreading across many open bins when residuals are plentiful.
    let open_f = open_bins_count as f64;
    let mean_r = mean_residual.max(0.0);
    let scarcity = 1.0 - (mean_r / bin_capacity as f64).min(1.0);
    score += open_f * 0.6 * scarcity;

    // Time horizon: early in the stream, be pickier about tight fits; late, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * fill_ratio * (1.0 - progress);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New empty bin candidate: only attractive if nothing fits well anywhere.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score += 150.0 - 130.0 * desperation - 25.0 * progress;
    }

    // Mild bonus for bins already below mean residual (consolidation).
    if (bin_residual as f64) < mean_r {
        score -= 5.0;
    }

    score
}

