pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = x * x * (3.0 - 2.0 * x); // smooth base: penalize mid-range waste, reward tight fits

    // Progress-coupled cubic interaction: waste tolerance shrinks as stream advances
    score += x * x * x * (0.5 + progress) * 2.0;

    // Reward filling bins deeply early, but avoid over-tight fits late if next item needs space
    let tight_bonus = (1.0 - x).powi(3);
    score -= tight_bonus * (1.0 - progress) * 1.5;

    // Lookahead coupling: penalize leaving residuals that barely fail next item
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let gap = (x - nx).abs();
        if x < nx {
            score += (nx - x).powi(2) * (1.0 + progress) * 3.0; // can't fit next item
        } else {
            score -= gap.powi(2) * (1.0 - progress) * 1.0; // next item fits snugly
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 {
        score -= 2.5 * (1.0 - progress);
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins) smoothly
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.8 * dev * dev - 0.4 * dev;

    // New-bin candidate: baseline score so it only wins when open bins are genuinely bad
    if bin_residual == bin_capacity {
        score += 6.0 + 4.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
    }

    score
}

