        // and the current item would leave a near-dead gap.
        if next_item_size > 0 && (next_item_size as f64) > mean_residual * 1.3 && item + next_item_size as f64 <= cap {
            score -= 30.0;
        }
    } else if open_bins_count > 3 && residual > 2.0 * mean_residual {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: bins whose post_residual lies in
    // "small residue" classes are valuable; penalize leaving awkward mid-range gaps.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Dead-space penalty: leftovers that are too small for typical future items
    // (residue in (0, 10)) are almost unusable -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Perfect fit reward: harmonic class 0 (post_residual % 10 == 0) is ideal.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual % 10 == 0 {
        score -= 25.0;
    }

    // Integer-division threshold: classify post_residual into bands of capacity/5.
    let band = (post_residual * 5) / bin_capacity; // 0..=4
    match band {
        0 => score += 15.0,          // tiny gap left, bin nearly full (good but fragile)
        1 => score -= 5.0,           // small useful gap
        2 => score -= 12.0,          // mid gap, quite reusable
        3 => score -= 8.0,
        _ => {}                      // large gap: essentially an empty-ish bin, neutral
    }

    // Coupling with lookahead: reward when post_residual exactly (or nearly)
    // accommodates the next item's harmonic class.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if (pr - ni).abs() < 1.0 {
            score -= 35.0;
        } else if pr >= ni {
            // leftover can host next item: reward proportional to tightness
            score -= 20.0 * (1.0 - (pr - ni) / cap);
        } else {
            // next item won't fit here: mild penalty scaled by how far off
            score += 6.0 * (ni - pr) / cap;
        }
        // Modulo coupling: next item in same decile class as leftover -> reusable
        if post_residual % 10 == next_item_size % 10 && pr >= ni {
            score -= 8.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when current bins would leave bad dead space or the
    // item is large relative to remaining space.
    if bin_residual == bin_capacity {
        // baseline for fresh bin: slightly worse than a good fit, better than waste
        score = cap * 0.55;
        if item_size >= bin_capacity / 2 {
            score -= 10.0; // large items start fresh bins happily
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 8.0; // room for pairing with next item
        }
        if fitting_bins_count <= 1 {
            score += 25.0; // don't abandon a last-chance bin
        }
    }

    // Late in the stream, consolidate: prefer existing bins more strongly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    if bin_residual != bin_capacity {
        score += 0.3 * (bin_residual as f64 - mean_residual);
    }

    // Mild penalty for proliferating bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post * post / cap;

    // Exact fill is ideal
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 330.0 / post;
    } else if post_residual < 12 {
        score += 90.0 + (12 - post_residual) as f64 * 6.0;
    } else {
        score -= 15.0 * (post / cap);
        if post_residual >= 40 { score -= 9.0; }
        if post_residual < 30 { score += 7.5 * (30 - post_residual) as f64 / 18.0; }
    }

    // Penalize small dead space generally
    if post > 0.0 && post < 0.25 * cap {
        score += 30.0 * (1.0 - post / (0.25 * cap));
    }

    // Lookahead: chain fit with next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let chain_tight = 1.0 - (post - nxt) / cap;
            score -= 52.0 * chain_tight;
            if post == nxt { score -= 68.0; }
            let slack = post - nxt;
            if slack <= 2.0 { score -= 14.0; }
            else if slack <= 6.0 { score -= 18.0; }
            if slack >= 1.0 && slack <= mean_residual * 0.5 { score -= 8.0; }
            if (slack as u32) == mean_residual as u32 { score -= 9.0; }
            if slack >= 1.0 && slack < 12.0 { score -= 4.0; }
            // NEW: reward chains that also leave room relative to mean residual
            if slack >= 1.0 && slack <= mean_residual * 1.2 { score -= 7.0 * (1.0 - slack / (mean_residual * 1.2).max(1.0)); }
        } else if post + 10.0 >= nxt {
            score += 6.0;
            if (nxt - post) as u32 <= 2 && fitting_bins_count > 1 { score += 15.0; }
        } else {
            score += 0.06 * (nxt - post);
        }
        // Next item would strand this residual
        if nxt > post && post_residual > 0 && post_residual < 20 {
            score += 12.0;
        }
        if nxt > post && post_residual > 0 && post_residual < (next_item_size / 2).max(1) {
            score += 6.0 * (1.0 - post_residual as f64 / (next_item_size / 2).max(1) as f64);
        }
        if post_residual > 0 && post_residual < 16 && nxt > post && (mean_residual as u32) > post_residual {
            score += 9.0 * (16 - post_residual) as f64 / 8.0;
        }
        // NEW: penalize stranding a residual that is a large fraction of next item
        if post_residual > 0 && nxt > post && post_residual >= (next_item_size * 3 / 4).max(1) {
            score += 5.0 * (post_residual as f64 - next_item_size as f64 * 0.75) / (next_item_size as f64 * 0.25).max(1.0);
        }
        // Dead-space ratio penalty when next item strands a mid residual
        let dead = post / cap;
        if nxt > post && dead > 0.35 && post as f64 > mean_residual * 1.5 && fitting_bins_count > 3 {
            score += 10.0 * (dead - 0.35);
        }
        // Near-exact two-item chain
        if nxt <= post && (post - nxt) <= 2.0 && dead > 0.4 {
            score -= 9.0;
        }
    } else {
        score += post * 2.2;
    }

    // Sliver penalty when next item cannot use it
    if post_residual > 0 && post_residual < 8 && next_item_size > post_residual {
        score += 26.0;
    }

    // Last-chance bin: strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    if fitting_bins_count > 4 && bin_residual != bin_capacity && post_residual > 30 {
        score += 3.0;
    }

    // Mean-residual relative comparison
    score -= 0.25 * (mean_residual - post);

    // Progress-aware fullness preference
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 8.0 * progress * (post / cap);

    // NEW: stronger fullness preference late in the stream
    if post_residual > 0 && progress > 0.6 {
        score += 4.0 * progress * (post / cap);
    }

    // New-bin candidate: only open when open bins are truly poor
    if bin_residual == bin_capacity {
        score += 18.0;
        if open_bins_count > 6 && progress > 0.5 {
            score -= 6.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 4 {
            score += 40.0;
        }
        if next_item_size > 0 && post_residual >= item_size + next_item_size {
            score += 25.0;
        }
        // NEW: never open a new bin when an open bin achieves an exact fit
        if post_residual == 0 {
            score += 500.0;
        }
    }

    score
}

