    if post_residual > 0 && post_residual < 8 && next_item_size > post_residual {
        score += 26.0;
    }
    if post_residual > 0 && post_residual < 16 && next_item_size > post_residual && (mean_residual as u32) > post_residual {
        score += 9.0 * (16 - post_residual) as f64 / 8.0;
    }

    // Semi-fit lookahead.
    if post_residual > 0 && next_item_size as f64 <= post && next_item_size as f64 > post_residual as f64 * 0.6 && post_residual <= 25 {
        score -= 13.0 * (1.0 - post_residual as f64 / 25.0);
    }
    if post_residual > 0 && post_residual < item_size && next_item_size as f64 > post && open_bins_count > 3 {
        score += 8.0;
    }
    if post_residual > 0 && next_item_size as f64 > post && post_residual < (next_item_size / 2) {
        score += 6.0 * (1.0 - post_residual as f64 / (next_item_size / 2).max(1) as f64);
    }
    if post_residual > 0 && post_residual % 10 == 0 && next_item_size as f64 <= post {
        score -= 5.0;
    }
    let dead = post / cap;
    if post_residual > 0 && next_item_size as f64 > post && dead > 0.35 && (post_residual as f64) > mean_residual * 1.5 && fitting_bins_count > 3 {
        score += 10.0 * (dead - 0.35);
    }
    if post_residual > 0 && next_item_size as f64 <= post && (post - next_item_size as f64) <= 2.0 && dead > 0.4 {
        score -= 9.0;
    }
    if fitting_bins_count > 4 && bin_residual != bin_capacity && post_residual > 30 {
        score += 3.0;
    }

    // Last-chance pressure.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    } else if fitting_bins_count <= 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Consolidation pressure.
    score += (open_bins_count as f64) * 1.5;

    // Mean-residual coupling.
    if residual < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score += 120.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 100.0 * progress;
        score += 10.0 * (open_bins_count as f64);
        if fitting_bins_count > 1 {
            score += 100.0 * (fitting_bins_count as f64 - 1.0);
        }
        score += 0.5 * mean_residual;
        if item_size < (bin_capacity / 2) {
            score += 12.0;
            if next_item_size > 0 && (next_item_size as f64) <= post {
                score += 20.0;
            }
        }
        // Huge items deserve fresh bins when residuals are small.
        if item > 0.8 * cap && mean_residual < item * 0.9 {
            score -= 200.0;
        }
        // Medium-large items late in stream when no open bin fits the next item.
        if item > 0.5 * cap && next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 120.0;
        }
        // Fresh bin for medium items when all open residuals are nearly dead.
        if item <= 0.5 * cap && open_bins_count > 2 && mean_residual < item * 0.55 && fitting_bins_count > 0 {
            score -= 45.0;
        }
        // NEW: fresh bin when the next item could chain perfectly into this item.
        if item > 0.6 * cap && next_item_size > 0 && (item + next_item_size as f64) <= cap {
            score -= 30.0;
        }
        // NEW: avoid fresh bins early in stream with plenty of open capacity.
        if open_bins_count > 5 && mean_residual > item * 1.5 {
            score += 40.0;
        }
    } else if open_bins_count > 3 && residual > 2.0 * mean_residual {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect match: next item fits with little slack.
    else if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 10 {
        score -= 35.0 - (post_residual - next_item_size) as f64;
    }
    // Next item does NOT fit: residual becomes dead space (penalize).
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 12.0 + (next_item_size - post_residual) as f64 * 0.3;
    }

    // Reward tight packing relative to current mean residual.
    let post_f = post_residual as f64;
    if post_f < mean_residual {
        score -= (mean_residual - post_f).min(30.0) * 0.5;
    } else {
        score += (post_f - mean_residual).min(30.0) * 0.3;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when post_residual is large (fresh bin)
    // and no open bin offers a good match; penalize otherwise to avoid bin sprawl.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let sprawl_penalty = 18.0 + 20.0 * (1.0 - progress);
        score += sprawl_penalty;
        // A fresh bin is good only if it promises near-perfect future use.
        if next_item_size > 0 && (bin_capacity - next_item_size) <= 15 {
            score -= 30.0;
        }
        // With many open bins, opening another is rarely beneficial.
        score += open_bins_count as f64 * 1.5;
    }

    // Small bonus for very tight fills overall.
    if post_residual <= 5 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post_residual non-linearly.
    if post_residual == 0 {
        score -= 200.0;
    } else {
        let pr = post_residual as f64;
        score += (pr * pr) / (bin_capacity as f64) * 0.6;
    }

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size <= post_residual {
            score -= 25.0 * (1.0 - (post - nxt) / (bin_capacity as f64));
        } else {
            // next item won't fit here; mild penalty scaled by wasted fraction
            score += 10.0 * (nxt / (bin_capacity as f64));
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Time horizon: early in the stream, be more conservative with open bins;
    // late in the stream, prefer filling existing bins aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 30.0 * progress;

    // Global state: many open bins with high mean residual -> encourage consolidation.
    let open_f = open_bins_count as f64;
    if open_bins_count > 0 {
        let consolidation = (mean_residual / bin_capacity as f64) * (1.0 - progress);
        score += 20.0 * consolidation;
        score -= 5.0 / open_f;
    }

    // New-bin candidate handling: empty bin should only win when current bin
    // is a poor fit (large post_residual) or lookahead suggests a fresh bin helps.
    if bin_residual == bin_capacity {
        let base_penalty = 55.0;
        let poor_fit = if post_residual as f64 > (bin_capacity as f64) * 0.5 { 0.0 } else { 80.0 };
        let lookahead_bonus = if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_capacity {
            -30.0
        } else {
            0.0
        };
        score += base_penalty + poor_fit + lookahead_bonus + 10.0 * (1.0 - progress);
    }

    // Slight preference for bins whose residual is close to item (best-fit flavor).
    let diff = (bin_residual as f64 - item_size as f64).abs();
    score += diff * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
