    // early on, prefer tight fills (low post_residual) strongly; later, allow waste
    let t = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score -= t * (pr / cap) * (cap - pr) * 0.6;

    // Reward filling the bin well (quadratic in fill fraction)
    let fill = (bin_residual as f64 - pr) / cap;
