pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues modulo 10 create
    // "compatible classes" of items (sizes 1..=100, capacity 100).
    let class = post_residual % 10;
    // Dead-space penalty grows super-linearly when post_residual falls into
    // a small, hard-to-fill class (0 < class < 10, especially tiny classes).
    if post_residual > 0 {
        if class == 0 {
            // Perfect harmonic alignment: large reward.
            score -= 12.0;
        } else if class >= 7 {
            score -= 3.0;
        } else if class <= 2 {
            // Tiny unusable residue class: penalize heavily.
            score += 15.0 + 5.0 * (2 - class) as f64;
        } else {
            score += class as f64 * 0.8;
        }
    } else {
        // Perfect fill: maximal reward.
        score -= 40.0;
    }

    // Integer-division thresholds: how many "typical" small items (size <= 10)
    // could still fit into post_residual.
    let slots = post_residual / 10;
    score -= slots as f64 * 2.0;

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, this is an excellent chain placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let next_class = post_residual - next_item_size;
            // Reward based on how harmonically the chain continues.
            if next_class % 10 == 0 {
                score -= 10.0;
            }
            score -= 4.0;
        } else {
            // Next item won't fit here regardless; slight penalty for
            // hoarding space the future cannot use harmonically.
            let waste = next_item_size - post_residual;
            if waste <= 10 {
                score += 2.0;
            }
