    // strongly prefer placing it here over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has neutral-ish baseline so
    // it only wins when all open bins would create bad dead space.
    if bin_residual == bin_capacity {
        score += 5.0;
