    // residual when we are filling them down toward zero (keeps class
    // diversity across open bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 0.3 * dev;

    // Mild pressure against accumulating too many open bins.
    score += open_bins_count as f64 * 0.15;

    // Fractional capacity coupling: reward placements leaving residual in
    // the upper half of the capacity (still flexible bins).
    if post_residual * 2 >= bin_capacity {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
