        }
        if nxt > post && post_residual > 0 && post_residual < (next_item_size / 2).max(1) {
            score += 6.0 * (1.0 - post_residual as f64 / (next_item_size / 2).max(1) as f64);
        }
        if post_residual > 0 && post_residual < 16 && nxt > post && (mean_residual as u32) > post_residual {
            score += 9.0 * (16 - post_residual) as f64 / 8.0;
        }
        // Dead-space ratio penalty when next item strands a mid residual
        let dead = post / cap;
        if nxt > post && dead > 0.35 && post as f64 > mean_residual * 1.5 && fitting_bins_count > 3 {
            score += 10.0 * (dead - 0.35);
        }
        // Near-exact two-item chain: residual fits both item and next tightly
        if nxt <= post && (post - nxt) <= 2.0 && dead > 0.4 {
            score -= 9.0;
        }
        // Best heuristic idea: residual just under next item is stranded
        if post_residual > 0 && next_item_size as f64 > post && post_residual >= (next_item_size * 3 / 4) && post_residual < next_item_size {
            score += 5.0 * (post_residual as f64 - next_item_size as f64 * 0.75) / (next_item_size as f64 * 0.25).max(1.0);
        }
        // Tight two-step chain within mean residual
        if post_residual > 0 && nxt <= post && (post - nxt) <= 12.0 && (post - nxt) <= mean_residual * 1.2 {
            score -= 7.0 * (1.0 - (post - nxt) / 12.0);
        }
    } else {
        score += post * 2.2;
    }

    // Sliver penalty when next item cannot use it
    if post_residual > 0 && post_residual < 8 && next_item_size > post_residual {
        score += 26.0;
    }

    // Last-chance bin: strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Many open bins: keep big residuals from hogging preference
    if fitting_bins_count > 4 && bin_residual != bin_capacity && post_residual > 30 {
        score += 3.0;
    }

    // Mean-residual relative comparison
    score -= 0.25 * (mean_residual - post);

    // Progress-aware fullness preference
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 8.0 * progress * (post / cap);

    // New-bin candidate: only open when open bins are truly poor
    if bin_residual == bin_capacity {
        score += 18.0;
        if open_bins_count > 6 && progress > 0.5 {
            score -= 6.0;
        }
        // Don't open a new bin when some open bin gives a near-exact fit
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size as u32 <= 4 {
            score += 40.0;
        }
        // Avoid opening new bins when an open bin can chain both current and next items
        if next_item_size > 0 && post_residual >= item_size + next_item_size {
            score += 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step match: post_residual equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Partial lookahead credit: how close post_residual is to next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 25.0 * (-gap / 12.0).exp();
        // Penalize post-residuals that are too small to fit the next item.
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Reward tight fits relative to mean residual across open bins.
    let post_f = post_residual as f64;
    if mean_residual > 0.0 {
        let ratio = post_f / mean_residual;
        score += 10.0 * (ratio - 1.0).abs();
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Penalize large dead space quadratically (unusable slivers).
    if post_f > 0.0 {
        score += 0.05 * post_f * post_f / bin_capacity as f64;
    }

    // New-bin candidate (empty bin): penalize so we only open when fits are poor.
    if bin_residual == bin_capacity {
        score += 55.0;
        // But allow opening a new bin if the current bin would leave a tiny dead sliver.
        if post_f > 0.0 && post_f < 10.0 {
            score -= 70.0;
        }
        // Late in the stream, closing out bins cleanly is valuable.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * progress;
    }

    // Mild preference for bins already partially filled (reduce bin count pressure).
    score -= 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.04;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins with small post_residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that cannot fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead coupling: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0; // blocks the lookahead item
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: make opening a new bin moderately expensive,
    // but attractive when open bins are all poorly utilized and item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let base_penalty = 20.0 + 10.0 * (1.0 - progress);
        // If item is large and current bin would leave a big hole, new bin is ok.
        let hole = (bin_residual - item_size) as f64;
        let hole_penalty = if hole > 40.0 { 0.0 } else { 15.0 };
        score += base_penalty + hole_penalty + 0.5 * open_bins_count as f64;
    }

    // Mild preference for bins below mean residual (keeps large residuals for large items).
    score += 0.3 * ((bin_residual as f64) - mean_residual).max(0.0);

    // Late in stream: consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 15.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post * post / cap;

    // Exact fill is ideal
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 330.0 / post;
    } else if post_residual < 12 {
        score += 90.0 + (12 - post_residual) as f64 * 6.0;
    } else {
        score -= 15.0 * (post / cap);
        if post_residual >= 40 { score -= 9.0; }
        if post_residual < 30 { score += 7.5 * (30 - post_residual) as f64 / 18.0; }
    }

    // Penalize small dead space generally
    if post > 0.0 && post < 0.25 * cap {
        score += 30.0 * (1.0 - post / (0.25 * cap));
    }

    // Lookahead: chain fit with next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = post - nxt;
            let chain_tight = 1.0 - slack / cap;
            score -= 52.0 * chain_tight;
            if post == nxt { score -= 68.0; }
            if slack <= 2.0 { score -= 14.0; }
            else if slack <= 6.0 { score -= 18.0; }
            if slack >= 1.0 && slack <= mean_residual * 0.5 { score -= 8.0; }
            if (slack as u32) == mean_residual as u32 { score -= 9.0; }
            if slack >= 1.0 && slack < 12.0 { score -= 4.0; }
            // Two-step lookahead: residual after chaining still fits next item
            if slack >= 1.0 && (slack as u32) >= next_item_size {
                score -= 10.0;
            }
            // Chain leaves residual close to mean: likely reusable
            if slack >= 1.0 && (slack as f64 - mean_residual).abs() <= 3.0 {
                score -= 6.0;
            }
        } else if post + 10.0 >= nxt {
            score += 6.0;
            if (nxt - post) as u32 <= 2 && fitting_bins_count > 1 { score += 15.0; }
        } else {
            score += 0.06 * (nxt - post);
        }
        // Next item would strand this residual
        if nxt > post && post_residual > 0 && post_residual < 20 {
            score += 12.0;
        }
        if nxt > post && post_residual > 0 && post_residual < (next_item_size / 2).max(1) {
            score += 6.0 * (1.0 - post_residual as f64 / (next_item_size / 2).max(1) as f64);
        }
        if post_residual > 0 && post_residual < 16 && nxt > post && (mean_residual as u32) > post_residual {
            score += 9.0 * (16 - post_residual) as f64 / 8.0;
        }
        // Dead-space ratio penalty when next item strands a mid residual
        let dead = post / cap;
        if nxt > post && dead > 0.35 && post as f64 > mean_residual * 1.5 && fitting_bins_count > 3 {
            score += 10.0 * (dead - 0.35);
        }
        // Near-exact two-item chain: residual fits both item and next tightly
        if nxt <= post && (post - nxt) <= 2.0 && dead > 0.4 {
            score -= 9.0;
        }
        // Residual just under next item is stranded
        if post_residual > 0 && nxt > post && post_residual >= (next_item_size * 3 / 4) && post_residual < next_item_size {
            score += 5.0 * (post_residual as f64 - nxt * 0.75) / (nxt * 0.25).max(1.0);
        }
        // Tight two-step chain within mean residual
        if post_residual > 0 && nxt <= post && (post - nxt) <= 12.0 && (post - nxt) <= mean_residual * 1.2 {
            score -= 7.0 * (1.0 - (post - nxt) / 12.0);
        }
        // Two-item chain: can current+next both land here exactly?
        if post_residual >= item_size + next_item_size {
            let two_slack = post_residual - item_size - next_item_size;
            if two_slack == 0 { score -= 30.0; }
            else if two_slack <= 5 { score -= 14.0; }
        }
    } else {
        score += post * 2.2;
    }

    // Sliver penalty when next item cannot use it
    if post_residual > 0 && post_residual < 8 && next_item_size > post_residual {
        score += 26.0;
    }

    // Last-chance bin: strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Many open bins: keep big residuals from hogging preference
    if fitting_bins_count > 4 && bin_residual != bin_capacity && post_residual > 30 {
        score += 3.0;
    }

    // Mean-residual relative comparison
    score -= 0.25 * (mean_residual - post);

    // Progress-aware fullness preference
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 8.0 * progress * (post / cap);

    // New-bin candidate: only open when open bins are truly poor
    if bin_residual == bin_capacity {
        score += 18.0;
        if open_bins_count > 6 && progress > 0.5 {
            score -= 6.0;
        }
        // Don't open a new bin when some open bin gives a near-exact fit
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 4 {
            score += 40.0;
        }
        // Avoid opening new bins when an open bin can chain both current and next items
        if next_item_size > 0 && post_residual >= item_size + next_item_size {
            score += 25.0;
        }
        // Avoid opening new bins when open bin residual is near-exact for item
        if bin_residual - item_size <= 3 && bin_residual != bin_capacity {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: penalize leftover space, with a superlinear (quadratic) growth
    // so that large dead space is disproportionately discouraged.
    let mut score = pr + 0.9 * (pr * pr) / cap;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early in the stream, moderate leftovers are acceptable (bins can be
    // filled later); late in the stream, leftover space is nearly wasted.
    let t = progress * std::f64::consts::PI;
    let urgency = 0.5 * (1.0 - t.cos()); // smooth 0..2 ramp
    score += urgency * (pr * pr) / cap;

    // Reward tight fits: small post_residual relative to item size.
    let item = item_size as f64;
    score -= (item / cap) * (cap - pr) * 0.5;

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, strongly reward this placement (perfect chain).
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let gap = (pr - nxt).abs();
        let fit_quality = 1.0 - (gap / cap).min(1.0);
        let chain = fit_quality * fit_quality;
        // Reward only when next item actually fits (pr >= nxt), smooth falloff otherwise.
        let fits = ((pr - nxt) / cap).max(0.0).min(1.0);
        score -= 8.0 * chain * (0.5 + fits);
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0 + urgency * 6.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer bins that are already well utilized.
        let fill = (cap - pr) / cap;
        score -= 3.0 * fill * fill;
    }

    // Mean-residual coupling: when open bins are on average quite full,
    // squeezing into an existing bin is more valuable.
    let mean_fill = 1.0 - (mean_residual / cap).min(1.0).max(0.0);
    score -= 4.0 * mean_fill * mean_fill;

    // Penalize scattering across many open bins mildly.
    score += (open_bins_count as f64).sqrt() * 0.4;

    // New-bin candidate (empty bin): make it slightly unattractive by
    // default, so it is only chosen when leftovers elsewhere are truly bad.
    if bin_residual == bin_capacity {
        score += 6.0 + urgency * 8.0 - 0.5 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post * post / cap;

    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 330.0 / post;
    } else if post_residual < 12 {
        score += 90.0 + (12 - post_residual) as f64 * 6.0;
    } else {
        score -= 15.0 * (post / cap);
        if post_residual >= 40 {
            score -= 9.0;
        }
        if post_residual < 30 {
            score += 7.5 * (30 - post_residual) as f64 / 18.0;
        }
    }

    // Sliver penalty: small residual that next item can't use.
    if post > 0.0 && post < 0.25 * cap {
        score += 30.0 * (1.0 - post / (0.25 * cap));
    }

    // Lookahead on next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let gap = post - nxt;
            let chain_tight = 1.0 - gap / cap;
            score -= 52.0 * chain_tight;
            if gap == 0.0 {
                score -= 68.0;
            }
            if post >= nxt + mean_residual {
                score -= 10.0;
            }
            if gap <= mean_residual * 0.5 {
                score -= 8.0;
            }
            if gap >= 1.0 && gap <= 4.0 {
                score -= 12.0;
            }
            if gap < 6.0 {
                score -= 18.0;
            }
        } else {
            // Next item won't fit here; penalize dead space proportional to miss.
            score += 0.06 * (nxt - post);
            if (nxt - post) as u32 <= 2 && fitting_bins_count > 1 {
                score += 15.0;
            }
            if (nxt - post) as u32 > 20 && post_residual > 0 && post_residual < 20 {
                score += 12.0;
            }
        }
    } else {
        score += post * 2.2;
    }

    // Tiny unusable slivers.
    if post_residual > 0 && post_residual < 8 && next_item_size > post_residual {
        score += 26.0;
    }
    if post_residual > 0 && post_residual < 16 && next_item_size > post_residual && (mean_residual as u32) > post_residual {
        score += 9.0 * (16 - post_residual) as f64 / 8.0;
    }
    if fitting_bins_count > 4 && bin_residual != bin_capacity && post_residual > 30 {
        score += 3.0;
    }

    // Half-fit lookahead: prefer residuals that could take half of next item later.
    if post_residual > 0 && next_item_size as f64 > post && post_residual < (next_item_size / 2).max(1) {
        score += 6.0 * (1.0 - post_residual as f64 / (next_item_size / 2).max(1) as f64);
    }

    // Dead-space vs mean residual: penalize bins with much more free space than average
    // when the next item doesn't fit.
    if post_residual > 0 && next_item_size as f64 > post {
        let dead = post / cap;
        if dead > 0.35 && (post_residual as f64) > mean_residual * 1.5 && fitting_bins_count > 3 {
            score += 10.0 * (dead - 0.35);
        }
    }

    // Chain into near-exact fits.
    if post_residual > 0 && next_item_size as f64 <= post && (post - next_item_size as f64) <= 12.0
        && (post - next_item_size as f64) <= mean_residual * 1.2 {
        score -= 7.0 * (1.0 - (post - next_item_size as f64) / 12.0);
    }

    // Last-chance bonus: only fitting bin — keep consolidating.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: open only when open bins fit poorly.
    if bin_residual == bin_capacity {
        score = 45.0 + mean_residual * 0.4;
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 40.0 * (1.0 - progress);
        // Late in stream, opening a new bin is more costly: raise baseline.
        if progress > 0.7 {
            score += 20.0 * (progress - 0.7) / 0.3;
        }
    }

    // Prefer tighter-than-average bins when consolidating.
    if bin_residual != bin_capacity && open_bins_count > 1 {
        let diff = bin_residual as f64 - mean_residual;
        score += 0.15 * diff;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" the leftover space is.
    // Class 0: post_residual == 0 (perfect fit) -> strongest reward.
    // Class 1: post_residual <= 10 (near-perfect) -> strong reward.
    // Class 2: post_residual divisible into capacity fractions (20/25/33/50) -> moderate reward.
    // Class 3: awkward remainder -> penalty.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 120.0;
    } else {
        // Fractional harmony: does post_residual divide nicely into capacity?
        let harmonic: [(u32, f64); 6] = [(50, 40.0), (33, 30.0), (25, 25.0), (20, 20.0), (34, 10.0), (40, 15.0)];
        let mut harmonic_bonus = 0.0;
        for &(d, b) in harmonic.iter() {
            if post_residual % d == 0 && post_residual >= d {
                harmonic_bonus = b * (post_residual as f64 / d as f64).min(4.0);
                break;
            }
        }
        score -= harmonic_bonus;

        // Awkward dead-space penalty: leftover that no plausible item (1..=80, common small sizes) fits well.
        if post_residual < 10 {
            score += 30.0;
        }
        // Integer-division threshold classes on post_residual
        let class = post_residual / 15; // 0..6
        score += match class {
            0 => 0.0,
            1 => -5.0,
            2 => 0.0,
            3 => 5.0,
            4 => 0.0,
            _ => -3.0,
        };
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportional to how snugly it packs.
            let snug = (post_residual - next_item_size) as f64;
            score -= 60.0 - snug * 0.5;
            // Harmonic match: next_item_size is a divisor-like partner
            if post_residual % next_item_size == 0 {
                score -= 25.0;
            }
        } else {
            // Next item won't fit here: slight penalty scaled by how much it overshoots.
            let over = (next_item_size - post_residual) as f64;
            score += over * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless post_residual would be terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: empty bin gets a baseline score so it wins only
    // when all open bins would create bad fits.
    if bin_residual == bin_capacity {
        score = 60.0 + mean_residual * 0.1 - (post_residual as f64);
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 40.0;
        // Many open bins -> discourage opening yet another.
        score += open_bins_count as f64 * 2.0;
        return score;
    }

    // Tightness reward: filling a bin closer to capacity is good.
    let fill = (bin_residual as f64 - post_residual as f64) / bin_capacity as f64;
    score -= fill * 30.0;

    // Mild preference for bins below mean residual (consolidate emptier bins).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
