pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strict dead-space avoidance archetype.
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        return -10000.0;
    }

    // Dead space is only "unusable" if it can't hold typical future items.
    // Threshold: smallest item size (1) means nothing is truly dead, but small
    // gaps (< next_item_size and < 10) are highly likely to be wasted.
    let dead_threshold = if next_item_size > 0 { next_item_size.min(80) } else { 10 };

    if (post_residual as f64) < mean_residual * 0.5 || post_residual < dead_threshold {
        // Harsh penalty for creating likely-unusable small gaps.
        score += (dead_threshold as f64 - post_residual as f64).max(0.0) * 3.0
            + (bin_capacity as f64 / post_residual as f64) * 2.0;
    } else {
        // Reward leaving a usable gap, more so if it can host the lookahead item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
        score -= 5.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins when residuals
    // are already fragmented; encourage consolidation.
    score += (open_bins_count as f64).ln().max(0.0) * 4.0;

    // Prefer bins with smaller residual before placement (tighter packing).
    score += (bin_residual as f64 - item_size as f64 - post_residual as f64) * 0.0; // no-op guard
    score += (bin_capacity as f64 - bin_residual as f64) * 0.1;

    // New-bin candidate: only attractive when no open bin offers a decent fit
    // (i.e., this call itself is the empty-bin candidate and current fit is bad).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // If the item is large relative to capacity, a fresh bin is fine.
        score -= (item_size as f64 / bin_capacity as f64) * 20.0;
        // Early in the stream, opening bins is cheaper (more future items to fill).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 15.0;
        // If many bins are open with fragmented residuals, new bin less attractive.
        score += (open_bins_count as f64) * 0.8;
    }

    // Slight tie-break toward bins that leave room matching the lookahead item exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.05;
    }

    score
}

