        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if nxt <= pr {
            let slack = pr - nxt;
            // Strong reward if next item exactly fills the bin
            score -= 12.0 * (1.0 - slack / bin_capacity as f64).powi(3);
            // Extra bonus for perfect closure
            if slack == 0.0 {
                score -= 20.0;
            }
        } else {
            // Next item won't fit here: penalize proportionally to overflow
            score += 0.15 * (nxt - pr);
        }
    }

    // Penalize leaving residual far from typical item sizes (dead space)
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 8.0; // tiny unusable sliver
    }

    // Compare against mean residual: prefer bins tighter than average
    score -= 0.5 * (mean_residual - pr);

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New empty bin candidate: make it costly unless nothing fits well
    if bin_residual == bin_capacity {
        score += 25.0;
        // But if current item is large relative to capacity, new bin is fine
        score -= 0.1 * item_size as f64;
    }

    // Late in stream: consolidate, penalize opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward tight fits: smaller post_residual relative to capacity
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 60.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack == 0.0 {
            score -= 300.0;
        } else {
            score -= 150.0 * (1.0 - slack / bin_capacity as f64);
        }
    }

    // Penalize leaving large dead space when the next item cannot use it
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += post_residual as f64 * 1.5;
    }

    // Time horizon: late in the stream, be more conservative — avoid opening new bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize opening new bins, more so late in the stream
        // and when many bins are open; but allow it when residuals are all small.
        let open_pressure = open_bins_count as f64 * 8.0;
        let mean_res_penalty = (mean_residual / bin_capacity as f64) * 50.0;
        score = 100.0 + open_pressure + mean_res_penalty * (1.0 - progress) + progress * 80.0;
    } else {
        // Slight bonus for placing into already-open bins when many are open
        score -= (open_bins_count as f64).ln().max(0.0) * 5.0;
        // Prefer bins whose residual deviates favorably from the mean (consolidation)
        score -= (mean_residual - bin_residual as f64) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let residual = bin_residual as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post * post / cap;

    // Perfect / near-perfect fit rewards.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 330.0 / post;
    } else if post_residual < 12 {
        score += 90.0 + (12 - post_residual) as f64 * 6.0;
    } else {
        score -= 15.0 * (post / cap);
        if post_residual >= 40 {
            score -= 9.0;
        }
        if post_residual < 30 {
            score += 7.5 * (30 - post_residual) as f64 / 18.0;
        }
    }

    // Tightness coupling.
    let fill_ratio = item / residual.max(1.0);
    score -= 24.0 * fill_ratio;

    // Fragmentation penalty for small residuals.
    if post > 0.0 && post < 0.25 * cap {
        score += 30.0 * (1.0 - post / (0.25 * cap));
    }

    // Lookahead chain-fit bonus (combined with fine residual anticipation).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let chain_tight = 1.0 - (post - nxt) / cap;
            score -= 52.0 * chain_tight;
            if post == nxt {
                score -= 68.0;
            }
            if post - nxt < 6.0 {
                score -= 18.0;
            }
            if post >= nxt + mean_residual {
                score -= 10.0;
            }
            if (post - nxt) as u32 == mean_residual as u32 {
                score -= 9.0;
            }
            if post >= nxt && (post - nxt) <= mean_residual * 0.5 {
                score -= 8.0;
            }
            if post - nxt >= 1.0 && post - nxt <= 4.0 {
                score -= 12.0;
            }
            // Two-step lookahead — after placing next item, gap should stay reusable.
            let gap_after_next = post - nxt;
            if gap_after_next > 0.0 && gap_after_next < mean_residual {
                score += 10.0 * (1.0 - gap_after_next / mean_residual.max(1.0));
            }
            if gap_after_next >= mean_residual {
                score -= 6.0;
            }
            // Extended chain anticipation: gap after next stays within mean residual band.
            if gap_after_next > 0.0 && gap_after_next <= 12.0 && gap_after_next <= mean_residual * 1.2 {
                score -= 7.0 * (1.0 - gap_after_next / 12.0);
            }
        } else if post + 10.0 >= nxt {
            score += 6.0;
        } else {
            score += 0.06 * (nxt - post);
        }
        if nxt > post && (nxt - post) as u32 <= 2 && fitting_bins_count > 1 {
            score += 15.0;
        }
        if nxt > post && (nxt - post) as u32 > 20 && post_residual > 0 && post_residual < 20 {
            score += 12.0;
        }
        // Semi-fit: next item nearly fits but residual is close to 3/4 of it.
        if post_residual > 0 && nxt > post_residual && post_residual >= (next_item_size * 3 / 4) && post_residual < next_item_size {
            score += 5.0 * (post_residual as f64 - nxt * 0.75) / (nxt * 0.25).max(1.0);
        }
    } else {
        score += post * 2.2;
    }

    // Dead-space penalty: residual too small for the next item.
    if post_residual > 0 && post_residual < 8 && next_item_size > post_residual {
        score += 26.0;
    }
    if post_residual > 0 && post_residual < 16 && next_item_size > post_residual && (mean_residual as u32) > post_residual {
        score += 9.0 * (16 - post_residual) as f64 / 8.0;
    }

    // Semi-fit lookahead.
    if post_residual > 0 && next_item_size as f64 <= post && next_item_size as f64 > post_residual as f64 * 0.6 && post_residual <= 25 {
        score -= 13.0 * (1.0 - post_residual as f64 / 25.0);
    }
    if post_residual > 0 && post_residual < item_size && next_item_size as f64 > post && open_bins_count > 3 {
        score += 8.0;
    }
    if post_residual > 0 && next_item_size as f64 > post && post_residual < (next_item_size / 2) {
        score += 6.0 * (1.0 - post_residual as f64 / (next_item_size / 2).max(1) as f64);
    }
    if post_residual > 0 && post_residual % 10 == 0 && next_item_size as f64 <= post {
        score -= 5.0;
    }
    let dead = post / cap;
    if post_residual > 0 && next_item_size as f64 > post && dead > 0.35 && (post_residual as f64) > mean_residual * 1.5 && fitting_bins_count > 3 {
        score += 10.0 * (dead - 0.35);
    }
    if post_residual > 0 && next_item_size as f64 <= post && (post - next_item_size as f64) <= 2.0 && dead > 0.4 {
        score -= 9.0;
    }
    if fitting_bins_count > 4 && bin_residual != bin_capacity && post_residual > 30 {
        score += 3.0;
    }

    // Last-chance pressure.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    } else if fitting_bins_count <= 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Consolidation pressure.
    score += (open_bins_count as f64) * 1.5;

    // Mean-residual coupling.
    if residual < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score += 120.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 100.0 * progress;
        score += 10.0 * (open_bins_count as f64);
        if fitting_bins_count > 1 {
            score += 100.0 * (fitting_bins_count as f64 - 1.0);
        }
        score += 0.5 * mean_residual;
        if item_size < (bin_capacity / 2) {
            score += 12.0;
            if next_item_size > 0 && (next_item_size as f64) <= post {
                score += 20.0;
            }
        }
        // Huge items deserve fresh bins when residuals are small.
        if item > 0.8 * cap && mean_residual < item * 0.9 {
            score -= 200.0;
        }
        // Medium-large items late in stream when no open bin fits the next item.
        if item > 0.5 * cap && next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 120.0;
        }
        // Fresh bin for medium items when all open residuals are nearly dead.
        if item <= 0.5 * cap && open_bins_count > 2 && mean_residual < item * 0.55 && fitting_bins_count > 0 {
            score -= 45.0;
        }
    } else if open_bins_count > 3 && residual > 2.0 * mean_residual {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // smooth non-linear coupling of post residual with stream progress
    let coupling = norm_pr * norm_pr * (1.0 + progress) - norm_pr * progress * (1.0 - progress);
    score += 12.0 * coupling;
    // penalize tight fits more as stream progresses
    score += 8.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;
    // reward low post residual early (better packing)
    score -= 6.0 * (1.0 - norm_pr) * (1.0 - progress);
    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }
    // lookahead: reward if next item fits post residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 5.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 4.0 * (1.0 - pr / cap);
    }
    // penalize many open bins with high mean residual divergence
    let spread = (mean_residual - pr).abs() / cap;
    score += 3.0 * spread * (open_bins_count as f64).ln();
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: classify post_residual into residue classes mod 10.
    // Small leftovers (perfect fits) are heavily rewarded.
    let pr = post_residual;
    let class = pr % 10;
    let harmonic_penalty = match class {
        0 => -40.0,                 // exact fit leftover multiple of 10
        1 | 2 => 6.0,               // nearly-useless slivers
        3 | 4 | 5 | 6 | 7 => 12.0,  // awkward dead zone
        8 | 9 => 2.0,               // recoverable with tiny items
        _ => 0.0,
    };
    score += harmonic_penalty;

    // Integer-division thresholds: leftover that still fits common item sizes is good.
    if pr >= 50 { score -= 8.0; }
    if pr >= 30 && pr < 50 { score -= 3.0; }
    if pr > 0 && pr < 10 { score += 5.0; } // sliver penalty

    // Lookahead coupling: reward if next item fits the leftover exactly or well.
    if next_item_size > 0 && next_item_size <= pr {
        let slack = (pr - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        if (pr - next_item_size) % 10 == 0 { score -= 5.0; }
    } else if next_item_size > pr {
        score += 4.0; // leftover unusable for the known next item
    }

    // Last-chance bonus: this is the only bin that fits; strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Penalize opening a new bin when open bins already have plenty of room.
    if bin_residual == bin_capacity {
        score += 25.0 + 5.0 * (open_bins_count as f64).sqrt();
        if mean_residual > item_size as f64 { score += 10.0; }
    }

    // Mild fragmentation pressure as stream progresses.
    score += (step_index as f64 / (total_items.max(1) as f64)) * 4.0
        * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero gaps are "unusable" dead space.
    // Any post_residual in (0, 10) is worthless; penalize it heavily, scaled by
    // how close it is to the worst dead-space band.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Reward tight fits (small waste relative to capacity).
        score -= 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
