    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= tightness * 20.0;

    // Relative to mean residual: prefer bins already below-average residual (well used)
    score += (post_residual as f64 - mean_residual) * 0.4;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent existing fits exist
    if bin_residual == bin_capacity {
        score += 15.0;
        if fitting_bins_count > 0 {
            score += (fitting_bins_count as f64) * 5.0;
