pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: exponential bonus as post_residual approaches zero
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward leaving space exactly matching next item,
    // penalize residual that can't fit the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 18.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 / (1.0 + slack);
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: prefer opening a fresh bin when existing fits are loose
    // or item is huge (little room for pairing).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let loose_existing = mean_residual - item_size as f64;
        score += 40.0
            + 0.5 * open_bins_count as f64
            - (loose_existing.max(0.0)).min(30.0)
            - (item_size as f64 - 50.0).max(0.0) * 0.3;
    } else {
        // Mild penalty for spreading across many open bins
        score += 0.15 * open_bins_count as f64;
    }

    // Global state: if mean residual is high, encourage consolidation into fuller bins
    score += 0.05 * (mean_residual - post_residual as f64).abs();

    // Time horizon: early in stream, be slightly conservative (keep bins flexible);
    // late in stream, prioritize closing bins out.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose post-residual is a "nice" size (multiples of 10 pair well)
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    score
}

