            score += 0.06 * (nxt - post);
        }
        // Next item would strand this residual
        if nxt > post && post_residual > 0 && post_residual < 20 {
            score += 12.0;
        }
        if nxt > post && post_residual > 0 && post_residual < (next_item_size / 2).max(1) {
            score += 6.0 * (1.0 - post_residual as f64 / (next_item_size / 2).max(1) as f64);
        }
        if post_residual > 0 && post_residual < 16 && nxt > post && (mean_residual as u32) > post_residual {
            score += 9.0 * (16 - post_residual) as f64 / 8.0;
        }
        // Dead-space ratio penalty when next item strands a mid residual
        let dead = post / cap;
        if nxt > post && dead > 0.35 && post as f64 > mean_residual * 1.5 && fitting_bins_count > 3 {
            score += 10.0 * (dead - 0.35);
        }
        // Near-exact two-item chain
        if nxt <= post && slack <= 2.0 && dead > 0.4 {
            score -= 9.0;
        }
        // Residual just under next item is stranded
        if post_residual > 0 && nxt > post && post_residual >= (next_item_size * 3 / 4) && post_residual < next_item_size {
            score += 5.0 * (post_residual as f64 - nxt * 0.75) / (nxt * 0.25).max(1.0);
        }
        // Tight two-step chain within mean residual
        if post_residual > 0 && nxt <= post && slack <= 12.0 && slack <= mean_residual * 1.2 {
            score -= 7.0 * (1.0 - slack / 12.0);
        }
        // Stranded small residual with many open bins
        if post_residual > 0 && post_residual < item_size && nxt > post && open_bins_count > 3 {
            score += 8.0;
        }
    } else {
        score += post * 2.2;
    }

    // Sliver penalty when next item cannot use it
    if post_residual > 0 && post_residual < 8 && next_item_size > post_residual {
        score += 26.0;
    }

    // Last-chance bin: strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Many open bins: keep big residuals from hogging preference
    if fitting_bins_count > 4 && bin_residual != bin_capacity && post_residual > 30 {
        score += 3.0;
    }

    // Mean-residual relative comparison
    score -= 0.25 * (mean_residual - post);

    // Progress-aware fullness preference
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 8.0 * progress * (post / cap);

    // New-bin candidate: only open when open bins are truly poor
    if bin_residual == bin_capacity {
        score += 18.0;
        if open_bins_count > 6 && progress > 0.5 {
            score -= 6.0;
        }
        if open_bins_count > 10 {
            score += 6.0 * (open_bins_count.min(20) as f64 - 10.0) / 10.0;
        }
        // Don't open a new bin when some open bin gives a near-exact fit
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 4 {
            score += 40.0;
        }
        // Avoid opening new bins when an open bin can chain both current and next items
        if next_item_size > 0 && post_residual >= item_size + next_item_size {
            score += 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr_norm = pr / cap;
    let pg = progress;
    let coupling = pr_norm * pr_norm * (1.0 + pg) - 2.0 * pr_norm * pg * (1.0 - pg);
    score += 12.0 * coupling;

    // Reward tight fits smoothly (quadratic in fill fraction).
    let fill = 1.0 - pr_norm;
    score -= 20.0 * fill * fill;

    // Lookahead synergy: next item exactly filling post_residual is excellent.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let gap = (pr - nxt) / cap;
            score -= 15.0 * (1.0 - gap * gap);
        } else {
            score += 5.0 * ((nxt - pr) / cap);
        }
    }

    // Last-chance bin: penalize skipping it (opening a new bin) via smooth term.
    if fitting_bins_count <= 1 {
        score -= 10.0 * (1.0 - progress);
    }

    // Penalize opening a brand-new empty bin unless residual would be small.
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * pr_norm * pr_norm;
    }

    // Mild penalty for fragmenting relative to the mean residual of open bins.
    score += 2.0 * (pr - mean_residual) / cap;

    score
}

