    // Harmonic class of post-residual: bins whose leftover falls into a
    // "reusable" class (large, cleanly divisible chunks) are rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Dead-space penalty grows super-linearly for small unusable leftovers.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 3.0;
