        // still host any item, [25..50] mid items, small classes are risky.
        let class = post_residual / 25; // 0,1,2,3,4 harmonic classes
        score -= class as f64 * 6.0;
    }

    // Fractional capacity coupling: reward bins whose fill ratio crosses
    // harmonic thresholds (1/2, 3/4 of capacity).
    let fill = (bin_capacity - post_residual) as f64 / cap;
    if fill >= 0.75 {
        score -= 8.0;
    } else if fill >= 0.5 {
        score -= 4.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // Reward proportional to how tightly the next item nests.
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap);
        } else {
            // Next item won't fit here; slight penalty for tight leftovers.
            score += 2.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin early in the stream or
    // when open bins have plenty of mean residual room.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = mean_residual / cap;
        score += 12.0 + 10.0 * (1.0 - pressure) + 5.0 * (1.0 - progress);
        // Late in stream with fragmented bins, opening fresh is less bad.
        if progress > 0.7 && mean_residual < 20.0 {
            score -= 10.0;
        }
    }

    // Mild tie-break: prefer bins that are already partially filled
    // (reduces bin count pressure) when many bins are open.
    if open_bins_count > 3 && bin_residual != bin_capacity {
        score -= 1.5;
    }

    score
}

