    // since they can never be filled by future items.
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0;
    }

    // Perfect fit bonus: no waste at all.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward tight fits: fraction of bin used by this placement.
    let fill = item_size as f64 / cap;
    score -= 15.0 * fill;

    // If next item fits exactly in the post residual, big bonus (chained fit).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot use the leftover gap -> dead space likely
        score += 0.15 * post;
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: discourage opening new bins when few bins are open;
    // encourage consolidation when many bins are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

