    }

    // Last-chance bin: strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Many open bins: keep big residuals from hogging preference
    if fitting_bins_count > 4 && bin_residual != bin_capacity && post_residual > 30 {
        score += 3.0;
    }

    // Mean-residual relative comparison
    score -= 0.25 * (mean_residual - post);

    // Progress-aware fullness preference
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 8.0 * progress * (post / cap);

    // New-bin candidate: only open when open bins are truly poor
    if bin_residual == bin_capacity {
        score += 18.0;
        if open_bins_count > 6 && progress > 0.5 {
            score -= 6.0;
        }
        // Don't open a new bin when some open bin gives a near-exact fit
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 4 {
            score += 40.0;
        }
        // Avoid opening new bins when an open bin can chain both current and next items
        if next_item_size > 0 && post_residual >= item_size + next_item_size {
            score += 25.0;
        }
        // NEW: don't open new bins when an open bin leaves a residual >= next item
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size as u32 <= 12 {
            score += 14.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // matches (or nearly matches) the next item's size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward for exact match, decaying quadratically with gap.
        score -= 60.0 * (-gap / 12.0).exp();
        // Extra bonus if post_residual is exactly the next item size.
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize leaving post_residual too small for the next item
        // (dead space that nothing small can use later).
        if post_residual < next_item_size && post_residual < 10 {
            score += 25.0;
        }
    }

    // Prefer tight fits: small post_residual relative to capacity.
    score += 0.5 * (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Compare against mean residual: bins already below mean residual are
    // "well used" — placing here deepens fragmentation, so prefer them.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Penalize opening new bins when existing bins fit reasonably.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But allow opening a new bin if no open bin is a good fit and
        // the item is large (poor fit everywhere).
        if fitting_bins_count > 0 && item_size >= 60 {
            score -= 20.0;
        }
    }

    // Slight preference for bins with larger residual when many bins open
    // (consolidate into emptier bins, keep tight bins for small items).
    score += 0.05 * (open_bins_count as f64) * (bin_residual as f64 / bin_capacity as f64);

    // Late-stream pressure: as the stream ends, prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
