        if mean_residual < item_size as f64 && open_bins_count > 2 {
            score += 10.0;
        }
        // many open bins with slack: prefer consolidating instead of new bin
        if open_bins_count > 5 && mean_residual > 0.4 * cap {
            score += 12.0;
        }
        // late stream: penalize new bins harder to force consolidation
        if progress > 0.7 && open_bins_count > 3 {
            score += 8.0 * progress;
        }
    } else {
        // tightness pressure toward fuller bins
        let tightness = 1.0 - (bin_residual as f64 / cap);
        score -= 10.0 * tightness;
        if fitting_bins_count > 4 && post_residual > 30 {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
