        let gap = (next_item_size as f64 - post_residual as f64) / next_item_size as f64;
        score += 12.0 * gap;
    } else if next_item_size > 0 && post_residual >= next_item_size as f64 {
        // Bonus: bin can still host the next item afterwards.
        let leftover = post_residual as f64 - next_item_size as f64;
        score -= 6.0 * (leftover / bin_capacity as f64);
    }

    // Exact-fill celebration.
    if post_residual == 0 {
        score -= 50.0;
    }

    // New-bin candidate handling: opening a bin is expensive early, cheap late.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let open_cost = 60.0 * (1.0 - 0.5 * progress);
    if bin_residual == bin_capacity {
        score += open_cost;
        // If the item is large relative to capacity, a fresh bin is more attractive.
        score -= 0.3 * item_size as f64;
        // If many bins are open with fat residuals, prefer consolidating instead.
        score += 0.15 * mean_residual;
    } else {
        // Reward using existing bins, especially when few fit.
        if fitting_bins_count == 1 {
            score -= 30.0; // last-chance bin: avoid opening a new bin
        }
        score -= 0.1 * fitting_bins_count as f64;
    }

    // Mild time-horizon shaping: later in the stream, squeeze bins harder.
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Global balance: prefer bins below mean residual (spreading load evenly).
    score += 0.05 * (mean_residual - post_residual as f64);

    // Small jitter-free tie-break on residual to prefer fuller bins deterministically.
    score += 0.01 * post_residual as f64;

    score
}

