pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: waste minimization with non-linear penalty on small residuals
    let mut score = pr as f64;
    score += 30.0 * norm_pr * norm_pr * (1.0 - progress);

    // Tight fit reward: strongly favor bins where item fills most of residual
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill * fill;

    // Lookahead coupling: penalize if post_residual cannot host next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 8.0 * (pr - ni) / cap;
        } else {
            score += 12.0 * (ni - pr) / cap;
        }
        // smooth interaction between fill and lookahead
        score -= 5.0 * fill * (ni / cap);
    }

    // Last-chance bin: strong reward to use it instead of opening new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly early, more when many bins open
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * open_bins_count as f64 * (0.5 + progress);
        // but allow new bin if existing fits are terrible
        score -= 10.0 * (1.0 - fill);
    }

    // Mean residual coupling: prefer bins deviating from mean residual (consolidate)
    let dev = (pr - mean_residual).abs() / cap;
    score += 6.0 * dev * dev * progress;

    // Late-stream smooth tightening: prefer fuller placements as stream ends
    score -= 20.0 * progress * (1.0 - norm_pr);

    score
}

