    } else if frac <= 0.25 {
        score -= 80.0;
    } else if frac <= 0.5 {
        score -= 20.0;
    } else if frac <= 0.75 {
        score += 10.0;
    } else {
        score += 25.0;
    }

    // Modulo / integer-division harmonic classes on post_residual:
    // residuals that are multiples of common small item sizes are reusable.
    if post_residual > 0 {
        let reusable = (post_residual % 10 == 0) || (post_residual % 20 == 0) || (post_residual % 25 == 0);
        if reusable { score -= 30.0; }
        // dead zone: residual too small to ever fit anything (min item size unknown, assume >=1)
        let dead = post_residual < 4;
        if dead { score += 60.0; }
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits after this placement: great chaining
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 + 0.5 * slack;
            // harmonic class: post residual exactly equals next item (perfect chain)
            if next_item_size == post_residual { score -= 120.0; }
        } else if next_item_size <= bin_residual {
            // next item would have fit now but not after this placement: mild penalty
            score += 15.0;
        }
    } else {
        // last item of stream: prefer tightest fill
        score -= 50.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no
    // existing bin offers a decent fit.
    if bin_residual == bin_capacity {
        // baseline cost of a fresh bin
        score += 120.0;
        // but if many bins are open and mean residual is large, new bins are cheap-ish
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 0.3 * mean_residual * (1.0 - progress);
        if fitting_bins_count == 0 { score -= 200.0; } // no alternative
    }

    // Prefer consolidating into fewer bins when many are open.
    score += 2.0 * open_bins_count as f64;

    // Small tie-break toward bins with residual close to item size (best-fit flavor).
    score += 0.1 * (bin_residual - item_size) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
