pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "usable slots"
    // (multiples of common item sizes 10..40), penalize dead-space classes.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect closure
    } else {
        // modulo-arithmetic harmony classes
        let class_bonus = |m: u32, b: f64| -> f64 { if pr % m == 0 { b } else { 0.0 } };
        score -= class_bonus(10, 12.0) + class_bonus(20, 8.0) + class_bonus(25, 6.0)
            + class_bonus(50, 5.0) + class_bonus(100, 4.0);
        // dead-space penalty for awkward residuals (prime-ish / odd classes)
        if pr % 2 == 1 { score += 3.0; }
        if pr > 0 && pr < 10 { score += 8.0; } // tiny unusable sliver
        if pr > 50 && pr < 60 { score += 2.0; }
    }

    // Coupling with lookahead: if next item fits post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 18.0 + (next_item_size as f64) * 0.15;
            // harmonic match: next item lands exactly on residual class
            if pr % next_item_size.max(1) == 0 { score -= 10.0; }
        } else {
            // next item won't fit here: penalize proportionally to wasted capacity
            score += ((next_item_size - pr) as f64) * 0.10;
        }
    } else {
        // last item: closing bins is pure gain
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): penalize opening a new bin unless all
    // existing fits are terrible (large post_residual) or many bins are open.
    if bin_residual == bin_capacity {
        let avg_post = mean_residual - item_size as f64;
        let mut new_score = post_residual as f64 - 20.0;
        if avg_post > 40.0 { new_score -= 15.0; } // existing bins leave bad fits anyway
        if open_bins_count > 8 { new_score += 5.0 * (open_bins_count as f64 - 8.0).min(6.0); }
        // keep new-bin attractive only when item is large relative to capacity
        new_score -= (item_size as f64 / bin_capacity as f64) * 10.0;
        score = score.max(new_score);
        score += 14.0; // base bias: prefer filling existing bins
    }

    // Progress term: mild pressure to consolidate early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Small tie-break noise-free deterministic jitter via integer division class.
    score += ((pr / 7) % 3) as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post * post / cap;

    // Exact fill is ideal
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 330.0 / post;
    } else if post_residual < 12 {
        score += 90.0 + (12 - post_residual) as f64 * 6.0;
    } else {
        score -= 15.0 * (post / cap);
        if post_residual >= 40 { score -= 9.0; }
        if post_residual < 30 { score += 7.5 * (30 - post_residual) as f64 / 18.0; }
    }

    // Penalize small dead space generally
    if post > 0.0 && post < 0.25 * cap {
        score += 30.0 * (1.0 - post / (0.25 * cap));
    }

    let dead = post / cap;

    // Lookahead: chain fit with next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = post - nxt;
            let chain_tight = 1.0 - slack / cap;
            score -= 52.0 * chain_tight;
            if post == nxt { score -= 68.0; }
            if slack <= 2.0 { score -= 14.0; }
            else if slack <= 6.0 { score -= 18.0; }
            if slack >= 1.0 && slack <= mean_residual * 0.5 { score -= 8.0; }
            if (slack as u32) == mean_residual as u32 { score -= 9.0; }
            if slack >= 1.0 && slack < 12.0 { score -= 4.0; }
            if slack >= 1.0 && (slack as u32) >= next_item_size { score -= 10.0; }
            if post >= nxt + mean_residual { score -= 10.0; }
            if slack >= 1.0 && slack <= 4.0 { score -= 12.0; }
            // Tight two-step chain within mean residual
            if post_residual > 0 && slack <= 12.0 && slack <= mean_residual * 1.2 {
                score -= 7.0 * (1.0 - slack / 12.0);
            }
            // Near-exact two-item chain
            if slack <= 2.0 && dead > 0.4 { score -= 9.0; }
            // Residual stays usable for typical future items
            if post_residual >= 10 && post_residual <= 30 {
                score -= 6.0 * (1.0 - dead);
            }
            if post_residual > 0 && post_residual % 10 == 0 { score -= 5.0; }
            if post_residual > 0 && post_residual <= 25 && nxt > post_residual as f64 * 0.6 {
                score -= 13.0 * (1.0 - post_residual as f64 / 25.0);
            }
        } else if post + 10.0 >= nxt {
            score += 6.0;
            if (nxt - post) as u32 <= 2 && fitting_bins_count > 1 { score += 15.0; }
        } else {
            score += 0.06 * (nxt - post);
        }
        // Next item would strand this residual
        if nxt > post && post_residual > 0 && post_residual < 20 {
            score += 12.0;
        }
        if nxt > post && post_residual > 0 && post_residual < (next_item_size / 2).max(1) {
            score += 6.0 * (1.0 - post_residual as f64 / (next_item_size / 2).max(1) as f64);
        }
        if post_residual > 0 && post_residual < 16 && nxt > post && (mean_residual as u32) > post_residual {
            score += 9.0 * (16 - post_residual) as f64 / 8.0;
        }
        // Dead-space ratio penalty when next item strands a mid residual
        if nxt > post && dead > 0.35 && post > mean_residual * 1.5 && fitting_bins_count > 3 {
            score += 10.0 * (dead - 0.35);
        }
        // Residual just under next item is stranded
        if post_residual > 0 && nxt > post && post_residual >= (next_item_size * 3 / 4) && post_residual < next_item_size {
            score += 5.0 * (post_residual as f64 - nxt * 0.75) / (nxt * 0.25).max(1.0);
        }
        // Strand-aware bonus: residual next item almost (but not) fits is dead
        if nxt > post && post_residual > 0 && (nxt - post) <= 6.0 && post_residual >= item_size {
            score += 8.0 * (1.0 - (nxt - post) / 6.0);
        }
        if post_residual > 0 && post_residual < item_size && nxt > post && open_bins_count > 3 {
            score += 8.0;
        }
        if nxt > post && (nxt - post) as u32 > 20 && post_residual > 0 && post_residual < 20 {
            score += 12.0;
        }
    } else {
        score += post * 2.2;
    }

    // Sliver penalty when next item cannot use it
    if post_residual > 0 && post_residual < 8 && next_item_size > post_residual {
        score += 26.0;
    }

    // Last-chance bin: strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Many open bins: keep big residuals from hogging preference
    if fitting_bins_count > 4 && bin_residual != bin_capacity && post_residual > 30 {
        score += 3.0;
    }

    // Mean-residual relative comparison
    score -= 0.25 * (mean_residual - post);

    // Progress-aware fullness preference
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 8.0 * progress * dead;

    // New-bin candidate: only open when open bins are truly poor
    if bin_residual == bin_capacity {
        score += 18.0;
        if open_bins_count > 6 && progress > 0.5 {
            score -= 6.0;
        }
        // Don't open a new bin when some open bin gives a near-exact fit
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 4 {
            score += 40.0;
        }
        // Avoid opening new bins when an open bin can chain both current and next items
        if next_item_size > 0 && post_residual >= item_size + next_item_size {
            score += 25.0;
        }
        // Don't open new bins when an open bin leaves a residual >= next item
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 12 {
            score += 14.0;
        }
    }

    score
}

