    score += 0.8 * pressure * (0.5 + 0.5 * progress);

    // New-bin candidate: prefer it only when its residual dominates mean residual
    // and current bins would leave a tight unusable gap.
    if bin_residual == bin_capacity {
        score = 55.0 + 0.3 * mean_residual - 0.5 * (open_bins_count as f64);
        if post_residual >= next_item_size && next_item_size > 0 {
            score -= 10.0;
        }
    }

    score
}

