pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step lookahead fit: next item exactly fills post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0 + 0.5 * (post_residual as f64);
        } else if post_residual >= next_item_size {
            // Next item fits, but leaves a new residual: mild reward scaled by leftover size.
            let new_residual = post_residual - next_item_size;
            score -= 15.0 - (new_residual as f64) * 0.2;
        } else {
            // Next item will NOT fit here: penalize small unusable leftovers.
            let waste = post_residual as f64;
            if waste < next_item_size as f64 {
                score += (next_item_size - post_residual) as f64 * 0.8;
            }
            // Tiny dead space is worst (unusable by anything in 1..100 range).
            if waste < 10.0 {
                score += 25.0;
            }
        }
    }

    // Prefer bins whose residual is already tight relative to the mean (compact bins).
    score -= 0.6 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins would leave tiny waste.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let base = 55.0 + 20.0 * progress;
        score = base + item_size as f64 * 0.3;
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 70.0; // fresh bin enabling perfect next fit is attractive
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: must open
        }
    }

    // Slight bonus for filling a large fraction of the bin's capacity.
    score -= 0.15 * (item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post * post / cap; // quadratic pressure: big leftovers hurt more

    if post_residual == 0 {
        score -= 1000.0; // perfect fit dominates
    } else {
        // dead slivers: strong penalty scaled by how unusable they are
        if post_residual < 10 {
            score += 330.0 / post;
        } else if post_residual <= 20 {
            score += 6.0;
        } else if post_residual < 40 {
            score -= 4.0;
        } else {
            score -= 9.0;
        }
        // dead-space band under 25% of capacity
        if post < 0.25 * cap {
            score += 30.0 * (1.0 - post / (0.25 * cap));
        }
        // harmony of the leftover space (kept but softened)
        if post % 50 == 0 { score -= 6.0; }
        if post % 25 == 0 { score -= 4.0; }
    }

    // Lookahead: reward if next item chains into the leftover
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let chain_tight = 1.0 - (post - nxt) / cap;
            score -= 52.0 * chain_tight;
            if post_residual == next_item_size { score -= 68.0; } // exact chain fill
            if post_residual % next_item_size == 0 { score -= 18.0; } // harmonic chain
            let gap = post_residual - next_item_size;
            if gap <= 4 { score -= 12.0; }
            if gap <= 12 && (gap as f64) <= mean_residual * 1.2 {
                score -= 7.0 * (1.0 - gap as f64 / 12.0);
            }
            if post >= nxt + mean_residual { score -= 10.0; }
        } else {
            // next item won't fit here
            if post_residual > 0 && post_residual < 10 { score += 26.0; }
            if nxt - post <= 2.0 && fitting_bins_count > 1 { score += 15.0; }
            if nxt - post > 20.0 && post_residual < 20 { score += 12.0; }
            if post_residual < next_item_size / 2 {
                score += 6.0 * (1.0 - post_residual as f64 / (next_item_size / 2).max(1) as f64);
            }
            // near-miss: bin almost fits the next item; avoid burning it now
            if nxt - post <= 10.0 && post_residual >= next_item_size * 3 / 4 {
                score += 5.0 * (post_residual as f64 - nxt * 0.75) / (nxt * 0.25).max(1.0);
            }
            // large dead residual with slack elsewhere: deprioritize
            if post / cap > 0.35 && post_residual as f64 > mean_residual * 1.5 && fitting_bins_count > 3 {
                score += 10.0 * (post / cap - 0.35);
            }
        }
    } else {
        score += post * 2.2;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        score -= 20.0; // base cost of opening a bin
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * (1.0 - progress); // early: bins cheap; late: consolidate
        if mean_residual < item_size as f64 && open_bins_count > 2 {
            score += 10.0;
        }
        // many open bins with slack: prefer consolidating instead of new bin
        if open_bins_count > 5 && mean_residual > 0.4 * cap {
            score += 12.0;
        }
        // late in the stream, opening bins is expensive
        if progress > 0.7 { score += 8.0 * (progress - 0.7) / 0.3; }
    } else {
        // tightness pressure toward fuller bins
        let tightness = 1.0 - (bin_residual as f64 / cap);
        score -= 10.0 * tightness;
        // many fitting bins means this choice matters less; slight penalty for sloppy fits
        if fitting_bins_count > 4 && post_residual > 30 {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor small post-residuals.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize residuals that are too small to ever be useful again
    // (dead space: nothing in [1,100] range fits well... residual < 10 is truly dead,
    //  but small residuals like 1..9 waste capacity).
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual <= 20 {
        score += 6.0;
    }

    // Lookahead coupling: reward leaving exactly enough space for the next item,
    // penalize leaving space that neither fits the next item nor is useful.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            // next item fits here: bonus scaled by how snugly
            let snug = 1.0 - ((post_residual as f64 - nxt) / (bin_capacity as f64));
            score -= 12.0 * snug;
        } else {
            // next item won't fit in this residual; mild penalty
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins have poor fits (large post_residual) or many bins are open.
    if bin_residual == bin_capacity {
        // baseline cost of a fresh bin
        score = 55.0;
        // cheaper to open a new bin late in the stream? actually early stream:
        // fewer open bins means less fragmentation risk; slightly favor new bins early
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
        // if many bins are open with big mean residual, prefer reusing: raise new-bin cost
        score += 0.15 * open_bins_count as f64;
        score += 0.05 * mean_residual;
        // if the item is large, a fresh bin gives a perfect fit
        if item_size >= bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Prefer bins whose residual is close to the item (perfect fit) even among
    // non-new bins: reward small |bin_residual - item_size| relative to capacity.
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.1 * gap;

    // Slight preference for using more-filled bins (lower residual) overall.
    score += 0.05 * bin_residual as f64;

    // Time-horizon modulation: late in the stream, prioritize minimizing bins now
    // (favor existing bins), early stream allow more exploration.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: prefer tight fits (low post_residual), with a convex quadratic
    // that penalizes large dead space super-linearly.
    let mut score = pr + 40.0 * norm_pr * norm_pr * cap;

    // Smooth non-linear coupling of post-residual with stream progress:
    // early in the stream, dead space is tolerable (bins can still be filled);
    // late in the stream, dead space becomes costly.
    let progress_coupling = 60.0 * norm_pr * (progress * progress) * (1.0 - progress * 0.5);
    score += progress_coupling;

    // Reward bins whose post-residual smoothly matches the next item size
    // (a Gaussian-like affinity term, subtracted to reward good lookahead fit).
    if next_item_size > 0 {
        let gap = norm_pr - norm_next;
        let affinity = (gap * gap) * 120.0;
        score += affinity; // penalize mismatch; perfect match => zero penalty
        // Slight bonus when next item fits exactly into post-residual
        let fits_next = if pr >= next_item_size as f64 { -12.0 * (1.0 - gap.abs()) } else { 0.0 };
        score += fits_next;
    }

    // Last-chance pressure: if this is the only fitting bin, reward using it
    // to avoid opening a new bin (smoothly scaled by progress).
    if fitting_bins_count == 1 {
        score -= 25.0 + 30.0 * progress;
    }

    // Mild penalty for contributing to bin proliferation when many bins are open.
    score += (open_bins_count as f64).ln().max(0.0) * norm_pr * 8.0;

    // Smooth deviation from mean residual: bins far from the mean residual
    // (either very full or very empty) are slightly deprioritized.
    let mean_dev = (bin_residual as f64 - mean_residual) / cap;
    score += mean_dev.abs() * mean_dev.abs() * 20.0;

    // Encourage consolidating into nearly-full bins: reward small post-residual
    // with a saturating term.
    score -= 30.0 * (1.0 - (-norm_pr * 6.0).exp());

    // New-bin candidate handling: an empty bin has large post_residual, so the
    // quadratic above already penalizes it; add a smooth opening-cost term
    // that decays as the stream progresses (early on, new bins are cheaper).
    if bin_residual == bin_capacity {
        score += 10.0 + 40.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
