pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize dead space into capacity fractions.
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap_f;

    // Reward small post_residual, but only within "usable" classes.
    // Class boundaries: multiples of 1/8 of capacity.
    let class = (frac * 8.0).floor() as i32;
    let class_center = (class as f64 + 0.5) / 8.0;

    // Prefer residuals that land in low classes (tight packing).
    score += class_center * 12.0;

    // Modulo arithmetic on post_residual: residuals divisible by common item
    // granularities (10, 20, 25) are more likely reusable by future items.
    if post_residual % 10 == 0 {
        score -= 4.0;
    }
    if post_residual % 20 == 0 {
        score -= 2.0;
    }
    if post_residual % 25 == 0 {
        score -= 2.0;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        // Dead space below minimum item size is wasted.
        score += 15.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            // Reward proportionally to how well next item would fit.
            let slack = (post_residual - next_item_size) as f64;
            score -= (1.0 - slack / cap_f) * 6.0;
        } else {
            // Next item won't fit here: mild penalty for blocking a large residual.
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin; more so when many bins are open and mean
        // residual is high (existing space is plentiful).
        score += 40.0 + 3.0 * open_bins_count as f64 + mean_residual * 0.3;
        // Early in the stream, opening fresh bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 15.0;
    }

    // Global balance: prefer bins whose residual is near the mean (avoid
    // fragmenting one very tight bin while others stay loose).
    score += (bin_residual as f64 - mean_residual).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are tiny (unusable gaps)
    // are heavily penalized beyond their raw value.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward placements that leave room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Leaves a gap the next item cannot use -> dead space risk.
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: penalize spreading across many bins slightly.
    score += 0.4 * open_bins_count as f64;

    // Prefer bins tighter than average (best-fit flavor).
    score += (post_residual as f64 - mean_residual) * 0.5;

    // New-bin candidate: default moderate score; open a new bin only when
    // current item is large and would leave a bad gap in any existing bin.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 55.0 + 20.0 * progress;
        if item_size > 50 && fitting_bins_count > 0 {
            // large item: opening fresh bin is often fine
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 8.0; // new bin can host both items
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
