            score -= 52.0 * chain_tight;
            if slack == 0.0 { score -= 68.0; }
            if slack <= 2.0 { score -= 14.0; }
            else if slack <= 6.0 { score -= 18.0; }
            if slack >= 1.0 && slack <= mean_residual * 0.5 { score -= 8.0; }
            if slack >= 1.0 && (slack as u32) == mean_residual as u32 { score -= 9.0; }
            if slack >= 1.0 && slack < 12.0 { score -= 4.0; }
            // Two-step lookahead: residual after chaining still fits next item
            if slack >= 1.0 && (slack as u32) >= next_item_size {
                score -= 10.0;
            }
            // Borrowed from best: mid-residual keeps working space
            if post_residual > 0 && nxt > post_residual as f64 * 0.6 && post_residual <= 25 {
                score -= 13.0 * (1.0 - post_residual as f64 / 25.0);
            }
            if post_residual > 0 && post_residual % 10 == 0 { score -= 5.0; }
            if slack >= 1.0 && slack <= 12.0 && slack <= mean_residual * 1.2 {
                score -= 7.0 * (1.0 - slack / 12.0);
            }
            if slack <= 2.0 && post / cap > 0.4 { score -= 9.0; }
        } else if post + 10.0 >= nxt {
