pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post residual, non-linear).
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness * tightness;

    // Reward perfect fits overwhelmingly.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize small dead space that likely becomes unusable (< next item or < min item).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }
    if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        score += 6.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead synergy: reward if next item fits the post-residual (chaining).
