        let chain_fit = 1.0 - (post_residual as f64 - next_item_size as f64) / cap;
        score -= 8.0 * chain_fit;
    }

    // Penalize opening a new empty bin unless item is large relative to capacity
    // (large items waste less of a fresh bin) or few bins are open.
