        }
        // If no other bin fits, opening is necessary: soften penalty.
        if fitting_bins_count == 0 {
            new_bin_penalty *= 0.2;
        }
        score += new_bin_penalty;
    }

    // Mild preference for fuller bins among equals (reduce fragmentation).
    score -= 0.05 * (bin_residual as f64);

    score
}

