    score += dead * cap * (1.5 - 0.8 * progress);

    // Reward tight fits: strong subtraction when post_residual is small relative to item.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness * tightness * (1.0 + 0.5 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: penalize if next item can't use the post residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx > pr {
            score += 0.05 * (nx - pr) * (1.0 - progress);
        } else {
            score -= 0.05 * (pr - nx) * (1.0 - progress);
        }
    }

    // Mild pressure against proliferating bins with high mean residual.
    score += 0.02 * open_bins_count as f64 * (mean_residual / cap).max(0.0);

    // New-bin candidate: neutral-ish baseline, slightly penalized early, more attractive late.
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.4 * progress) - 15.0 * progress;
    }

    score
}

