pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which capacity-fraction band does the leftover fall in?
    let frac = post_residual as f64 / bin_capacity as f64;

    // Penalize large dead space (wasted capacity), non-linearly.
    if post_residual > 0 {
        score += (frac * frac) * 40.0;
    } else {
        // Perfect fill: strong reward.
        score -= 60.0;
    }

    // Integer-division thresholds on post_residual: tiny leftovers (<10) are dead space.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0; // unusable sliver
    }
    if post_residual >= 10 && post_residual < 20 {
        score -= 5.0; // still usable for smallest class
    }

    // Modulo arithmetic: classify post_residual into harmonic classes mod 10.
    let class = post_residual % 10;
    // Residuals that are multiples of 10 pair well with the smallest items (10..20).
    if class == 0 {
        score -= 8.0;
    } else if class >= 6 {
        score += (class as f64) * 1.5; // awkward off-class leftovers
    }

    // Lookahead coupling: does next_item_size fit in the post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Excellent: chains into this bin.
            let tight = (next_item_size as f64) / (post_residual as f64);
            score -= 10.0 + 15.0 * tight;
        } else {
            // Next item cannot use this leftover: dead space penalty grows with next item size.
            score += 0.15 * (next_item_size as f64);
        }
    }

    // Last-chance logic: if this is the only fitting bin, avoid forcing a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // Many options: prefer tighter fits, so mild penalty relative to alternatives.
        score += 0.5;
    }

    // New-bin candidate handling: empty bin gets a fixed opening cost so we only
    // open new bins when existing fits are poor.
    if bin_residual == bin_capacity {
        score += 55.0;
        // But if the item is large relative to typical residual, opening is more attractive.
        let fill_frac = item_size as f64 / bin_capacity as f64;
        score -= 30.0 * fill_frac;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0; // fresh bin can chain the next item too
        }
    }

    // Stream progression: late in the stream, prefer closing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - frac);

    // Prefer bins whose residual deviates favorably from the mean (tighter than average).
    score += 0.3 * ((post_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual that is too small to hold the minimum item (1..100 unknown,
    // but treat < 10 as near-dead) is wasted capacity.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 120.0 - pr * 8.0; // steep penalty in the dead zone
    }

    // Perfect fits are gold.
    if post_residual == 0 {
        score -= 200.0;
    } else if next_item_size > 0 && post_residual == next_item_size {
        // this bin becomes a perfect fit for the lookahead item
        score -= 90.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // placing here kills the lookahead's ability to reuse this bin
        score += 25.0;
    }

    // Reward tight fits relative to the item size (low waste ratio).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 30.0;

    // Open-bin pressure: with many bins open, prefer consolidating into
    // existing bins rather than opening new ones.
    let open_pressure = (open_bins_count as f64).ln().max(0.0) * 12.0;
    if bin_residual == bin_capacity {
        // Candidate is a brand-new empty bin: apply pressure so it only
        // wins when existing fits are genuinely bad.
        score += open_pressure + 40.0;
        // Late in the stream, be even more reluctant to open new bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 25.0;
    } else {
        // Existing bins get a mild bonus scaled by how many alternatives exist.
        if fitting_bins_count <= 1 {
            // last chance bin: strongly prefer using it over a new bin
            score -= 60.0;
        }
        score -= open_pressure * 0.5;
    }

    // Mean residual coupling: if average residual is high, we have slack
    // everywhere, so tolerate mediocre fits less (prefer tight packing).
    score += (mean_residual - pr).abs() * 0.15;

    // Small global tightening term to break ties toward fuller bins.
    score -= (bin_residual - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post * post / cap;

    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 330.0 / post; // near-perfect sliver: reward strongly
    } else if post_residual < 12 {
        score += 90.0 + (12 - post_residual) as f64 * 6.0;
    } else {
        score -= 15.0 * (post / cap);
        if post_residual >= 40 { score -= 9.0; }
        if post_residual < 30 { score += 7.5 * (30 - post_residual) as f64 / 18.0; }
    }

    if post > 0.0 && post < 0.25 * cap {
        score += 30.0 * (1.0 - post / (0.25 * cap));
    }

    // Lookahead: reward if next item chains into the leftover
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let chain_tight = 1.0 - (post - nxt) / cap;
            score -= 52.0 * chain_tight;
            if post == nxt { score -= 68.0; }
