    score += 3.0 * dev * dev * cap * 0.1;

    // Last-chance bonus: strongly favor the only fitting bin, smoothly scaled by progress
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Lookahead coupling: reward leaving space compatible with next item
