        score -= 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post * post / cap;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 900.0;
    } else if post_residual <= 5 {
        score -= 300.0 / post as f64;
    } else if post_residual < 12 {
        // Tiny unusable gaps: heavy penalty.
        score += 90.0 + (12 - post_residual) as f64 * 6.0;
    } else {
        score -= 15.0 * (post / cap);
        if post_residual >= 40 {
            score -= 9.0;
        }
        if post_residual < 30 {
            score += 7.5 * (30 - post_residual) as f64 / 18.0;
        }
    }

    // Dead-space pressure for small residuals relative to capacity.
    if post > 0.0 && post < 0.25 * cap {
        score += 30.0 * (1.0 - post / (0.25 * cap));
    }

    // Lookahead (k=1): reward leaving room for next item, penalize otherwise.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let chain_tight = 1.0 - (post - nxt) / cap;
            score -= 52.0 * chain_tight;
            if post == nxt {
                score -= 68.0;
            }
            if post >= nxt && (post - nxt) <= mean_residual * 0.5 {
                score -= 8.0;
            }
            if post - nxt >= 1.0 && post - nxt <= 4.0 {
                score -= 12.0;
            }
