        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 5.0 * progress;
    }

    // Mild preference for bins with residuals below the mean (balance load).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Prefer filling larger residual bins when many bins are open.
    score -= 0.02 * bin_residual as f64 * (open_bins_count.min(20) as f64 / 20.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let residual = bin_residual as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post * post / cap;

    // Perfect / near-perfect fit rewards.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 330.0 / post;
    } else if post_residual < 12 {
        score += 90.0 + (12 - post_residual) as f64 * 6.0;
    } else {
        score -= 15.0 * (post / cap);
        if post_residual >= 40 {
            score -= 9.0;
        }
        if post_residual < 30 {
            score += 7.5 * (30 - post_residual) as f64 / 18.0;
        }
    }

    // Tightness coupling.
    let fill_ratio = item / residual.max(1.0);
    score -= 24.0 * fill_ratio;

    // Fragmentation penalty for small residuals.
    if post > 0.0 && post < 0.25 * cap {
        score += 30.0 * (1.0 - post / (0.25 * cap));
    }

    // Lookahead chain-fit bonus.
    if next_item_size > 0 {
