    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post-residual (fraction of capacity left after placement)
    let pr_norm = post_residual as f64 / bin_capacity as f64;

    // Smooth non-linear coupling: waste penalty grows super-linearly with dead space,
    // and its weight increases with stream progress (late items need tight packing).
    let waste_coupling = pr_norm * pr_norm * (1.0 + progress * 3.0);
    score += 30.0 * waste_coupling;

    // Cubic interaction: very small residuals are either perfect fits (good) or dead space (bad),
    // resolved by whether the next item could use them.
    if next_item_size > 0 {
        let next_norm = next_item_size as f64 / bin_capacity as f64;
        let fit_gap = (pr_norm - next_norm).abs();
        score += 15.0 * fit_gap * fit_gap * (0.5 + progress);
        // Reward bins whose post-residual smoothly anticipates the next item
        if pr_norm >= next_norm {
            score -= 8.0 * (1.0 - (pr_norm - next_norm)) * (1.0 + progress);
        }
    } else {
        // Last item: prefer filling bins as completely as possible
        score -= 20.0 * (1.0 - pr_norm);
    }

    // Last-chance bonus: smooth reward when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - progress);
    }

    // Penalize spreading across too many open bins relative to mean residual (smooth coupling)
    let mean_pr = mean_residual / bin_capacity as f64;
    score += 5.0 * (pr_norm - mean_pr) * (pr_norm - mean_pr) * (open_bins_count as f64).sqrt();

    // Mild reward for tight fits (low post-residual) amplified late in the stream
    score -= 10.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * progress;

    // Prefer using existing bins over opening new ones, more so early on
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress) + 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
