pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo classes over capacity fractions
    let pr = post_residual;
    let class = pr % 10;
    // Penalize awkward residuals (dead space in "bad" harmonic classes)
    let class_penalty = match class {
        0 => -12.0,          // perfectly reusable (e.g. 50, 40, 30...)
        1 | 9 => 8.0,        // nearly useless slivers
        2 | 8 => 4.0,
        3 | 7 => 1.0,
        4 | 6 => -2.0,
        _ => 0.0,
    };
