    if next_item_size > 0 {
        if (next_item_size as u32) <= pr {
            score -= 6.0; // chain potential
            // harmonic match: next item divides residual nicely
            if pr % next_item_size.max(1) == 0 {
                score -= 5.0;
            }
        } else {
            // next item won't fit here; penalize leaving a large-but-blocked residual
            let gap = next_item_size as u32 - pr;
            if gap <= 10 {
                score += 5.0; // just barely blocked -> bad dead space
            }
        }
    }

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate handling: only attractive when current bins are badly fragmented
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let fragmentation = (mean_residual - bin_residual as f64).abs();
    if bin_residual as u32 == bin_capacity {
        // opening a new bin: penalize mildly, less when many bins are fragmented
        score = cap * 0.45 + fragmentation * 0.3 + progress * 5.0;
        if open_bins_count == 0 {
            score -= 50.0;
        }
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 10.0; // big item coming, fresh bin is useful
        }
    }

    // Mild bias toward bins whose residual differs from the mean (specialization)
    score += fragmentation * 0.05;

    // Tie-break with harmonic class of item itself
    let iclass = item_size % 10;
    if iclass == 0 {
        score -= 2.0; // round items pack predictably
    }

    score
}

