pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step match: post_residual equals next item size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 25.0 * (1.0 - diff / (bin_capacity as f64));
        // bonus for perfect match
        if post_residual == next_item_size {
            score -= 15.0;
        }
        // penalize leaving dead space too small for the next item
        if post_residual < next_item_size && post_residual > 0 {
            score += 8.0;
        }
    }

    // Penalize new-bin opening unless current bin would leave large dead space
    if bin_residual == bin_capacity {
        // new bin baseline: neutral residual; discourage slightly so good fits win
        score += 6.0;
        // but if no open bin fits well (last chance), encourage new bin when fit is terrible
        if post_residual > 0 && post_residual < 10 {
            score -= 12.0;
        }
    }

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // Penalize waste relative to mean residual (avoid fragmenting average bins)
    score += 0.05 * (post_residual as f64 - mean_residual).max(0.0);

    // Slight preference for tighter bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let residual = bin_residual as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post * post / cap;

    // Perfect / near-perfect fit rewards.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 330.0 / post;
    } else if post_residual < 12 {
        score += 90.0 + (12 - post_residual) as f64 * 6.0;
    } else {
        score -= 15.0 * (post / cap);
        if post_residual >= 40 {
            score -= 9.0;
        }
        if post_residual < 30 {
            score += 7.5 * (30 - post_residual) as f64 / 18.0;
        }
    }

    // Tightness coupling.
    let fill_ratio = item / residual.max(1.0);
    score -= 24.0 * fill_ratio;

    // Fragmentation penalty for small residuals.
    if post > 0.0 && post < 0.25 * cap {
        score += 30.0 * (1.0 - post / (0.25 * cap));
    }

    // Lookahead chain-fit bonus (combined with fine residual anticipation).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let chain_tight = 1.0 - (post - nxt) / cap;
            score -= 52.0 * chain_tight;
            if post == nxt {
                score -= 68.0;
            }
            if post - nxt < 6.0 {
                score -= 18.0;
            }
            if post >= nxt + mean_residual {
                score -= 10.0;
            }
            if (post - nxt) as u32 == mean_residual as u32 {
                score -= 9.0;
            }
            if post >= nxt && (post - nxt) <= mean_residual * 0.5 {
                score -= 8.0;
            }
            if post - nxt >= 1.0 && post - nxt <= 4.0 {
                score -= 12.0;
            }
            // Two-step lookahead — after placing next item, gap should stay reusable.
            let gap_after_next = post - nxt;
            if gap_after_next > 0.0 && gap_after_next < mean_residual {
                score += 10.0 * (1.0 - gap_after_next / mean_residual.max(1.0));
            }
            if gap_after_next >= mean_residual {
                score -= 6.0;
            }
            // NEW: gap after next item should still admit a typical item.
            if gap_after_next > 0.0 && gap_after_next < nxt * 0.5 {
                score += 7.0;
            }
        } else if post + 10.0 >= nxt {
            score += 6.0;
        } else {
            score += 0.06 * (nxt - post);
        }
        if nxt > post && (nxt - post) as u32 <= 2 && fitting_bins_count > 1 {
            score += 15.0;
        }
        if nxt > post && (nxt - post) as u32 > 20 && post_residual > 0 && post_residual < 20 {
            score += 12.0;
        }
    } else {
        score += post * 2.2;
    }

    // Dead-space penalty: residual too small for the next item.
    if post_residual > 0 && post_residual < 8 && next_item_size > post_residual {
        score += 26.0;
    }
    if post_residual > 0 && post_residual < 16 && next_item_size > post_residual && (mean_residual as u32) > post_residual {
        score += 9.0 * (16 - post_residual) as f64 / 8.0;
    }

    // Semi-fit lookahead.
    if post_residual > 0 && next_item_size as f64 <= post && next_item_size as f64 > post_residual as f64 * 0.6 && post_residual <= 25 {
        score -= 13.0 * (1.0 - post_residual as f64 / 25.0);
    }
    if post_residual > 0 && post_residual < item_size && next_item_size as f64 > post && open_bins_count > 3 {
        score += 8.0;
    }
    if post_residual > 0 && next_item_size as f64 > post && post_residual < (next_item_size / 2) {
        score += 6.0 * (1.0 - post_residual as f64 / (next_item_size / 2).max(1) as f64);
    }
    if post_residual > 0 && post_residual % 10 == 0 && next_item_size as f64 <= post {
        score -= 5.0;
    }
    let dead = post / cap;
    if post_residual > 0 && next_item_size as f64 > post && dead > 0.35 && (post_residual as f64) > mean_residual * 1.5 && fitting_bins_count > 3 {
        score += 10.0 * (dead - 0.35);
    }
    if post_residual > 0 && next_item_size as f64 <= post && (post - next_item_size as f64) <= 2.0 && dead > 0.4 {
        score -= 9.0;
    }
    // Borrowed from best: near-exact chain fit scaled by mean residual.
    if post_residual > 0 && next_item_size as f64 <= post && (post - next_item_size as f64) <= 12.0 && (post - next_item_size as f64) <= mean_residual * 1.2 {
        score -= 7.0 * (1.0 - (post - next_item_size as f64) / 12.0);
    }
    if post_residual > 0 && next_item_size > post_residual && post_residual >= (next_item_size * 3 / 4) && post_residual < next_item_size {
        score += 5.0 * (post_residual as f64 - next_item_size as f64 * 0.75) / (next_item_size as f64 * 0.25).max(1.0);
    }
    if fitting_bins_count > 4 && bin_residual != bin_capacity && post_residual > 30 {
        score += 3.0;
    }

    // Last-chance pressure.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    } else if fitting_bins_count <= 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Consolidation pressure.
    score += (open_bins_count as f64) * 1.5;

    // Mean-residual coupling.
    if residual < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score += 120.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 100.0 * progress;
        score += 10.0 * (open_bins_count as f64);
        if fitting_bins_count > 1 {
            score += 100.0 * (fitting_bins_count as f64 - 1.0);
        }
        score += 0.5 * mean_residual;
        if item_size < (bin_capacity / 2) {
            score += 12.0;
            if next_item_size > 0 && (next_item_size as f64) <= post {
                score += 20.0;
            }
        }
        // Huge items deserve fresh bins when residuals are small.
        if item > 0.8 * cap && mean_residual < item * 0.9 {
            score -= 200.0;
        }
        // Medium-large items late in stream when no open bin fits the next item.
        if item > 0.5 * cap && next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 120.0;
        }
        // Fresh bin for medium items when all open residuals are nearly dead.
        if item <= 0.5 * cap && open_bins_count > 2 && mean_residual < item * 0.55 && fitting_bins_count > 0 {
            score -= 45.0;
        }
        // NEW: early stream — keep bins consolidated, resist opening new bins.
        if progress < 0.25 && item <= 0.4 * cap {
            score += 40.0;
        }
    } else if open_bins_count > 3 && residual > 2.0 * mean_residual {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size).
    let fit_ratio = post_residual as f64 / (item_size.max(1) as f64);
    score -= 6.0 * (1.0 - fit_ratio).max(0.0) * (bin_capacity as f64 / 100.0);

    // Penalize dead space: post residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: if the next item fits perfectly in the post residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_tightness = (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 8.0 * (1.0 - chain_tightness);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't chain here; mild penalty proportional to wasted potential.
        score += 2.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 {
        score -= 10.0;
    } else if fitting_bins_count > 1 {
        // Many candidates: prefer the one that preserves bin diversity (larger residual).
        score += 1.5 * (post_residual as f64 / bin_capacity as f64);
    }

    // Global state: when many open bins exist, prefer consolidation into emptier bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if open_bins_count > 4 {
        score += (mean_residual - post_residual as f64).abs() * 0.5 * progress;
    }

    // Time horizon: early in the stream, opening new bins is cheap (favor exploration);
    // late in the stream, packing density matters more.
    score -= 3.0 * (1.0 - progress) * (bin_residual as f64 / bin_capacity as f64);
    score += 2.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: opening a new bin is attractive only if current bin
    // fit is poor (large post_residual) or the item nearly fills the new bin.
    if bin_residual == bin_capacity {
        let fill_fraction = item_size as f64 / bin_capacity as f64;
        let early = 1.0 - progress;
        score = 30.0 - 25.0 * fill_fraction - 6.0 * early;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 5.0;
        }
        if fitting_bins_count <= 1 {
            score += 5.0; // don't abandon the last-chance bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    // Quadratic dead-space base: small residuals hurt much more
    let mut score = post * post / cap;

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 330.0 / post;
    } else if post_residual < 12 {
        score += 90.0 + (12 - post_residual) as f64 * 6.0;
    } else {
        score -= 15.0 * (post / cap);
        if post_residual >= 40 {
            score -= 9.0;
        }
        if post_residual < 30 {
            score += 7.5 * (30 - post_residual) as f64 / 18.0;
        }
    }

    // Dead space relative to capacity
    if post > 0.0 && post < 0.25 * cap {
        score += 30.0 * (1.0 - post / (0.25 * cap));
    }

    // Lookahead chain logic
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let chain_tight = 1.0 - (post - nxt) / cap;
            score -= 52.0 * chain_tight;
            if post == nxt {
                score -= 68.0;
            }
            if post >= nxt + mean_residual {
                score -= 10.0;
            }
            if post - nxt >= 1.0 && post - nxt <= 4.0 {
                score -= 12.0;
            }
            if nxt <= post && post - nxt < 6.0 {
                score -= 18.0;
            }
        } else if post + 10.0 >= nxt {
            score += 6.0;
        } else {
            score += 0.06 * (nxt - post);
        }
        // Next item barely misses this bin while other bins fit: mild penalty for hoarding gap
        if nxt > post && (nxt - post) as u32 <= 2 && fitting_bins_count > 1 {
            score += 15.0;
        }
        if nxt > post && (nxt - post) as u32 > 20 && post_residual > 0 && post_residual < 20 {
            score += 12.0;
        }
    } else {
        score += post * 2.2;
    }

    // Tiny unusable gap that next item cannot use
    if post_residual > 0 && post_residual < 8 && next_item_size > post_residual {
        score += 26.0;
    }
    if post_residual > 0 && post_residual < 16 && next_item_size > post_residual && (mean_residual as u32) > post_residual {
        score += 9.0 * (16 - post_residual) as f64 / 8.0;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Mean residual coupling
    score -= (mean_residual - post) * 0.3;

    // New-bin candidate: penalize more when many bins already open and gap is decent
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64 * (1.0 + 0.4 * progress);
        score += 20.0 + open_pressure;
    }

