pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on residual space.
    let pr = post_residual as i64;
    let cap = bin_capacity as i64;
    let half = cap / 2;
    let quarter = cap / 4;

    // Residuals in "dead zone" (small, hard-to-fill) get penalized.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }
    // Perfectly harmonic residuals (multiples of 10) are attractive.
    if pr % 10 == 0 {
        score -= 8.0;
    }
    if pr % 20 == 0 {
        score -= 6.0;
    }
    if pr % 25 == 0 {
        score -= 5.0;
    }

    // Quarter/half-fill harmonic classes: leaving exactly half is excellent.
    if pr == half {
        score -= 12.0;
    } else if pr == quarter || pr == 3 * quarter {
        score -= 7.0;
    }

    // Integer-division threshold on post_residual: how many items of typical
    // size (>=10) could still land here.
    let slots = pr / 10;
    score -= slots as f64 * 2.0;

    // Lookahead coupling: if the next item fits the post residual exactly
    // or harmonically, strongly favor this bin.
    if next_item_size > 0 {
        let ni = next_item_size as i64;
        if pr >= ni {
            let gap = pr - ni;
            if gap == 0 {
                score -= 30.0;
            } else if gap % 10 == 0 {
                score -= 14.0;
            } else if gap < 10 {
                score += 10.0; // creates dead space for the next item
            }
        } else {
            // Next item cannot use this residual: mild penalty scaled by gap.
            score += (ni - pr).min(40) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the item
    // is large or the fit in existing bins is poor.
    if bin_residual == bin_capacity {
        let tight = item_size as f64 / bin_capacity as f64;
        score += 18.0 - tight * 15.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0; // a fresh bin can serve the next item too
        }
    }

    // Stream progression: early on, be conservative (favor existing bins);
    // later, allow slightly more aggressive consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0;

    // Deviation from mean residual: prefer bins whose residual is close to
    // the mean (balanced packing), penalize outliers.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Mild penalty for too many open bins relative to residual wealth.
    if open_bins_count > 4 && mean_residual < 30.0 {
        score += 4.0;
    }

    score
}

