    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // to future items (which are >= 1, but small gaps < ~15 are rarely reusable
    // given typical item sizes) are heavily penalized.
    if post_residual > 0 {
        let dead = if post_residual < 15 {
            (15 - post_residual) as f64 * 3.0
        } else if post_residual < 25 {
            ((25 - post_residual) as f64) * 1.2
        } else {
            0.0
        };
        score += dead;
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits relative to residual (high fill ratio).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 15.0;

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing bins; opening new bins becomes less attractive.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let bin_pressure = (open_bins_count as f64).ln().max(0.0) * (2.0 + 3.0 * progress);
