        score += 10.0 * (dead - 0.35);
    }
    if post_residual > 0 && next_item_size as f64 <= post && (post - next_item_size as f64) <= 2.0 && dead > 0.4 {
        score -= 9.0;
    }
    if fitting_bins_count > 4 && bin_residual != bin_capacity && post_residual > 30 {
        score += 3.0;
    }

    // Last-chance pressure.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    } else if fitting_bins_count <= 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Consolidation pressure.
    score += (open_bins_count as f64) * 1.5;

    // Mean-residual coupling.
    if residual < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score += 120.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 100.0 * progress;
        score += 10.0 * (open_bins_count as f64);
        if fitting_bins_count > 1 {
            score += 100.0 * (fitting_bins_count as f64 - 1.0);
        }
        score += 0.5 * mean_residual;
        if item_size < (bin_capacity / 2) {
            score += 12.0;
            if next_item_size > 0 && (next_item_size as f64) <= post {
                score += 20.0;
            }
        }
        // Huge items deserve fresh bins when residuals are small.
        if item > 0.8 * cap && mean_residual < item * 0.9 {
            score -= 200.0;
        }
        // Medium-large items late in stream when no open bin fits the next item.
        if item > 0.5 * cap && next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 120.0;
        }
        // Fresh bin for medium items when all open residuals are nearly dead.
        if item <= 0.5 * cap && open_bins_count > 2 && mean_residual < item * 0.55 && fitting_bins_count > 0 {
            score -= 45.0;
        }
        // Fresh-bin cost scales with how well the item could fit an existing bin.
        if fitting_bins_count > 0 && residual_fit_quality(item, mean_residual) > 0.7 {
            score += 60.0;
        }
    } else if open_bins_count > 3 && residual > 2.0 * mean_residual {
        score += 15.0;
    }

    score
}

fn residual_fit_quality(item: f64, mean_residual: f64) -> f64 {
    if mean_residual <= 0.0 { return 0.0; }
    (item / mean_residual).min(1.0)
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let p2 = progress * progress;
    let p3 = p2 * progress;
    // Early stream: mild penalty on residual; late stream: strong penalty to tighten packing.
    let tightness = 1.0 + 3.0 * progress + 2.0 * p2 + p3;
    score += 8.0 * (norm_pr * norm_pr) * tightness * cap;

    // Reward near-perfect fits smoothly (quadratic trough at norm_pr ~ 0).
    score -= 12.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * cap * (0.5 + 0.5 * progress);

    // Coupling residual with mean residual across open bins: prefer bins deviating below mean.
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev * cap - 3.0 * dev * cap;

    // Lookahead coupling: reward residual that matches the next item size (smooth Gaussian-like).
    if next_item_size > 0 {
        let diff = norm_pr - norm_next;
        score -= 10.0 * (-diff * diff * 40.0).exp() * cap;
        // Penalize leaving residual too small for the next item (dead space).
        if pr < next_item_size as f64 {
            score += (next_item_size as f64 - pr) * (1.0 + 2.0 * progress);
        }
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // New-bin candidate: smooth penalty that relaxes with progress and item size,
    // so opening a new bin is only preferred for large items late in stream.
    if bin_residual == bin_capacity {
        let relax = 0.6 + 0.4 * (1.0 - norm_item);
        score += (18.0 + 30.0 * (1.0 - progress) * relax) * cap * 0.1;
        score -= 6.0 * norm_item * cap * progress;
    }

    // Mild penalty for spreading across many open bins.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post * post / cap;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 330.0 / post;
    } else if post_residual < 12 {
        // Small dead space: strong penalty scaled by closeness.
        score += 90.0 + (12 - post_residual) as f64 * 6.0;
    } else {
        score -= 15.0 * (post / cap);
        if post_residual >= 40 {
            score -= 9.0;
        }
        if post_residual < 30 {
            score += 7.5 * (30 - post_residual) as f64 / 18.0;
        }
    }

    // Penalize residuals too small for typical items (dead space fraction).
    if post > 0.0 && post < 0.25 * cap {
        score += 30.0 * (1.0 - post / (0.25 * cap));
    }

    // Lookahead chaining with the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let chain_tight = 1.0 - (post - nxt) / cap;
            score -= 52.0 * chain_tight;
            if post == nxt {
                score -= 68.0;
            }
            if post >= nxt + mean_residual {
                score -= 10.0;
            }
            if post - nxt >= 1.0 && post - nxt <= 4.0 {
                score -= 12.0;
            }
            if post - nxt <= mean_residual * 0.5 {
                score -= 8.0;
            }
        } else if post + 10.0 >= nxt {
            score += 6.0;
        } else {
            score += 0.06 * (nxt - post);
        }
        // Next item won't fit here and residual is tiny: waste.
        if post_residual > 0 && post_residual < 8 && nxt > post_residual {
            score += 26.0;
        }
        if post_residual > 0 && post_residual < 16 && nxt > post_residual && (mean_residual as u32) > post_residual {
            score += 9.0 * (16 - post_residual) as f64 / 8.0;
        }
        // Barely-missed fit: keep bin alive for a slightly smaller future item.
        if nxt > post_residual && post_residual >= (next_item_size * 3 / 4) && post_residual < next_item_size {
            score += 5.0 * (post_residual as f64 - nxt * 0.75) / (nxt * 0.25).max(1.0);
        }
        if nxt > post && (nxt - post) as u32 <= 2 && fitting_bins_count > 1 {
            score += 15.0;
        }
    } else {
        score += post * 2.2;
    }

    // Last-chance bin: avoid opening a new one when this is the only fit.
    if fitting_bins_count == 1 {
        score -= 10.0;
    } else if fitting_bins_count > 4 && bin_residual != bin_capacity && post_residual > 30 {
        score += 3.0;
    }

    // Global consolidation pressure as the stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if open_bins_count > 3 && post_residual > 0 && next_item_size as f64 > post && post_residual < item_size {
        score += 8.0;
    }

    // New-bin candidate: only open a new bin when the item nearly fills it
    // or all existing fits are terrible.
    if bin_residual == bin_capacity {
        let fill_fraction = item_size as f64 / cap;
        let early = 1.0 - progress;
        score = 30.0 - 25.0 * fill_fraction - 6.0 * early;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 5.0;
        }
        if fitting_bins_count <= 1 {
            score += 5.0;
        }
        if fill_fraction > 0.7 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit).
    // Harmonic class: post_residual bucketed by integer division thresholds.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit, huge reward
    } else if pr <= 10 {
        score -= 25.0;
    } else if pr <= 20 {
        score -= 10.0;
    } else if pr <= 30 {
        score -= 3.0;
    } else {
        // large dead space penalty, superlinear
        score += (pr as f64 - 30.0) * 0.6;
    }

    // Modulo arithmetic on post_residual: residuals that are "friendly"
    // to common item sizes (multiples of 5/10) are more reusable.
    let friendly = pr % 10 == 0 || pr % 5 == 0;
    if friendly { score -= 6.0; } else { score += 4.0; }

    // Coupling with next item: reward if post_residual exactly or nearly
    // accommodates the lookahead item.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size < pr {
            let slack = pr - next_item_size;
            if slack <= 10 { score -= 18.0; }
            else if slack <= 20 { score -= 8.0; }
            else { score += slack as f64 * 0.15; }
        } else {
            // lookahead won't fit here; mildly penalize
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize so it only wins when fits are terrible.
    if bin_residual == bin_capacity {
        score += 45.0;
        // but if current item is huge and would leave tiny unusable residue elsewhere,
        // new bin becomes attractive
        if pr <= 5 && item_size >= 60 { score -= 55.0; }
    }

    // Stream progression: late in stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 8.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));

    // Prefer filling bins with above-mean residual (balance avoidance of many near-empty bins).
    if bin_residual > bin_capacity && false { score += 0.0; }
    if (bin_residual as f64) > mean_residual && bin_residual < bin_capacity {
        score -= 4.0;
    }

    // Many open bins: discourage spreading; reward compacting into existing bins.
    if open_bins_count > 4 && bin_residual < bin_capacity {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that are too small to be
    // useful for typical future items are heavily penalized.
    let gap = post_residual as f64;
    if gap > 0.0 {
        // A gap is "dead" if it cannot fit even a small future item (<= 20)
        // or if it is an awkward mid-range sliver.
        if gap < 20.0 {
            score += 40.0 * (1.0 - gap / 20.0); // tiny slivers are worst
        } else if gap < 35.0 {
            score += 12.0; // awkward zone: fits only small items
        } else if gap < 55.0 {
            score += 3.0; // moderately useful
        }
        // Perfect or near-perfect fits are strongly rewarded.
        if gap == 0.0 {
            score -= 30.0;
        } else if gap <= 5.0 {
            score -= 10.0;
        }
    }

    // Lookahead coupling: if the next item fits into the post residual,
    // this placement is excellent (chain packing).
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 15.0;
            // Exact chain fit bonus
            if post_residual == next_item_size {
                score -= 10.0;
            }
        } else {
            // Next item won't fit here; residual becomes potential dead space.
            score += 8.0 * (gap / capacity);
        }
    }

    // Open-bin pressure: discourage opening/using many bins simultaneously
    // when few are needed; encourage consolidation when bins are plentiful.
    let pressure = open_bins_count as f64;
    score += 0.8 * pressure;

    // Mean-residual coupling: bins whose residual deviates favorably from
    // the mean (i.e., we consume the excess) are preferred.
    score -= 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, using it avoids
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mild preference for filling existing bins more as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - gap / capacity);

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        score += 20.0 + 2.0 * pressure;
        if fitting_bins_count <= 1 {
            score -= 15.0;
        }
    }

    score
}

