pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Aggressive 2-step lookahead: if the next item fits exactly into the
    // post residual, strongly favor this bin.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs();
        if post_residual == next_item_size {
            score -= 25.0; // perfect 2-step match
        } else if (post_residual as u32) >= next_item_size {
            // next item fits, prefer small leftover after that
            let second_left = post_residual - next_item_size;
            score -= 18.0 * (1.0 - (second_left as f64) / (bin_capacity as f64));
        } else {
            // next item won't fit: mild penalty scaled by how much it misses
            let miss = (next_item_size as f64 - post_residual as f64) / (bin_capacity as f64);
            score += 10.0 * miss;
        }
        let _ = gap;
    }

    // Penalize residuals far from mean (dead space outlier bins).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when reasonable open bins exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_pressure = mean_residual / (bin_capacity as f64);
        score += 15.0 + 20.0 * (1.0 - progress) * (0.5 + avg_pressure);
        // but if nothing fits well anywhere, new bin is fine
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
        // large items prefer fresh bins
        if item_size > bin_capacity / 2 {
            score -= 12.0;
        }
    }

    // Prefer bins that are already fairly full (waste less space overall).
    let fill = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * fill;

    score
