    // or residual capacity is plentiful, less so late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = mean_residual / bin_capacity as f64;
        score += 55.0 + 10.0 * open_bins_count as f64 - 30.0 * progress + 40.0 * waste;
    }

    // Mild preference for bins with residual near mean (balance load).
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;
    let is_new = if bin_residual == bin_capacity { 1.0 } else { 0.0 };

    // Base: post residual, with non-linear polynomial coupling to progress
    let mut score = pr
        + 12.0 * prn * prn * cap
        - 20.0 * prn * prn * prn * cap * progress;

    // Tight fits rewarded, dead space penalized more late in stream
    let tightness = 1.0 - prn;
    score -= 15.0 * tightness * tightness * (0.5 + progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 && is_new == 0.0 {
        score -= 25.0 + 10.0 * progress;
    }

    // Lookahead: reward if next item fits residual, penalize otherwise
    if next_item_size > 0 {
        let fits = if (next_item_size as f64) <= pr { 1.0 } else { 0.0 };
        score += (1.0 - fits) * 18.0 * (1.0 - progress)
            - fits * 8.0 * prn;
    }

    // New-bin penalty grows with number of open bins and early stream
    score += is_new * (10.0 + 4.0 * open_bins_count as f64 + 15.0 * (1.0 - progress));

