            }
            // Two-step lookahead: gap after next item stays reusable.
            let gap_after_next = post - nxt;
            if gap_after_next > 0.0 && gap_after_next < mean_residual {
                score += 10.0 * (1.0 - gap_after_next / mean_residual.max(1.0));
            }
            if gap_after_next >= mean_residual {
                score -= 6.0;
            }
            // NEW: exact multi-fit anticipation — gap fits next item plus a small remainder.
            if gap_after_next > 0.0 && nxt > 0.0 && gap_after_next % nxt.max(1.0) == 0.0 {
                score -= 14.0;
            }
        } else if post + 10.0 >= nxt {
            score += 6.0;
        } else {
            score += 0.06 * (nxt - post);
        }
        if nxt > post && (nxt - post) as u32 <= 2 && fitting_bins_count > 1 {
