        score += 26.0;
    }
    if post_residual > 0 && post_residual < 16 && next_item_size > post_residual && (mean_residual as u32) > post_residual {
        score += 9.0 * (16 - post_residual) as f64 / 8.0;
    }

    // Semi-fit lookahead.
    if post_residual > 0 && next_item_size as f64 <= post && next_item_size as f64 > post_residual as f64 * 0.6 && post_residual <= 25 {
        score -= 13.0 * (1.0 - post_residual as f64 / 25.0);
    }
    if post_residual > 0 && post_residual < item_size && next_item_size as f64 > post && open_bins_count > 3 {
        score += 8.0;
    }
    if post_residual > 0 && next_item_size as f64 > post && post_residual < (next_item_size / 2) {
        score += 6.0 * (1.0 - post_residual as f64 / (next_item_size / 2).max(1) as f64);
    }
    if post_residual > 0 && post_residual % 10 == 0 && next_item_size as f64 <= post {
        score -= 5.0;
    }
    let dead = post / cap;
    if post_residual > 0 && next_item_size as f64 > post && dead > 0.35 && (post_residual as f64) > mean_residual * 1.5 && fitting_bins_count > 3 {
        score += 10.0 * (dead - 0.35);
    }
    if post_residual > 0 && next_item_size as f64 <= post && (post - next_item_size as f64) <= 2.0 && dead > 0.4 {
        score -= 9.0;
    }
    // NEW: near-fit gap penalty scaled by mean residual.
    if post_residual > 0 && next_item_size as f64 <= post && (post - next_item_size as f64) <= 12.0 && (post - next_item_size as f64) <= mean_residual * 1.2 {
        score -= 7.0 * (1.0 - (post - next_item_size as f64) / 12.0);
    }
    // NEW: residual that could hold 3/4 of next item gets a partial-credit bonus.
    if post_residual > 0 && next_item_size > post_residual && post_residual >= (next_item_size * 3 / 4) && post_residual < next_item_size {
        score += 5.0 * (post_residual as f64 - next_item_size as f64 * 0.75) / (next_item_size as f64 * 0.25).max(1.0);
    }
    if fitting_bins_count > 4 && bin_residual != bin_capacity && post_residual > 30 {
        score += 3.0;
    }

    // Last-chance pressure.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    } else if fitting_bins_count <= 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Consolidation pressure.
    score += (open_bins_count as f64) * 1.5;

    // Mean-residual coupling.
    if residual < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score += 120.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 100.0 * progress;
        score += 10.0 * (open_bins_count as f64);
        if fitting_bins_count > 1 {
            score += 100.0 * (fitting_bins_count as f64 - 1.0);
        }
        score += 0.5 * mean_residual;
        if item_size < (bin_capacity / 2) {
            score += 12.0;
            if next_item_size > 0 && (next_item_size as f64) <= post {
                score += 20.0;
            }
        }
        // Huge items deserve fresh bins when residuals are small.
        if item > 0.8 * cap && mean_residual < item * 0.9 {
            score -= 200.0;
        }
        // Medium-large items late in stream when no open bin fits the next item.
        if item > 0.5 * cap && next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 120.0;
        }
        // Fresh bin for medium items when all open residuals are nearly dead.
        if item <= 0.5 * cap && open_bins_count > 2 && mean_residual < item * 0.55 && fitting_bins_count > 0 {
            score -= 45.0;
        }
        // NEW: fresh bin when placing item would strand a nearly-dead residual.
        if item <= 0.5 * cap && open_bins_count > 1 && post_residual > 0 && (post_residual as f64) < mean_residual * 0.4 {
            score -= 25.0;
        }
    } else if open_bins_count > 3 && residual > 2.0 * mean_residual {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Baseline: prefer tight fits (small post_residual), but scale by progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect match: next item exactly fills the residual -> huge reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0 + 80.0 * progress;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportional to how snugly it fits afterwards.
            let two_step_residual = (post_residual - next_item_size) as f64;
            score -= 40.0 - 0.35 * two_step_residual;
        } else {
            // Next item won't fit here: penalize leftover that is likely dead space,
            // especially when the leftover is small (unusable).
            let gap = (next_item_size - post_residual) as f64;
            if post_residual < 10 {
                score += 60.0; // tiny dead space, very undesirable
            } else {
                score += 0.15 * gap;
            }
        }
    }

    // Reward bins that are already well-used (small residual relative to mean).
    score += 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    score += 2.0 * open_bins_count as f64;

    // Late in the stream, tighten placements further.
    score *= 1.0 + 0.5 * progress;

    // New-bin candidate: neutral-ish baseline so it only wins when fits are bad.
    if bin_residual == bin_capacity {
        score = 55.0 + 20.0 * progress - 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize small unusable leftovers, scaled by whether next item could use them
    if post_residual > 0 {
        let dead = if next_item_size > 0 && post_residual >= next_item_size {
            0.0
        } else {
            1.0
        };
        score += dead * (post_residual as f64).sqrt() * 3.0;
    }

    // Reward bins whose residual is close to item size (tight fit)
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * 40.0;

    // Lookahead: if next item fits in post_residual, bonus
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // Lookahead conflict: next item fits better in a tighter residual
    if next_item_size > 0 && bin_residual >= next_item_size && post_residual < next_item_size {
        score += 8.0; // this bin is the only one that can chain
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Crowding: many open bins -> prefer filling existing ones
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64).ln().max(0.0) * 5.0 * (0.5 + progress);

    // Mean residual coupling: if this bin's residual deviates high from mean, penalize mildly
    score += ((bin_residual as f64) - mean_residual) * 0.2;

    // New-bin candidate: make it attractive only when fits are poor
    if bin_residual == bin_capacity {
        let poor_fit = if fitting_bins_count <= 1 { 0.0 } else { 30.0 };
        score = 95.0 + poor_fit - progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post * post / cap; // quadratic pressure: big leftovers hurt more

    if post_residual == 0 {
        score -= 1000.0; // perfect fit dominates
    } else {
        // Harmony of the leftover space
        if post % 10 == 0 { score -= 12.0; }
        if post % 20 == 0 { score -= 8.0; }
        if post % 25 == 0 { score -= 8.0; }
        if post % 50 == 0 { score -= 6.0; }
        if post_residual < 10 {
            score += 330.0 / post; // dead sliver: strong penalty
        } else if post_residual <= 20 {
            score += 6.0; // marginal
        } else if post_residual < 40 {
            score -= 4.0; // useful band
        } else {
            score -= 9.0; // large leftover is still usable
        }
        // dead-space band under 25% of capacity
        if post < 0.25 * cap {
            score += 30.0 * (1.0 - post / (0.25 * cap));
        }
        // borrowed from best: reward small usable residuals more aggressively
        if post_residual >= 5 && post_residual < 12 {
            score -= 3.0 * (12 - post_residual) as f64;
        }
        if post_residual >= 40 {
            score -= 4.0;
        }
    }

    // Lookahead: reward if next item chains into the leftover
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let chain_tight = 1.0 - (post - nxt) / cap;
            score -= 52.0 * chain_tight;
            if post_residual == next_item_size { score -= 68.0; } // exact chain fill
            if post_residual % next_item_size == 0 { score -= 18.0; } // harmonic chain
            if (post_residual - next_item_size) % 10 == 0 { score -= 6.0; }
            if post_residual - next_item_size <= 4 { score -= 12.0; } // near-perfect chain
            if post >= nxt + mean_residual { score -= 10.0; }
            if (post - nxt) <= mean_residual * 0.5 { score -= 8.0; }
            if post - nxt < 6.0 { score -= 18.0; }
            if (post_residual as f64 - nxt) as u32 == mean_residual as u32 { score -= 9.0; }
            if post_residual <= 25 && next_item_size as f64 > post_residual as f64 * 0.6 {
                score -= 13.0 * (1.0 - post_residual as f64 / 25.0);
            }
        } else {
            // next item won't fit here
            if post_residual > 0 && post_residual < 10 { score += 26.0; }
            if nxt - post <= 2.0 && fitting_bins_count > 1 { score += 15.0; }
            if nxt - post > 20.0 && post_residual < 20 { score += 12.0; }
            if post_residual < next_item_size / 2 {
                score += 6.0 * (1.0 - post_residual as f64 / (next_item_size / 2).max(1) as f64);
            }
            if post_residual > 0 && post_residual < item_size && open_bins_count > 3 { score += 8.0; }
        }
    } else {
        score += post * 2.2;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        score -= 20.0; // base cost of opening a bin
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * (1.0 - progress); // early: bins cheap; late: consolidate
        if mean_residual < item_size as f64 && open_bins_count > 2 {
            score += 10.0;
        }
        // many open bins with slack: prefer consolidating instead of new bin
        if open_bins_count > 5 && mean_residual > 0.4 * cap {
            score += 12.0;
        }
        // late stream: opening new bins is expensive, tighten further
        if progress > 0.6 && open_bins_count > 3 {
            score += 8.0;
        }
    } else {
        // tightness pressure toward fuller bins
        let tightness = 1.0 - (bin_residual as f64 / cap);
        score -= 10.0 * tightness;
        // many fitting bins means this choice matters less; slight penalty for sloppy fits
        if fitting_bins_count > 4 && post_residual > 30 {
            score += 3.0;
        }
        // penalize leaving dead space when next item is much larger than residual
        if post_residual > 0 && next_item_size as f64 > post && post_residual as f64 > mean_residual * 1.5 && fitting_bins_count > 3 {
            score += 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;
    let fill = 1.0 - pr_norm;

    // Base: penalize large post-residual, non-linearly
    let mut score = pr_norm * pr_norm * 40.0 + pr_norm * 20.0;

    // Smooth coupling with stream progress: later in stream, prefer tight fills
    score -= fill * fill * (1.0 + 30.0 * progress) * 4.0;

    // Interaction: post_residual vs mean residual deviation
    let dev = pr - mean_residual;
    score += 0.15 * dev * dev / (cap * cap) * 10.0;

    // Lookahead: reward post_residual that can host next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 12.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 8.0 * (nx - pr) / cap;
        }
    }

    // Last-chance bin: strong reward to use it rather than open new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * fill;
    }

    // Mild penalty for proliferating open bins when a tight fit exists
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * (1.0 - fill);

    // New-bin candidate: penalize opening unless current bins are poor fits
    if bin_residual == bin_capacity {
        score += 30.0 - 25.0 * progress;
        if fitting_bins_count == 0 { score -= 60.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (residual 0) heavily rewarded.
    if post_residual == 0 {
        score -= 200.0;
    } else {
        // Small dead-space classes penalized more than proportionally.
        if post_residual <= 5 {
            score += 20.0;
        }
        // Modulo-10 harmonic classes: residuals near multiples of 10 pair well
        // with common item sizes (10..80 range multiples of 5/10).
        let r10 = post_residual % 10;
        if r10 == 0 {
            score -= 10.0;
        } else if r10 == 5 {
            score -= 5.0;
        } else {
            score += (5 - r10 as i32).unsigned_abs() as f64 * 0.5;
        }
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            score -= 15.0;
            if gap == 0 {
                score -= 60.0;
            } else {
                score += gap as f64 * 0.3;
            }
        } else {
            // Dead end for lookahead item: penalize, worse when residual large.
            score += post_residual as f64 * 0.2;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
