    let prog2 = progress * progress;
    let prog3 = prog2 * progress;
    score += (0.5 + 1.5 * prog2 + 2.0 * prog3) * pr;
    // penalize large dead space relative to capacity, more so mid-stream
    let dead = pr / cap;
    score += 20.0 * dead * dead * (1.0 - progress);
    // reward tight fits (small post_residual) especially when many bins fit item
    if fitting_bins_count > 1 {
        score -= 8.0 * (1.0 - pr / cap) * (1.0 - pr / cap);
    }
    // last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 12.0;
    }
    // lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 4.0 * (next_item_size as f64 / cap) * (pr / cap);
    }
    // penalize opening new bins when many open with slack
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * (mean_residual / cap) - 5.0 * progress;
    }
    // smooth interaction of mean residual with progress
    score += 3.0 * (mean_residual / cap) * prog2;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post * post / cap; // quadratic pressure: big leftovers hurt more

    if post_residual == 0 {
        score -= 1000.0; // perfect fit dominates
    } else if post_residual <= 5 {
        score -= 330.0 / post; // near-dead sliver: reward tiny leftovers strongly
    } else if post_residual < 12 {
        score += 90.0 + (12 - post_residual) as f64 * 6.0; // marginal band penalty
    } else {
        score -= 15.0 * (post / cap); // useful leftover reward scaled by size
        if post_residual >= 40 {
            score -= 9.0; // large leftover is still usable
        }
        if post_residual < 30 {
            score += 7.5 * (30 - post_residual) as f64 / 18.0;
        }
    }

    // Harmony of the leftover space
    if post_residual > 0 {
        if post % 10 == 0 { score -= 5.0; }
        if post % 25 == 0 { score -= 4.0; }
        if post % 50 == 0 { score -= 3.0; }
    }
    // dead-space band under 25% of capacity
    if post > 0.0 && post < 0.25 * cap {
        score += 30.0 * (1.0 - post / (0.25 * cap));
    }

    // Lookahead: reward if next item chains into the leftover
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let chain_tight = 1.0 - (post - nxt) / cap;
            score -= 52.0 * chain_tight;
            if post == nxt { score -= 68.0; } // exact chain fill
            if post_residual % next_item_size == 0 { score -= 18.0; } // harmonic chain
            if post >= nxt + mean_residual { score -= 10.0; }
            if (post - nxt) <= mean_residual * 0.5 { score -= 8.0; }
            if (post - nxt) as u32 == mean_residual as u32 { score -= 9.0; }
            if post - nxt >= 1.0 && post - nxt <= 4.0 { score -= 12.0; } // near-perfect chain
            if post - nxt < 6.0 { score -= 18.0; }
            if post_residual <= 25 && nxt > post_residual as f64 * 0.6 {
                score -= 13.0 * (1.0 - post_residual as f64 / 25.0);
            }
            if (post - nxt) <= 12.0 && (post - nxt) <= mean_residual * 1.2 {
                score -= 7.0 * (1.0 - (post - nxt) / 12.0);
            }
            if (post - nxt) <= 2.0 && post / cap > 0.4 { score -= 9.0; }
        } else {
            // next item won't fit here
            if post_residual > 0 && post_residual < 8 && next_item_size > post_residual { score += 26.0; }
            if post + 10.0 >= nxt { score += 6.0; }
            if nxt - post > 20.0 && post_residual > 0 && post_residual < 20 { score += 12.0; }
            if post_residual < (next_item_size / 2).max(1) {
                score += 6.0 * (1.0 - post_residual as f64 / (next_item_size / 2).max(1) as f64);
            }
            if post_residual > 0 && post_residual < item_size && open_bins_count > 3 { score += 8.0; }
            if post_residual > 0 && post_residual < 16 && next_item_size > post_residual && (mean_residual as u32) > post_residual {
                score += 9.0 * (16 - post_residual) as f64 / 8.0;
            }
            // near-miss: residual barely too small wastes potential
            if (nxt - post) as u32 <= 2 && fitting_bins_count > 1 { score += 15.0; }
        }
        // partially-fitting next item: residual that can host 3/4 of next item is poor
        if post_residual > 0 && next_item_size > post_residual
            && post_residual >= (next_item_size * 3 / 4).max(1) {
            score += 5.0 * (post_residual as f64 - next_item_size as f64 * 0.75)
                / (next_item_size as f64 * 0.25).max(1.0);
        }
    } else {
        score += post * 2.2;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        score -= 20.0; // base cost of opening a bin
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * (1.0 - progress); // early: bins cheap; late: consolidate
        if mean_residual < item_size as f64 && open_bins_count > 2 {
            score += 10.0;
        }
        // many open bins with slack: prefer consolidating instead of new bin
        if open_bins_count > 5 && mean_residual > 0.4 * cap {
            score += 12.0;
        }
        // late stream: opening new bins is expensive, tighten further
        if progress > 0.6 && open_bins_count > 3 {
            score += 8.0;
        }
        // next item large relative to capacity: reserve fresh bin for big items
        if next_item_size as f64 > 0.7 * cap {
            score -= 6.0;
        }
    } else {
        // tightness pressure toward fuller bins
        let tightness = 1.0 - (bin_residual as f64 / cap);
        score -= 10.0 * tightness;
        // many fitting bins means this choice matters less; slight penalty for sloppy fits
        if fitting_bins_count > 4 && post_residual > 30 {
            score += 3.0;
        }
        // penalize leaving dead space when next item is much larger than residual
        let dead = post / cap;
        if post_residual > 0 && next_item_size as f64 > post && dead > 0.35
            && post_residual as f64 > mean_residual * 1.5 && fitting_bins_count > 3 {
            score += 10.0 * (dead - 0.35);
        }
    }

    score
}

