    // classes for small items (multiples of 10, 25, 50), penalize awkward ones.
    let pr = post_residual;
    if pr % 10 == 0 {
        score -= 6.0;
    }
    if pr % 25 == 0 {
        score -= 4.0;
    }
    if pr % 50 == 0 {
        score -= 4.0;
    }

