    let band = pr / 15; // 0..6 bands
    score -= band as f64 * 1.5;

    // Very tight fit: post_residual below smallest plausible item is dead space.
    if pr < 8 {
        score += 10.0 * (1.0 - post / cap);
    }

    // Lookahead coupling: does post_residual accommodate next item (harmonic
    // modulo match between post_residual and next_item_size)?
    if next_item_size > 0 && next_item_size <= pr {
        score -= 8.0;
        if pr % next_item_size.max(1) == 0 {
            score -= 6.0; // perfect harmonic reuse of leftover
        }
    } else if next_item_size > pr {
        // leftover cannot serve next item: penalize proportionally
        score += (next_item_size as f64 - post).min(15.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: prefer only when few fitting bins exist or stream early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
