pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: prefer minimizing post_residual (tight fits).
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity-fraction buckets.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_frac = pr / cap; // fraction of capacity left over

    // Dead-space penalty: residuals in awkward ranges (e.g. (0,10)) are nearly unusable
    // since smallest item is 1..100; small leftovers below 10 waste space.
    if post_residual < 10 {
        score += 25.0; // tiny dead space: heavy penalty
    } else if post_residual < 20 {
        score += 8.0;
    } else if post_residual < 30 {
        score += 3.0;
    }

    // Perfect fit reward: post_residual exactly 0 or a "harmonic" class value.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual % 10 == 0 {
        // residual divisible by 10 is a nice harmonic class (easy to fill later)
        score -= 10.0;
    } else if post_residual % 5 == 0 {
        score -= 5.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size < post_residual {
            // next item fits: reward proportional to how well it fills the leftover
            let fill = (next_item_size as f64) / pr.max(1.0);
            score -= 20.0 * fill;
            // harmonic bonus if post_residual - next_item_size lands on a nice class
            let after = post_residual - next_item_size;
            if after % 10 == 0 {
                score -= 10.0;
            } else if after % 5 == 0 {
                score -= 5.0;
            }
        } else {
            // next item won't fit here: mild penalty for leaving a "trap" residual
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Its natural score is post_residual == capacity - item_size, which is large,
    // so it only wins when existing bins would create awful fits. Add a mild
    // preference term so a fresh bin isn't chosen unless fits are poor:
    if bin_residual == bin_capacity {
        // opening a new bin: penalize slightly, scaled by how many bins already open
        // and how much mean residual exists (waste avoidance).
        score += 12.0 + 0.5 * (open_bins_count as f64).sqrt() + 0.1 * mean_residual;
        // but if item is large relative to capacity, opening fresh is fine
        if (item_size as f64) / cap > 0.6 {
            score -= 8.0;
        }
    } else {
        // Existing bin: reward using bins with low residual (consolidation),
        // mild pressure toward packing tighter bins first.
        score -= 0.15 * (cap - bin_residual as f64) / cap;
    }

    // Stream progression: early in the stream, be slightly more willing to open
    // bins (spread items); late in the stream, squeeze harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 6.0 * (1.0 - progress);
    } else {
        score -= 6.0 * progress * (1.0 - pr_frac);
    }

    score
}

