        if post_residual == next_item_size {
            score -= 60.0;
        } else if diff <= 10.0 {
            score -= 30.0 - diff * 2.0;
        } else {
            // Penalize residual that is too small to be useful (dead space)
            // but slightly less if it is small absolute waste.
            score += diff * 0.5;
        }
        // If post_residual cannot fit the next item at all, penalize dead space.
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    } else {
        // Last item: minimize waste directly.
        score = post_residual as f64 * 1.5;
    }

    // Relative-to-mean coupling: prefer bins whose resulting residual stays
    // below the current mean residual (tight packing trend).
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: neutral-ish baseline, but discourage opening
    // a new bin when a decent fit exists (post_residual <= ~40 is a good fit).
    if bin_residual == bin_capacity {
        score = 45.0 + post_residual as f64 * 0.5;
        // Late in the stream, consolidate more aggressively.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        // If many bins are open already, prefer using them.
        score += open_bins_count as f64 * 0.5;
        // If next item would perfectly fill the new bin after this one, allow it.
        if next_item_size > 0 && item_size + next_item_size >= bin_capacity {
            score -= 40.0;
        }
    }

    // Mild reward for very tight fits overall.
    if post_residual <= 5 {
        score -= 15.0;
    }

    score
}

