pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more aggressively as the stream progresses.
    let t = step_index as f64 / total_items.max(1) as f64;
    score -= (100.0 - post_residual as f64).powf(1.4) * (0.4 + 0.6 * t);

    // Penalize dead space: post_residual too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - t);
    }

    // Lookahead: if the next item fits into the post-residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 35.0 + 0.5 * next_item_size as f64;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; slight penalty if post-residual becomes stranded.
        score += 8.0 * (post_residual as f64 / 20.0).min(1.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 50.0;
    } else {
        // Many fitting bins: prefer tighter ones (score already encodes this), add mild diversity pressure.
        score += 2.0 * fitting_bins_count as f64;
    }

    // Global state: when mean residual is high, prefer spreading load (favor fuller bins less).
    score += 0.15 * (mean_residual - post_residual as f64);

    // Prefer bins whose residual is close to the item (best-fit coupling).
    score += (bin_residual as f64 - item_size as f64).abs() * 0.3;

    // New-bin candidate handling: opening a new bin is only attractive early or when
    // the item would leave a very awkward residual in every existing bin.
    if bin_residual == bin_capacity {
        let awkward = post_residual as f64 / bin_capacity as f64;
        score = 40.0 - 30.0 * awkward + 120.0 * t - 10.0 * (open_bins_count as f64).ln();
        if fitting_bins_count <= 1 {
            score += 200.0; // never open new bin if only this bin fits
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post * post / cap; // quadratic pressure: big leftovers hurt more

    if post_residual == 0 {
        score -= 1000.0; // perfect fit dominates
    } else if post_residual <= 5 {
        // tiny sliver: nearly dead, but a perfect-looking fill is still good
        score -= 330.0 / post;
    } else if post_residual < 12 {
        score += 90.0 + (12 - post_residual) as f64 * 6.0;
    } else {
        score -= 15.0 * (post / cap);
        if post_residual >= 40 {
            score -= 9.0;
        }
        if post_residual < 30 {
            score += 7.5 * (30 - post_residual) as f64 / 18.0;
        }
        // harmony of the leftover space
        if post % 10 == 0 { score -= 6.0; }
        if post % 25 == 0 { score -= 5.0; }
    }

    // dead-space band under 25% of capacity
    if post > 0.0 && post < 0.25 * cap {
        score += 30.0 * (1.0 - post / (0.25 * cap));
    }

    // Lookahead: reward if next item chains into the leftover
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let chain_tight = 1.0 - (post - nxt) / cap;
            score -= 52.0 * chain_tight;
            if post_residual == next_item_size { score -= 68.0; } // exact chain fill
            if post_residual % next_item_size == 0 { score -= 12.0; } // harmonic chain
            if post >= nxt + mean_residual { score -= 10.0; }
            if (post - nxt) <= mean_residual * 0.5 { score -= 8.0; }
            if post - nxt >= 1.0 && post - nxt <= 4.0 { score -= 12.0; }
            if post - nxt < 6.0 { score -= 18.0; }
            if (post_residual as f64 - nxt) as u32 == mean_residual as u32 { score -= 9.0; }
            if post_residual <= 25 && nxt > post_residual as f64 * 0.6 {
                score -= 13.0 * (1.0 - post_residual as f64 / 25.0);
            }
            if (post - nxt) <= 12.0 && (post - nxt) <= mean_residual * 1.2 {
                score -= 7.0 * (1.0 - (post - nxt) / 12.0);
            }
        } else if post + 10.0 >= nxt {
            // next item just barely misses: mild penalty for near-miss bins
            score += 6.0;
        } else {
            // next item won't fit here
            score += 0.06 * (nxt - post);
            if post_residual > 0 && post_residual < 10 { score += 26.0; }
            if nxt - post <= 2.0 && fitting_bins_count > 1 { score += 15.0; }
            if nxt - post > 20.0 && post_residual < 20 { score += 12.0; }
            if post_residual > 0 && post_residual < (next_item_size / 2) {
                score += 6.0 * (1.0 - post_residual as f64 / (next_item_size / 2).max(1) as f64);
            }
            if post_residual > 0 && post_residual < item_size && open_bins_count > 3 { score += 8.0; }
            // near-miss trap: residual could hold most of next item
            if post_residual >= (next_item_size * 3 / 4) && post_residual < next_item_size {
                score += 5.0 * (post_residual as f64 - next_item_size as f64 * 0.75) / (next_item_size as f64 * 0.25).max(1.0);
            }
            if post_residual > 0 && post_residual < 16 && (mean_residual as u32) > post_residual {
                score += 9.0 * (16 - post_residual) as f64 / 8.0;
            }
        }
    } else {
        score += post * 2.2;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        score -= 20.0; // base cost of opening a bin
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * (1.0 - progress); // early: bins cheap; late: consolidate
        if mean_residual < item_size as f64 && open_bins_count > 2 {
            score += 10.0;
        }
        // many open bins with slack: prefer consolidating instead of new bin
        if open_bins_count > 5 && mean_residual > 0.4 * cap {
            score += 12.0;
        }
        // late stream: opening new bins is expensive, tighten further
        if progress > 0.6 && open_bins_count > 3 {
            score += 8.0;
        }
    } else {
        // tightness pressure toward fuller bins
        let tightness = 1.0 - (bin_residual as f64 / cap);
        score -= 10.0 * tightness;
        // many fitting bins means this choice matters less; slight penalty for sloppy fits
        if fitting_bins_count > 4 && post_residual > 30 {
            score += 3.0;
        }
        // penalize leaving dead space when next item is much larger than residual
        let dead = post / cap;
        if post_residual > 0 && next_item_size as f64 > post && dead > 0.35
            && post_residual as f64 > mean_residual * 1.5 && fitting_bins_count > 3 {
            score += 10.0 * (dead - 0.35);
        }
    }

    score
