pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize larger post-residuals super-linearly.
    let pr = post_residual as f64;
    score += 0.35 * pr * pr / bin_capacity as f64;

    // Perfect or near-perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 150.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0 + 0.5 * item_size as f64;
        if post_residual <= 20 {
            score -= 40.0;
        }
    }

    // Lookahead coupling: reward placing item here if next item fits the
    // post-residual (chain packing), penalize if next item would be stranded.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 45.0;
        } else {
            score += 25.0 + 0.3 * (next_item_size - post_residual) as f64;
        }
        // If next item also fits exactly with residual, extra reward.
        if post_residual == next_item_size {
            score -= 30.0;
        }
    }

    // Penalize creating dead space relative to the mean residual of open bins:
    // a residual far below mean means this bin is becoming an outlier.
    let dead = mean_residual - pr;
    if dead > 0.0 {
        score += 0.4 * dead;
    } else {
        score += 0.1 * dead; // slight reward for staying above mean residual
    }

    // Time horizon: early in the stream, be conservative (favor spreading);
    // late in the stream, favor consolidation into fewer bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 60.0 * progress * (1.0 - pr / bin_capacity as f64);

    // Many open bins: encourage filling existing bins rather than opening more.
    score += 2.0 * open_bins_count as f64 * (pr / bin_capacity as f64);

    // New-bin candidate handling: opening a new bin is only attractive when
    // item is large relative to capacity or when existing fit is very poor.
    if bin_residual == bin_capacity {
