pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable" residue
    // classes (divisible by common item sizes) should be rewarded.
    let pr = post_residual;
    if pr > 0 {
        // Reward post_residuals that are multiples of small harmonic denominators
        if pr % 10 == 0 { score -= 6.0; }
        else if pr % 5 == 0 { score -= 3.0; }
        else if pr % 20 == 0 { score -= 7.0; }
        else { score += 2.0; }

        // Penalize tiny dead-space classes (< 10 unusable for min item)
        if pr < 10 { score += 25.0; }
        else if pr < 20 { score += 8.0; }
    } else {
        // Perfect closure: huge reward
        score -= 40.0;
    }

    // Integer-division threshold coupling: how well next_item_size divides into post_residual
    if next_item_size > 0 && next_item_size <= pr {
        let fits = pr / next_item_size;
        let rem = pr % next_item_size;
        // Reward when the lookahead leaves a harmonic remainder
        if rem == 0 { score -= 10.0 + 3.0 * fits as f64; }
        else if rem < 10 { score += 6.0; } else { score -= 2.0; }
    } else if next_item_size > pr && pr > 0 {
        // Next item can't use this bin's leftover: penalize proportionally to wasted class
        score += 5.0;
    }

    // Capacity-fraction coupling: exact-fill fractions of capacity are golden
    let used = bin_capacity - bin_residual + item_size;
    if used == bin_capacity { score -= 30.0; }
    else if bin_capacity % used == 0 && used > 0 { score -= 5.0; }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: prefer opening a new bin only when existing fits are terrible
    if bin_residual == bin_capacity {
        score += 20.0;
        if next_item_size > 0 && next_item_size > item_size {
            score -= 5.0; // big lookahead may deserve a fresh bin
        }
        score += (open_bins_count as f64) * 0.5;
    }

