    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 4.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));

    // Tightness reward: prefer bins that become nearly full
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 8.0;

