        0 => score -= 30.0,
        1 => score += 12.0,
        2 => score -= 4.0,
        3 => score -= 8.0,
        _ => {}
    }

    // Lookahead coupling: if next item fits the post residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
        // extra harmonic bonus if next item exactly matches a class boundary
