            score -= 18.0; // item nearly fills a fresh bin: fine to open one
        } else {
            score += 10.0 + 20.0 * progress; // increasingly avoid opening bins late in stream
        }
    }

    // Slight preference for consolidating into fewer bins as stream grows.
    score += 0.5 * open_bins_count as f64 / (open_bins_count as f64 + 5.0);

    score
}

