            let fit_quality = 1.0 - ((post - nxt) / cap);
            score -= 20.0 * fit_quality.powf(3.0);
        } else {
            // next item cannot use residual: penalize large residuals mildly
            score += 5.0 * dead;
        }
    }

    // Stream progress: early on be tolerant (keep bins flexible),
    // later be strict about waste (smooth ramp)
