            0 => 220.0, // 1..9 : nearly dead space
            1 => 80.0,  // 10..19: only tiny items fit
            2 => 40.0,  // 20..29
            3 => 20.0,  // 30..39
            _ => 5.0,   // large residual: flexible
        };

