        // penalize proportional to the gap if it does not.
        if next_item_size > 0 {
            if next_item_size <= post_residual {
                score -= 50.0 + 0.3 * next_item_size as f64;
            } else {
                score += 0.6 * (next_item_size - post_residual) as f64;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    } else if fitting_bins_count > 1 {
        // mild congestion penalty: prefer bins where choice is scarce
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Reward bins that are already well-filled (keeps open-bin count low).
    score += 0.15 * (bin_capacity as f64 - bin_residual as f64);

    // Encourage balancing residuals toward the mean across open bins.
    score += 0.1 * (post_residual as f64 - mean_residual).abs();

    // Late in the stream, tighten tolerance for waste.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.25 * progress;

    score
}

