pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where post_residual is small.
    score -= (bin_capacity as f64 - post_residual as f64).powi(2) * 0.05;

    // Dead space penalty: post_residual that is too small to ever be useful
    // (less than the minimum conceivable item size) is wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item can fit into the post_residual,
    // reward this placement (chaining placements).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > 0 && next_item_size <= bin_residual && next_item_size > post_residual {
        // Next item would have fit before but not after this placement: mild penalty.
        score += 5.0;
    }

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: an empty bin is a fallback. Penalize it
    // unless the item fits badly everywhere (large post_residual elsewhere)
    // or there are no open bins at all.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        } else {
            // Prefer reusing open bins; cost of a new bin grows with
            // how many bins are already open and how much residual exists.
            score += 30.0 + 0.5 * mean_residual + open_bins_count as f64 * 2.0;
            // Late in the stream, consolidation matters more: discourage new bins.
            let progress = step_index as f64 / (total_items.max(1) as f64);
            score += 20.0 * progress;
            // If the item leaves a large post_residual in an open bin anyway,
            // opening a fresh bin is not much worse.
            if post_residual as f64 > 0.6 * bin_capacity as f64 {
                score -= 15.0;
            }
        }
    }

    // Global state: when many bins are open with large mean residual,
    // prefer placements that reduce fragmentation (small post_residual).
    score += 0.05 * (mean_residual - post_residual as f64);

    // Mild time-horizon term: early on, keep bins balanced; late, pack tight.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * post_residual as f64 * 0.3;
    score -= (1.0 - progress) * (bin_residual as f64 - post_residual as f64) * 0.1;

    score
}

