            if (post_residual as f64 - nxt) as u32 == mean_residual as u32 { score -= 9.0; }
            if post_residual <= 25 && nxt > post_residual as f64 * 0.6 {
                score -= 13.0 * (1.0 - post_residual as f64 / 25.0);
            }
            // NEW: graded chain tightness — closer chains get stronger reward
            let gap = post - nxt;
            if gap <= mean_residual * 1.2 {
                score -= 7.0 * (1.0 - gap / (mean_residual * 1.2 + 1.0));
            }
            if gap <= 2.0 && post > 0.4 * cap {
                score -= 9.0;
            }
        } else {
            // next item won't fit here
            if post_residual > 0 && post_residual < 10 { score += 26.0; }
            if nxt - post <= 2.0 && fitting_bins_count > 1 { score += 15.0; }
            if nxt - post > 20.0 && post_residual < 20 { score += 12.0; }
            if post_residual < next_item_size / 2 {
                score += 6.0 * (1.0 - post_residual as f64 / (next_item_size / 2).max(1) as f64);
            }
            if post_residual > 0 && post_residual < item_size && open_bins_count > 3 { score += 8.0; }
            // NEW: penalize leaving residual that is almost-but-not-quite next item size
            if post_residual >= (next_item_size * 3 / 4) && post_residual < next_item_size {
                score += 5.0 * (post_residual as f64 - next_item_size as f64 * 0.75)
                    / (next_item_size as f64 * 0.25).max(1.0);
            }
            // NEW: dead-space ratio penalty when next item overshoots
            let dead = post / cap;
            if dead > 0.35 && post_residual as f64 > mean_residual * 1.5 && fitting_bins_count > 3 {
                score += 10.0 * (dead - 0.35);
            }
        }
    } else {
        score += post * 2.2;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        score -= 20.0; // base cost of opening a bin
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * (1.0 - progress);
        if mean_residual < item_size as f64 && open_bins_count > 2 {
            score += 10.0;
        }
        if open_bins_count > 5 && mean_residual > 0.4 * cap {
            score += 12.0;
        }
        if progress > 0.6 && open_bins_count > 3 {
            score += 8.0;
        }
        // NEW: opening a bin is more expensive when many bins can still fit the item
        if fitting_bins_count > 2 {
            score += 6.0 + fitting_bins_count as f64;
        }
    } else {
        // tightness pressure toward fuller bins
        let tightness = 1.0 - (bin_residual as f64 / cap);
        score -= 10.0 * tightness;
        if fitting_bins_count > 4 && post_residual > 30 {
            score += 3.0;
        }
        if post_residual > 0 && next_item_size as f64 > post
            && post_residual as f64 > mean_residual * 1.5 && fitting_bins_count > 3 {
            score += 8.0;
        }
    }

    score
}

