        if open_bins_count > 1 && mean_residual > item * 0.8 {
            score += 40.0 * ((mean_residual / item.max(1.0)) - 0.8).min(1.5);
        }
        // NEW: late-stream fresh bins are cheaper (fewer items remain to consolidate).
        if progress > 0.85 {
            score -= 25.0 * (progress - 0.85) / 0.15;
        }
    } else if open_bins_count > 3 && residual > 2.0 * mean_residual {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual modulo capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Penalize dead space in harmonic bands: residuals that are hard to fill
    let class = post_residual % 10;
    let class_penalty = match class {
        0 => -8.0,           // round residual, easy to pair
        1 | 2 => 6.0,        // awkward slivers
        3 | 4 => 2.0,
        5 => -4.0,           // half-decade residual, pairs with mid items
        6 | 7 => 1.0,
        8 | 9 => 5.0,        // near-full but unusable
        _ => 0.0,
    };
    score += class_penalty;

    // Integer division thresholds on post_residual: unusable if below min item size
    if post_residual < 10 {
        score -= 12.0; // item fully consumes bin, great
    } else if post_residual <= 20 {
        score += 4.0; // small pocket, may be dead space
    }

    // Lookahead coupling: harmonic match between post_residual and next item
    if next_item_size > 0 {
        let diff = post_residual as i64 - next_item_size as i64;
        if diff == 0 {
            score -= 15.0; // next item fits exactly after this
        } else if diff > 0 && diff < 10 {
            score += 5.0; // leaves sliver before next item
        } else if diff < 0 {
            score += 3.0; // next item won't fit here anyway
        }
        // modulo harmony: next item shares class with post_residual
        if next_item_size % 10 == post_residual % 10 && next_item_size <= post_residual {
            score -= 6.0;
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: prefer it only when no open bin fits well
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * (mean_residual / cap);
        if fitting_bins_count == 0 {
            score -= 50.0;
        } else if mean_residual > 0.35 * cap && pressure > 2.0 {
            score += 25.0; // plenty of slack spread around, avoid new bin
        } else {
            score += 10.0;
        }
    }

    // Mild preference for fuller bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - frac) * 5.0 * (0.5 + progress);

    // Tie-break toward bins below mean residual (balance exploitation)
    if pr < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
