}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance: unusable small gaps are heavily penalized ---
    // A gap is "unusable" if it cannot hold even the smallest plausible item.
    // Since sizes are 1..100 with unknown distribution, treat gaps below a
    // soft threshold as increasingly toxic (quadratic dead-space penalty).
    let gap = post_residual as f64;
    let dead_threshold = 15.0_f64;
    if gap > 0.0 && gap < dead_threshold {
        score += (dead_threshold - gap) * (dead_threshold - gap) * 0.6;
    } else if gap == 0.0 {
        // Perfect fill is the ideal outcome: strong reward.
        score -= 40.0;
    } else {
        // Usable gaps: mildly reward small usable leftovers, penalize large waste.
        score += gap * 0.15;
    }

    // --- Tight fit reward: item fills a large fraction of the residual ---
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // --- Last-chance pressure: if this is the only bin that fits, prefer using it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // With many options, be pickier about wasted space.
        score += post_residual as f64 * 0.1 * ((fitting_bins_count as f64).ln() + 1.0);
    }

    // --- Open-bin pressure: discourage opening new bins when many are already open ---
    let is_new_bin = bin_residual == bin_capacity && post_residual == bin_capacity - item_size;
    if is_new_bin {
        let pressure = open_bins_count as f64 * 8.0
            + mean_residual * 0.3
            + (1.0 - step_index as f64 / (total_items.max(1) as f64)) * 10.0;
        score += pressure;
        // Allow opening a new bin if the item is huge and would leave a tiny gap anyway.
        if item_size >= bin_capacity - 15 {
            score -= 45.0;
        }
    }

    // --- Lookahead (k=2): favor placements that still accommodate the next item ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward leaving room exactly usable by the next item; best if near-perfect.
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 - slack * 0.2;
        } else {
            // Placement strands the lookahead item into a new bin: penalize.
            score += 12.0;
        }
    } else {
        // Last item: maximize packing density aggressively.
        score -= 15.0;
    }

    // --- Mild preference for filling bins with larger mean residual (balance avoidance) ---
    if bin_residual as f64 > mean_residual + 1.0 {
        score += 3.0; // avoid leaving one bin bloated while draining others
    } else {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: exact match of post_residual to next item's size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + diff);
        // Bonus if next item fits exactly or nearly after this placement.
        if post_residual >= next_item_size {
            score -= 12.0 * (post_residual as f64 - next_item_size as f64 + 1.0).ln().max(0.0);
        } else {
            // Penalize dead space the next item cannot use.
            score += 0.35 * (post_residual as f64);
        }
    }

    // Reward tight fits relative to bin capacity (small post_residual is good).
    score += 0.5 * (post_residual as f64 / bin_capacity as f64) * (post_residual as f64 / bin_capacity as f64) * bin_capacity as f64;

    // Compare against mean residual: placing into a bin with residual far below
    // mean is efficient (uses scarce space); penalize bins with excess space
    // being wasted on small items.
    let res_f = bin_residual as f64;
    if res_f > mean_residual {
        score += 0.25 * (res_f - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - res_f);
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make it costly unless nothing fits well.
    if bin_residual == bin_capacity {
        let mut base = 75.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            base += 20.0; // fresh bin keeps room for next item
        }
        if fitting_bins_count == 0 {
            base = 0.0; // must open a new bin
        }
        score += base;
    }

    // Late-stream pressure: consolidate as stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * (open_bins_count as f64).ln().max(0.0);

    score
}

