    let mut score = post_residual as f64;

    // Strongly reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Penalize large dead space, especially when it can't fit the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size as f64 {
            score += 0.35 * (next_item_size as f64 - post_residual);
        } else {
            // Reward leaving room for the next item.
            score -= 0.15 * (post_residual as f64 - next_item_size as f64).min(30.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Penalize opening new bins when many bins can fit the item.
    if fitting_bins_count > 1 {
        score += 8.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: prefer it only when it truly beats poor fits.
    if bin_residual == bin_capacity {
        // Mild penalty so we only open new bins when fits are bad.
        score += 25.0;
        // If the current item is large relative to capacity, a fresh bin is fine.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 30.0;
        }
        // Fewer open bins => opening a new bin is cheaper.
        if open_bins_count <= 2 {
            score -= 10.0;
        }
    }

    // Tightness bonus: prefer bins whose fill ratio after placement is high.
    let fill_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * fill_ratio * fill_ratio;

