pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to fit even the
    // smallest plausible item are "dead". Penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0; // unusable sliver
    } else if post_residual == 0 {
        score -= 30.0; // perfect fit: fully consumed bin
    }

    // Penalize gaps too small for the lookahead item (k=2 lookahead synergy).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.35 * (next_item_size - post_residual) as f64;
    }
    // Reward gaps that exactly accommodate the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    }

    // Reward tight fits relative to bin capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Open-bin pressure: discourage spreading across many bins unless fit is tight.
    let pressure = open_bins_count as f64 / (1.0 + (total_items as f64).max(1.0).ln());
    score += 1.5 * pressure * (1.0 - tightness);

    // Last-chance bonus: if this is the only fitting bin, prefer using it
    // (avoiding a new bin) unless the fit creates dead space.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0 + 0.2 * item_size as f64;
        if post_residual > 0 && post_residual < 10 {
            score += 55.0; // but never if it strands a sliver
        }
    }

    // New-bin candidate handling: an empty bin is attractive when the current
    // item would leave a large awkward gap elsewhere, or open-bin pressure is low.
    if bin_residual == bin_capacity {
        let gap_penalty = if post_residual > 0 && post_residual < 10 { 0.0 } else { 0.0 };
        let _ = gap_penalty;
        // Base cost of opening a bin, discounted early in the stream and
        // when the item is large (large items fit best in fresh bins).
        let mut new_bin_score = 25.0
            - 6.0 * (step_index as f64 / total_items.max(1) as f64)
            - 0.15 * item_size as f64;
        // Prefer new bin if all existing fits would strand dead space.
        if post_residual == bin_capacity - item_size && item_size >= 50 {
            new_bin_score -= 15.0;
        }
        // If other bins fit but would leave slivers, opening fresh is better.
        if fitting_bins_count > 0 && mean_residual > 0.0 && (mean_residual - item_size as f64) < 10.0 {
            new_bin_score -= 20.0;
        }
        score = score.min(new_bin_score);
    }

    // Mean-residual coupling: prefer bins whose residual is below average
    // (concentrate waste into few bins rather than spreading it).
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals next item size -> chain perfectly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-match lookahead: penalize wasted space relative to what next item could use.
    if next_item_size > 0 && post_residual >= next_item_size {
        // slack the next item leaves behind after following placement
        let slack = (post_residual - next_item_size) as f64;
        score += 0.35 * slack;
    } else if next_item_size > 0 {
        // dead space: next item cannot use this residual
        let dead = (next_item_size - post_residual) as f64;
        score += 0.55 * dead;
    }

    // Compare residual against mean residual of open bins.
    if post_residual as f64 > mean_residual {
        score += 0.25 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly prefer filling the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize opening a new bin unless the fit is genuinely poor.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        if tightness > 0.85 {
            score -= 30.0; // large item: new bin is fine
        } else {
            score += 20.0 * (1.0 - tightness); // small item: avoid wasting a fresh bin
        }
    }

    // Late in stream: consolidate, avoid leaving many small residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.10 * post_residual as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual) non-linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Penalize small unusable dead space (< typical minimum item size 10).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: only this bin fits the item.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Lookahead: reward if next item fits the post-residual well.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score += 0.3 * gap;
        if post_residual >= next_item_size {
            score -= 4.0; // bin stays useful for the next item
        }
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 0.5 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Slight preference for bins with residual near the mean (balanced use).
    score += 0.1 * ((bin_residual as f64 - mean_residual).abs());

    // New-bin candidate: penalize opening a new bin unless item is large
    // relative to capacity or existing fits are poor.
    if bin_residual == bin_capacity {
        let big_item = (item_size as f64 / bin_capacity as f64) > 0.6;
        let poor_fit = (post_residual as f64 / bin_capacity as f64) < 0.25;
        if big_item || poor_fit {
            score -= 8.0;
        } else {
            score += 12.0; // discourage wasting a fresh bin on small items
        }
    }

    // Mild time-decay: later in the stream, favor tighter packing more.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 2.0 * t * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let residual = bin_residual as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post * post / cap;

    // Perfect / near-perfect fit rewards.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 330.0 / post;
    } else if post_residual < 12 {
        score += 90.0 + (12 - post_residual) as f64 * 6.0;
    } else {
        score -= 15.0 * (post / cap);
        if post_residual >= 40 {
            score -= 9.0;
        }
        if post_residual < 30 {
            score += 7.5 * (30 - post_residual) as f64 / 18.0;
        }
    }

    // Tightness coupling.
    let fill_ratio = item / residual.max(1.0);
    score -= 24.0 * fill_ratio;

    // Fragmentation penalty for small residuals.
    if post > 0.0 && post < 0.25 * cap {
        score += 30.0 * (1.0 - post / (0.25 * cap));
    }

    // Lookahead chain-fit bonus.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let chain_tight = 1.0 - (post - nxt) / cap;
            score -= 52.0 * chain_tight;
            if post == nxt {
                score -= 68.0;
            }
            if post - nxt < 6.0 {
                score -= 18.0;
            }
            if post >= nxt + mean_residual {
                score -= 10.0;
            }
            if (post - nxt) as u32 == mean_residual as u32 {
                score -= 9.0;
            }
            if post >= nxt && (post - nxt) <= mean_residual * 0.5 {
                score -= 8.0;
            }
            if post - nxt >= 1.0 && post - nxt <= 4.0 {
                score -= 12.0;
            }
            let gap_after_next = post - nxt;
            if gap_after_next > 0.0 && gap_after_next < mean_residual {
                score += 10.0 * (1.0 - gap_after_next / mean_residual.max(1.0));
            }
            if gap_after_next >= mean_residual {
                score -= 6.0;
            }
            // NEW: graded chain-tightness reward for medium gaps.
            if gap_after_next > 4.0 && gap_after_next <= 12.0 {
                score -= 7.0 * (1.0 - gap_after_next / 12.0);
            }
        } else if post + 10.0 >= nxt {
            score += 6.0;
        } else {
            score += 0.06 * (nxt - post);
        }
        if nxt > post && (nxt - post) as u32 <= 2 && fitting_bins_count > 1 {
            score += 15.0;
        }
        if nxt > post && (nxt - post) as u32 > 20 && post_residual > 0 && post_residual < 20 {
            score += 12.0;
        }
    } else {
        score += post * 2.2;
    }

    // Dead-space penalty: residual too small for the next item.
    if post_residual > 0 && post_residual < 8 && next_item_size > post_residual {
        score += 26.0;
    }
    if post_residual > 0 && post_residual < 16 && next_item_size > post_residual && (mean_residual as u32) > post_residual {
        score += 9.0 * (16 - post_residual) as f64 / 8.0;
    }

    // Semi-fit lookahead.
    if post_residual > 0 && next_item_size as f64 <= post && next_item_size as f64 > post_residual as f64 * 0.6 && post_residual <= 25 {
        score -= 13.0 * (1.0 - post_residual as f64 / 25.0);
    }
    if post_residual > 0 && post_residual < item_size && next_item_size as f64 > post && open_bins_count > 3 {
        score += 8.0;
    }
    if post_residual > 0 && next_item_size as f64 > post && post_residual < (next_item_size / 2) {
        score += 6.0 * (1.0 - post_residual as f64 / (next_item_size / 2).max(1) as f64);
    }
    if post_residual > 0 && post_residual % 10 == 0 && next_item_size as f64 <= post {
        score -= 5.0;
    }
