    if post_residual > 0 && next_item_size as f64 > post && dead > 0.35 && (post_residual as f64) > mean_residual * 1.5 && fitting_bins_count > 3 {
        score += 10.0 * (dead - 0.35);
    }
    if post_residual > 0 && next_item_size as f64 <= post && (post - next_item_size as f64) <= 2.0 && dead > 0.4 {
        score -= 9.0;
    }
    // Borrowed: graded chain-tightness with mean_residual coupling.
    if post_residual > 0 && next_item_size as f64 <= post && (post - next_item_size as f64) <= 12.0 && (post - next_item_size as f64) <= mean_residual * 1.2 {
        score -= 7.0 * (1.0 - (post - next_item_size as f64) / 12.0);
    }
    // Borrowed: near-fit penalty shaping.
    if post_residual > 0 && next_item_size > post_residual && post_residual >= (next_item_size * 3 / 4) && post_residual < next_item_size {
        score += 5.0 * (post_residual as f64 - next_item_size as f64 * 0.75) / (next_item_size as f64 * 0.25).max(1.0);
    }
    if fitting_bins_count > 4 && bin_residual != bin_capacity && post_residual > 30 {
        score += 3.0;
    }

    // Last-chance pressure.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    } else if fitting_bins_count <= 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Consolidation pressure.
    score += (open_bins_count as f64) * 1.5;

    // Mean-residual coupling.
    if residual < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score += 120.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 100.0 * progress;
        score += 10.0 * (open_bins_count as f64);
        if fitting_bins_count > 1 {
            score += 100.0 * (fitting_bins_count as f64 - 1.0);
        }
        score += 0.5 * mean_residual;
        if item_size < (bin_capacity / 2) {
            score += 12.0;
            if next_item_size > 0 && (next_item_size as f64) <= post {
