    }

    // Penalize small dead space fraction.
    if post > 0.0 && post < 0.25 * cap {
        score += 30.0 * (1.0 - post / (0.25 * cap));
    }

    // Lookahead: reward if next item fits in the post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let gap = post - nxt;
            let chain_tight = 1.0 - gap / cap;
            score -= 52.0 * chain_tight;
            if post_residual == next_item_size { score -= 68.0; }
            if post >= nxt + mean_residual { score -= 10.0; }
            if gap <= mean_residual * 0.5 { score -= 8.0; }
            if gap >= 1.0 && gap <= 4.0 { score -= 12.0; }
            if gap < 6.0 { score -= 18.0; }
            if gap as u32 == mean_residual as u32 { score -= 9.0; }
        } else if post + 10.0 >= nxt {
            score += 6.0;
        } else {
            score += 0.06 * (nxt - post);
        }
        if nxt > post && (nxt - post) as u32 <= 2 && fitting_bins_count > 1 { score += 15.0; }
