        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 40.0 * (1.0 - progress);
        // Late in the stream, opening bins is expensive: raise the bar.
        if progress > 0.8 { score += 25.0 * (progress - 0.8) * 5.0; }
    }

    // Prefer tighter-than-average bins when consolidating.
    if bin_residual != bin_capacity && open_bins_count > 1 {
        let diff = bin_residual as f64 - mean_residual;
