}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: coarse residue classes mod 10
    let item_class = item_size % 10;
    let next_class = next_item_size % 10;

    // Perfect fit bonus: post_residual in small harmonic classes
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual % 10 == 0 {
        // post_residual itself lands on a harmonic boundary — likely reusable
        score -= 50.0;
    }

    // Complementary pairing: if next item exactly fills post_residual
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 500.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // next item fits here: mild reward scaled by how snugly
        let snug = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - snug / bin_capacity as f64);
    } else if next_item_size > 0 {
        // next item does NOT fit after placement: penalize dead space creation
        let waste = next_item_size - post_residual;
        score += 20.0 + waste as f64 * 0.5;
    }

    // Class-match coupling: same harmonic class items tend to tile together
    if next_item_size > 0 && item_class == next_class {
        score -= 15.0;
    }

    // Integer-division thresholds on post_residual: dead-zone penalties
    if post_residual > 0 && post_residual < 10 {
        score += 150.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize slightly unless current bins are crowded
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 80.0 - 40.0 * progress - 2.0 * crowd;
        // open new bin if mean residual is very tight
        if mean_residual < item_size as f64 * 0.5 {
            score -= 60.0;
        }
    }

    // Deviation from mean residual: prefer bins below mean (tighter bins)
    score += (bin_residual as f64 - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
