            if (post - nxt) <= mean_residual * 0.5 { score -= 8.0; }
            if post - nxt < 6.0 { score -= 18.0; }
            if (post_residual as f64 - nxt) as u32 == mean_residual as u32 { score -= 9.0; }
            if post_residual <= 25 && next_item_size as f64 > post_residual as f64 * 0.6 {
