pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no item can usefully fill are heavily penalized.
    // Items range 1..=100; treat residual < ~10 as near-dead, and mid-range gaps (11..30)
    // as partially dead since few items fit them well.
    let pr = post_residual as f64;
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 60.0;
    } else if post_residual < 10 {
        // Tiny unusable gap: penalize beyond its raw size.
        score += (10 - post_residual) as f64 * 2.0;
    } else if post_residual <= 30 {
        // Mid-range gap: moderate dead-space penalty.
        score += pr * 0.35;
    }

    // Reward tight fits (fill ratio of the bin).
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill * 25.0;

    // Lookahead: if next item fits exactly into post_residual, this is a great chain placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // Next item won't fit here: leaving a gap that may strand the next item.
            score += 8.0;
        }
    }

