pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    score = post_residual as f64 * 1.0;

    // Aggressive 2-step lookahead: reward when the next item exactly fills the
    // post_residual (perfect chain), penalize when it leaves a new awkward gap.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0; // perfect 2-item completion
        } else if post_residual > next_item_size {
            let leftover = (post_residual - next_item_size) as f64;
            // Reward proportional to small leftover after hypothetical next placement,
            // but penalize if leftover becomes dead space (< 10).
            if leftover < 10.0 {
                score -= 30.0 - leftover * 2.0;
            } else {
                score += leftover * 0.35; // chained placement leaves big gap
            }
        } else {
            // next item cannot follow in this bin: mild penalty, stronger if
            // the residual left now is small (good) vs large (bad).
            let tightness = post_residual as f64 / bin_capacity as f64;
            score += 12.0 * (1.0 - tightness);
        }
    }

    // Compare against mean residual across open bins: prefer bins whose
    // post_residual deviates favorably (smaller) from the mean.
    let mean_post = mean_residual - item_size as f64;
    if mean_post > 0.0 {
        let diff = post_residual as f64 - mean_post;
        score += diff * 0.25;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: make an empty bin attractive only when the
    // item is large relative to capacity or no good fit exists elsewhere.
    if bin_residual == bin_capacity {
