        // But if item is huge, empty bin is fine (near-perfect fill).
        if fill_ratio > 0.8 {
            score -= 15.0;
        }
        // If many bins are open and mean residual is high, opening fresh is ok.
        if open_bins_count > 3 && mean_residual > item_size as f64 * 1.5 {
            score -= 10.0;
