                score += 6.0 * (1.0 - post_residual as f64 / (next_item_size / 2).max(1) as f64);
            }
            if post_residual > 0 && post_residual < item_size && open_bins_count > 3 { score += 8.0; }
            // near-miss: residual just under next item, dead ratio high
            if post + 10.0 >= nxt { score += 6.0; }
            if nxt > post && post_residual >= (next_item_size * 3 / 4) && post_residual < next_item_size {
                score += 5.0 * (post_residual as f64 - nxt * 0.75) / (nxt * 0.25).max(1.0);
            }
            if post_residual > 0 && next_item_size as f64 > post
                && dead_ratio(post, cap) > 0.35
                && post_residual as f64 > mean_residual * 1.5 && fitting_bins_count > 3 {
                score += 10.0 * (dead_ratio(post, cap) - 0.35);
            }
        }
    } else {
        score += post * 2.2;
    }

    // small residual that next item cannot use
    if post_residual > 0 && post_residual < 16 && next_item_size > post_residual && (mean_residual as u32) > post_residual {
        score += 9.0 * (16 - post_residual) as f64 / 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        score -= 20.0; // base cost of opening a bin
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * (1.0 - progress); // early: bins cheap; late: consolidate
        if mean_residual < item_size as f64 && open_bins_count > 2 {
            score += 10.0;
        }
        // many open bins with slack: prefer consolidating instead of new bin
        if open_bins_count > 5 && mean_residual > 0.4 * cap {
            score += 12.0;
        }
        // late stream: opening new bins is expensive, tighten further
        if progress > 0.6 && open_bins_count > 3 {
            score += 8.0;
        }
        // next item large relative to capacity: opening fresh bin may be wise
        if next_item_size as f64 > 0.5 * cap && progress > 0.4 {
            score -= 6.0;
        }
    } else {
        // tightness pressure toward fuller bins
        let tightness = 1.0 - (bin_residual as f64 / cap);
        score -= 10.0 * tightness;
        // many fitting bins means this choice matters less; slight penalty for sloppy fits
        if fitting_bins_count > 4 && post_residual > 30 {
            score += 3.0;
        }
        // penalize leaving dead space when next item is much larger than residual
        if post_residual > 0 && next_item_size as f64 > post && post_residual as f64 > mean_residual * 1.5 && fitting_bins_count > 3 {
            score += 8.0;
        }
    }

    score
}

#[inline]
fn dead_ratio(post: f64, cap: f64) -> f64 {
    if cap > 0.0 { post / cap } else { 0.0 }
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: multiples of 10 are "usable" classes,
    // small non-zero remainders are dead space.
    let class = post_residual % 10;
    if post_residual > 0 {
        if class == 0 {
            score -= 8.0; // perfectly harmonic residual, highly reusable
        } else if class <= 3 {
            score += 12.0; // tiny sliver, nearly dead space
        } else if class <= 6 {
            score += 4.0; // mildly awkward class
        } else {
            score -= 2.0; // 7..9 still roomy-ish
        }
    }

    // Zero residual is the ideal closure.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits exactly or well in post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let next_fit = post_residual - next_item_size;
            if next_fit == 0 {
                score -= 18.0; // chain of perfect fits
            } else if next_fit % 10 == 0 {
                score -= 10.0; // next item leaves harmonic residual
            } else if next_fit <= 3 {
                score += 3.0; // next item would leave a sliver
            }
        } else {
            score += 5.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: neutral baseline, slightly penalized so only chosen
    // when open bins have genuinely bad residuals.
    if bin_residual == bin_capacity {
        score += 10.0 + mean_residual * 0.05;
    }

    // Prefer filling bins when many bins are open (consolidation pressure).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (open_bins_count as f64).ln() * 2.0 * (0.5 + progress);

    // Nudge toward bins tighter than the mean residual.
    score -= (mean_residual - bin_residual as f64) * 0.08;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let residual = bin_residual as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post * post / cap;

    // Perfect / near-perfect fit rewards.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 330.0 / post;
    } else if post_residual < 12 {
        score += 90.0 + (12 - post_residual) as f64 * 6.0;
    } else {
        score -= 15.0 * (post / cap);
        if post_residual >= 40 {
            score -= 9.0;
        }
        if post_residual < 30 {
            score += 7.5 * (30 - post_residual) as f64 / 18.0;
        }
    }

    // Tightness coupling.
    let fill_ratio = item / residual.max(1.0);
    score -= 24.0 * fill_ratio;

    // Fragmentation penalty for small residuals.
    if post > 0.0 && post < 0.25 * cap {
        score += 30.0 * (1.0 - post / (0.25 * cap));
    }

    // Lookahead chain-fit bonus with fine residual anticipation.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let chain_tight = 1.0 - (post - nxt) / cap;
            score -= 52.0 * chain_tight;
            if post == nxt {
                score -= 68.0;
            }
            if post >= nxt + mean_residual {
                score -= 10.0;
            }
            if post >= nxt && (post - nxt) <= mean_residual * 0.5 {
                score -= 8.0;
            }
            if post - nxt >= 1.0 && post - nxt <= 4.0 {
                score -= 12.0;
            }
            if post - nxt < 6.0 {
                score -= 18.0;
            }
            if (post - nxt) as u32 == mean_residual as u32 {
                score -= 9.0;
            }
            // Two-step lookahead: keep gap reusable for the stream.
            let gap_after_next = post - nxt;
            if gap_after_next > 0.0 && gap_after_next < mean_residual {
                score += 10.0 * (1.0 - gap_after_next / mean_residual.max(1.0));
            }
            if gap_after_next >= mean_residual {
                score -= 6.0;
            }
            if gap_after_next > 0.0 && gap_after_next <= 12.0 && gap_after_next <= mean_residual * 1.2 {
                score -= 7.0 * (1.0 - gap_after_next / 12.0);
            }
        } else if post + 10.0 >= nxt {
            score += 6.0;
        } else {
            score += 0.06 * (nxt - post);
        }
        if nxt > post && (nxt - post) as u32 <= 2 && fitting_bins_count > 1 {
            score += 15.0;
        }
        if nxt > post && (nxt - post) as u32 > 20 && post_residual > 0 && post_residual < 20 {
            score += 12.0;
        }
        // Semi-fit: residual barely misses next item but fits 3/4 of it.
        if post_residual > 0 && post_residual >= (next_item_size * 3 / 4) && post_residual < next_item_size {
            score += 5.0 * (post_residual as f64 - nxt * 0.75) / (nxt * 0.25).max(1.0);
        }
    } else {
        score += post * 2.2;
    }

    // Dead-space penalty: residual too small for the next item.
    if post_residual > 0 && post_residual < 8 && next_item_size > post_residual {
        score += 26.0;
    }
    if post_residual > 0 && post_residual < 16 && next_item_size > post_residual && (mean_residual as u32) > post_residual {
        score += 9.0 * (16 - post_residual) as f64 / 8.0;
    }

    // Semi-fit lookahead.
    if post_residual > 0 && next_item_size as f64 <= post && next_item_size as f64 > post_residual as f64 * 0.6 && post_residual <= 25 {
        score -= 13.0 * (1.0 - post_residual as f64 / 25.0);
    }
    if post_residual > 0 && post_residual < item_size && next_item_size as f64 > post && open_bins_count > 3 {
        score += 8.0;
    }
    if post_residual > 0 && next_item_size as f64 > post && post_residual < (next_item_size / 2) {
        score += 6.0 * (1.0 - post_residual as f64 / (next_item_size / 2).max(1) as f64);
    }
    if post_residual > 0 && post_residual % 10 == 0 && next_item_size as f64 <= post {
        score -= 5.0;
    }
    let dead = post / cap;
    if post_residual > 0 && next_item_size as f64 > post && dead > 0.35 && (post_residual as f64) > mean_residual * 1.5 && fitting_bins_count > 3 {
        score += 10.0 * (dead - 0.35);
    }
    if post_residual > 0 && next_item_size as f64 <= post && (post - next_item_size as f64) <= 2.0 && dead > 0.4 {
        score -= 9.0;
    }
    if fitting_bins_count > 4 && bin_residual != bin_capacity && post_residual > 30 {
        score += 3.0;
    }

    // Last-chance pressure.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    } else if fitting_bins_count <= 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Consolidation pressure.
    score += (open_bins_count as f64) * 1.5;

    // Mean-residual coupling.
    if residual < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score += 120.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 100.0 * progress;
        score += 10.0 * (open_bins_count as f64);
        if fitting_bins_count > 1 {
            score += 100.0 * (fitting_bins_count as f64 - 1.0);
        }
        score += 0.5 * mean_residual;
        if item_size < (bin_capacity / 2) {
            score += 12.0;
            if next_item_size > 0 && (next_item_size as f64) <= post {
                score += 20.0;
            }
        }
        // Huge items deserve fresh bins when residuals are small.
        if item > 0.8 * cap && mean_residual < item * 0.9 {
            score -= 200.0;
        }
        // Medium-large items late in stream when no open bin fits the next item.
        if item > 0.5 * cap && next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 120.0;
        }
        // Fresh bin for medium items when all open residuals are nearly dead.
        if item <= 0.5 * cap && open_bins_count > 2 && mean_residual < item * 0.55 && fitting_bins_count > 0 {
            score -= 45.0;
        }
        // Extra: fresh bin is attractive when best open residual barely fits item.
        if item <= 0.6 * cap && mean_residual < item * 0.35 && open_bins_count > 1 {
            score -= 30.0;
        }
    } else if open_bins_count > 3 && residual > 2.0 * mean_residual {
        score += 15.0;
    }

    score
}

