    } else if post_residual <= 5 {
        score -= 330.0 / post;
    } else if post_residual < 12 {
        score += 90.0 + (12 - post_residual) as f64 * 6.0;
    } else {
        score -= 15.0 * (post / cap);
        if post_residual >= 40 { score -= 9.0; }
        if post_residual < 30 { score += 7.5 * (30 - post_residual) as f64 / 18.0; }
    }

    // Dead-space penalty for very small residuals relative to capacity
    if post > 0.0 && post < 0.25 * cap {
        score += 30.0 * (1.0 - post / (0.25 * cap));
    }

    // Lookahead coupling with next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let chain_tight = 1.0 - (post - nxt) / cap;
            score -= 52.0 * chain_tight;
            if post == nxt { score -= 68.0; }
            if post >= nxt + mean_residual { score -= 10.0; }
            if post >= nxt && (post - nxt) <= mean_residual * 0.5 { score -= 8.0; }
            if post - nxt >= 1.0 && post - nxt <= 4.0 { score -= 12.0; }
            if (post - nxt) as u32 == mean_residual as u32 { score -= 9.0; }
            if post_residual % 10 == 0 { score -= 5.0; }
        } else if post + 10.0 >= nxt {
            score += 6.0;
        } else {
            score += 0.06 * (nxt - post);
        }
        if nxt <= post && post - nxt < 6.0 { score -= 18.0; }
        if nxt > post && (nxt - post) as u32 <= 2 && fitting_bins_count > 1 { score += 15.0; }
        if nxt > post && (nxt - post) as u32 > 20 && post_residual > 0 && post_residual < 20 { score += 12.0; }
    } else {
        score += post * 2.2;
    }

    // Small-residual blocking penalties
    if post_residual > 0 && post_residual < 8 && next_item_size > post_residual {
        score += 26.0;
    }
    if post_residual > 0 && post_residual < 16 && next_item_size > post_residual && (mean_residual as u32) > post_residual {
        score += 9.0 * (16 - post_residual) as f64 / 8.0;
    }
    if post_residual > 0 && next_item_size as f64 > post && post_residual < (next_item_size / 2).max(1) {
        score += 6.0 * (1.0 - post_residual as f64 / (next_item_size / 2).max(1) as f64);
    }
    if post_residual > 0 && post_residual < item_size && next_item_size as f64 > post && open_bins_count > 3 {
        score += 8.0;
    }

    // Mutated: partial-fit lookahead reward calibrated on residual quarter
    if post_residual > 0 && next_item_size > post_residual && post_residual >= (next_item_size * 3 / 4) && post_residual < next_item_size {
        score += 5.0 * (post_residual as f64 - next_item_size as f64 * 0.75) / (next_item_size as f64 * 0.25).max(1.0);
    }

    // Mutated: tight chain with dead-space coupling
    if post_residual > 0 && next_item_size as f64 <= post && (post - next_item_size as f64) <= 2.0 && post / cap > 0.4 {
        score -= 9.0;
    }
    if post_residual > 0 && next_item_size as f64 <= post && (post - next_item_size as f64) <= 12.0 && (post - next_item_size as f64) <= mean_residual * 1.2 {
        score -= 7.0 * (1.0 - (post - next_item_size as f64) / 12.0);
    }

    // Mutated: fragmented-bin pressure when next item cannot fit and residual is dead
    if post_residual > 0 && next_item_size as f64 > post && post / cap > 0.35 && (post_residual as f64) > mean_residual * 1.5 && fitting_bins_count > 3 {
        score += 10.0 * (post / cap - 0.35);
    }

    // Mild pressure against accumulating many open bins with large residuals
    if fitting_bins_count > 4 && bin_residual != bin_capacity && post_residual > 30 {
        score += 3.0;
    }

    // New-bin candidate handling: only open when open bins are truly fragmented
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / cap;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if mean_residual < 25.0 || open_bins_count == 0 {
            score -= 20.0 + 10.0 * (1.0 - fragmentation);
        } else {
            score += 15.0 + 10.0 * progress * fragmentation;
        }
    }

    // Last-chance bin reward
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward: post_residual exactly matches the next item (perfect 2-step chain)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 {
        // Penalize mismatch between post_residual and next item size
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.4 * gap;
    }

    // Penalize dead space below the minimum item size (unusable gap)
    if post_residual < 10 {
        score += 35.0;
    } else if post_residual < 20 {
        score += 10.0;
    }

    // Reward tightening the bin relative to the mean residual of open bins
    if (post_residual as f64) < mean_residual {
        score -= 0.5 * (mean_residual - post_residual as f64);
    } else {
        score += 0.3 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Prefer existing bins over opening a new one, more so early in the stream
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    }

    // Mild preference for keeping a moderate number of open bins
    score += 0.2 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio;

    // Penalize leaving dead space that no small item could use.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0; // tiny unusable sliver
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; slight penalty for blocking
            score += 3.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Many open bins: prefer consolidating into existing bins.
    let open_pressure = open_bins_count as f64 / (1.0 + step_index as f64);
    score -= 5.0 * open_pressure * fit_ratio;

    // Mean residual coupling: if this bin is much tighter than average, prefer it.
    score -= 4.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;

    // Time horizon: early in stream, be slightly exploratory toward new bins;
    // later, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus exploration bonus early on.
        score = bin_capacity as f64 - 20.0 * (1.0 - progress) + 10.0 * progress;
        if next_item_size > 0 && next_item_size as f64 > bin_capacity as f64 * 0.5 && fit_ratio == 1.0 {
            score -= 10.0; // big next item may warrant fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;
    let mut score = post * post / cap;

    // Perfect fit: overwhelming preference.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 330.0 / post;
    } else if post_residual < 12 {
        score += 90.0 + (12 - post_residual) as f64 * 6.0;
    } else {
        score -= 15.0 * (post / cap);
        if post_residual >= 40 {
            score -= 9.0;
        }
        if post_residual < 30 {
            score += 7.5 * (30 - post_residual) as f64 / 18.0;
        }
    }

    // Penalize very small dead space relative to capacity.
    if post > 0.0 && post < 0.25 * cap {
        score += 30.0 * (1.0 - post / (0.25 * cap));
    }

    // Lookahead coupling: reward bins that chain with the next item.
    if next_item_size > 0 {
        if nxt <= post {
            let chain_tight = 1.0 - (post - nxt) / cap;
            score -= 52.0 * chain_tight;
            if post == nxt {
                score -= 68.0;
            }
            if post >= nxt + mean_residual {
                score -= 10.0;
            }
            if post - nxt >= 1.0 && post - nxt <= 4.0 {
                score -= 12.0;
            }
            if post - nxt >= 1.0 && post - nxt <= 12.0 && (post - nxt) <= mean_residual * 1.2 {
                score -= 7.0 * (1.0 - (post - nxt) / 12.0);
            }
        } else if post + 10.0 >= nxt {
            score += 6.0;
        } else {
            score += 0.06 * (nxt - post);
        }

        // Near-miss lookahead: bin almost fits next item; slight penalty to
        // preserve it if other bins can take the current item.
        if nxt > post && (nxt - post) as u32 <= 2 && fitting_bins_count > 1 {
            score += 15.0;
        }
        if nxt > post && (nxt - post) as u32 > 20 && post_residual > 0 && post_residual < 20 {
            score += 12.0;
        }
    } else {
        score += post * 2.2;
    }

    // Small residual that cannot hold the lookahead item: dead space.
    if post_residual > 0 && post_residual < 8 && next_item_size > post_residual {
        score += 26.0;
    }
    if post_residual > 0 && post_residual < 16 && next_item_size > post_residual && (mean_residual as u32) > post_residual {
        score += 9.0 * (16 - post_residual) as f64 / 8.0;
    }

    // With many open bins, prefer consolidating into fuller ones.
    if fitting_bins_count > 4 && bin_residual != bin_capacity && post_residual > 30 {
        score += 3.0;
    }

    // Open-bin pressure: discourage opening yet another bin when many exist.
    let pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
    score += pressure * 3.0;

    // Last chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin guard: make an empty bin less attractive unless the item is
    // large relative to typical residuals (avoids wasteful bin openings).
    if bin_residual == bin_capacity {
        score += 45.0 + 0.35 * mean_residual;
        if next_item_size > 0 && next_item_size >= item_size && post_residual == bin_capacity {
            score += 10.0;
        }
    }

    // Slightly favor bins below mean residual (more packed bins).
    if bin_residual != bin_capacity && (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    // Fractional-dead-space guard for medium gaps the lookahead misses.
    if post_residual > 0 && next_item_size as f64 > post && post_residual < (next_item_size / 2).max(1) {
        score += 6.0 * (1.0 - post_residual as f64 / (next_item_size / 2).max(1) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Smooth polynomial coupling of post residual with stream progress
    let mut score = pr;
    score += 30.0 * (1.0 - progress) * x * x;      // early: penalize large leftovers less/more smoothly
    score -= 25.0 * progress * x * (1.0 - x);      // late: reward tight fits
    score += 10.0 * progress * (1.0 - progress) * x * x * x; // mid-stream dead-space penalty

    // Lookahead: reward if next item fits into post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr as f64 {
            score -= 12.0 * (1.0 - nx / cap) * (0.5 + 0.5 * progress);
        } else {
            score += 8.0 * (nx - pr as f64) / cap;
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Slight penalty when bin deviates from mean residual (favor typical bins)
    score += 0.05 * (pr - mean_residual).abs();

    // Mild pressure against accumulating too many bins when a tight fit exists
    score += 0.02 * open_bins_count as f64 * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: partition post_residual into capacity-fraction classes.
    // Small post_residuals are "dead space" classes; mid residuals are reusable.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // capacity fraction remaining

    // Class 1: near-perfect fill (post_residual <= 5) -> strong reward
    if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    } else if post_residual <= 20 {
        score -= 10.0;
    }

    // Class 2: dead-space band (21..=35) -> penalty, hard to refill
    if post_residual >= 21 && post_residual <= 35 {
        score += 15.0;
    }

    // Modulo arithmetic on post_residual: residuals divisible by common
    // item-size classes (10, 20, 25, 50) are refillable -> reward.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 12.0; }
        if post_residual % 20 == 0 { score -= 8.0; }
        if post_residual % 25 == 0 { score -= 6.0; }
        if post_residual % 50 == 0 { score -= 4.0; }
    }

    // Lookahead coupling: next item fits exactly or nearly into post_residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (next_item_size as u32) == post_residual {
            score -= 50.0; // perfect chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here: mild penalty proportional to overshoot class
            let over = ((next_item_size - post_residual as u32) / 10) as f64;
            score += 5.0 * over;
        }
        // harmonic pairing: item + next sums to a capacity fraction
        let s = (item_size + next_item_size) as f64;
        if s == cap { score -= 15.0; }
        if s == cap / 2.0 { score -= 5.0; }
    }

    // Integer-division thresholds on fill level (harmonic quarters of capacity)
    let used = bin_residual - post_residual;
    let quarter = bin_capacity / 4;
    match used / quarter {
        3 => score -= 8.0,  // bin nearly full, prefer finishing it
        2 => score -= 3.0,
        _ => {}
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: neutral baseline; only attractive when
    // open bins are all poor fits (large mean residual spread).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Opening new bins costs more early; mean residual high => open bins are fragmented
        score = 40.0 + 30.0 * progress - 0.1 * mean_residual;
        if fitting_bins_count <= 1 {
            score -= 20.0; // few alternatives, new bin reasonable
        }
    }

    // Many open bins: discourage spreading, favor consolidation
    score += 0.5 * open_bins_count as f64 * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
