    score += (open_bins_count as f64) * 1.5;

    // Mean-residual coupling.
    if residual < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score += 120.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 100.0 * progress;
        score += 10.0 * (open_bins_count as f64);
        if fitting_bins_count > 1 {
            score += 100.0 * (fitting_bins_count as f64 - 1.0);
        }
        score += 0.5 * mean_residual;
        if item_size < (bin_capacity / 2) {
            score += 12.0;
            if next_item_size > 0 && (next_item_size as f64) <= post {
                score += 20.0;
            }
        }
