    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    if post_residual == 0 {
        score -= 40.0; // perfect fit reward
    }

    // Tight fit bonus: item fills a large fraction of the residual.
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_frac;

    // Lookahead: penalize if remaining space can't fit next item usefully.
    if next_item_size > 0 && post_residual > 0 {
        if post_residual < next_item_size {
            score += 15.0; // stranded gap before next arrival
        } else if post_residual - next_item_size < 10 {
            score += 10.0; // next item would create dead space here
        } else {
            score -= 8.0; // chain fit is good
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor consolidation.
    score += 0.8 * open_bins_count as f64;

    // Prefer bins whose residual is below mean (filling emptier bins less).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate: allow opening a fresh bin only when no open bin offers
    // a good fit (item nearly fills residual) or fits are scarce.
    if bin_residual == bin_capacity {
        let good_fit_elsewhere = fill_frac > 0.6;
        if good_fit_elsewhere || (fitting_bins_count > 0 && next_item_size > 0 && post_residual + item_size as u32 >= bin_capacity) {
            score += 500.0; // keep using open bins
        } else if fitting_bins_count == 0 {
            score -= 10.0; // forced new bin
        } else {
            // poor fits only: modest penalty so a bad-fit open bin loses only if truly awful
            score += 45.0;
        }
    }

    score
