pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (low post residual relative to capacity)
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    if post == 0.0 {
        score -= 200.0; // perfect fit: absolutely prefer
    } else {
        // Penalize dead space super-linearly when it can't fit even the smallest item
        if post < 10.0 {
            score += 30.0; // tiny unusable sliver
        }
        // Reward fits that leave space usable by typical items (>= 10)
        if post >= 10.0 {
            score -= 10.0;
        }
    }

    // 2-step lookahead: reward when next item exactly fills the resulting residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0; // chain: next item perfectly consumes this bin
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // still favorable if the next item fits with modest slack
            score -= 40.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here after placement: mild penalty
            score += 15.0;
        }
    }

    // Compare post_residual against mean residual: prefer bins that end below mean
    // (concentrates filling into emptier bins, preserving larger residuals elsewhere)
    score -= 0.5 * (mean_residual - post);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: penalize opening a fresh bin unless the item
    // is huge relative to capacity or no good fits exist
    if bin_residual == bin_capacity {
        // opening new bin is attractive for very large items (little waste anyway)
        // but discouraged when many bins already fit the item
        score += 25.0 + 8.0 * (fitting_bins_count as f64);
        if item_size as f64 > 0.7 * cap {
            score -= 50.0; // large items: fresh bin wastes little
        }
    }

    // Mild preference for fuller bins as the stream progresses (hedge against fragmentation)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
