pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Best-fit core: tighter fit wins
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= tightness * 12.0;

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Penalize dead space that is too small for the smallest plausible item (1..100 range)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this bin
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= (15.0 * (1.0 - slack / 50.0)).max(0.0);
        }
        // If next item cannot fit here but would fit elsewhere, slight penalty for hoarding space
        if next_item_size > post_residual && post_residual < 15 {
            score += 8.0;
        }
    }

    // Last-chance bonus: only bin that fits the item
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Time horizon: early in the stream, be conservative and prefer filling existing bins;
    // late in the stream, tolerate opening new bins less (prefer packing tightly)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 6.0;

    // Global residual pressure: if mean residual is high, prefer using fuller bins
    score += (mean_residual - post_residual as f64) * 0.15;

    // Many open bins -> discourage new bins implicitly via residual; few open bins -> allow spread
    if open_bins_count > 8 {
        score += 3.0;
    } else if open_bins_count <= 2 {
        score -= 2.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well
    if bin_residual == bin_capacity {
        // base cost of opening a bin, discounted when item is large
