    let mut score = post_residual as f64;

    // Strongly penalize small unusable dead space (gaps too small for typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits (exact or near-exact).
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Pressure from number of open bins: prefer consolidating into fewer bins.
    score += open_bins_count as f64 * 0.5;

    // Prefer bins with residual below mean residual (pack fuller bins first).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 10.0;
    }

    // Mild preference for opening a new bin when many bins are already very full.
    if bin_residual == bin_capacity {
        score -= 20.0;
    }

    score
}

