        for d in [10u32, 20, 25, 40, 50] {
            if pr % d == 0 {
                harmonic_bonus += d as f64 * 0.15;
            }
        }
        score -= harmonic_bonus;
        // Integer-division threshold: leftover in a "mid" band is awkward.
        let band = pr / 10; // 0..=10
        if band >= 1 && band <= 2 {
            score += 8.0; // 10..29 leftover: hard to reuse
        } else if band >= 8 {
            score += 2.0; // large leftover is fine (flexible)
        }
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tight fit reward relative to capacity fractions.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= fill_frac * 15.0;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if next item can exactly fill the post_residual,
    // reward heavily (harmonic chaining).
