        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let r2 = post_residual - next_item_size;
            if r2 < 10 {
                score += (10 - r2) as f64 * 1.5; // would create new dead space
            } else {
                score -= 5.0;
            }
        } else {
            // Next item won't fit here anyway; slight bonus for big leftover.
            score += 3.0;
        }
    }

    // New-bin candidate handling: opening a bin is penalized more when many
    // bins are open (amortization) or early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + 20.0 * progress + open_bins_count as f64 * 2.0;
        // But if mean residual across open bins is small (all bins nearly full),
        // opening fresh is less bad.
        score -= (mean_residual / bin_capacity as f64) * 15.0;
