        if post_residual >= 40 {
            score -= 9.0;
        }
        if post_residual < 30 {
            score += 7.5 * (30 - post_residual) as f64 / 18.0;
        }
    }

    // Penalize very small leftover gaps (dead space).
    if post > 0.0 && post < 0.25 * cap {
        score += 30.0 * (1.0 - post / (0.25 * cap));
    }

    // Lookahead: reward chains that leave room for the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let chain_tight = 1.0 - (post - nxt) / cap;
            score -= 52.0 * chain_tight;
            if post == nxt {
                score -= 68.0;
            }
            if post >= nxt + mean_residual {
                score -= 10.0;
            }
            if post >= nxt && (post - nxt) <= mean_residual * 0.5 {
                score -= 8.0;
            }
            if post - nxt >= 1.0 && post - nxt <= 4.0 {
                score -= 12.0;
            }
            if post - nxt < 6.0 {
                score -= 18.0;
            }
        } else if post + 10.0 >= nxt {
            score += 6.0;
        } else {
            score += 0.06 * (nxt - post);
        }
        // Near-miss: opening a bin for the next item is cheap if the gap is tiny.
        if nxt > post && (nxt - post) as u32 <= 2 && fitting_bins_count > 1 {
            score += 15.0;
        }
        if nxt > post && (nxt - post) as u32 > 20 && post_residual > 0 && post_residual < 20 {
            score += 12.0;
        }
    } else {
        score += post * 2.2;
    }

    // Dead-space relative to lookahead item.
    if post_residual > 0 && post_residual < 8 && next_item_size as f64 > post_residual as f64 {
        score += 26.0;
    }
    if post_residual > 0 && post_residual < 16 && next_item_size as f64 > post_residual as f64
        && (mean_residual as u32) > post_residual {
        score += 9.0 * (16 - post_residual) as f64 / 8.0;
    }

    // Many open bins: discourage spreading across bins when a big fit is available.
    if fitting_bins_count > 4 && bin_residual != bin_capacity && post_residual > 30 {
        score += 3.0;
    }

    // Chain-fit bonus: residual that fits 3/4 of the next item.
    if post_residual > 0 && next_item_size > post_residual
        && post_residual >= (next_item_size * 3 / 4) && post_residual < next_item_size {
        score -= 5.0 * (post_residual as f64 - next_item_size as f64 * 0.75)
            / (next_item_size as f64 * 0.25).max(1.0);
    }

    // Open-bin pressure: mild, scaled by stream length.
    let pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
    score += pressure * 2.0;

    // Last-chance bin: keep it attractive to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer bins already more packed than average.
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    // New-bin guard: only open a new bin when the best existing fit is truly poor.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 45.0 + (post_residual as f64).min(50.0);
        }
        // Early stream: slightly cheaper to open bins (more future packing freedom).
        if step_index < total_items / 4 {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match with next item is gold.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post == nxt {
            score -= 40.0; // exact 2-chain: fill fully next step
        } else if post > nxt {
            let slack = post - nxt;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
        } else {
            // next item won't fit here; penalize leftover dead space more
            score += 8.0 * (nxt - post) / 100.0;
        }
        // bonus if chain completes leaving near-zero residual
        if nxt >= post && post == 0.0 {
            score -= 25.0;
        }
    } else {
        // last item: just minimize residual
        score -= 5.0;
    }

    // Reward tight fits relative to mean residual
    let post_f = post_residual as f64;
    if post_f < mean_residual {
        score -= (mean_residual - post_f) * 0.3;
    } else {
        score += (post_f - mean_residual) * 0.15;
    }

    // Last-chance bin: strong penalty to open a new bin instead
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New empty bin candidate: only attractive when current item leaves
    // awkward residual that no other bin wants (high dead-space risk).
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        let awkward = (post_residual > 0 && post_residual < 10)
            || (next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 20);
        if awkward && fitting_bins_count > 1 {
            score -= 15.0; // allow opening a fresh bin for bad fits
        } else {
            score += 25.0 + open_bins_count as f64 * 0.5; // prefer reusing open bins
        }
    }

    // Mild progress-aware scaling: late in stream, be greedier about tight fits
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 2.0 * (1.0 - post_f / bin_capacity as f64);

    score
}

