pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post_residual non-linearly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 50.0 + (10 - post_residual) as f64 * 5.0;
    } else {
        // Penalize large dead space quadratically.
        score += (post_residual as f64).powi(2) / 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual, big bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 200.0;
        } else if post_residual >= next_item_size {
            score -= 20.0 - (post_residual - next_item_size) as f64 * 0.2;
        } else {
            // Next item won't fit here; penalize wasted space relative to next item.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Prefer fuller bins relative to the mean residual of open bins.
    score += (mean_residual - bin_residual as f64) * 0.5;

    // When many bins are open, encourage consolidation into existing bins.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: penalize opening a new bin unless current item is large
    // and no good fit exists (encourage first-fit-like behavior early, but allow
    // fresh bins when the item nearly fills a whole bin).
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // New bins are more acceptable for large items late in the stream.
        score += 60.0 - fill_ratio * 70.0 + progress * 10.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Small global pressure: prefer bins whose residual stays usable for
    // typical small items (residual >= 10 keeps options open).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // dead space penalty (unusable fragment)
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, tight residuals matter more.
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (20.0 + 40.0 * progress);

    // Reward near-perfect fits with a smooth quartic dip.
    score -= (1.0 - norm_pr).powi(4) * 30.0;

    // Penalize dead space that next item cannot use (smooth interaction).
    if next_item_size > 0 {
        let gap = norm_pr - norm_next;
        if gap > 0.0 {
            score += gap * gap * 25.0 * (1.0 - progress);
        }
        // Bonus when this placement sets up the lookahead item exactly.
        let match_up = 1.0 - (norm_pr - norm_next).abs() * 2.0;
        if match_up > 0.0 {
            score -= match_up * match_up * 15.0;
        }
    }

    // Last-chance bin: strongly favor using it (smooth in fitting count).
    if fitting_bins_count == 1 {
        score -= 12.0 + 10.0 * progress;
    } else if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0).sqrt() * 3.0;
    }

    // Mild penalty for hoarding many open bins, smoothed by progress.
    score += (open_bins_count as f64).ln1p() * 2.0 * (1.0 + progress);

    // Pull score toward mean residual alignment (smooth quadratic).
    score += ((pr - mean_residual) / cap).powi(2) * 8.0;

    // New-bin candidate: make it less attractive unless residuals are very tight.
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) + 6.0 * norm_item;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 create "dead space classes".
    let residue_class = post_residual % 10;
    // Penalize residual classes that are hard to fill later (small nonzero leftovers).
    if post_residual > 0 {
        if residue_class <= 3 {
            score += (4 - residue_class) as f64 * 2.5; // nasty dead space
        } else if residue_class >= 7 {
            score -= 1.5; // large-enough slot, likely reusable
        }
    }

    // Integer-division thresholds on post_residual: quarter buckets.
    let quarter = bin_capacity / 4;
    if post_residual <= quarter / 2 {
        score += 6.0; // nearly full bin: excellent packing, strong reward
    } else if post_residual <= quarter {
        score += 2.0;
    } else if post_residual > bin_capacity / 2 {
        score += 3.0; // leaving > half empty wastes the bin
    }

    // Modulo coupling with next_item_size: does post_residual harmonically align?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits exactly or near-exactly: reward harmonic alignment.
            let gap = post_residual - next_item_size;
            if gap % 5 == 0 {
                score -= 4.0;
            }
            if gap == 0 {
                score -= 8.0;
            } else if gap <= 5 {
                score -= 3.0;
            }
        } else {
            // Next item cannot use this bin's leftover: penalize generous leftovers
            // that will strand space (unless leftover is tiny).
            if post_residual >= next_item_size / 2 {
                score += 2.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 7.0;
    }

    // New-bin candidate handling: opening a bin is fine early, discouraged late.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 12.0 + 18.0 * progress; // new bins get costlier as stream progresses
    }

    // Tie-break with mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Slight preference for bins with larger current residual among similar fits
    // (fill emptier bins first when residuals are equivalent modulo class).
    score -= (bin_residual % 10) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
