pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    } else if post_residual >= 20 && post_residual < 35 {
        score += 8.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into more bins
    // unless the fit is good; encourage consolidation.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score += open_pressure * (post_residual as f64) * 0.15;

    // New-bin candidate handling: only attractive when the item is large relative
    // to residual capacity or fits nowhere well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Prefer new bin when current item nearly fills a fresh bin
        // or when the next item is large and would waste this bin's residual.
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        let next_waste = if next_item_size > 0 && post_residual > 0 && (next_item_size as u32) > post_residual {
            1.0
        } else {
            0.0
        };
        // Neutral-ish base for new bin; make it competitive only via adjustments.
        score += 5.0;
        score -= fill_ratio * 30.0;
        score -= next_waste * 20.0;
        // With few open bins, opening a new one is cheap.
        if open_bins_count < 4 {
            score -= 10.0;
        }
        // Late in stream, avoid leaving many half-empty bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Lookahead: if next item fits snugly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 50.0;
        } else if gap > 0 && gap < 10 {
            score -= 15.0;
        }
    }

    // Mild preference for tighter fits overall (best-fit bias).
    score -= (bin_residual - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 50.0;
    }

    // 2-step lookahead: reward when next item fits into post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_fit = (post_residual - next_item_size) as f64;
        score -= 30.0 + 0.5 * chain_fit;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // dead space for the next item
        score += 20.0 + (next_item_size - post_residual) as f64 * 0.5;
    }

    // Penalize bins far above mean residual (wasteful big residual bins)
    score += 0.3 * (bin_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    if bin_residual == bin_capacity {
        score += 150.0;
        // opening a bin is fine if the next item is large and post_residual tiny
        if next_item_size > 0 && post_residual < next_item_size && post_residual < 15 {
            score -= 120.0;
        }
    }

    // Late in stream: consolidate, discourage new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 100.0 * progress;
    } else {
        score -= 30.0 * progress;
    }

