pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_post = post_residual as f64 / bin_capacity as f64;
    let norm_item = item_size as f64 / bin_capacity as f64;

    // Smooth non-linear coupling: waste penalty grows with progress
    let waste_coupling = norm_post * norm_post * (0.5 + 2.0 * progress);
    score += waste_coupling * bin_capacity as f64 * 0.5;

    // Reward tight fits with a smooth saturating term
