    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 20.0 * progress;
    }

    // New-bin candidate: penalize opening new bins early, less so late
    if bin_residual == bin_capacity {
        score += 5.0 + 25.0 * (1.0 - progress) * (1.0 - progress);
    }

    // Lookahead: penalize leaving residual just below next item (smooth)
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64) as f64;
        let sig = 1.0 / (1.0 + (-gap / 10.0).exp());
        score -= (1.0 - sig) * 8.0; // penalize when next item won't fit
