    } else if post_residual % eighth == 0 {
        // Exact harmonic multiples (12, 25, 50, 75...) are reusable targets
        score -= 8.0;
    } else if post_residual % 10 == 0 {
        // Multiple of smallest item size: still usable
        score -= 4.0;
    }

    // Perfect fit: zero waste is ideal
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: only attractive when the item fits poorly everywhere
    if bin_residual == bin_capacity {
        // Base new-bin penalty grows with number of open bins (consolidate first)
        score += 25.0 + 3.0 * open_bins_count as f64;
        // But if this bin would leave a harmonic-class residual that the
        // next item can use, opening a new bin is good.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 30.0;
        }
        // Late in the stream, avoid opening bins unless necessary
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
    }

