    if next_item_size > 0 && next_item_size <= post_residual && post_residual > 0 {
        let tightness = 1.0 - (post_residual - next_item_size) as f64 / c;
        score -= 10.0 + 10.0 * tightness;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use the leftover: dead space likely
        score += 15.0;
    }

