pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for any plausible future item are wasted.
    // Treat post_residual < 10 as fully dead: push score high so tight fits win.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - pr) * 8.0; // unusable sliver -> strong penalty
    } else if post_residual == 0 {
        score -= 30.0; // perfect fit: big reward
    } else {
        // Usable leftover: mild reward proportional to how well it can host next item
