            score -= 10.0; // leftover can host the lookahead item
        }
        // Prefer leaving round, reusable gaps (>= 20) over awkward mid gaps
        if post_residual >= 20 {
            score -= 5.0;
        }
    }

    // Tightness reward: fraction of the bin filled by this placement
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 20.0;

    // Open-bin pressure: with many open bins, favor consolidating into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * 0.8;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make empty bin attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
