        // Neutral baseline for a fresh bin.
        score = 0.35 * bin_capacity as f64;
        // Early stream: opening bins is cheap (future items can fill them).
        score -= 20.0 * (1.0 - t);
        // Many open bins with scattered residuals: prefer consolidation instead.
        if open_bins_count > 2 && mean_residual > 15.0 {
            score += 0.8 * mean_residual;
