        // Small current item wastes a fresh bin less; large item should go to open bins.
        score += 0.5 * item_size as f64;
        // If no other bin fits, opening is mandatory — make it attractive.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Existing-bin scaling: reward using bins with above-average residual
        // (keeps tight bins available for small future items).
        let dev = bin_residual as f64 - mean_residual;
        score -= 0.15 * dev;
        // Late in the stream: consolidate aggressively, avoid leftover fragments.
        score += 10.0 * t * (post_residual as f64 / bin_capacity as f64);
        // Prefer bins that already carry load (avoid bin sprawl).
        score -= (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
