pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Tightness: reward small post residuals, especially those below typical small item sizes
        let tight = (post_residual as f64) / (bin_capacity as f64);
        score += 30.0 * tight;
        if post_residual < 10 {
            score -= 40.0; // dead space too small for anything is fine
        } else if post_residual <= 20 {
            score -= 15.0; // usable only by small items — mildly bad
        }
    }

    // Lookahead coupling: if next item fits in post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 60.0 + 0.5 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // post residual can't host next item: penalize proportionally
        score += 10.0 + 0.3 * post_residual as f64;
    }

    // Last chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Crowding: when many bins are open, prefer consolidating (low residual bins)
    if open_bins_count > 4 {
        score -= 0.5 * open_bins_count as f64 * (1.0 - (post_residual as f64 / bin_capacity as f64));
    }

    // Global residual pressure: if mean residual is low, prefer tight fits even more
    let mean_gap = mean_residual - post_residual as f64;
    score += 0.3 * mean_gap;

    // Time horizon: late in stream, be more conservative, favor filling existing bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 25.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: penalize opening a new bin unless item is large and nothing fits well
    if bin_residual == bin_capacity {
        let base_penalty = 120.0;
        let relief = if next_item_size > 0 && next_item_size >= item_size { 30.0 } else { 0.0 };
        let big_item_relief = if item_size >= 60 { 40.0 } else { 0.0 };
        let late_relief = 40.0 * progress;
        score += base_penalty - relief - big_item_relief - late_relief;
    }

    score
}

