    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress;
    score += 40.0 * poly;

    // Reward tight fits, stronger late in the stream
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * (0.5 + progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 + 20.0 * progress;
    }

    // Penalize bins far below mean residual (fragmentation avoidance)
    let dev = (mean_residual - pr) / cap;
    score += 10.0 * dev * dev;

    // Lookahead: reward leaving space for the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            score -= 12.0 * (1.0 - ((pr - ns) / cap).abs());
        } else {
            score += 8.0;
        }
    }

