    score += 2.0 * open_bins_count as f64 * (1.0 - progress) * 0.1;

    // New-bin candidate: penalize unless current bin would leave dead space
    if bin_residual == bin_capacity {
        score += 5.0 - 30.0 * (1.0 - tightness) * (1.0 - tightness);
    }

    score
}

