        // Base reluctance grows with stream progress.
        new_bin_score += 55.0 + 45.0 * progress;
        // Small items should almost never open a new bin.
        if item_frac < 0.5 {
            new_bin_score += 40.0 * (0.5 - item_frac);
        }
        // If a fitting bin gives a decent (small) residual, strongly prefer it.
        if tight_fit_exists {
            new_bin_score += 150.0;
        }
