    // Penalize them quadratically; reward "harmonic" residuals divisible into common sizes.
    if post_residual > 0 {
        // Dead-space penalty grows for tiny residuals.
        if post_residual < 10 {
            score += 60.0 * (10.0 - post) ;
        }
