        let r = post_residual;
        if r % 10 == 0 { score -= 12.0; }
        if r % 20 == 0 { score -= 8.0; }
        if r % 25 == 0 { score -= 6.0; }
        if r % 50 == 0 { score -= 10.0; }
        // Integer-division thresholds: classify residual into bands.
        let band = r / 10; // 0..=10
        score += match band {
            0 => 40.0,          // 1..9 : dead space
            1 => 5.0,           // 10..19 : only tiny items fit
            2 => 0.0,           // 20..29
            3 => -2.0,          // 30..39
            4 => -4.0,          // 40..49
            5 => -6.0,          // 50..59
            6 => -8.0,          // 60..69
            7 => -10.0,         // 70..79
            8 => -12.0,         // 80..89
            9 => -14.0,         // 90..99
            _ => 0.0,           // full/empty bin
        };
    }

    // Lookahead coupling: penalize if next item cannot use the post residual.
    if next_item_size > 0 {
        if next_item_size > post_residual {
            // Next item won't fit here after placement; mild penalty scaled by waste.
            score += 15.0;
        } else {
            // Reward residuals that exactly accommodate the next item (harmonic pairing).
            if next_item_size == post_residual {
                score -= 25.0;
            } else if post_residual % next_item_size == 0 {
                score -= 10.0;
            }
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: an empty bin should only win when open bins are bad.
    if bin_residual == bin_capacity {
