        // but more open bins => mild amortization discount.
        score = 55.0 - 0.5 * open_bins_count as f64;
        // If the next item is huge, a fresh bin is more attractive.
        if next_item_size >= 60 {
            score -= 5.0;
        }
        // If many bins already fit the item, opening a new bin is unattractive.
        if fitting_bins_count > 2 {
            score += 20.0;
        }
        // Late in stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Slight preference for tighter bins relative to mean residual.
    score -= 0.3 * (mean_residual - post);

    score
}

