            score += gap.min(30.0) * 0.8;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // Prefer bins tighter than the mean residual (good fits), penalize loose bins.
    score += (bin_residual as f64 - mean_residual) * 0.25;

    // Slight preference for reusing bins over opening new ones as stream progresses.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize mildly unless current bin fits are terrible.
        score += 12.0 + 8.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Late-stream consolidation: favor filling existing bins more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

