    let mut score = post_residual as f64;

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: small leftover gaps are the worst outcome.
    // If the leftover cannot accommodate even the next item (or a small item),
    // it is likely dead space -> strong penalty.
