    }

    // Moderate leftover (roughly half bin or less) is also wasteful unless usable.
    if post_residual > 0 && post_residual <= bin_capacity / 4 {
        score += 25.0;
    }

    // Reward bins that can still host the next item with this leftover.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0 + 0.5 * next_item_size as f64;
    }

