pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect match: next item fits leaving small slack.
    else if next_item_size > 0 && post_residual > next_item_size {
        let slack = post_residual - next_item_size;
        score -= 30.0 - (slack as f64).min(30.0);
        // Penalize slack that is too small to hold any plausible item (dead space).
