            score += (10 - slack) as f64 * 1.5;
        }
    }
    // Next item does NOT fit this bin after placement: penalize proportionally,
    // but less if this bin still holds a large usable residual.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.6;
        if post_residual < 10 {
            score += (10 - post_residual) as f64 * 2.0; // dead space penalty
        }
    }

    // Compare residual against mean residual across open bins: keep balanced bins.
    let dev = post_residual as f64 - mean_residual;
    score += 0.35 * dev.abs();

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Late in the stream, tighten packing: prefer minimal post residual.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.4;

    // New-bin candidate: neutral-ish but discouraged unless current bin fit is bad.
    if bin_residual == bin_capacity {
        score += 15.0;
        // Opening a new bin is attractive only if the next item is large and
        // this placement would leave a very tight residual elsewhere.
        if next_item_size > 0 && post_residual < next_item_size && post_residual < 15 {
            score -= 40.0;
        }
    }

    score
}

