    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    } else {
        // Penalize dead space non-linearly (dead space grows quadratically in pain).
        let dead = post_residual as f64;
        score += (dead / cap) * (dead / cap) * 40.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (next - post_residual as f64).abs() <= 2.0 {
            score -= 30.0;
        } else if next <= post_residual as f64 {
            score -= 8.0 * (1.0 - next / cap);
        } else {
            // Next item won't fit here: slight penalty proportional to leftover.
            score += 4.0;
        }
    }

    // Last-chance bonus: only one bin fits this item — strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are terrible.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 30.0;
        // Early in stream or few open bins: opening bins is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 100.0;
        }
        // If many bins fit the item, discourage opening a new one.
        score += 5.0 * fitting_bins_count as f64;
    }

    // Global residual pressure: if mean residual is small (bins are tight),
    // prefer placements that leave little waste; if mean residual large, be pickier.
    let mean_gap = (mean_residual - post_residual as f64).abs();
    score += 0.3 * mean_gap;

    // Mild preference for bins with residuals close to item size (good fit ratio).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fit_ratio;

    score
}

