pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post / cap;

    // Base: prefer small post-residual, with smooth polynomial sharpening over stream progress.
    let mut score = post * (1.0 + 0.8 * progress * norm_post * norm_post);

    // Reward tight fits: smooth coupling of item size and post-residual.
    score -= 0.35 * item * (1.0 - norm_post) * (1.0 - norm_post);

    // Penalize dead space relative to mean residual across open bins (smooth interaction).
    score += 0.25 * (post - mean_residual).abs() * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 0.45 * cap * (1.0 - progress);
    }

    // Lookahead: penalize if post-residual cannot fit next item (smooth decay).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = if post >= nxt { 1.0 } else { 0.0 };
        score -= 0.2 * fits_next * nxt / cap * (1.0 - progress);
        // Penalize leaving residual just below next item size (smooth wedge penalty).
        let gap = (nxt - post).max(0.0) / cap;
        score += 0.15 * gap * (1.0 - gap) * nxt / cap;
    }

    // Mild penalty for proliferating bins late in the stream.
    score += 0.02 * open_bins_count as f64 * progress;

    // New-bin candidate shaping: empty bin gets a moderate prior; only chosen when
    // existing residuals are poor.
    if bin_residual == bin_capacity {
        score += 0.30 * cap * (1.0 - 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post * post / cap; // quadratic pressure: big leftovers hurt more

    if post_residual == 0 {
        score -= 1000.0; // perfect fit dominates
    } else {
        // Harmony of the leftover space
        if post % 10 == 0 { score -= 12.0; }
        if post % 20 == 0 { score -= 8.0; }
        if post % 25 == 0 { score -= 8.0; }
        if post % 50 == 0 { score -= 6.0; }
        if post_residual < 10 {
            score += 330.0 / post; // dead sliver: strong penalty
        } else if post_residual <= 20 {
            score += 6.0; // marginal
        } else if post_residual < 40 {
            score -= 4.0; // useful band
        } else {
            score -= 9.0; // large leftover is still usable
        }
        // dead-space band under 25% of capacity
        if post < 0.25 * cap {
            score += 30.0 * (1.0 - post / (0.25 * cap));
        }
        // borrowed from best: reward small usable residuals more aggressively
        if post_residual >= 5 && post_residual < 12 {
            score -= 3.0 * (12 - post_residual) as f64;
        }
        if post_residual >= 40 {
            score -= 4.0;
        }
        // NEW: gradual small-residual penalty ramp (from best heuristic)
        if post_residual < 30 && post_residual >= 12 {
            score += 7.5 * (30 - post_residual) as f64 / 18.0;
        }
    }

    // Lookahead: reward if next item chains into the leftover
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let chain_tight = 1.0 - (post - nxt) / cap;
            score -= 52.0 * chain_tight;
            if post_residual == next_item_size { score -= 68.0; } // exact chain fill
            if post_residual % next_item_size == 0 { score -= 18.0; } // harmonic chain
            if (post_residual - next_item_size) % 10 == 0 { score -= 6.0; }
            if post_residual - next_item_size <= 4 { score -= 12.0; } // near-perfect chain
            if post >= nxt + mean_residual { score -= 10.0; }
            if (post - nxt) <= mean_residual * 0.5 { score -= 8.0; }
            if post - nxt < 6.0 { score -= 18.0; }
            if (post_residual as f64 - nxt) as u32 == mean_residual as u32 { score -= 9.0; }
            if post_residual <= 25 && next_item_size as f64 > post_residual as f64 * 0.6 {
                score -= 13.0 * (1.0 - post_residual as f64 / 25.0);
            }
            // NEW: mid-range chain bonus scaled by dead-space ratio
            let chain_gap = post - nxt;
            if chain_gap <= 12.0 && chain_gap <= mean_residual * 1.2 {
                score -= 7.0 * (1.0 - chain_gap / 12.0);
            }
            if chain_gap <= 2.0 && post > 0.4 * cap {
                score -= 9.0;
            }
        } else {
            // next item won't fit here
            if post_residual > 0 && post_residual < 10 { score += 26.0; }
            if nxt - post <= 2.0 && fitting_bins_count > 1 { score += 15.0; }
            if nxt - post > 20.0 && post_residual < 20 { score += 12.0; }
            if post_residual < next_item_size / 2 {
                score += 6.0 * (1.0 - post_residual as f64 / (next_item_size / 2).max(1) as f64);
            }
            if post_residual > 0 && post_residual < item_size && open_bins_count > 3 { score += 8.0; }
            // NEW: near-miss penalty scaled by how close next item is
            if post_residual > 0 && nxt - post <= 10.0 {
                score += 4.0 * (1.0 - (nxt - post) / 10.0);
            }
            // NEW: penalize large dead space when next item overshoots badly
            let dead = post / cap;
            if dead > 0.35 && post_residual as f64 > mean_residual * 1.5 && fitting_bins_count > 3 {
                score += 10.0 * (dead - 0.35);
            }
            // NEW: residual just under next item (wasted near-fit)
            if post_residual >= (next_item_size * 3 / 4) && post_residual < next_item_size {
                score += 5.0 * (post_residual as f64 - next_item_size as f64 * 0.75) / (next_item_size as f64 * 0.25).max(1.0);
            }
        }
    } else {
        score += post * 2.2;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        score -= 20.0; // base cost of opening a bin
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * (1.0 - progress); // early: bins cheap; late: consolidate
        if mean_residual < item_size as f64 && open_bins_count > 2 {
            score += 10.0;
        }
        // many open bins with slack: prefer consolidating instead of new bin
        if open_bins_count > 5 && mean_residual > 0.4 * cap {
            score += 12.0;
        }
        // late stream: opening new bins is expensive, tighten further
        if progress > 0.6 && open_bins_count > 3 {
            score += 8.0;
        }
    } else {
        // tightness pressure toward fuller bins
        let tightness = 1.0 - (bin_residual as f64 / cap);
        score -= 10.0 * tightness;
        // many fitting bins means this choice matters less; slight penalty for sloppy fits
        if fitting_bins_count > 4 && post_residual > 30 {
            score += 3.0;
        }
        // penalize leaving dead space when next item is much larger than residual
        if post_residual > 0 && next_item_size as f64 > post && post_residual as f64 > mean_residual * 1.5 && fitting_bins_count > 3 {
            score += 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" is the leftover space.
    // Items are 1..100, so a leftover that can't hold a mid-size item is dead space.
    let dead_threshold = 20u32;
    if post_residual > 0 && post_residual < dead_threshold {
        // Nearly-dead space: penalize proportionally to how close to zero it is,
        // creating a strong incentive for tight fits (post_residual == 0 is perfect).
        score += (dead_threshold - post_residual) as f64 * 3.0;
    } else if post_residual == 0 {
        // Perfect closure of the bin: big reward.
        score -= 60.0;
    }

    // Modulo/harmonic classes of post_residual relative to capacity fractions.
    // Leftovers in "quarter classes" (25/50/75) are statistically reusable.
    let quarter = bin_capacity / 4;
    let class = post_residual % quarter.max(1);
    if class == 0 && post_residual > 0 {
        score -= 8.0; // aligns with capacity fractions: likely to fit future items
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            // reward leftovers that leave a good class for the next item
            let chain = post_residual - next_item_size;
            if chain < dead_threshold {
                score -= 15.0 - chain as f64 * 0.5;
            } else {
                score -= 5.0;
            }
        } else {
            // next item cannot use this bin's leftover: mild penalty unless leftover is large
            if post_residual < next_item_size {
                score += (next_item_size - post_residual) as f64 * 0.3;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // Only prefer a new bin when all open bins would create tiny dead space.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = 35.0;
        // Slightly cheaper to open bins early in the stream (amortization).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 10.0;
        // If many bins are open, discourage adding more (fragmentation control).
        score += open_bins_count as f64 * 0.5;
        // If the next item is huge, a fresh bin is more valuable.
        if next_item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    } else {
        // Prefer bins whose residual is closest to the item (best-fit core),
        // but reward bins that are "harmonically aligned" with the item size.
        let tightness = (bin_residual - item_size) as f64;
        score += tightness * 0.1;
        // Reward using bins with below-mean residual (consolidate fuller bins).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
        // Harmonic class of item: items that are exact divisors/multiples of 25
        // pack well into quarter classes.
        if item_size % 25 == 0 {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Perfect fit gets a big reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits in the post residual, reward; otherwise penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 + (next_item_size as f64 / 10.0);
        } else if post_residual > 0 {
            score += 5.0;
        }
    }

    // Open-bin pressure: prefer fewer open bins when residuals are similar.
    score += open_bins_count as f64 * 0.3;

    // New-bin candidate: only attractive when all open bins would leave large dead space.
    if bin_residual == bin_capacity {
        let mean_dead = mean_residual - item_size as f64;
        if mean_dead > 0.0 && mean_dead < 15.0 {
            score -= 10.0; // opening new bin beats wasting near-full gaps
        } else {
            score += 15.0; // prefer existing bins otherwise
        }
    }

    // Mild progress scaling: tighter fits matter more early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.2 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
