            let waste = (post_residual - next_item_size) as f64;
            score -= 80.0 - 0.5 * waste.min(80.0);
        } else {
            // next item cannot use the leftover: penalize proportional overshoot
            let over = (next_item_size - post_residual) as f64;
            score += 0.6 * over.min(90.0);
        }
    }

    // Compare against mean residual: avoid leaving far more (or far less) than average
    let diff = post_residual as f64 - mean_residual;
    score += 0.3 * diff.abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // New-bin candidate: only attractive if all open bins are nearly full
    if bin_residual == bin_capacity {
        let tight = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
