        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 30.0; // fresh bin can host a good pair
        }
    }

    // Slight preference for filling more-opened bins early in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.1 * (1.0 - progress) * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is already favored; amplify it.
    let tightness = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 4.0 * tightness;

    // Penalize dead space: post residuals too small to ever be useful (assume min item ~1, but
    // heavily punish residuals that fit almost nothing relative to typical item sizes).
    if post_residual > 0 {
        let deadness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score += 2.0 * deadness * deadness * (item_size as f64 / 100.0);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Lookahead: if the next item could exactly use the post residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            // next item still fits here: mild reward proportional to how well it pairs.
            let pair_waste = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - pair_waste / bin_capacity as f64);
        } else {
            // next item won't fit after this placement: penalize leaving a stranded residual
            score += 0.05 * post_residual as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer the tightest (already encoded), slight crowding penalty
        score += 0.3 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate logic: opening a new bin wastes bin_residual of an existing bin.
    // Penalize the new-bin candidate when open bins exist with reasonable residual,
    // reward it when existing residuals are fragmented and item is large.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        // Waste of keeping open bins around: compare mean residual to item size.
        let fragmentation = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // If mean residual is large and item is small, prefer filling existing bins.
        score += 8.0 * fragmentation * (1.0 - item_size as f64 / 100.0);
        // Late in the stream, opening fresh bins is less costly (fewer future items to strand).
        score -= 5.0 * progress;
        // If next item is large and would need a fresh bin anyway, opening now is fine.
        if next_item_size > 0 && next_item_size > mean_residual as u32 {
            score -= 6.0;
        }
    }

    // Mild preference for keeping the number of open bins low early on.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer minimal post residual, but with a non-linear (quadratic) bias
    // so small dead space is strongly favored over moderate dead space.
    let mut score = post / cap;
    score += 0.35 * (post / cap) * (post / cap);

    // Smooth interaction: as the stream progresses, penalize residual waste more
    // aggressively (late in the stream, dead space matters more).
    score += 0.5 * progress * (post / cap);

    // Cubic coupling between progress and normalized residual: smooth, no piecewise
    score += 0.25 * progress * progress * progress * (post / cap);

    // Penalize bins whose residual is far below the mean residual (they are scarce space),
    // reward bins close to the mean (balanced usage).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.2 * dev * dev.abs();

    // Lookahead: reward residual that can fit the next item smoothly.
    if next_item_size > 0 {
        let fits_next = (post_residual >= next_item_size) as i32 as f64;
        let tight = (next_item_size as f64 / cap).min(1.0);
        score -= 0.4 * fits_next * (1.0 - tight) * (1.0 - progress);
    }

    // Last-chance bonus: smooth reward when this is the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 0.6 * (1.0 - post / cap);
    }

    // Mild penalty for many open bins to discourage unnecessary fragmentation.
    score += 0.02 * open_bins_count as f64 * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post * post / cap;

    // Exact fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 330.0 / post;
    } else if post_residual < 12 {
        score += 90.0 + (12 - post_residual) as f64 * 6.0;
    } else {
        score -= 15.0 * (post / cap);
        if post_residual >= 40 {
            score -= 9.0;
        }
        if post_residual < 30 {
            score += 7.5 * (30 - post_residual) as f64 / 18.0;
        }
    }

    // Lookahead: next item chains tightly into the remaining space.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let chain_tight = 1.0 - (post - nxt) / cap;
            score -= 52.0 * chain_tight;
            if post == nxt {
                score -= 68.0;
            }
            if post >= nxt && (post - nxt) <= mean_residual * 0.5 {
                score -= 8.0;
            }
            if post - nxt >= 1.0 && post - nxt <= 4.0 {
                score -= 12.0;
            }
        } else if post + 10.0 >= nxt {
            score += 6.0;
        } else {
            score += 0.06 * (nxt - post);
        }
        if nxt <= post && post - nxt < 6.0 {
            score -= 18.0;
        }
        if nxt > post && (nxt - post) as u32 <= 2 && fitting_bins_count > 1 {
            score += 15.0;
        }
        if nxt > post && (nxt - post) as u32 > 20 && post_residual > 0 && post_residual < 20 {
            score += 12.0;
        }
    } else {
        score += post * 2.2;
    }

    // Dead space that is too small to be useful for the next item.
    if post_residual > 0 && post_residual < 8 && next_item_size > post_residual {
        score += 26.0;
    }
    if post_residual > 0 && post_residual < 16 && next_item_size > post_residual && (mean_residual as u32) > post_residual {
        score += 9.0 * (16 - post_residual) as f64 / 8.0;
    }

    // Prefer tighter bins relative to the mean.
    let mean_diff = (bin_residual as f64) - mean_residual;
    score += 0.3 * mean_diff;

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Consolidation pressure when many bins compete.
    if fitting_bins_count > 4 && bin_residual != bin_capacity && post_residual > 30 {
        score += 3.0;
    }
    score += 0.05 * open_bins_count as f64;

    // Half-fit lookahead bonus: residual that can still host a large fraction of next item.
    if post_residual > 0 && next_item_size as f64 <= post && next_item_size as f64 > post_residual as f64 * 0.6 && post_residual <= 25 {
        score -= 13.0 * (1.0 - post_residual as f64 / 25.0);
    }

    // Avoid creating fragments smaller than the next item when alternatives exist.
    if post_residual > 0 && post_residual < item_size && next_item_size as f64 > post && open_bins_count > 3 {
        score += 8.0;
    }
    if post_residual > 0 && next_item_size as f64 > post && post_residual < (next_item_size / 2).max(1) {
        score += 6.0 * (1.0 - post_residual as f64 / (next_item_size / 2).max(1) as f64);
    }
    if post_residual > 0 && next_item_size as f64 > post && post < 0.25 * cap {
        score += 30.0 * (1.0 - post / (0.25 * cap));
    }

    // New-bin logic: early in the stream, opening a fresh bin is cheap; later, resist it.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_bonus = 40.0 * (1.0 - progress);
    if bin_residual == bin_capacity {
        score -= new_bin_bonus;
        // Late in the stream, only open a new bin if no open bin gives a decent fit.
        if progress > 0.5 && post_residual > 0 && fitting_bins_count > 0 {
            score += 25.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lies in "reusable"
    // residue classes (multiples of common small item sizes) are more valuable.
    let classes: [u32; 6] = [10, 20, 25, 33, 50, 0];
