    // New-bin candidate: penalize opening a fresh bin unless current bin
    // would leave large unusable residue.
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.1;
        if post_residual > 60 {
            score += 10.0;
        }
    }

    // Mean-residual alignment: prefer bins near the mean residual (balanced use).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    score
}

