        if dead > 0.35 && (post_residual as f64) > mean_residual * 1.5 && fitting_bins_count > 3 {
            score += 10.0 * (dead - 0.35);
        }
    }
    if post_residual > 0 && next_item_size as f64 <= post && (post - next_item_size as f64) <= 2.0 && post / cap > 0.4 {
        score -= 9.0;
    }
    if post_residual > 0 && next_item_size as f64 <= post {
        let gap = post - next_item_size as f64;
        if gap <= 12.0 && gap <= mean_residual * 1.2 {
            score -= 7.0 * (1.0 - gap / 12.0);
        }
    }
    if post_residual > 0 && next_item_size > post_residual && post_residual >= (next_item_size * 3 / 4) && post_residual < next_item_size {
        score += 5.0 * (post_residual as f64 - next_item_size as f64 * 0.75) / (next_item_size as f64 * 0.25).max(1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space that no plausible item can fill (items >= 1, typical >= 10).
    let dead = if post_residual < 10 { post_residual as f64 * 0.0 } else { 0.0 };
    score += dead;

    // Lookahead: reward bins whose post_residual exactly matches the next item,
    // or can still fit the next item (chained packing).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 0.5 {
            // Perfect chain: place next item here too.
            score -= 25.0;
        } else if post_residual >= next_item_size {
            // Next item still fits after this placement.
            score -= 10.0;
        } else {
            // Post-residual too small for next item: penalize proportionally to waste.
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 8.0 * waste;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than the mean residual
    // (best-fit behavior), penalize bins looser than average.
    let rel = post_residual as f64 - mean_residual;
    score += 0.15 * rel;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin for a mediocre fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: make opening a new bin costly unless the item fits
    // poorly everywhere. An empty bin has post_residual == capacity - item_size,
    // which is large; the base score already penalizes it. Add extra penalty
    // scaled by how early in the stream we are (preserve open-bin flexibility).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * (1.0 - 0.5 * progress);
    }

    // Mild preference for compacting many open bins as stream matures.
    score += 0.05 * open_bins_count as f64 * (1.0 - step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor placements leaving little dead space.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 14.0 * tight * tight;

    // Lookahead: if the next item fits exactly or well into the post-residual,
    // this placement chains nicely; reward it.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_gap = post_residual - next_item_size;
        score -= 9.0 * (1.0 - chain_gap as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item can't use leftover space: mild penalty proportional to wasted residual.
        score += 0.06 * post_residual as f64;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no
    // existing bin fits well, or the item is large relative to residual capacity
    // of the stream's typical demand. Penalize new bins mildly by default.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Early in stream: opening bins is cheap; later: prefer consolidation.
        score += 6.0 + 10.0 * progress;
        // If many bins fit the item, opening a new one is wasteful.
        if fitting_bins_count > 1 {
            score += 8.0 * (fitting_bins_count as f64 - 1.0).min(4.0);
        }
        // If the current bin leaves a residual that no plausible next item uses
        // (residual smaller than min plausible size 1 => perfect), skip.
        if post_residual == 0 {
            score -= 100.0; // perfect fill of a fresh bin is impossible; guard
        }
    } else {
        // Reward using existing bins when mean residual is high (fragmentation risk).
        if mean_residual > (item_size as f64) {
            score -= 3.0;
        }
        // Prefer filling bins that are already relatively full.
        let filled = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
        score -= 5.0 * filled;
        // Penalize leaving residuals in the awkward 1..10 dead-zone.
        if post_residual >= 1 && post_residual < 10 {
            score += 7.0;
        }
        // Many open bins: encourage consolidation.
        score += 0.35 * open_bins_count as f64;
    }

    // Exact fill is always ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post * post / cap;

