    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: reward tight fits (small post residual)
    let mut score = pr as f64;

    // Non-linear polynomial coupling with stream progress:
    // early in stream, prefer leaving moderate residual (flexibility);
    // late in stream, strongly prefer very small post residuals.
    let flex = x * (1.0 - x); // peaks at x=0.5, zero at perfect fit / empty bin
    score -= 12.0 * flex * (1.0 - progress);

    // Penalize large dead space with a convex term, weighted by progress
    score += 30.0 * x * x * progress;

    // Lookahead coupling: reward post residual that still fits next item smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= 6.0 * (1.0 - slack) * (1.0 - progress);
            score += 4.0 * slack * slack;
        } else {
            // post residual too small for next item: penalize proportionally
            let gap = (nx - pr) / cap;
            score += 10.0 * gap * (0.5 + 0.5 * progress);
        }
    }

    // Last-chance bin: strong bonus when few fitting bins (avoid new bin)
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - x);
