    // Mild penalty when many bins are open and fit is loose
    score += (open_bins_count as f64).ln() * x * 2.0;

    // Mean residual deviation coupling: prefer bins below mean residual (tighter)
    let dev = (mean_residual - pr) / cap;
    score -= 5.0 * dev;

    // New-bin candidate: neutral-ish baseline with slight progress-dependent penalty
    if bin_residual == bin_capacity {
        score = cap * (0.55 + 0.25 * progress) + 5.0 * x * x;
    }

    score
}

