    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: quarter-band classification
    let quarter = post_residual / (bin_capacity / 4).max(1);
    let band_penalty = match quarter {
        0 => -18.0,               // near-perfect fill: reward strongly
        1 => -4.0,                // good fill
        2 => 6.0,                 // mediocre
        _ => 14.0,                // wasteful residual
    };
    score += band_penalty;

    // Modulo-10 harmonic class: residuals divisible by 10 are more reusable
    let mod10 = post_residual % 10;
    if mod10 == 0 {
        score -= 8.0;
    } else if mod10 <= 2 {
        score += 3.0;             // awkward sliver
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
