                score -= 25.0;
            } else {
                score -= 12.0 * (1.0 - gap / cap);
            }
        } else {
            // next item won't fit here: penalize more if residual is large dead space
            score += 0.05 * (post_residual as f64);
        }
    } else {
        // last item: pure fill maximization
        score -= 10.0;
    }

    // Last-chance bin before opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: make it moderately unattractive unless residuals are bad
    if bin_residual == bin_capacity {
        score += 30.0
            + 0.25 * mean_residual
            + (open_bins_count as f64).sqrt() * 4.0;
        // but if nothing fits well anywhere (large mean residual), opening is fine
        if mean_residual > 0.6 * cap {
            score -= 35.0;
        }
    }

    // Slight tightening over stream progression
    score -= 4.0 * (step_index as f64 / total_items.max(1) as f64);

    // Integer-division threshold: residuals > half capacity are semi-wasteful
    if post_residual > bin_capacity / 2 {
        score += 5.0;
    }

    score
}

