        // Base cost of consuming a fresh bin.
        score += 55.0;
        // Large items justify a fresh bin more; small items do not.
        score -= (item_size as f64 / bin_capacity as f64) * 40.0;
        // If nothing else fits, opening a bin is mandatory: soften cost.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Late in the stream, leftover capacity has less chance to be reused;
    // tighten dead-space tolerance slightly over time.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.15;

