    // New-bin candidate: only attractive when many items pending and poor fits abound
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = (post_residual as f64) / bin_capacity as f64;
        score = 100.0 + 50.0 * (1.0 - progress) - 30.0 * (1.0 - waste);
