pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post * post / cap;

    // Reward exact or near-exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 330.0 / post;
    } else if post_residual < 12 {
        score += 90.0 + (12 - post_residual) as f64 * 6.0;
    } else {
        score -= 15.0 * (post / cap);
        if post_residual >= 40 {
            score -= 9.0;
        }
        if post_residual < 30 {
            score += 7.5 * (30 - post_residual) as f64 / 18.0;
        }
    }

    // Aggressive lookahead: if the next item fits into post_residual, reward tight chains.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let chain_tight = 1.0 - (post - nxt) / cap;
            score -= 52.0 * chain_tight;
            if post == nxt {
                score -= 68.0;
            }
            if post >= nxt + mean_residual {
                score -= 10.0;
            }
            if (post - nxt) >= 1.0 && (post - nxt) <= 4.0 {
                score -= 12.0;
            }
            if (post - nxt) < 6.0 {
                score -= 18.0;
            }
        } else if post + 10.0 >= nxt {
            score += 6.0;
        } else {
            score += 0.06 * (nxt - post);
        }
        // Next item won't fit here: penalize tiny useless residuals.
        if nxt > post && post_residual < 10 {
            score += 60.0;
        }
        if nxt > post && (nxt - post) as u32 <= 2 && fitting_bins_count > 1 {
            score += 15.0;
        }
        if nxt > post && (nxt - post) as u32 > 20 && post_residual > 0 && post_residual < 20 {
            score += 12.0;
        }
    } else {
        score += post * 2.2;
    }

    // Small residual that next item can't use: waste penalty.
    if post_residual > 0 && post_residual < 8 && next_item_size > post_residual {
        score += 26.0;
    }

