pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;
    let item_norm = item_size as f64 / cap;

    // Base: prefer small post_residual, with non-linear polynomial shaping
    let mut score = post_norm * (1.0 + 0.8 * post_norm * post_norm);

    // Smooth coupling: residual quality weighted by stream progress
    // Early on, larger residual space is more valuable; later, tight fits dominate
    let tight_fit_bonus = (1.0 - post_norm) * (1.0 - post_norm);
    score -= tight_fit_bonus * (0.5 + 1.5 * progress);

    // Penalize dead space relative to mean residual (smooth quadratic divergence)
    let dead = (post - mean_residual) / cap;
    score += 0.3 * dead * dead.abs();

    // Reward using bins that would otherwise be wasted when few fitting bins remain
