pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose residual falls into
    // "small" residue classes modulo 10 are dead space; penalize them.
    let post = post_residual;
    let class = post % 10;
    let dead_penalty = match class {
        0 => -6.0,                       // perfectly reusable chunk
        1..=3 => 4.0,                    // nearly dead space
        4..=7 => 0.0,
        _ => 2.0,
    };
    score += dead_penalty;

    // Integer-division thresholds: residual in [1..=9] is unusable for any
    // item (min size 1, but typically small); strong penalty for tiny residue.
    if post > 0 && post <= 5 {
        score += 12.0;
    }

    // Reward near-perfect fits (residual 0) heavily.
    if post == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 18.0;
        } else if next_item_size < post {
            // harmonic class match on modulo 10 of next item vs post residual
            if next_item_size % 10 == post % 10 {
                score -= 6.0;
            }
            score += (post - next_item_size) as f64 * 0.15;
        } else {
            // next item won't fit here; slight penalty proportional to overshoot class
            let overshoot_class = (next_item_size - post) / 10;
            score += overshoot_class as f64 * 0.8;
