    // Last-chance bin: if this is the only fitting bin, discourage opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: empty bin gets a mild handicap so we prefer
    // reusing open bins, but handicap shrinks as stream progresses or when
    // existing residuals are fragmented (mean residual low).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        score += 10.0 - 6.0 * progress - 4.0 * fragmentation;
        // If item is large relative to capacity, opening fresh bin is fine.
        if item_size as f64 > 0.7 * cap {
            score -= 5.0;
        }
    }

