    if post % 50 == 0 && post > 0 {
        score -= 3.0;
    } else if post % 25 == 0 && post > 0 {
        score -= 1.5;
    }

    // Mild normalization by mean residual: spread load when residuals are large.
    score += (mean_residual - post as f64) * 0.05;

    score
}

