pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: reward bins whose leftover can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 2.0 * next_item_size as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);
        } else {
            // leftover too small for next item: penalize dead space, worse if truly tiny
            let waste = post_residual as f64;
            if waste < 10.0 {
                score += 8.0;
            }
            // if next item barely misses, mild penalty
            score += 0.5 * (next_item_size - post_residual).min(20) as f64;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when current bin fits are poor
    if bin_residual == bin_capacity {
        score += 40.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // late in stream, prefer filling existing bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 * progress;
        // many open bins with large mean residual: discourage new bin
        score += 2.0 * open_bins_count as f64 + 0.5 * mean_residual;
    }

    // Tight-fit preference among open bins: smaller relative leftover is better
    score += 0.3 * (post_residual as f64 - mean_residual).max(-50.0).abs().min(50.0) * -1.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth non-linear coupling: residual waste scaled by progress pressure
    let pr_norm = pr / cap;
    let poly = pr_norm * pr_norm * (1.0 - pr_norm); // peaks mid-range residual
    score += 12.0 * poly * (0.5 + progress);

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - pr_norm;
    score -= 20.0 * tightness * tightness * progress;

    // Penalize leaving residual that can't fit the next item (smooth interaction)
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0);
        let gap_norm = gap / cap;
        score += 15.0 * gap_norm * gap_norm * (1.0 - progress);
    }

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.4 + 0.6 * progress);
    }

    // Slight penalty for spreading across many open bins
    score += 0.3 * open_bins_count as f64 * pr_norm;

    // Prefer bins below mean residual (denser bins) with smooth term
    score += 0.5 * (mean_residual - pr) * (0.5 + progress);

    // New-bin candidate: penalize opening new bins unless residual is large
    if bin_residual == bin_capacity {
        score += 8.0 + 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: perfect fits are strongly rewarded.
    let post = post_residual as i64;
    if post == 0 {
        score -= 1000.0; // exact fill, ideal
    } else if post <= 10 {
        score -= 60.0; // near-perfect, dead space negligible
    } else {
        // Penalize residuals that are "harmonically awkward": not expressible
        // as a small multiple of common item classes (mod 10 buckets).
        let class = post % 10;
        let awkward = match class {
            1..=3 => 1.0,          // slivers almost no item can use
            8 | 9 => 0.4,          // close to a full decade, decent
            4..=7 => 0.7,
            _ => 0.0,              // decade-aligned residuals (0,10,20,...) are reusable
        };
        // Larger awkward residuals waste more absolute space.
        score += awkward * post as f64 * 1.5;

        // Integer-division threshold: residual divisible by 20 is a good harbor
        // for mid-size items.
        if post % 20 == 0 {
            score -= 25.0;
        }
        if post % 50 == 0 {
            score -= 15.0;
        }
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual as u32 {
            score -= 400.0;
        } else if next_item_size <= post_residual as u32 {
            // next item fits: leftover after next placement matters
            let post2 = post_residual - next_item_size;
            score -= 40.0 + 0.3 * post2 as f64;
            if post2 % 10 == 0 {
                score -= 20.0;
            }
        } else {
            // next item will NOT fit here: this residual is likely dead
            score += 30.0 + 0.5 * (next_item_size - post_residual as u32) as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Prefer fuller bins relative to the fleet's mean residual (best-fit flavor).
    let res_frac = post_residual as f64 / cap;
    score += (res_frac - mean_residual / cap).abs() * 20.0;

    // Slight preference for reusing bins over opening new ones as stream matures.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses / many bins open.
        score += 35.0 + 60.0 * progress + (open_bins_count as f64).ln().max(0.0) * 10.0;
    } else {
        score -= 10.0 * progress;
    }

    // Capacity fraction harmonic: bins whose residual sits in the top usable
    // band (>50%) are good long-term hosts for medium items.
    if post_residual as f64 > 0.5 * cap {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are tiny (>0) are unusable
    // for any future item (min item size 1..100 unknown, but small gaps < ~10
    // are almost certainly dead). Penalize hard when 0 < post_residual < 10.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 40.0; // next item nearly fills leftover
        } else {
            score -= 15.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // leftover too small for next item: dead space penalty scaled
        score += 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // Open-bins pressure: with many open bins, avoid spreading; encourage
    // filling existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    score -= pressure * 4.0;

    // Mean-residual coupling: bins with residual far below mean are already
    // tight; filling them further is efficient. Penalize bins much looser
    // than the mean.
    let dev = mean_residual - bin_residual as f64;
    if dev < 0.0 {
        score += (-dev) * 0.5;
    } else {
        score -= dev * 0.3;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (handled implicitly by fitting_bins_count bonus) and stream is early.
    if bin_residual == bin_capacity {
        // base cost of opening a bin; reduced late in the stream is irrelevant,
        // keep a constant handicap so tight fits in open bins win.
        score += 25.0;
        if fitting_bins_count == 0 {
            score -= 200.0; // nothing fits anywhere: must open
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // can still host the next item (chained packing).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits here: reward, but prefer tightest chain
            // (post_residual close to next_item_size leaves least dead space).
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 + slack * 0.15;
        } else {
            // Next item cannot fit after this placement: penalize dead space,
            // more so the smaller the leftover (unusable gap).
            let dead = post_residual as f64;
            score += 8.0 + (1.0 - dead / bin_capacity as f64) * 6.0;
        }
    }

    // Last-chance bin: if this is the only open bin that fits, using it
    // avoids opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Mild penalty for the brand-new empty bin candidate so we only open
    // a new bin when existing bins are genuinely poor fits.
    if bin_residual == bin_capacity {
        score += 10.0;
        // If next item is large, a fresh bin is more attractive.
        if next_item_size > 0 && next_item_size >= post_residual {
            score -= 6.0;
        }
    }

    // Relative-to-mean coupling: bins with residual far above the mean
    // are "wasted space" holders; prefer packing into them when the
    // post-residual is small (tight fit).
    let pr = post_residual as f64;
    score -= (mean_residual - pr) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large post-residual relative to capacity (dead space).
    score += (post_residual as f64 / bin_capacity as f64) * 30.0;

    // Reward tight fits: residual close to item size means good packing.
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= tightness * 25.0;

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0;
        // Extra reward if next item almost fills the remaining space.
        let next_fill = next_item_size as f64 / post_residual.max(1) as f64;
        score -= next_fill * 15.0;
    } else if next_item_size > post_residual {
        // Next item won't fit here after placement; penalize if post_residual is small but unusable.
        if post_residual > 0 && post_residual < 10 {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Many open bins: discourage spreading; prefer filling existing bins.
    let open_pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score -= open_pressure * 8.0 * tightness;

    // Time horizon: early in stream, be more exploratory (favor new bins slightly less penalized);
    // late in stream, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses (consolidation).
        score += 15.0 + progress * 25.0;
        // But early on, if mean residual across bins is low (all bins tight), opening new bin is fine.
        score -= (mean_residual / bin_capacity as f64) * 10.0;
    } else {
        // Existing bin: reward more strongly late in the stream.
        score -= progress * 10.0;
    }

    // Prefer bins whose residual deviates favorably from mean (above-mean residual bins absorb items).
    let residual_gap = bin_residual as f64 - mean_residual;
    score += residual_gap * 0.05;

    // Small item into large residual: mild penalty to save space for bigger items.
    if (item_size as f64) < 0.3 * bin_residual as f64 && bin_residual != bin_capacity {
        score += 6.0;
    }

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
