pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Core: quadratic penalty on wasted residual (dead space), normalized
    let mut score = pr * pr / cap;

    // Linear residual component weighted by stream progress:
    // late in the stream, residual waste matters more (fewer chances to fill it)
    score += pr * (0.5 + 1.5 * progress);

    // Reward tight fits: subtract a bonus that grows as post_residual -> 0
    let tightness = 1.0 - pr / cap;
    score -= 20.0 * tightness * tightness;

    // Lookahead coupling: if next item fits exactly into post_residual, reward strongly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fill_ratio = nxt / pr.max(1.0);
            score -= 15.0 * fill_ratio * fill_ratio;
        } else {
            // next item won't fit: penalize residuals that are "almost useful"
            let gap = nxt - pr;
            score += 0.3 * gap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // mild penalty to spread preference toward best-fit among many candidates
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: empty bin gets a baseline cost,
    // reduced late in the stream or when many bins are open (consolidation pressure)
    if bin_residual == bin_capacity {
        let mut new_bin_cost = 30.0;
        new_bin_cost -= 10.0 * progress;
        new_bin_cost -= 3.0 * (open_bins_count as f64).ln().max(0.0);
        // discourage new bin if mean residual across open bins could host this item
        if mean_residual > item {
            new_bin_cost += 5.0;
        }
        score += new_bin_cost;
    }

    // Smooth interaction: residual variance pressure — penalize bins far from mean residual
    let dev = (pr - mean_residual).abs();
    score += 0.05 * dev * dev / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
