                    score += (post_residual as f64) * 0.3;
                }
            }

            // Progress-dependent tightness: late in stream, prefer tight packing.
            let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
            score += (post_residual as f64 / cap) * (1.0 + progress) * 10.0;
