        if post_residual < 30 { score += 7.5 * (30 - post_residual) as f64 / 18.0; }
        if post % 10 == 0 { score -= 5.0; }
    }

    // dead-space band under 25% of capacity
    if post > 0.0 && post < 0.25 * cap {
        score += 30.0 * (1.0 - post / (0.25 * cap));
    }

    // Lookahead: reward if next item chains into the leftover
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let chain_tight = 1.0 - (post - nxt) / cap;
            score -= 52.0 * chain_tight;
            if post == nxt { score -= 68.0; }
            if post >= nxt + mean_residual { score -= 10.0; }
            if (post - nxt) <= mean_residual * 0.5 { score -= 8.0; }
            if post - nxt >= 1.0 && post - nxt <= 4.0 { score -= 12.0; }
            if post - nxt < 6.0 { score -= 18.0; }
            if (post - nxt) as u32 == mean_residual as u32 { score -= 9.0; }
            if post_residual <= 25 && nxt > post_residual as f64 * 0.6 {
                score -= 13.0 * (1.0 - post_residual as f64 / 25.0);
            }
            if post_residual % next_item_size == 0 { score -= 10.0; }
        } else if post + 10.0 >= nxt {
            score += 6.0;
        } else {
            score += 0.06 * (nxt - post);
        }
        if nxt > post && post_residual < 10 { score += 60.0; }
        if nxt > post && (nxt - post) as u32 <= 2 && fitting_bins_count > 1 { score += 15.0; }
        if nxt > post && (nxt - post) as u32 > 20 && post_residual > 0 && post_residual < 20 { score += 12.0; }
        // next item too big for this residual: penalize small residuals harder
        if post_residual > 0 && post_residual < item_size && nxt > post && open_bins_count > 3 { score += 8.0; }
        if post_residual > 0 && nxt > post && post_residual < (next_item_size / 2).max(1) {
            score += 6.0 * (1.0 - post_residual as f64 / (next_item_size / 2).max(1) as f64);
        }
