    if post_residual > 0 && next_item_size > post_residual && post_residual >= (next_item_size * 3 / 4) && post_residual < next_item_size {
        score += 5.0 * (post_residual as f64 - next_item_size as f64 * 0.75) / (next_item_size as f64 * 0.25).max(1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum possible item
    // size (1..=100 interface => floor of 1, but small gaps < 10 are near-dead)
    // are pure waste. Penalize small nonzero post_residual super-linearly.
    if post_residual > 0 {
        let dead = post_residual as f64;
        // penalty grows sharply as post_residual approaches unusability
        score += (100.0 / (dead + 5.0)).powi(2) * 2.0;
        if dead < 10.0 {
            score += (10.0 - dead) * 8.0; // hard penalty for tiny gaps
        }
    } else {
        // perfect fit: strong reward
        score -= 25.0;
    }

    // Reward tight fits: small post_residual relative to item size
    if item_size > 0 {
        let tightness = (bin_residual - post_residual) as f64 / bin_residual as f64;
        score -= tightness * 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin, more when many bins open
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * 3.0;
        // but if lookahead fits the fresh bin perfectly alongside, soften
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 15.0;
        }
    }

    // Lookahead coupling: if next item exactly fills the post_residual, reward heavily
    if next_item_size > 0 && next_item_size <= post_residual {
        let exact = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - exact / 100.0);
    }

    // Open bins pressure: mildly prefer filling existing bins as count grows
    if bin_residual != bin_capacity {
        score -= (open_bins_count as f64).sqrt() * 1.5;
    }

    // Mean residual coupling: prefer bins deviating below mean (consolidating space)
    score += (mean_residual - post_residual as f64) * 0.1;

    // Late-stream pressure: as stream progresses, be greedier about tight fits
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

