pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 and 20
    let r10 = (post_residual % 10) as f64;
    let r20 = (post_residual % 20) as f64;
    // Small residues mean post_residual is nearly a "class boundary" -> dead space risk
    score += (10.0 - r10) * 0.35 * (r10 / 10.0);
    score += (20.0 - r20) * 0.15;

    // Integer-division threshold: post_residual in low half of capacity fraction
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac < 0.2 {
        score -= 25.0; // tiny residual left = excellent packing (nearly full bin)
    } else if frac < 0.5 {
        score += 6.0;  // awkward mid-size dead space
    }

    // Lookahead: if next item fits exactly into post_residual, reward strongly
    if next_item_size > 0 && next_item_size <= post_residual {
        let perfect = (post_residual == next_item_size) as f64;
        score -= 30.0 * perfect;
        // harmonic match: next_item_size shares class with post_residual
        if next_item_size % 10 == post_residual % 10 {
            score -= 8.0;
        }
        // penalize leaving residual that neither fits next item nor is tiny
    } else if next_item_size > 0 {
        score += 5.0;
    }

    // Last-chance bin: strongly favor to avoid opening new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: penalize unless current bins are nearly exhausted
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fill = 1.0 - mean_residual / bin_capacity as f64;
        // open new bin only when open bins are well-filled or few can fit
        score = 100.0 - 40.0 * avg_fill - 10.0 * progress;
        if fitting_bins_count <= 1 {
            score -= 15.0;
        }
    }

    // Encourage tight fits: item fills most of bin residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
