        // Dead space: next item cannot use the leftover residual.
        score += 8.0 + 0.15 * post_residual as f64;
    }

    // Penalize bins far below the mean residual (wasteful use of a roomy bin)
    // and reward bins near the mean (balanced packing).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.1 * dev;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when existing bins fit well, unless stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let new_bin_penalty = 20.0 + 10.0 * (1.0 - progress);
        score += new_bin_penalty;
        // But a new bin is attractive if the item leaves a large awkward residual
        // that no open bin structure helps with.
        if post_residual as f64 > mean_residual {
            score -= 10.0;
        }
    }

    // Slight preference to fill bins with more residual first (largest-fit-first).
    score -= 0.05 * bin_residual as f64;

    score
}

