pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful" residue classes
    // (multiples of common item sizes) are more reusable.
    let pr = post_residual;
    if pr > 0 {
        // Reward leftovers that are multiples of small harmonics (10, 20, 25, 50)
        let harmonic_bonus = if pr % 50 == 0 { 12.0 }
            else if pr % 25 == 0 { 8.0 }
            else if pr % 20 == 0 { 6.0 }
            else if pr % 10 == 0 { 4.0 }
            else { 0.0 };
        score -= harmonic_bonus;

        // Penalize dead space: leftovers too small for the smallest plausible item (<= 9)
        if pr < 10 {
            score += 25.0;
        }
        // Integer division thresholds: leftover in awkward mid-range bands is less flexible
        let band = pr / 10; // 0..=10 harmonic band
        score += (band as f64).powi(2) * 0.3;

        // Lookahead: if next item fits exactly into the post residual, strongly favor this bin
        if next_item_size > 0 {
            if next_item_size == pr {
                score -= 40.0;
            } else if next_item_size <= pr {
                // next fits: reward proportional to tightness
                score -= 15.0 * (next_item_size as f64 / pr as f64);
                // harmonic match between next item and post residual
                if pr % next_item_size == 0 {
                    score -= 8.0;
                }
            } else {
                // next item won't fit here: mild penalty scaled by wasted potential
                score += 5.0 + 0.1 * (next_item_size as f64 - pr as f64);
            }
        }
    } else {
        // Perfect fit: huge reward
        score -= 60.0;
    }

    // Tight fit reward relative to bin residual before placement
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness * tightness;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity when open bins fit well.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: full remaining capacity is "dead" until filled
        score = cap * 0.85;
        if fitting_bins_count <= 1 {
            // No real alternative: new bin is fine
            score -= 30.0;
        }
        // Early in stream, allow opening bins more freely (bins will be filled later)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
        // If current item is large and mean residual is small, new bin is reasonable
        if item_size as f64 > mean_residual {
            score -= 12.0;
        }
    } else {
        // Prefer bins below mean residual (fill emptier bins first when ties)
        score += 0.05 * (mean_residual - bin_residual as f64);
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize residuals that are too small to be useful.
    // Residuals below the minimum item size (1) are impossible, but tiny residuals
    // (< 20) are hard to fill and act as wasted capacity.
    if post_residual > 0 {
        if post_residual < 20 {
            score += 15.0; // unusable sliver
        } else if post_residual < 35 {
            score += 6.0; // marginal gap
        } else {
            // Larger residuals are more reusable; reward them mildly.
            score -= 2.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Exact-fit lookahead: if the next item exactly fills the post_residual,
    // this placement is ideal.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }
    // If next item fits into the post residual, mildly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into existing
    // bins rather than spreading; penalize less when few bins are open.
    let bin_pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual != bin_capacity {
        score -= 3.0 * bin_pressure; // reward using existing bins when many are open
    } else {
        // New-bin candidate: penalize opening new bins, more strongly under pressure.
        score += 10.0 + 8.0 * bin_pressure;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it to
    // avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is relatively full; filling near-full bins is good (reduces bin count).
    let residual_gap = mean_residual - post_residual as f64;
    score += 0.05 * residual_gap;

    // Progress factor: late in the stream, prefer tighter packing (waste matters more).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
