pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with slight superlinearity
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 30.0;

    // 2-step lookahead: strongly reward post_residual == next_item_size (perfect chain)
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 45.0 * (-diff / 12.0).exp();

        // Reward leaving room for next item at all
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // Penalize stranding: post_residual too small for the next item (dead space)
            score += (post_residual as f64).powi(2) * 0.05;
        }
    }

    // Relative to mean residual: prefer using bins that are already depleted
    score -= (mean_residual - bin_residual as f64) * 0.15;

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when good fitting bins exist
    if bin_residual == bin_capacity {
        score += 40.0 + 10.0 * (fitting_bins_count as f64);
        // Early in stream, new bins are cheap
        score -= 25.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
