    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let chain_tight = 1.0 - (post - nxt) / cap;
            score -= 52.0 * chain_tight;
            if post == nxt {
                score -= 68.0;
            }
            if post >= nxt + mean_residual {
                score -= 10.0;
            }
            if (post - nxt) >= 1.0 && (post - nxt) <= 4.0 {
                score -= 12.0;
            }
            if post - nxt < 6.0 {
                score -= 18.0;
            }
            if post_residual as u32 == mean_residual as u32 {
                score -= 9.0;
            }
        } else if post + 10.0 >= nxt {
            score += 6.0;
        } else {
            score += 0.06 * (nxt - post);
