    if post_residual > 0 && next_item_size as f64 > post && post_residual < (next_item_size / 2).max(1) {
        score += 6.0 * (1.0 - post_residual as f64 / (next_item_size / 2).max(1) as f64);
    }

    // Round residuals pair well with typical item sizes.
    if post_residual > 0 && post_residual % 10 == 0 && next_item_size as f64 <= post {
        score -= 5.0;
    }

    // Large dead fraction vs. mean: discourage.
    if post_residual > 0 && next_item_size as f64 > post && post / cap > 0.35 && post_residual as f64 > mean_residual * 1.5 && fitting_bins_count > 3 {
        score += 10.0 * (post / cap - 0.35);
    }

