        score += 12.0;
    }

    // Lookahead: does next item fit the post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0; // chain placement possible
            // harmonic coupling: next item divides residual evenly
            if post_residual % next_item_size == 0 {
                score -= 6.0;
            }
        } else {
            // residual too small for next item: dead space unless near zero
            if post_residual >= 1 {
                score += (next_item_size - post_residual) as f64 * 0.15;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current bins are heavily fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        // open new bin if mean residual of open bins is small (poor reuse potential)
        score = 50.0 + 40.0 * fragmentation - 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative
        }
    }

    // Mild pressure to consolidate when many bins open
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: any post_residual that is too small to
    // hold a typical future item (assume min useful item ~10, but with unknown
    // distribution be conservative: gaps < 10 are pure dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 500.0; // heavy penalty: unusable sliver
    }

    // Gaps that cannot fit the lookahead item are less useful than ones that can.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 80.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0; // reward leaving room for the next item
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoids bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Open-bins pressure: with many open bins, avoid spreading; with few open
    // bins, tolerate a new bin slightly less.
    score += open_bins_count as f64 * 5.0;

    // New-bin candidate: only attractive when it's genuinely needed.
    // A fresh bin starts with residual == capacity; make it a mediocre default
    // (post_residual == 100) so tight fits into existing bins always win,
    // but it beats bins that would create dead space.
    if bin_residual == bin_capacity {
        // Neutral baseline; add mild pressure that grows with open bins count
        // so we consolidate when possible, but subtract when current bin
        // would be badly fragmented (handled above via their penalties).
        score += 60.0 + (open_bins_count as f64).sqrt() * 10.0;
        // If no existing bin fits at all, opening new bin is mandatory anyway.
        if fitting_bins_count == 0 {
            score -= 1000.0;
        }
    }

    // Mean residual coupling: if the fleet average residual is high, prefer
    // placements that reduce dispersion (target the largest residuals).
    if (post_residual as f64) < mean_residual {
        score -= 15.0;
    } else {
        score += 15.0;
    }

    // Progression: early in stream, be slightly more willing to open bins
    // (plenty of stream left to fill them); late, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= progress * 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
