pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact or near-exact chain fits
    // (post_residual == next_item_size means the next item fills this bin perfectly).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - nxt).abs();
        // Perfect chain match: strong reward
        if diff < 0.5 {
            score -= 40.0;
        } else if diff <= 5.0 {
            score -= 25.0 - 3.0 * diff;
        } else {
            // Penalize leaving a residual that is too small for the next item
            // (dead space), scaled by how close the next item is to fitting.
            if pr < nxt {
                let dead = nxt - pr;
                score += (dead as f64) * 0.8;
            }
        }
        // If post_residual could still fit the next item, mild reward for flexibility
        if pr >= nxt && diff > 5.0 {
            score -= 4.0;
        }
    } else {
        // Last item: strongly prefer minimal post_residual
        score -= 20.0;
    }

    // Tight fit reward: placing item leaves little waste in this bin
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 10.0 * tightness;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the item
    // is large relative to capacity or open bins are already crowded/tight.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin
        score += 45.0;
        // Less penalty if the item is big (a fresh bin wastes less relative space)
        score -= (item_size as f64) * 0.4;
        // If open bins have large mean residual, a new bin is more acceptable
        score -= (mean_residual * 0.15).min(15.0);
        // Early in the stream, opening bins is cheaper (future items need bins anyway)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // If no other bin fits (fitting_bins_count==0 for new bin context), drop penalty
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Prefer filling bins whose residual deviates below the mean (consolidate waste)
    if bin_residual < bin_capacity {
        let dev = mean_residual - (bin_residual as f64);
        if dev > 0.0 {
            score -= (dev * 0.3).min(10.0);
        } else {
            score += (-dev * 0.2).min(8.0);
        }
    }

    // Slight preference to spread across bins when many are open (balance load)
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: reward if next item fits exactly or well into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize leaving medium dead space.
            let dead = post_residual as f64;
            if dead > 0.0 && dead < next_item_size as f64 {
                score += 0.25 * dead;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0 + 0.1 * item_size as f64;
    }

    // Penalize wasting a nearly-full bin's potential when many bins are open.
    if bin_residual < item_size as f64 as u32 {
        score += 1000.0; // should not happen (bin wouldn't be a candidate), safety
    }

    // Global state: many open bins with high mean residual -> prefer consolidating
    // into bins with below-average residual (fill the emptier-ish bins less; prefer
    // filling tighter bins to preserve large residual bins for big future items).
    if mean_residual > 0.0 {
        let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 8.0 * dev;
    }

    // Time horizon: late in the stream, be more aggressive about closing gaps
    // (avoid new bins), early on be pickier about fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * progress * tightness;
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: opening a bin is only attractive when the current fit is bad
    // (large post_residual) or no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of a new bin, discounted when item is large relative to capacity
        // and stream is early (big items early are fine to start fresh bins).
        let base = 40.0 + 0.3 * post_residual as f64;
        let discount = 1.0 - 0.5 * (item_size as f64 / bin_capacity as f64) * (1.0 - progress);
        score += base * discount;
        // If other bins fit, opening new is wasteful late in stream.
        if fitting_bins_count > 0 {
            score += 15.0 * progress;
        }
    }

    // Mild penalty for creating awkward small gaps (5..15) that few items can use.
    if post_residual >= 1 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
