pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post * post / cap;

    // Reward exact or near-exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 330.0 / post;
    } else if post_residual < 12 {
        score += 90.0 + (12 - post_residual) as f64 * 6.0;
    } else {
        score -= 15.0 * (post / cap);
        if post_residual >= 40 {
            score -= 9.0;
        }
        if post_residual < 30 {
            score += 7.5 * (30 - post_residual) as f64 / 18.0;
        }
    }

    // Small residual that cannot hold next item: dead space penalty.
    if post_residual > 0 && post_residual < 8 && next_item_size > post_residual {
        score += 26.0;
    }

    // Lookahead: next item fits into post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let chain_tight = 1.0 - (post - nxt) / cap;
            score -= 52.0 * chain_tight;
            if post == nxt {
                score -= 68.0;
            }
            let gap = post - nxt;
            if gap >= 1.0 && gap <= 4.0 {
                score -= 12.0;
            }
            if gap < 6.0 {
                score -= 18.0;
            }
            if gap <= 12.0 && gap <= mean_residual * 1.2 {
                score -= 7.0 * (1.0 - gap / 12.0);
            }
        } else if post + 10.0 >= nxt {
            score += 6.0;
        } else {
            score += 0.06 * (nxt - post);
        }
        if nxt > post && post_residual < 10 {
            score += 60.0;
        }
        if nxt > post && (nxt - post) as u32 <= 2 && fitting_bins_count > 1 {
            score += 15.0;
        }
        if nxt > post && (nxt - post) as u32 > 20 && post_residual > 0 && post_residual < 20 {
            score += 12.0;
        }
        if post_residual > 0 && nxt <= post && nxt > post_residual as f64 * 0.6 && post_residual <= 25 {
            score -= 13.0 * (1.0 - post_residual as f64 / 25.0);
        }
    } else {
        score += post * 2.2;
    }

    // Prefer tighter bins relative to mean residual.
    let mean_diff = (bin_residual as f64) - mean_residual;
    score += 0.3 * mean_diff;

    // Last-chance bin: strongly prefer using the only fitting open bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Consolidation pressure when many bins are open.
    if fitting_bins_count > 4 && bin_residual != bin_capacity && post_residual > 30 {
        score += 3.0;
    }
    score += 0.05 * open_bins_count as f64;

    // New-bin decision: early in stream more willing to open, later less.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_bonus = 40.0 * (1.0 - progress);
    if bin_residual == bin_capacity {
        score -= new_bin_bonus;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
        if fitting_bins_count > 2 && post_residual >= next_item_size {
            score += 14.0;
        }
    }

    // Avoid leaving residuals that are too small for the next item when many bins open.
    if post_residual > 0 && post_residual < item_size && next_item_size as f64 > post && open_bins_count > 3 {
        score += 8.0;
    }
    if post_residual > 0 && next_item_size as f64 > post && post_residual < (next_item_size / 2).max(1) {
        score += 6.0 * (1.0 - post_residual as f64 / (next_item_size / 2).max(1) as f64);
    }
    let dead = post / cap;
    if post_residual > 0 && next_item_size as f64 > post && dead > 0.35 && (post_residual as f64) > mean_residual * 1.5 && fitting_bins_count > 3 {
        score += 10.0 * (dead - 0.35);
    }
    if post_residual > 0 && next_item_size as f64 <= post && (post - next_item_size as f64) <= 2.0 && dead > 0.4 {
        score -= 9.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping.
    let mut score = pr;

    // Smooth polynomial coupling of post-residual with stream progress:
    // early on, prefer tight fits (low post_residual) more strongly;
    // late in stream, dead space matters even more.
    let progress_coupling = 1.0 + 0.8 * progress * (1.0 - progress) * 4.0;
    score += progress_coupling * norm_pr * norm_pr * cap * 0.3;

    // Reward using bins with small residuals overall (cubic in mean residual).
    let norm_mean = mean_residual / cap;
    score -= 12.0 * norm_mean * norm_mean * norm_mean;

    // Penalize leaving residual close to next item size mismatch:
    // if next item fits perfectly in post residual, reward heavily.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fit_quality = 1.0 - (pr - nxt) / cap;
            score -= 8.0 * fit_quality * fit_quality;
        } else {
            // post residual too small for next item: penalize dead space
            score += 5.0 * (1.0 - progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - 0.5 * progress);
    }

    // Mild penalty when many bins are open (encourage consolidation).
    score += 0.3 * (open_bins_count as f64).ln().max(0.0);

    // Reward high fill ratio with smooth saturating term.
    let fill = 1.0 - norm_pr;
    score -= 6.0 * fill * fill * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
