pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: low post_residual is good.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Harmonic class of post_residual: modulo classes on capacity fractions.
    let class = post_residual % 10;
    // Residuals in "awkward" classes (1..9 not matching common small items) get penalized.
    if class >= 1 && class <= 4 {
        score += 6.0;
    } else if class == 0 {
        score -= 4.0; // perfectly divisible residual is reusable
    }

    // Integer-division thresholds: residual large enough for next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0; // leaves room for lookahead
            // Extra reward if post_residual / next_item_size >= 2 (integer division)
            if post_residual / next_item_size.max(1) >= 2 {
                score -= 3.0;
            }
        } else {
            score += 10.0; // dead space relative to lookahead
        }
        // Exact match of post_residual to next item is ideal
        if post_residual == next_item_size {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening new bins unless current fit is poor.
    if bin_residual == bin_capacity {
        score += 20.0;
        // But if this is the last item, a new bin is fine.
        if next_item_size == 0 && step_index + 1 == total_items {
            score -= 25.0;
