pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Progress ratio of the stream (time horizon coupling).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Detect the brand-new empty bin candidate.
    let is_new_bin = bin_residual == bin_capacity;

    // Dead-space penalty: residuals too small for any plausible item (min size 1,
    // but small slivers < ~10 are nearly unusable) are wasted capacity.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold {
        // Sliver: strongly penalize leaving unusable dust.
        score += (dead_threshold - post_residual as f64) * 3.0;
    }

    // Perfect-fit reward: leaving exactly zero residual is ideal.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual as f64 <= dead_threshold {
        // small but not zero residual: mild penalty already applied above.
    } else {
        // Sweet-spot reward: residual in a range where a future item likely fits.
        // Mid-range residuals (10..50) are reusable; huge residuals on old bins
        // suggest the bin was poorly packed.
        let pr = post_residual as f64;
        if pr >= 10.0 && pr <= 60.0 {
            score -= 8.0 * (1.0 - ((pr - 35.0).abs() / 35.0).min(1.0));
        }
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item,
    // penalize bins that barely fail to host it (near-miss wasted potential).
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if (post_residual as f64) >= ni {
            // Next item fits: reward proportionally to how snugly it fits.
            let slack = post_residual as f64 - ni;
            score -= 12.0 * (1.0 - (slack / cap).min(1.0));
        } else {
            // Near miss: penalize if the shortfall is small (we nearly kept chain alive).
            let shortfall = ni - post_residual as f64;
            if shortfall <= 20.0 {
                score += 6.0 * (1.0 - shortfall / 20.0);
            }
        }
    }

    // Last-chance logic: if this is the ONLY bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin is expensive; only attractive when
    // existing bins are crowded or the item is large relative to mean residual.
    if is_new_bin {
        let crowding = (mean_residual / cap).clamp(0.0, 1.0);
        // Base penalty for opening a new bin.
        let mut new_penalty = 40.0;
        // Less penalty late in the stream (fewer future items to waste space on)
        // and when open bins are nearly full anyway.
        new_penalty *= 1.0 - 0.4 * progress;
        new_penalty *= 1.0 - 0.5 * crowding;
        // If very few bins fit the item, opening fresh is more acceptable.
        if fitting_bins_count <= 1 {
            new_penalty *= 0.4;
        }
        score += new_penalty;
    } else {
        // Mild reward for consolidating into existing bins when many are open.
        score -= (open_bins_count.min(20) as f64) * 0.3;
    }

    // Global-state coupling: if mean residual across open bins is high, prefer
    // filling the emptiest-feeling bins (low residual) to reduce fragmentation.
    score += (mean_residual - post_residual as f64) * 0.05;

    // Slight preference for tighter fits overall, scaled by stream progress:
    // early on, keep bins flexible; late, pack tight.
    score += (post_residual as f64 / cap) * (5.0 + 10.0 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;

    // Base: waste after placement, with smooth non-linear penalty
    let mut score = pr * (1.0 + 0.6 * (pr / cap).powi(2));

    // Reward tight fits (item nearly fills residual) via smooth polynomial
    score -= 40.0 * fit_ratio.powi(3) * (1.0 - progress * 0.3);

    // Penalize leaving residual that next item can't use; reward perfect pairing
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let leftover = pr - nxt;
            score -= 25.0 * (1.0 - leftover / cap) * (1.0 - progress * 0.5);
        } else {
            score += 8.0 * (1.0 - pr / cap) * (nxt / cap);
        }
    } else {
        // Last item: strongly prefer minimal final waste
        score += pr * pr / cap;
    }

    // Last-chance bin: avoid opening a new bin if fit is decent
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - (pr / cap).powi(2));
    }

    // Encourage consolidation when many bins are open
    score -= 5.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * (1.0 - fit_ratio);

    // Mean-residual coupling: prefer bins below mean residual (tighter bins)
    score += 3.0 * ((pr - mean_residual) / cap);

    // Smooth late-stream preference for filling existing bins rather than opening new ones
    score += 20.0 * progress * (pr / cap).powi(2);

    // New-bin candidate: penalize opening fresh bins unless current fit is bad
    if bin_residual == bin_capacity {
        score += 35.0 - 25.0 * (1.0 - fit_ratio.abs().min(1.0)) + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
