pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity-fraction band it lands in.
    // Classes: [0..10) dead, [10..20) tight, [20..34) mid, [34..51) half-ish, [51..100) roomy.
    let class = match post_residual {
        0 => 0u32,
        1..=9 => 1,
        10..=19 => 2,
        20..=33 => 3,
        34..=50 => 4,
        _ => 5,
    };

    // Dead-space penalty: residuals that almost nothing can fit are wasted.
    // Reward exact fills and residuals that perfectly host the next item.
    match class {
        0 => score -= 60.0,                    // perfect closure — excellent
        1 => score += 55.0,                    // dead space 1..9 — very bad
        2 => score += 18.0,                    // tight but usable for small items
        3 => score -= 5.0,                     // mid band — mildly good
        4 => score -= 12.0,                    // ~half full — good target
        _ => {}                                // roomy — neutral
    }

    // Lookahead coupling: strongly reward if next item fits post residual exactly or well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;                     // perfect harmonic pair
        } else if next_item_size <= post_residual {
            let leftover = post_residual - next_item_size;
            // penalize by how dead the leftover would be (mod-style banding)
            let band_pen = match leftover {
                0 => -30.0,
                1..=9 => 25.0,
                10..=19 => 8.0,
                _ => -6.0,
            };
            score += band_pen;
            score -= (post_residual as f64 - next_item_size as f64) * 0.15;
        } else {
            // next item won't fit here; mild penalty scaled by how far off
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
    }

    // Last-chance logic: if this is the only bin that fits, prefer using it
    // unless the fit creates dead space (class 1).
    if fitting_bins_count == 1 && class != 1 {
        score -= 35.0;
    }
    if fitting_bins_count == 1 && class == 1 {
        // forced bad fit vs new bin: compare against opening a fresh bin
        score += 10.0;
    }

    // New-bin candidate handling: empty bin should win only when current fits are poor.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score = 45.0;
        // more attractive late in the stream when many bins are already open
        score -= open_bins_count as f64 * 1.5;
        // less attractive early (consolidate first)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (1.0 - progress) * 15.0;
        // if next item is large, a fresh bin is valuable
        if next_item_size >= 50 {
            score -= 20.0;
        }
    }

    // Mild global pressure: prefer bins whose residual is near the mean
    // (keeps residual distribution balanced across bins).
    score += ((post_residual as f64 - mean_residual) * 0.05).abs();

    // Tiny tie-break favoring fuller bins.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
