pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: small post_residual is good; extra bonus for exact/very tight fits.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Penalize leaving dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < item_size.max(10) {
        score += 8.0;
