    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 + 0.25 * (next_item_size as f64);
        } else {
            score += 6.0;
        }
        // Pairing bonus: current + next fill the bin almost exactly.
        let pair = (item_size + next_item_size) as f64;
        if pair <= bin_capacity as f64 {
            let waste = bin_capacity as f64 - pair;
            if (bin_residual as f64 - waste).abs() < 1e-6 {
                score -= 30.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = mean_residual / bin_capacity as f64;
        score += 60.0;
        score -= 35.0 * crowding;
        score -= 10.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && next_item_size >= item_size && mean_residual < next_item_size as f64 {
            score -= 20.0;
        }
    }

    // Mild preference for fuller bins relative to global mean residual.
    score -= 0.15 * (bin_residual as f64 - mean_residual);

    // Early in the stream, be slightly conservative about fragmenting bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress < 0.2 {
        score += 0.05 * post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
