pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - pr / cap;

    // Base: penalize leftover residual, weighted non-linearly by fill ratio
    let mut score = pr * (1.0 + 0.6 * fill * fill);

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, tight fits matter more; dead space penalized more
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += pr * (0.5 * p2 + 0.7 * p3);

    // Perfect/near-perfect fit reward (smooth, not piecewise)
    let fit_quality = 1.0 - pr / cap;
    score -= 8.0 * fit_quality * fit_quality * fit_quality;

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 12.0 + 6.0 * progress;
    } else {
        score -= 2.0 / fitting_bins_count.max(1) as f64;
    }

    // Lookahead: reward leaving space compatible with next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
