            score -= 4.0 * slack_match * slack_match;
        } else {
            score += 3.0 * (nx - pr) / cap;
        }
    }

    // Mild preference for consolidating into fuller bins vs. sparse ones
    score += 1.5 * (mean_residual - pr) / cap;

    // New-bin candidate: penalize slightly unless current bin leaves unusable space
    if bin_residual == bin_capacity {
        let waste_if_reject = if next_item_size > 0 && (next_item_size as f64) <= pr { 0.0 } else { 4.0 };
        score += 6.0 + waste_if_reject - 5.0 * progress;
    }

