    // "resonant" class (divisible by common small item sizes) are rewarded.
    let pr = post_residual;
    if pr > 0 {
        let mut harmony = 0.0f64;
        for &m in &[5u32, 10, 20, 25, 50] {
            if pr % m == 0 {
                harmony += 6.0;
            }
        }
        if pr % 100 == 0 { harmony += 4.0; }
        score -= harmony;
    } else {
        // Perfect fill: best possible outcome.
        score -= 40.0;
    }

    // Penalize large dead space that no typical item can use:
    // leftover in (0..10) is pure waste.
    if pr > 0 && pr < 10 {
        score += 12.0;
    }
    // Leftover in awkward mid-band (31..40, 51..55) is hard to fill too.
    if (31..40).contains(&pr) || (51..55).contains(&pr) {
        score += 5.0;
    }

