            // by how much space would be stranded relative to next item.
            score += (pr as f64) * (next_item_size as f64 / cap) * 0.3;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when current open bins are
    // nearly full on average or the fit here is terrible.
    if bin_residual == bin_capacity {
        let tight = mean_residual / cap;
        score = cap * 0.55 + tight * cap * 0.6;
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative, must open
        }
        if next_item_size > 0 && next_item_size >= bin_capacity - 10 {
            score -= 10.0; // big item coming, fresh bin useful
