    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (bin_residual as f64 / cap) * (1.0 - progress) * 2.0;

    // Tie-break toward fewer open bins (consolidation).
    score += open_bins_count as f64 * 0.01;

    score
}

