        score += 40.0; // heavy penalty for creating unusable slivers
    }
    // Perfect fit is maximally rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Coupling: penalize gaps that cannot fit the lookahead item (k=2),
    // but only if the gap is also too small for typical future items.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as f64 {
        score += 12.0;
    }
    // Reward gaps that exactly accommodate the next item (chained fit).
    if next_item_size > 0 && post_residual as f64 == next_item_size as f64 {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 8.0;
    score += pressure * (post_residual as f64 / bin_capacity as f64);

