    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when open bins would waste a lot
    // (tightness of existing fit is poor) or there are no open bins.
    if bin_residual == bin_capacity {
        let waste = mean_residual - item_size as f64;
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        } else if waste > 20.0 {
            score -= 15.0; // existing fits are poor -> fresh bin is fine
        } else {
