        score -= 40.0;
    }

    // Prefer bins with residuals below mean (tighter packing), discourage above-mean.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate: only attractive when current bin would leave large waste
    // or no open bins exist. Penalize opening new bins early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 + 20.0 * (1.0 - progress);
        if post_residual >= next_item_size && next_item_size > 0 {
            score -= 10.0; // fresh bin can serve the next item too
        }
    }

    // Mild preference for bins that become perfectly full.
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post * post / cap; // quadratic pressure: big leftovers hurt more

    if post_residual == 0 {
        score -= 1000.0; // perfect fit dominates
    } else {
        // Harmony of the leftover space
        if post % 10 == 0 { score -= 12.0; }
        if post % 20 == 0 { score -= 8.0; }
        if post % 25 == 0 { score -= 8.0; }
        if post % 50 == 0 { score -= 6.0; }
        if post_residual <= 5 {
            score -= 330.0 / post; // near-perfect sliver: strong reward
        } else if post_residual < 12 {
            score += 90.0 + (12 - post_residual) as f64 * 6.0; // marginal band
        } else {
            score -= 15.0 * (post / cap); // larger leftovers scale down
            if post_residual >= 40 { score -= 9.0; }
            if post_residual < 30 { score += 7.5 * (30 - post_residual) as f64 / 18.0; }
        }
        // dead-space band under 25% of capacity
        if post > 0.0 && post < 0.25 * cap {
            score += 30.0 * (1.0 - post / (0.25 * cap));
        }
    }

    // Lookahead: reward if next item chains into the leftover
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let chain_tight = 1.0 - (post - nxt) / cap;
            score -= 52.0 * chain_tight;
            if post == nxt { score -= 68.0; } // exact chain fill
            if post >= nxt + mean_residual { score -= 10.0; }
            if (post - nxt) <= mean_residual * 0.5 { score -= 8.0; }
            if post - nxt >= 1.0 && post - nxt <= 4.0 { score -= 12.0; }
            if post - nxt < 6.0 { score -= 18.0; }
            if (post - nxt) as u32 == mean_residual as u32 { score -= 9.0; }
            if post_residual <= 25 && nxt > post_residual as f64 * 0.6 {
                score -= 13.0 * (1.0 - post_residual as f64 / 25.0);
            }
            if post_residual % next_item_size == 0 { score -= 10.0; } // harmonic chain
        } else if post + 10.0 >= nxt {
            score += 6.0; // near-miss: mild penalty
        } else {
            score += 0.06 * (nxt - post); // gap-proportional penalty
        }
        if nxt > post && post_residual < 10 { score += 60.0; }
        if nxt > post && (nxt - post) as u32 <= 2 && fitting_bins_count > 1 { score += 15.0; }
        if nxt > post && (nxt - post) as u32 > 20 && post_residual > 0 && post_residual < 20 { score += 12.0; }
        // half-cover lookahead: residual too small to hold half of next item
        if nxt > post && post_residual > 0 && post_residual < (next_item_size / 2).max(1) {
            score += 6.0 * (1.0 - post_residual as f64 / (next_item_size / 2).max(1) as f64);
        }
    } else {
        score += post * 2.2;
    }

    if post_residual > 0 && post_residual < 8 && next_item_size > post_residual {
        score += 26.0; // tiny residual that next item cannot use
    }
    if post_residual > 0 && post_residual < 16 && next_item_size > post_residual && (mean_residual as u32) > post_residual {
        score += 9.0 * (16 - post_residual) as f64 / 8.0;
    }

    // residual vs mean alignment
    let mean_diff = (bin_residual as f64) - mean_residual;
    score += 0.3 * mean_diff;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    if fitting_bins_count > 4 && bin_residual != bin_capacity && post_residual > 30 {
        score += 3.0;
    }

    // New-bin candidate handling
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_bonus = 40.0 * (1.0 - progress);
    if bin_residual == bin_capacity {
        score -= new_bin_bonus;
        if next_item_size > 0 && post_residual >= next_item_size { score -= 8.0; }
        if fitting_bins_count > 2 && post_residual >= next_item_size { score += 14.0; }
        if mean_residual < item_size as f64 && open_bins_count > 2 { score += 10.0; }
        if open_bins_count > 5 && mean_residual > 0.4 * cap { score += 12.0; }
        if progress > 0.6 && open_bins_count > 3 { score += 8.0; }
    } else {
        // tightness pressure toward fuller bins
        let tightness = 1.0 - (bin_residual as f64 / cap);
        score -= 10.0 * tightness;
        // penalize leaving dead space when next item is much larger than residual
        if post_residual > 0 && next_item_size as f64 > post && post_residual as f64 > mean_residual * 1.5 && fitting_bins_count > 3 {
            score += 8.0;
        }
    }

    // dead-space slope beyond 35% of capacity
    let dead = post / cap;
    if post_residual > 0 && next_item_size as f64 > post && dead > 0.35 && (post_residual as f64) > mean_residual * 1.5 && fitting_bins_count > 3 {
        score += 10.0 * (dead - 0.35);
    }
    if post_residual > 0 && next_item_size as f64 <= post && (post - next_item_size as f64) <= 2.0 && dead > 0.4 {
        score -= 9.0;
    }
    if post_residual > 0 && next_item_size as f64 <= post {
        let gap = post - next_item_size as f64;
        if gap <= 12.0 && gap <= mean_residual * 1.2 {
            score -= 7.0 * (1.0 - gap / 12.0);
        }
    }
    // near-fit rejection: residual barely below next item
    if post_residual > 0 && next_item_size > post_residual && post_residual >= (next_item_size * 3 / 4) && post_residual < next_item_size {
        score += 5.0 * (post_residual as f64 - next_item_size as f64 * 0.75) / (next_item_size as f64 * 0.25).max(1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize large dead space after placement (non-linear waste penalty).
    if post_residual > 0 {
        score += (post_residual as f64).powf(1.35) * 0.06;
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.10 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space that the next item cannot use.
        score += 4.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it over a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is attractive only when global
    // residuals are fragmented or the fit here is poor.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // Cost of a fresh bin grows with stream progress (fewer chances to reuse).
        let mut new_bin_score = bin_capacity as f64 * 0.85 + 15.0 * progress;
        // If many open bins with small mean residual, fragmentation is high -> new bin OK.
        if mean_residual < 25.0 && open_bins_count > 3 {
            new_bin_score -= 10.0;
        }
        // Poor current fit pushes toward a new bin.
        if fit_ratio < 0.55 {
            new_bin_score -= 12.0;
        }
        score = score.min(new_bin_score + score * 0.5);
    }

    // Mild pressure to consolidate: many open bins -> favor filling existing ones.
    score -= 0.35 * open_bins_count as f64;

    // Slight preference early in the stream to keep bins balanced.
    score += 3.0 * (1.0 - progress) * (bin_residual as f64 - mean_residual).abs() / bin_capacity as f64;

    score
}

