pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let item = item_size as f64;

    // Base: prefer small post-residual (tight fit), non-linearly.
    let norm_post = post / cap; // 0..1
    let mut score = post * (1.0 + 2.0 * norm_post * norm_post);

    // Polynomial coupling: tight fits are increasingly valuable as stream progresses.
    let tightness = 1.0 - norm_post;
    score -= tightness * tightness * item * (0.5 + 2.0 * progress);

    // Penalize residuals that cannot fit the next item (dead space) more as stream advances.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += (nxt - post) * (1.0 + 3.0 * progress);
        } else {
            // Reward leaving room for the next item, smoothly.
            score -= (post - nxt).min(30.0) * 0.3 * (1.0 - progress);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // New-bin candidate handling: mild penalty early, larger later (reuse bins).
    if bin_residual == bin_capacity {
        score += 8.0 + 30.0 * progress + 0.5 * open_bins_count as f64;
    } else {
        // Reward using bins with below-average residual (balance/consolidation).
        let dev = mean_residual - bin_residual as f64;
        score += 0.1 * dev * dev * 0.01 * (1.0 - progress);
    }

    // Late-stream pressure to fill existing bins tightly.
    score -= progress * progress * (cap - post) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Prefer a new bin when no existing bin fits or only a tight last-chance exists,
        // but penalize opening bins when a near-perfect fit is available elsewhere.
        let scarcity = if fitting_bins_count == 0 { 0.0 } else if fitting_bins_count == 1 { 30.0 } else { 60.0 };
        score = bin_capacity as f64 + scarcity;
        // Late in stream, slightly discourage new bins (cleanup phase)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        // If next item is large, a fresh bin is valuable
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 15.0;
        }
        return score;
    }

    // Harmonic class of post_residual: residues divisible by coarse classes are more reusable
    let pr = post_residual;
    // Class 1: multiples of 25 (harmonic with capacity quarters) -> very reusable
    if pr % 25 == 0 {
        score -= 12.0;
    }
    // Class 2: multiples of 10 -> decent reusability
    else if pr % 10 == 0 {
        score -= 6.0;
    }
    // Class 3: small residues (< 10) are dead space -> penalize
    if pr < 10 && pr > 0 {
        score += 8.0;
    }

    // Perfect fit bonus
    if pr == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            // Next item fits; reward proportional to how much would remain after
            let next_post = pr - next_item_size;
            if next_post % 25 == 0 { score -= 10.0; }
            else if next_post % 10 == 0 { score -= 5.0; }
            if next_post < 10 { score += 5.0; }
        } else {
            // Next item won't fit here: mild penalty scaled by overshoot class
            let overshoot = (next_item_size - pr) / 10;
            score += 3.0 + overshoot as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Tie-break by mean residual: prefer bins below mean residual (tighter packing)
    score += (mean_residual - post_residual as f64) * 0.1;

    // Mild preference for fuller bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

