pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest plausible
    // future item (<= ~10) are pure waste; penalize them nonlinearly.
    if post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual < 25 {
        // "awkward zone": hard to fill, mildly penalized
        score += (25 - post_residual) as f64 * 1.5;
    }

    // Reward tight fits: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.9 {
        score -= 25.0 * fill_ratio;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> prefer existing bins, discourage new ones.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate handling: make it attractive only when existing bins
    // would leave very bad dead space or no bin fits well.
    if bin_residual == bin_capacity {
        // Baseline new-bin score: moderate, scaled by how fragmented open bins are.
        score = 55.0 + open_bins_count as f64 * 2.0;
        // Early in stream, opening bins is cheap; later, prefer consolidation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 20.0;
        // If the next item fits well in the fresh residual, new bin is promising.
        if next_item_size > 0 && next_item_size <= bin_capacity {
            let pair_waste = (bin_capacity - item_size - next_item_size.min(bin_capacity - item_size)) as f64;
            score -= 30.0_f64.max(0.0) - pair_waste;
            score -= pair_waste * 0.8;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Lookahead: this bin's leftover won't fit the next item -> dead space likely.
        score += 6.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Perfect chain: leftover fits the next item exactly-ish.
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 12.0;
        }
    }

    // Slight preference for bins with low residual (fill emptier bins first? no:
    // lower residual bins are closer to full; prefer placing into them to close them).
    score += (bin_residual as f64 / bin_capacity as f64) * 4.0;

    // Mean-residual coupling: if open bins are on average quite full, keep using them.
    if bin_residual < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
