pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 100.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits the residual left behind
    if next_item_size > 0 {
        let next_f = next_item_size as f64;
        let post_f = post_residual as f64;
        if post_residual >= next_item_size {
            // next item fits exactly-ish: strong reward for tight coupling
            let gap = post_f - next_f;
            if gap == 0.0 {
                score -= 150.0;
            } else {
                score -= 60.0 * (1.0 - gap / bin_capacity as f64);
            }
        } else {
            // next item does not fit in leftover: penalize dead space proportionally
            score += 0.5 * post_f;
        }
    }

    // Compare against mean residual: prefer bins tighter than average
    let dev = post_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Penalize opening a brand-new bin when decent alternatives exist,
    // unless the item is large and fit is poor elsewhere
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fitting_bins_count > 0 {
            score += 50.0 + 40.0 * (1.0 - fill_ratio);
        } else {
            score -= 30.0;
        }
    }

    // Early stream: be slightly more conservative with open bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post * post / cap; // quadratic pressure: big leftovers hurt more

    if post_residual == 0 {
        score -= 1000.0; // perfect fit dominates
    } else {
        // Harmony of the leftover space
        if post % 10 == 0 { score -= 12.0; }
        if post % 20 == 0 { score -= 8.0; }
        if post % 25 == 0 { score -= 8.0; }
        if post % 50 == 0 { score -= 6.0; }
        if post_residual < 10 {
            score += 330.0 / post; // dead sliver: strong penalty
        } else if post_residual < 12 {
            score += 90.0 + (12 - post_residual) as f64 * 6.0; // marginal band
        } else {
            score -= 15.0 * (post / cap); // larger leftovers scale down
            if post_residual >= 40 { score -= 9.0; }
            if post_residual < 30 { score += 7.5 * (30 - post_residual) as f64 / 18.0; }
        }
        // dead-space band under 25% of capacity
        if post > 0.0 && post < 0.25 * cap {
            score += 30.0 * (1.0 - post / (0.25 * cap));
        }
    }

    // Lookahead: reward if next item chains into the leftover
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let chain_tight = 1.0 - (post - nxt) / cap;
            score -= 52.0 * chain_tight;
            if post == nxt { score -= 68.0; } // exact chain fill
            if post >= nxt + mean_residual { score -= 10.0; }
            if (post - nxt) <= mean_residual * 0.5 { score -= 8.0; }
            if post - nxt >= 1.0 && post - nxt <= 4.0 { score -= 12.0; }
            if post - nxt < 6.0 { score -= 18.0; }
            if (post - nxt) as u32 == mean_residual as u32 { score -= 9.0; }
            if post_residual <= 25 && nxt > post_residual as f64 * 0.6 {
                score -= 13.0 * (1.0 - post_residual as f64 / 25.0);
            }
            if post_residual % next_item_size == 0 { score -= 10.0; } // harmonic chain
            // new: two-step chain anticipation — residual could still fit a mean-sized item after
            let gap = post - nxt;
            if gap > 0.0 && gap <= mean_residual * 1.5 && gap <= 12.0 {
                score -= 7.0 * (1.0 - gap / 12.0);
            }
        } else if post + 10.0 >= nxt {
            score += 6.0; // near-miss: mild penalty
        } else {
            score += 0.06 * (nxt - post); // gap-proportional penalty
        }
        if nxt > post && post_residual < 10 { score += 60.0; }
        if nxt > post && (nxt - post) as u32 <= 2 && fitting_bins_count > 1 { score += 15.0; }
        if nxt > post && (nxt - post) as u32 > 20 && post_residual > 0 && post_residual < 20 { score += 12.0; }
        // new: near-fit rejection scaled by how close residual is to 75% of next item
        if post_residual > 0 && nxt > post && post_residual >= (next_item_size * 3 / 4) {
            score += 5.0 * (post - nxt * 0.75) / (nxt * 0.25).max(1.0);
        }
        // new: residual below half of next item — likely permanent dead space
        if post_residual > 0 && post < (next_item_size / 2).max(1) as f64 {
            score += 6.0 * (1.0 - post / ((next_item_size / 2).max(1) as f64));
        }
    } else {
        score += post * 2.2;
    }

    if post_residual > 0 && post_residual < 16 && next_item_size > post_residual && (mean_residual as u32) > post_residual {
        score += 9.0 * (16 - post_residual) as f64 / 8.0;
    }

    // residual vs mean alignment
    let mean_diff = (bin_residual as f64) - mean_residual;
    score += 0.3 * mean_diff;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    if fitting_bins_count > 4 && bin_residual != bin_capacity && post_residual > 30 {
        score += 3.0;
    }

    // New-bin candidate handling
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_bonus = 40.0 * (1.0 - progress);
    if bin_residual == bin_capacity {
        score -= new_bin_bonus;
        if next_item_size > 0 && post_residual >= next_item_size { score -= 8.0; }
        if fitting_bins_count > 2 && post_residual >= next_item_size { score += 14.0; }
        if mean_residual < item_size as f64 && open_bins_count > 2 { score += 10.0; }
        if open_bins_count > 5 && mean_residual > 0.4 * cap { score += 12.0; }
        if progress > 0.6 && open_bins_count > 3 { score += 8.0; }
    } else {
        // tightness pressure toward fuller bins
        let tightness = 1.0 - (bin_residual as f64 / cap);
        score -= 10.0 * tightness;
        // penalize leaving dead space when next item is much larger than residual
        if post_residual > 0 && next_item_size as f64 > post && post_residual as f64 > mean_residual * 1.5 && fitting_bins_count > 3 {
            score += 8.0;
        }
    }

    // dead-space slope beyond 35% of capacity
    let dead = post / cap;
    if post_residual > 0 && next_item_size as f64 > post && dead > 0.35 && (post_residual as f64) > mean_residual * 1.5 && fitting_bins_count > 3 {
        score += 10.0 * (dead - 0.35);
    }
    if post_residual > 0 && next_item_size as f64 <= post && (post - next_item_size as f64) <= 2.0 && dead > 0.4 {
        score -= 9.0;
    }
    // near-fit rejection: residual barely below next item
    if post_residual > 0 && next_item_size > post_residual && post_residual >= (next_item_size * 3 / 4) && post_residual < next_item_size {
        score += 5.0 * (post_residual as f64 - next_item_size as f64 * 0.75) / (next_item_size as f64 * 0.25).max(1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: normalized fill ratio of the item in this bin.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize creating dead space that is too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: reward leaving post_residual that can host next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0 * (post_residual as f64 / cap);
        }
        // Prefer bins where both current and next item pack well together.
        let pair_sum = item_size as f64 + next_item_size as f64;
        if pair_sum <= bin_residual as f64 {
            score -= 10.0 * (pair_sum / bin_residual as f64);
        }
    } else {
        // Last item: fill as much as possible.
        score -= 20.0 * fit_ratio;
    }

    // Global state: many open bins -> prefer consolidation into existing bins.
    let open_f = open_bins_count as f64;
    let mean_dev = (mean_residual - post_residual as f64).abs();
    score += 0.05 * open_f;
    score += 0.3 * mean_dev * (open_f / (open_f + 10.0));

    // Time horizon: late in the stream, avoid opening new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and bins accumulate.
        score += 15.0 + 35.0 * progress + 2.0 * open_f;
        // Allow new bin early on when existing bins would be badly fragmented.
        if fit_ratio < 0.35 && progress < 0.4 {
            score -= 20.0;
        }
    } else {
        score -= 10.0 * progress;
    }

    // Mild preference for bins with larger residuals when fits are comparable.
    score -= 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: tight fit is good (low post_residual preferred)
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // later in the stream, small residuals become more valuable (harder to fill),
    // so penalize wasted space super-linearly as progress grows.
    let wasted = pr / cap;
    score += progress * wasted * wasted * cap * 0.8;
    score += (1.0 - progress) * wasted * cap * 0.2;

    // Perfect fit reward (smooth, non-linear)
    if pr == 0 {
        score -= 50.0 + 30.0 * progress;
    }

    // Penalize residuals that exactly invite the next item only if they barely fit;
    // reward when next item fits snugly in the post-residual.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            let next_fit = (pr - ni) / cap; // leftover after next item
            score -= 10.0 * (1.0 - next_fit * next_fit) * (0.5 + progress);
        } else {
            // residual too small for next item: mild dead-space penalty
            score += 3.0 * (ni - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // New-bin candidate: only attractive when current bins fit poorly
    let is_new_bin = bin_residual == bin_capacity && post_residual == bin_capacity;
    if is_new_bin {
        score = cap * 0.9 + mean_residual * 0.1 - 20.0 * (1.0 - progress);
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    // Mild dispersion pressure: prefer bins below mean residual early (keep big gaps consolidated)
    score += (mean_residual - pr) * 0.05 * (1.0 - progress);

    score
}

