pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: partition residual space into capacity-fraction classes.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = (bin_capacity / 4) as f64;

    // Class 0: exact fill (post_residual == 0) -> huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= bin_capacity / 10 {
        // Tiny dead space (<=10): nearly perfect, strong reward.
        score -= 80.0;
    } else {
        // Integer-division class on post_residual by quarters of capacity.
        let class = post_residual / (bin_capacity / 4).max(1); // 0..4
        score += class as f64 * 12.0;

        // Modulo structure: penalize residuals that fall in "awkward" residue bands.
        let m = post_residual % (bin_capacity / 5).max(1);
        if m >= (bin_capacity / 10) {
            score += 6.0; // residue in upper half of a 20-unit cell: hard to fill later
        }
    }

    // Lookahead coupling: does next_item_size fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item chains perfectly: reward, stronger if it exactly fills.
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 200.0;
            } else {
                score -= 40.0 + (slack as f64).min(60.0);
            }
        } else {
            // Next item won't fit here: penalize proportionally to overshoot.
            let over = next_item_size - post_residual;
            score += 10.0 + over as f64 * 0.5;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin gets a baseline cost that rises
    // with stream progression and open-bin count, but drops when the item is
    // large relative to capacity (big items deserve fresh bins).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let size_frac = item_size as f64 / cap;
        let base = 55.0 + 25.0 * progress + 2.0 * open_bins_count as f64;
        score = base - 60.0 * size_frac;
        // If no open bin could fit, new bin is mandatory anyway (handled by fitting count).
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
        // Prefer new bin when item is large and next item likely large too.
        if next_item_size > bin_capacity / 2 {
            score -= 20.0;
        }
    } else {
        // Existing bin: mild preference for bins tighter than the mean residual.
        if pr < mean_residual {
            score -= 8.0;
        } else {
            score += 4.0;
        }
    }

    // Harmonic fraction bonus: post_residual close to an exact capacity fraction
    // (1/2, 1/3, 1/4) is more reusable; reward small deviations.
    for (num, den, w) in [(1u32, 2u32, 10.0), (1, 3, 6.0), (1, 4, 4.0)] {
        let target = bin_capacity * num / den;
        let d = (post_residual as i64 - target as i64).unsigned_abs();
        if d <= 5 {
            score -= w;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
