pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // Dead space = post_residual that cannot hold even the smallest item (size 1..100 unknown,
    // treat anything below ~10 as near-dead, and scale penalty quadratically).
    let dead = (bin_capacity as f64 * 0.10).max(1.0);
    if (post_residual as f64) < dead && post_residual > 0 {
        score += (dead - post_residual as f64) * (dead - post_residual as f64) * 4.0;
    }

    // Perfect fit bonus: exact zero residual is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward tight fits generally: smaller post_residual already favored by base term,
    // add mild extra reward proportional to fill ratio.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill * 20.0;

    // Open-bin pressure: discourage spreading across many bins unless fit is tight.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid new-bin cascade).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // or existing bins have poor fits.
    if bin_residual == bin_capacity {
        score += 40.0;
        // If lookahead item is large, a fresh bin may be valuable for pairing.
        if next_item_size >= 50 {
            score -= 10.0;
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    } else if next_item_size > post_residual && next_item_size <= bin_residual {
        // Next item would have fit now but not after placement — penalize.
        score += 15.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins),
    // keeping looser bins available for larger future items.
    if (bin_residual as f64) > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.3;
    }

    // Early stream: be slightly more conservative about opening bins early.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity && progress < 0.2 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Baseline: prefer tight packing (small post_residual)
    score = post_residual as f64;

    // 2-step lookahead: reward when post_residual exactly matches next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        // Perfect match => strong bonus (subtract)
        if diff < 0.5 {
            score -= 60.0;
        } else {
            // Partial reward decaying with mismatch
            score -= 30.0 * (-diff / 25.0).exp();
        }
        // Penalize if next item cannot fit in post_residual (dead space for lookahead)
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    } else {
        // Last item: pure tightness, no lookahead concerns
        score -= 10.0;
    }

    // Relative to mean residual: bins with residual well below mean are scarce; using them
    // for a loose fit wastes them. Prefer placing into bins with residual near/above mean.
    let res = post_residual as f64;
    if res > mean_residual + 15.0 {
        score += (res - mean_residual - 15.0) * 0.5;
    } else if res < mean_residual {
        score -= (mean_residual - res).min(20.0) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): penalize unless item is large relative to capacity
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio >= 0.8 {
            score -= 20.0; // large item: fresh bin is fine
        } else {
            score += 40.0 * (0.8 - fill_ratio); // discourage opening bin for small items
        }
    }

    // Early in stream, be slightly more willing to open bins (future flexibility)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 1.0 };
    score -= (1.0 - progress) * 5.0;

    // Slight tie-break toward fewer open bins
    score += open_bins_count as f64 * 0.05;

    score
}

