        1 => score += 2.0,          // 10..19
        2 | 3 => score -= 1.0,      // 20..39
        4 | 5 => score -= 3.0,      // 40..59: sweet spot
        6 | 7 => score -= 2.0,
        _ => {}                     // large residual: neutral (bin mostly empty)
