    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: prefer new bin only when item is huge relative
    // to residual spread and current bin would be badly fragmented.
    if bin_residual == bin_capacity {
