        let progress = step_index as f64 / total_items.max(1) as f64;
        score = c - pr; // = 0 for empty bin
        score += 2.0;   // small penalty so good fits in open bins win
        if next_item_size > 0 && next_item_size >= 50 && item_size >= 50 {
            score -= 6.0; // pair of large items: fresh bin useful
        }
        if progress > 0.8 && open_bins_count > 3 {
