pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post * post / cap;

    // Reward exact or near-exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 330.0 / post;
    } else if post_residual < 12 {
        score += 90.0 + (12 - post_residual) as f64 * 6.0;
    } else {
        // Penalize dead space relative to capacity (non-linear).
        let dead_frac = post / cap;
        score += 50.0 * dead_frac * dead_frac;
        if post_residual >= 40 {
            score -= 9.0;
        }
        if post_residual < 30 {
            score += 7.5 * (30 - post_residual) as f64 / 18.0;
        }
    }

    // Aggressive 2-step lookahead.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            let lookahead_waste = post_residual - next_item_size;
            score -= 80.0;
            score -= 2.0 * nxt;
            score += 0.5 * (lookahead_waste as f64);
            if lookahead_waste == 0 {
                score -= 300.0;
            }
            // Chain-friendly residual: leaves room for another mid-size item.
            if lookahead_waste <= 4 {
                score -= 12.0;
            }
            if (post - nxt) <= mean_residual * 0.5 {
                score -= 8.0;
            }
        } else {
            // Next item won't fit here.
            if post_residual < 10 {
                score += 60.0;
            }
            score += 10.0;
            // Residual just below next item size: nearly usable, mild penalty relief.
            if (next_item_size - post_residual) <= 2 && fitting_bins_count > 1 {
                score += 15.0;
            }
            if post_residual >= (next_item_size * 3 / 4) {
                score += 5.0 * (post_residual as f64 - nxt * 0.75) / (nxt * 0.25).max(1.0);
            }
            // Tiny dead space that next item cannot use: penalize harder when alternatives exist.
            if post_residual < (next_item_size / 2).max(1) && fitting_bins_count > 2 {
                score += 6.0 * (1.0 - post_residual as f64 / (next_item_size / 2).max(1) as f64);
            }
        }
    }

    // Prefer tighter bins relative to the mean.
    let mean_diff = (bin_residual as f64) - mean_residual;
    score += 0.3 * mean_diff;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Consolidation pressure when many bins fit.
    if fitting_bins_count > 4 && bin_residual != bin_capacity && post_residual > 30 {
        score += 3.0;
    }
    score += 0.05 * open_bins_count as f64;

