    // open a new bin when a good chain fit exists in an open bin.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_bonus = 40.0 * (1.0 - progress);
    if bin_residual == bin_capacity {
        score -= new_bin_bonus;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
        if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
            score += 14.0;
        }
    }

    // Penalize residuals that are too small to ever be useful for typical items.
    if post_residual > 0 && post_residual < 8 && next_item_size > post_residual {
        score += 26.0;
    }

    score
}

