    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residuals divisible by common
    // item sizes (10/20/25/50) are more reusable, reward them.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 6.0; }
        if post_residual % 20 == 0 { score -= 3.0; }
        if post_residual % 25 == 0 { score -= 2.5; }
        if post_residual % 50 == 0 { score -= 4.0; }
    } else {
        // Perfect fill is ideal.
        score -= 40.0;
    }

    // Penalize dead space too small for the minimum item (1..100 unknown,
    // but small leftovers are less useful than mid-size ones).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // strongly favor this bin (harmonic chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.4;
        } else {
            // Next item won't fit here; slight penalty scaled by overflow.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    } else {
        // Last item: prefer closing bins tightly.
        score -= 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or
    // the fit here would leave large unusable residue.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = open_bins_count as f64 / (mean_residual / bin_capacity as f64 + 1.0);
        score = bin_capacity as f64 * 0.9
            - progress * 5.0
            - crowded * 0.5
            - (mean_residual / bin_capacity as f64) * 20.0;
        if item_size == bin_capacity {
            score -= 100.0; // perfect fresh fit
        }
    }

    // Tight fits are good: reward small post_residual relative to item size.
    score -= (item_size as f64) * 0.1;

    // Mean-residual coupling: prefer bins below mean residual (tighter bins
    // get filled first, keeping large residuals flexible).
    if (bin_residual as f64) > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - bin_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core dead-space avoidance: residuals below the minimum item size (1..=100,
    // assume worst-case small items ~10) are "unusable" gaps.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score += 50.0; // hard penalty for creating a dead gap
    } else {
        // Soft penalty growing as post_residual approaches unusable range
        score += 8.0 * ((dead_threshold * 2.0 - post_residual as f64).max(0.0) / dead_threshold);
    }

    // Reward tight fits (low post_residual relative to bin capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness;

    // Exact / near-exact fill bonus
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless this item would
    // otherwise create a dead gap in every fitting bin.
    if bin_residual == bin_capacity {
        let would_dead = post_residual < 10 && fitting_bins_count >= 1;
        if would_dead {
            score -= 25.0; // allow new bin to preserve open-bin flexibility
        } else {
            score += 45.0 + 5.0 * open_bins_count as f64; // discourage proliferation
        }
    }

    // Lookahead: if next item fits exactly in the post residual, big reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 55.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0 * (next_item_size as f64 / post_residual.max(1) as f64);
    } else if next_item_size > post_residual && post_residual < 10 {
        score += 25.0; // residual can't host next item and is dead space
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing ones
    score += 0.8 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Late in the stream, prefer closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: bins far from mean residual get mild normalization
    score += 0.3 * ((post_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward: post_residual exactly matches the next item size (perfect 2-step chain).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 {
        // Distance-based partial reward for near-matches (soft lookahead matching).
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= (40.0 / (1.0 + gap)).min(25.0);
    }

    // Penalize leaving residuals that are likely dead space: small residuals that
    // cannot plausibly fit any future item (items >= 1, but typical sizes larger).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Penalize residuals far below the mean residual of open bins (wasting space
    // in already-sparse bins creates imbalance).
    score += 0.5 * (mean_residual - post_residual as f64).abs();

    // Last chance: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive if it enables a perfect lookahead chain
    // with the next item (residual = capacity - item = next item size), or late
    // in the stream when open bins are crowded.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 55.0; // fresh bin perfectly primed for the next item
        } else {
            score += 15.0 + 0.3 * open_bins_count as f64; // discourage unnecessary openings
        }
    }

    // Mild late-stream tightening: prefer tight fits as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward tight fits (low post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * (item_size as f64);

    // Penalize dead space: post_residual too small to be useful for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            score -= 15.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty proportional to leftover
            score += 8.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are poor
    if bin_residual == bin_capacity {
        // baseline penalty that shrinks late in stream or when few bins open
        score += 20.0 + 0.5 * (open_bins_count as f64);
        // if item is large, opening fresh bin is more attractive
        score -= 0.15 * (item_size as f64);
        // early in stream, exploring new bins is cheaper
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 * progress;
    }

    // Global state coupling: prefer filling bins when mean residual is high (many partly-full bins)
    score -= 0.1 * mean_residual * tightness;

    // Time horizon: late in the stream, consolidate aggressively
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear coupling of post-residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - norm_pr) * (1.0 - norm_pr);
    score -= 40.0 * poly * (0.5 + 0.5 * progress);

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - (pr / cap);
    score -= 12.0 * tightness * tightness * (1.0 + progress);

    // Penalize small dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 8.0 * (nxt - pr) * (0.5 + progress);
        } else {
            // smooth reward when lookahead fits in the post residual
            let slack = (pr - nxt) / cap;
            score -= 6.0 * (1.0 - slack) * (1.0 - slack);
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    // Pull toward mean residual: prefer bins near average fill state
    score += 0.3 * (pr - mean_residual).abs();

    // New-bin candidate: penalize unless post_residual is very large (poor fits elsewhere)
    if bin_residual == bin_capacity {
        score += 15.0 - 10.0 * norm_pr;
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
