        if post_residual < 30 {
            score += 7.5 * (30 - post_residual) as f64 / 18.0;
        }
        // harmony rewards for round residuals
        if post % 10 == 0 { score -= 6.0; }
        if post % 25 == 0 { score -= 4.0; }
    }

    if post > 0.0 && post < 0.25 * cap {
        score += 30.0 * (1.0 - post / (0.25 * cap));
    }

    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let chain_tight = 1.0 - (post - nxt) / cap;
            score -= 52.0 * chain_tight;
            if post == nxt { score -= 68.0; }
            if post_residual % next_item_size == 0 && next_item_size > 1 { score -= 12.0; }
            if post >= nxt + mean_residual { score -= 10.0; }
            if (post - nxt) <= mean_residual * 0.5 { score -= 8.0; }
            if post - nxt >= 1.0 && post - nxt <= 4.0 { score -= 12.0; }
            if post - nxt < 6.0 { score -= 18.0; }
            if (post - nxt) as u32 == mean_residual as u32 { score -= 9.0; }
            if post_residual <= 25 && nxt > post_residual as f64 * 0.6 {
                score -= 13.0 * (1.0 - post_residual as f64 / 25.0);
            }
            let chain_gap = post - nxt;
            if chain_gap <= 12.0 && chain_gap <= mean_residual * 1.2 {
                score -= 7.0 * (1.0 - chain_gap / 12.0);
            }
            if chain_gap <= 2.0 && post > 0.4 * cap { score -= 9.0; }
        } else {
            // next item won't fit here
            if post_residual > 0 && post_residual < 10 { score += 60.0; }
            if (nxt - post) as u32 <= 2 && fitting_bins_count > 1 { score += 15.0; }
            if (nxt - post) as u32 > 20 && post_residual > 0 && post_residual < 20 { score += 12.0; }
            if post_residual > 0 && post_residual < (next_item_size / 2).max(1) {
                score += 6.0 * (1.0 - post_residual as f64 / (next_item_size / 2).max(1) as f64);
            }
            if post_residual > 0 && nxt - post <= 10.0 {
                score += 4.0 * (1.0 - (nxt - post) / 10.0);
            }
            // residual just under next item: wasted near-fit
            if post_residual >= (next_item_size * 3 / 4).max(1) && post_residual < next_item_size {
                score += 5.0 * (post_residual as f64 - next_item_size as f64 * 0.75)
                    / (next_item_size as f64 * 0.25).max(1.0);
            }
            let dead = post / cap;
            if dead > 0.35 && post_residual as f64 > mean_residual * 1.5 && fitting_bins_count > 3 {
                score += 10.0 * (dead - 0.35);
            }
        }
    } else {
        score += post * 2.2;
    }

    // small dead sliver with no chain potential
    if post_residual > 0 && post_residual < 8 && next_item_size > post_residual { score += 26.0; }
    if post_residual > 0 && post_residual < 16 && next_item_size > post_residual && (mean_residual as u32) > post_residual {
        score += 9.0 * (16 - post_residual) as f64 / 8.0;
    }

    // pull toward bins with above-average remaining space
    let mean_diff = (bin_residual as f64) - mean_residual;
    score += 0.3 * mean_diff;

    // last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    if fitting_bins_count > 4 && bin_residual != bin_capacity && post_residual > 30 {
        score += 3.0;
    }

    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_bonus = 40.0 * (1.0 - progress);
    if bin_residual == bin_capacity {
        score -= new_bin_bonus;
        if next_item_size > 0 && post_residual >= next_item_size { score -= 8.0; }
        if fitting_bins_count > 2 && post_residual >= next_item_size { score += 14.0; }
        if mean_residual < item_size as f64 && open_bins_count > 2 { score += 10.0; }
        if open_bins_count > 5 && mean_residual > 0.4 * cap { score += 12.0; }
        if progress > 0.6 && open_bins_count > 3 { score += 8.0; }
    } else {
        let tightness = 1.0 - (bin_residual as f64 / cap);
        score -= 10.0 * tightness;
        if post_residual > 0 && next_item_size as f64 > post
            && post_residual as f64 > mean_residual * 1.5 && fitting_bins_count > 3 {
            score += 8.0;
        }
    }

    score
}

