pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // classes (multiples of small denominators) are favored.
    let pr = post_residual;
    if pr == 0 {
        // Perfect fit: extremely desirable.
        score -= 1000.0;
    } else {
        // Dead-space penalty grows when residual is small and awkward.
        let class = pr % 10;
        // Residuals that are multiples of 5 or 10 are more likely reusable
        // (many item sizes are multiples of 5/10 in practice).
        if pr % 10 == 0 {
            score -= 30.0;
        } else if pr % 5 == 0 {
            score -= 15.0;
        } else {
            // Awkward odd residual: penalize proportionally to awkwardness.
            score += (class as f64) * 2.0;
        }

        // Small dead space that nothing can use (below min item size 1 is fine,
        // but tiny residuals < 10 waste capacity unless exactly 0).
        if pr < 10 && pr > 0 {
            score += 40.0;
        }

        // Harmonic fraction of the bin used: reward high fill ratio.
        let fill = (bin_capacity - pr) as f64 / bin_capacity as f64;
        score -= fill * 50.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // Lookahead coupling: if next item fits in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= pr {
        score -= 60.0;
        // Extra reward if next item exactly fills the leftover.
        if next_item_size == pr {
            score -= 80.0;
        }
    } else if next_item_size > pr {
        // Leftover too small for next item: penalize if it's tiny dead space.
        if pr > 0 && pr < next_item_size {
            score += (pr as f64) * 0.5;
        }
    }

    // New-bin candidate logic: empty bin should win only when fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, scaled by stream progression
        // (later in stream, more conservative about new bins).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 150.0 + 100.0 * progress;

        // If few bins fit the item, opening a new bin is less attractive.
        if fitting_bins_count <= 1 {
            score += 250.0;
        }
        // If existing bins are crowded (low mean residual), new bin is ok.
        if mean_residual < 20.0 {
            score -= 60.0;
        }
    }

    // Mild tie-breaker: prefer bins with residual close to item (tight fit)
    // via integer division threshold classes.
    let tight = bin_residual / item_size.max(1);
    if tight == 1 {
        score -= 10.0;
    }

    // Prefer using already-open bins when many are open (avoid sprawl).
    score += (open_bins_count as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if no realistic item (size >= 1, but practically < 10 rare) fits well.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny sliver -> wasted space
    } else if post_residual < 20 {
        score += 12.0; // near-dead zone
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit: strongly rewarded
    }

    // Reward tight fits generally: shrink score toward zero for small post_residual.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.15;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: with many open bins, avoid spreading; prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.8 + 0.6 * progress);

    // Lookahead: if the next item fits exactly into the post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            score += 6.0; // next item can't use this residual anyway
        }
    }

    // New-bin candidate handling: an empty bin has neutral post_residual = capacity.
    // Make it moderately attractive only when existing fits are poor.
    if bin_residual == bin_capacity {
        // Baseline: empty bin score should sit above good fits but below dead-space fits.
        score = 55.0 + open_bins_count as f64 * 0.5;
        if post_residual >= next_item_size && next_item_size > 0 {
            score -= 10.0; // fresh bin can host the next item too
        }
    }

    // Mean residual coupling: if mean residual across bins is high, prefer consolidation
    // into bins below the mean (this bin's residual below mean => good target).
    if bin_residual != bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post * post / cap; // quadratic pressure: big leftovers hurt more

    if post_residual == 0 {
        score -= 1000.0; // perfect fit dominates
    } else if post_residual <= 5 {
        // tiny slivers are almost-dead space: strong penalty (borrowed from best)
        score -= 330.0 / post;
    } else if post_residual < 12 {
        score += 90.0 + (12 - post_residual) as f64 * 6.0;
    } else {
        score -= 15.0 * (post / cap);
        if post_residual >= 40 { score -= 9.0; }
        if post_residual < 30 { score += 7.5 * (30 - post_residual) as f64 / 18.0; }
    }

    // Harmony of the leftover space
    if post_residual > 0 {
        if post % 10 == 0 { score -= 12.0; }
        if post % 20 == 0 { score -= 8.0; }
        if post % 25 == 0 { score -= 8.0; }
        if post % 50 == 0 { score -= 6.0; }
        // dead-space band under 25% of capacity
        if post < 0.25 * cap {
            score += 30.0 * (1.0 - post / (0.25 * cap));
        }
    }

    // Lookahead: reward if next item chains into the leftover
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let chain_tight = 1.0 - (post - nxt) / cap;
            score -= 52.0 * chain_tight;
            if post == nxt { score -= 68.0; } // exact chain fill
            if post >= nxt + mean_residual { score -= 10.0; }
            if (post - nxt) <= mean_residual * 0.5 { score -= 8.0; }
            if post - nxt >= 1.0 && post - nxt <= 4.0 { score -= 12.0; }
            if post - nxt < 6.0 { score -= 18.0; }
            if (post - nxt) as u32 == mean_residual as u32 { score -= 9.0; }
            if post_residual <= 25 && nxt > post_residual as f64 * 0.6 {
                score -= 13.0 * (1.0 - post_residual as f64 / 25.0);
            }
            if post_residual % next_item_size == 0 { score -= 10.0; } // harmonic chain
        } else if post + 10.0 >= nxt {
            score += 6.0; // near-miss: mild penalty
        } else {
            score += 0.06 * (nxt - post); // gap-proportional penalty
        }
        if nxt > post && post_residual < 10 { score += 60.0; }
        if nxt > post && (nxt - post) as u32 <= 2 && fitting_bins_count > 1 { score += 15.0; }
        if nxt > post && (nxt - post) as u32 > 20 && post_residual > 0 && post_residual < 20 { score += 12.0; }
        // near-fit rejection: residual barely below next item (from best)
        if post_residual > 0 && nxt > post_residual && post_residual >= (next_item_size * 3 / 4) && post_residual < next_item_size {
            score += 5.0 * (post_residual as f64 - nxt * 0.75) / (nxt * 0.25).max(1.0);
        }
        // residual far below half of next item: likely dead space (from best)
        if post_residual > 0 && nxt > post && post_residual < (next_item_size / 2).max(1) {
            score += 6.0 * (1.0 - post_residual as f64 / (next_item_size / 2).max(1) as f64);
        }
    } else {
        score += post * 2.2;
    }

    if post_residual > 0 && post_residual < 16 && next_item_size > post_residual && (mean_residual as u32) > post_residual {
        score += 9.0 * (16 - post_residual) as f64 / 8.0;
    }

    // residual vs mean alignment
    let mean_diff = (bin_residual as f64) - mean_residual;
    score += 0.3 * mean_diff;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    if fitting_bins_count > 4 && bin_residual != bin_capacity && post_residual > 30 {
        score += 3.0;
    }

    // New-bin candidate handling
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_bonus = 40.0 * (1.0 - progress);
    if bin_residual == bin_capacity {
        score -= new_bin_bonus;
        if next_item_size > 0 && post_residual >= next_item_size { score -= 8.0; }
        if fitting_bins_count > 2 && post_residual >= next_item_size { score += 14.0; }
        if mean_residual < item_size as f64 && open_bins_count > 2 { score += 10.0; }
        if open_bins_count > 5 && mean_residual > 0.4 * cap { score += 12.0; }
        if progress > 0.6 && open_bins_count > 3 { score += 8.0; }
    } else {
        // tightness pressure toward fuller bins
        let tightness = 1.0 - (bin_residual as f64 / cap);
        score -= 10.0 * tightness;
        if post_residual > 0 && next_item_size as f64 > post && post_residual as f64 > mean_residual * 1.5 && fitting_bins_count > 3 {
            score += 8.0;
        }
    }

    // dead-space slope beyond 35% of capacity
    let dead = post / cap;
    if post_residual > 0 && next_item_size as f64 > post && dead > 0.35 && (post_residual as f64) > mean_residual * 1.5 && fitting_bins_count > 3 {
        score += 10.0 * (dead - 0.35);
    }
    if post_residual > 0 && next_item_size as f64 <= post && (post - next_item_size as f64) <= 2.0 && dead > 0.4 {
        score -= 9.0;
    }
    if post_residual > 0 && next_item_size as f64 <= post {
        let gap = post - next_item_size as f64;
        if gap <= 12.0 && gap <= mean_residual * 1.2 {
            score -= 7.0 * (1.0 - gap / 12.0);
        }
        if post_residual % 10 == 0 { score -= 5.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills strongly
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward when post_residual matches next item exactly
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 300.0;
        } else {
            score += diff as f64 * 0.5;
        }
        // Penalize if next item cannot fit in post_residual (dead space risk)
        if next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
        // Bonus if next item fits snugly (small leftover after both)
        let post2 = post_residual as i64 - next_item_size as i64;
        if post2 >= 0 && post2 <= 10 {
            score -= 50.0;
        }
    }

    // Compare residual against mean residual: prefer bins with tighter residual
    score += (bin_residual as f64 - mean_residual) * 0.2;

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize choosing a fresh bin when open bins could fit, unless item is huge
    if bin_residual == bin_capacity {
        if item_size >= 60 {
            score -= 20.0;
        } else {
            score += 120.0;
        }
    }

    // Late in stream: be greedier about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: squared post-residual punishes wasted space super-linearly.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits into this bin's post-residual, reward;
    // if next item is large and post-residual is small dead space, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            let waste = post_residual as f64 / bin_capacity as f64;
            score += waste * 12.0;
        }
        // Bonus if post-residual leaves a "useful" chunk for the future item.
        if post_residual >= next_item_size && post_residual < next_item_size + 10 {
            score -= 5.0;
        }
    }

    // New-bin candidate handling: only attractive when existing bins fit poorly
    // or there are no open bins.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if open_bins_count == 0 {
            score -= 50.0; // must open
        } else {
            // Penalize opening new bins early in the stream; relax later when
            // fragmentation of open bins is high.
            let progress = step_index as f64 / (total_items.max(1) as f64);
            let fragmentation = (mean_residual - post_residual as f64).abs() / bin_capacity as f64;
            score += 18.0 - 10.0 * progress + 6.0 * fragmentation;
        }
    } else {
        // Reward using existing bins relative to mean residual state.
        if (bin_residual as f64) < mean_residual {
            score -= 3.0; // prefer below-average residual bins (denser bins)
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.05 * (post_residual as f64 / bin_capacity as f64);

    // Late-stream tightness: as stream ends, waste matters more (no future to fill gaps).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit = item_size as f64;

    // Base: post-residual (lower is better), with smooth non-linear shaping.
    let mut score = post * (1.0 + 0.35 * progress * (post / cap));

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post / cap).clamp(0.0, 1.0);
    score -= 18.0 * tightness * tightness * (1.0 + 0.6 * progress);

    // Penalize dead space that can't fit a typical next item: smooth interaction
    // between post_residual and next_item_size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let can_fit_next = (post >= nxt) as i32 as f64;
        // If next item fits, reward slightly; if not, penalize wasted space.
        score -= can_fit_next * 6.0 * (1.0 - (post - nxt) / cap).clamp(0.0, 1.0);
        score += (1.0 - can_fit_next) * (post / cap) * 14.0;
    }

    // Last-chance bonus: this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: prefer existing bins unless the item fits
    // perfectly nowhere. Penalize opening a new bin mildly, more early on
    // (amortization of the new bin), less late when fragmentation dominates.
    if bin_residual == bin_capacity {
        score = cap - fit; // post_residual of new bin
        score += 8.0 * (1.0 - progress) + 3.0;
        // If item fills new bin perfectly, allow it.
        if fit >= cap * 0.9 {
            score -= 30.0;
        }
        // If there is exactly one fitting bin, don't open a new one.
        if fitting_bins_count >= 1 {
            score += 20.0;
        }
    }

    // Smooth coupling with mean residual: prefer bins below mean residual
    // (fill emptier bins first when residuals are large on average).
    let dev = (post - mean_residual) / cap;
    score += 5.0 * dev * dev.abs();

    // Mild penalty for spreading across many open bins late in stream.
    score += (open_bins_count as f64).ln().max(0.0) * 0.4 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions.
    // Residuals that are "nice" fractions of capacity (multiples of 10/20/25)
    // are more reusable; penalize awkward residuals (dead space).
    let pr = post_residual;
    let awkward = if pr == 0 { 0.0 }
        else if pr % 25 == 0 { -12.0 }
        else if pr % 20 == 0 { -9.0 }
        else if pr % 10 == 0 { -6.0 }
        else if pr % 5 == 0 { -2.0 }
        else { (pr % 5) as f64 * 2.5 };
    score += awkward;

    // Perfect fit gets a strong bonus.
    if pr == 0 {
        score -= 30.0;
    }

    // Lookahead: does the next item fit into the post-residual?
    if next_item_size > 0 && pr > 0 {
        if next_item_size <= pr {
            // Great: residual remains usable for the next item.
            score -= 8.0 + (next_item_size as f64 / cap) * 6.0;
        } else {
            // Next item won't fit; this residual is likely dead space.
            score += 6.0 + (pr as f64 / cap) * 4.0;
        }
    }

    // Last chance: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current residual is truly bad
    // (large awkward leftover or cannot host next item) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let bad_fit = (pr as f64 / cap) > 0.35 && (pr % 10 != 0);
        let lookahead_bad = next_item_size > 0 && next_item_size > pr && pr > 0;
        let penalty = 25.0
            + open_bins_count as f64 * 1.5
            + (1.0 - progress) * 10.0
            - mean_residual * 0.15;
        if bad_fit || lookahead_bad {
            score -= penalty * 0.35;
        } else {
            score += penalty;
        }
    }

    // Mild preference for filling fuller bins (low post_residual fraction).
    score += (pr as f64 / cap) * 3.0;

    // Slight penalty when bin residual is far from item size (poor coupling).
    let gap = (bin_residual as f64 - item_size as f64) / cap;
    score += gap * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
