            score -= 52.0 * chain_tight;
            if post == nxt {
                score -= 68.0;
            }
            if post >= nxt + mean_residual {
                score -= 10.0;
            }
            let gap = post - nxt;
            if gap >= 1.0 && gap <= 4.0 {
                score -= 12.0;
            }
            if gap < 6.0 {
                score -= 18.0;
            }
            if gap <= 12.0 && gap <= mean_residual * 1.2 {
                score -= 7.0 * (1.0 - gap / 12.0);
            }
            if (gap as u32) == mean_residual as u32 {
                score -= 9.0;
            }
            // Tight-chain bonus in small residuals.
            if nxt > post * 0.6 && post_residual <= 25 {
                score -= 13.0 * (1.0 - post_residual as f64 / 25.0);
            }
        } else {
            // Next item won't fit: penalize tiny useless residuals.
            if post_residual < 10 {
                score += 60.0;
