    }

    // Prefer tighter bins relative to mean residual.
    let mean_diff = (bin_residual as f64) - mean_residual;
    score += 0.3 * mean_diff;

    // Last-chance bin: strongly prefer using it over opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }
    if fitting_bins_count > 4 && bin_residual != bin_capacity && post_residual > 30 {
        score += 3.0;
    }

    // Consolidation pressure with many open bins.
    score += 0.05 * open_bins_count as f64;

    // New-bin decision: early in stream be willing to open; later, fill existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_bonus = 40.0 * (1.0 - progress);
    if bin_residual == bin_capacity {
        score -= new_bin_bonus;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
        if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
            score += 14.0;
        }
    }

    // Waste-avoidance: if next item can't use this residual and residual is far above mean, penalize.
    if post_residual > 0 && next_item_size as f64 > post
        && post / cap > 0.35
        && (post_residual as f64) > mean_residual * 1.5
        && fitting_bins_count > 3 {
        score += 10.0 * (post / cap - 0.35);
    }
    if post_residual > 0 && post_residual < item_size
        && next_item_size as f64 > post && open_bins_count > 3 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for typical
    // future items (below the smallest plausible item) are pure waste.
    let dead_threshold = 12.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0; // heavy penalty for unusable slivers
    }

    // Non-linear dead-space shaping: penalize mid-range residuals that are
    // unlikely to be exactly filled by future items.
    let pr = post_residual as f64;
    score += 0.05 * (pr * (100.0 - pr) / 100.0).sqrt() * 2.0;

    // Perfect fit reward: zero residual is ideal.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward residuals that can still fit the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 {
        score += 4.0; // this bin becomes dead for the next item
    }

    // Open-bin pressure: discourage scattering across many bins; prefer
    // filling existing bins when several are open.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 3.0;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when existing residuals are large/wasted.
    if bin_residual == bin_capacity {
        let mean_gap = mean_residual - pr; // how much better the average open bin is
        score = score * 0.5 + 55.0 + mean_gap.max(0.0) * 0.3;
        // Late in the stream, opening new bins is less costly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0;
    }

    // Mild alignment with mean residual: prefer bins close to the mean state.
    score += ((post_residual as f64) - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
