pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for exact / near-exact fits (small post_residual).
    score *= 1.0 + 30.0 / (post_residual as f64 + 1.0);

    // 2-step lookahead: reward bins whose post_residual matches next_item_size well.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 25.0 / (1.0 + gap);
        // Perfect chain: item fits exactly, next item fills remainder exactly.
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize leaving a residual that no plausible next item can use.
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Relative-to-mean coupling: bins already tighter than average are better targets.
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless residuals of open bins are hopeless.
    if bin_residual == bin_capacity {
        score += 15.0;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 25.0 * (1.0 - progress);
        // If no open bin fits well, allow new bin.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Mild penalty for wasting a large bin on a tiny item.
    score += (item_size as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
