        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 330.0 / post_residual as f64;
    } else if post_residual < 12 {
        score += 90.0 + (12 - post_residual) as f64 * 6.0;
    } else {
        score -= 15.0 * (post / cap);
