pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on wasted space
    let waste = post_residual as f64;
    score += 0.35 * waste * waste / bin_capacity as f64;

    // Perfect / near-perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead: penalize if next item cannot use the post-residual (dead space),
    // reward if next item fits snugly into the leftover
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if next > post {
            score += 0.8 * (next - post); // leftover likely wasted
        } else {
            let leftover = post - next;
            score -= 12.0 - 0.3 * leftover; // chain-fit reward
            if leftover == 0.0 {
                score -= 20.0; // two-item exact closure
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Global pressure: many open bins -> prefer filling existing ones
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 6.0;

    // Mean residual coupling: if this bin's residual deviates from mean,
    // prefer bins that are more filled (residual below mean)
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // New-bin candidate logic: empty bin is penalized unless current bins fit poorly
    if bin_residual == bin_capacity {
        let open_fits = fitting_bins_count as f64;
        let desperation = if next_item_size > 0 && (next_item_size as f64) > mean_residual { 1.2 } else { 0.4 };
        score += 40.0 + desperation * 15.0 - open_fits * 2.0;
        // Late in the stream, opening bins is cheaper than fragmentation
        score -= progress * 10.0;
    }

    // Small item into large residual: mild penalty to preserve space for big items
    if item_size < 30 && bin_residual > 70 && bin_residual < bin_capacity {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
