pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: post-residual, mildly non-linear in residual size
    let mut score = pr + 8.0 * pr_norm * pr_norm * cap;

    // Polynomial coupling of post-residual with stream progress:
    // early on, larger residuals are fine; late, penalize wasted space harder
    let coupling = 1.0 + 2.5 * progress * progress + 1.5 * (1.0 - progress) * progress;
    score += coupling * pr;

    // Reward tight fits (small post-residual) non-linearly
    let tight = 1.0 - pr_norm;
    score -= 20.0 * tight * tight * tight;

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 25.0 * progress;
    }

    // Penalize bins whose residual deviates badly from mean residual
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // Lookahead: if next item fits exactly in post-residual, strong reward
    if next_item_size > 0 {
        if (next_item_size as f64 - pr).abs() < 1.0 {
            score -= 30.0;
        } else if (next_item_size as u32) <= post_residual {
            score -= 8.0 * (1.0 - ((pr - next_item_size as f64) / cap).abs());
        }
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * pr_norm;

    // New-bin candidate: keep it neutral-to-slightly-high unless residual math favors it
    if bin_residual == bin_capacity {
        score += 5.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Dead-space penalty: post_residual that is too small to be useful for typical items.
    if post_residual > 0 {
        let pr = post_residual as f64;
        let class = (post_residual % 10) as f64; // harmonic class of leftover
        if post_residual < 10 {
            score += 18.0; // nearly dead space
        } else {
            // leftover in [1..9] mod 10 wastes a class; penalize awkward classes
            score += 4.0 * (class / 9.0);
        }
        // residual divisible into nice chunks (multiples of 10) are reusable
        if post_residual % 10 == 0 {
            score -= 6.0;
        }
        // harmonic threshold: leftover can host the next item exactly
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
            if next_item_size == post_residual {
                score -= 15.0; // perfect chaining
            }
        } else if next_item_size > 0 {
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it over a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when existing residuals are poor.
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64;
        let mean_r = mean_residual;
        // penalize opening new bins generally, more so early in the stream
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + 3.0 * open_pressure * (1.0 - 0.5 * progress);
        // but if mean residual is small (all bins nearly full), opening is fine
        if mean_r < 15.0 {
            score -= 35.0;
        }
        // if next item is large, a fresh bin is valuable
        if next_item_size > 50 {
            score -= 12.0;
        }
    }

    // Mild preference for bins with residuals near the mean (balance preservation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Late-stream tightening: be greedier about tight fits as stream ends.
    if total_items > 0 {
        let t = step_index as f64 / total_items as f64;
        score -= 8.0 * t * fill_ratio;
    }

    // Integer-division threshold on post_residual classes (harmonic buckets).
    let bucket = post_residual / 20; // 0..5 buckets
    score -= match bucket {
        0 => 2.0,           // post_residual < 20: risky but small waste
        1 => 0.0,
        2 => -1.0,          // 40-59: very reusable
        3 => -1.5,          // 60-79: half-bin, great
        4 => -0.5,
        _ => -2.0,          // near-empty bin
    };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

