    let pr = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // ---- STRICT DEAD SPACE AVOIDANCE ----
    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Penalize leftovers too small to ever be useful (unusable gap).
        // Threshold grows slightly with progress: late in the stream, tiny
        // gaps are almost certainly wasted forever.
        let min_useful = 10.0 + 5.0 * progress;
        if pr < min_useful {
            score += (min_useful - pr) * 4.0;
        }
        // Penalize leftovers that cannot host the lookahead item (k=2):
        // this residual becomes dead space for the next arrival.
        if next_item_size > 0 {
            let ni = next_item_size as f64;
            if pr < ni {
                score += (ni - pr) * 2.0;
            } else {
                // Small reward if the leftover exactly accommodates the next item.
                if (pr - ni).abs() < 0.5 {
                    score -= 8.0;
                }
            }
        }
    }

    // ---- OPEN BINS PRESSURE ----
    if is_new_bin {
        // Opening a new bin is penalized increasingly with the number of
        // already-open bins and with stream progression (consolidate early
        // waste is forgivable, late waste is not).
        score += 5.0 + open_bins_count as f64 * 3.0 + 15.0 * progress;
    } else {
        // Reward reusing existing bins, scaled by how many are open.
        score -= open_bins_count as f64 * 1.5;
        // Last-chance bin: if this is the ONLY open bin that fits the item,
        // strongly favor it to avoid opening a new bin unnecessarily.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    // ---- MEAN RESIDUAL COUPLING ----
    // Favor tighter-than-average bins (best-fit pressure): a bin whose
    // residual is below the mean is closer to being completed.
    score -= (mean_residual - bin_residual as f64) * 0.15;

    // Slight cap-awareness: reward leaving residuals that remain divisible
    // into plausible future item sizes (soft, non-linear shaping).
    if post_residual > 0 && !is_new_bin {
        let half = (bin_capacity as f64) * 0.5;
        if (pr - half).abs() < 1.0 {
            score -= 3.0; // a half-full leftover stays highly reusable
        }
    }

    score
}

