    }
    if post_residual > 0 && next_item_size as f64 <= post && (post - next_item_size as f64) <= 2.0 && dead > 0.4 {
        score -= 9.0;
    }
    if post_residual > 0 && next_item_size as f64 <= post {
        let gap = post - next_item_size as f64;
        if gap <= 12.0 && gap <= mean_residual * 1.2 {
            score -= 7.0 * (1.0 - gap / 12.0);
        }
    }
    // near-fit rejection: residual barely below next item
    if post_residual > 0 && next_item_size > post_residual && post_residual >= (next_item_size * 3 / 4) && post_residual < next_item_size {
        score += 5.0 * (post_residual as f64 - next_item_size as f64 * 0.75) / (next_item_size as f64 * 0.25).max(1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step match: post_residual equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Reward if next item fits in post_residual (partial lookahead credit).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Penalize dead space the next item cannot use.
        score += 15.0;
    }

    // Penalize post_residual that is small but unusable (dead space) relative to mean residual.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Compare against mean residual: prefer bins with above-average residual usage.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin is a good fit.
    if bin_residual == bin_capacity {
        let base = 40.0 + (post_residual as f64);
        // Discourage opening new bins early in the stream or when few bins open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = base - 20.0 * progress - (open_bins_count as f64).min(20.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
