pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap;
    let p2 = progress * progress;
    let p3 = p2 * progress;
    // Early: prefer tight fits (penalize large post_residual more); late: relax
    let coupling = norm_pr * (1.0 + 3.0 * progress + 2.0 * p2 + 1.5 * p3);
    score += 4.0 * coupling;

    // Smooth quadratic dead-space penalty around mid residuals
    let dead = norm_pr * (1.0 - norm_pr);
    score += 6.0 * dead * (1.0 - progress);

    // Reward filling bins nearly full (smooth exponential bonus)
    score -= 10.0 * (-3.0 * norm_pr).exp();

    // Last-chance bonus: strongly favor this bin if it's the only fitting one
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // Lookahead: penalize if post_residual can't fit next item (smooth)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = (post_residual as f64 - nxt).max(0.0) / cap;
        score += 3.0 * (1.0 - fits_next.min(1.0)) * (1.0 - progress);
        // Bonus if next item exactly fits post_residual
        if (post_residual as f64 - nxt).abs() < 1.0 {
            score -= 8.0;
        }
    }

    // Penalize spreading across too many open bins (smooth in open_bins_count)
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    // Deviation from mean residual: prefer bins near mean to keep balance
    score += 0.3 * ((pr - mean_residual) / cap).abs();

    // New-bin candidate: penalize mildly early, more late (prefer using open bins)
    if bin_residual == bin_capacity {
        score += 5.0 + 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: which capacity fraction class does it land in?
    let pr = post_residual;
    // class boundaries at C/5 steps: 0,20,40,60,80,100
    let class = pr / 20; // 0..=5
    // Reward tight fits (small post_residual) superlinearly
    score -= (cap - (pr as f64)).min(cap) * 0.0; // no-op placeholder to keep structure clear
    if pr == 0 {
        score -= 60.0; // perfect closure
    } else {
        // modulo arithmetic: residuals that are multiples of common item sizes (10,20,25,50)
        // are more likely to be filled exactly by future items.
        let harmonic_bonus = if pr % 50 == 0 { 25.0 }
        else if pr % 25 == 0 { 18.0 }
        else if pr % 10 == 0 { 12.0 }
        else if pr % 5 == 0 { 6.0 }
        else { 0.0 };
        score -= harmonic_bonus;
    }

    // Penalize residuals in "dead zones": 1..=9 (too small for min item) — pure waste.
    if pr >= 1 && pr <= 9 {
        score += 30.0;
    }
    // Penalize mid dead zones (e.g. 61..79 hard-to-fill band) except harmonic multiples
    if (61..=69).contains(&pr) {
        score += 8.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            // next fits: leftover after next placement
            let pr2 = pr - next_item_size;
            if pr2 == 0 { score -= 30.0; }
            else if pr2 % 10 == 0 { score -= 10.0; }
            else if pr2 <= 9 { score += 10.0; } // creates dead space after next
            score -= 5.0;
        } else {
            // next item won't fit here: bin becomes single-use; penalize if class is high-value
            score += 5.0 + class as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // base penalty so open bins with decent fit win
        score += 55.0;
        // but if many open bins exist and mean residual is low (all nearly full),
        // opening fresh is reasonable — reduce penalty
        score -= (open_bins_count as f64).min(20.0) * 0.5;
        if mean_residual < 15.0 {
            score -= 25.0;
        }
        // large item relative to capacity: fresh bin gives full flexibility
        if item_size >= 70 {
            score -= 20.0;
        }
    }

    // Progression: later in stream, prefer closing bins tightly (waste matters more).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    // Tie-break: prefer bins with lower residual generally (best-fit flavor)
    score += (bin_residual as f64) * 0.1;
    // slight preference when few bins open (keep bin count low)
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post * post / cap; // quadratic pressure: big leftovers hurt more

    if post_residual == 0 {
        score -= 1000.0; // perfect fit dominates
    } else if post_residual <= 5 {
        // tiny leftover that only very small items can use: treat as near-dead
        score -= 330.0 / post;
        if next_item_size > post_residual {
            score += 26.0;
        }
    } else if post_residual < 12 {
        score += 90.0 + (12 - post_residual) as f64 * 6.0; // marginal band
    } else {
        score -= 15.0 * (post / cap); // larger leftovers scale down
        if post_residual >= 40 { score -= 9.0; }
        if post_residual < 30 { score += 7.5 * (30 - post_residual) as f64 / 18.0; }
    }
    // harmony of the leftover space
    if post_residual > 0 {
        if post % 10 == 0 { score -= 12.0; }
        if post % 20 == 0 { score -= 8.0; }
        if post % 25 == 0 { score -= 8.0; }
        if post % 50 == 0 { score -= 6.0; }
    }
    // dead-space band under 25% of capacity
    if post > 0.0 && post < 0.25 * cap {
        score += 30.0 * (1.0 - post / (0.25 * cap));
    }

    // Lookahead: reward if next item chains into the leftover
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let chain_tight = 1.0 - (post - nxt) / cap;
            score -= 52.0 * chain_tight;
            if post == nxt { score -= 68.0; } // exact chain fill
            if post >= nxt + mean_residual { score -= 10.0; }
            if (post - nxt) <= mean_residual * 0.5 { score -= 8.0; }
            if post - nxt >= 1.0 && post - nxt <= 4.0 { score -= 12.0; }
            if post - nxt < 6.0 { score -= 18.0; }
