    // --- Lookahead (k=2): reward bins whose residual admits the next item ---
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 + slack * 0.15; // tighter future fit is better
    } else if next_item_size > 0 {
        // Next item won't fit here: mild penalty proportional to how far off.
        score += (next_item_size as f64 - post_residual as f64).min(30.0) * 0.3;
    }

    // --- New-bin candidate pressure ---
    if bin_residual == bin_capacity {
        // Base reluctance to open a new bin, growing with open bin count.
        score += 30.0 + open_bins_count as f64 * 1.5;
        // But if the item is large, a fresh bin leaves a large useful residual:
        // relax the pressure slightly for large items.
        if item_size > 60 {
            score -= 15.0;
        }
    }

    // --- Last-chance bin: if this is the ONLY bin that fits, use it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // --- Coupling with mean residual across open bins ---
    // Prefer bins whose resulting residual sits near the fleet mean (balanced packing).
    score += (mean_residual - post_residual as f64) * 0.06;

    // --- Late-stream consolidation: as the stream progresses, prefer filling
    // existing bins harder to avoid scattering residual capacity. ---
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 6.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

