        } else {
            // next item cannot follow: dead space penalty grows with gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.8;
        }
    }

    // Tight fit preference: penalize large post residuals relative to capacity
    score += (post_residual as f64 / bin_capacity as f64) * 50.0;

    // Compare against mean residual: prefer filling bins that are already low
    if (post_residual as f64) < mean_residual {
        score -= 20.0;
    } else {
        score += 10.0;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Discard new-bin candidate unless current bins are poor fits
    if bin_residual == bin_capacity {
        // new bin: baseline score = capacity residual; add fixed opening cost
        score += 120.0;
        // if few fitting bins, opening new bin is more attractive
        if fitting_bins_count <= 1 {
            score -= 60.0;
        }
        // late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post * post / cap; // quadratic pressure

    if post_residual == 0 {
        score -= 1000.0; // perfect fit dominates
    } else {
        // Harmony of the leftover space
        if post % 10 == 0 { score -= 12.0; }
        if post % 20 == 0 { score -= 8.0; }
        if post % 25 == 0 { score -= 8.0; }
        if post % 50 == 0 { score -= 6.0; }
        if post_residual < 10 {
            score += 330.0 / post; // dead sliver: strong penalty
        } else if post_residual <= 20 {
            score += 6.0;
        } else if post_residual < 40 {
            score -= 4.0;
        } else {
            score -= 9.0;
        }
        // dead-space band under 25% of capacity
        if post < 0.25 * cap {
            score += 30.0 * (1.0 - post / (0.25 * cap));
        }
        if post_residual >= 5 && post_residual < 12 {
            score -= 3.0 * (12 - post_residual) as f64;
        }
        // gradual small-residual penalty ramp
        if post_residual < 30 && post_residual >= 12 {
            score += 7.5 * (30 - post_residual) as f64 / 18.0;
        }
        // borrowed from best: reward large usable residuals relative to capacity
        score -= 15.0 * (post / cap);
        if post_residual >= 40 { score -= 4.0; }
    }

    // Lookahead: reward if next item chains into the leftover
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let chain_tight = 1.0 - (post - nxt) / cap;
            score -= 52.0 * chain_tight;
