pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward tight fits (small post residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 20.0 * (1.0 - 2.0 * tightness).max(0.0);

    // Penalize dead space that no plausible item can fill
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable sliver
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty proportional to wasted gap
            score += 5.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: prefer new bin only when existing fit is terrible
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a bin, discounted early in the stream
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut open_cost = 60.0 - 20.0 * progress;
        // If many open bins with large mean residual, opening a new bin is less attractive
        open_cost += open_bins_count as f64 * 1.5;
        open_cost += mean_residual * 0.3;
        score += open_cost;
    } else {
        // Slight preference for bins with residual close to item (best-fit flavor)
        score += 0.1 * (bin_residual as f64 - item_size as f64).abs();
    }

    // Global state coupling: when mean residual is high, encourage consolidating into fuller bins
    if !is_new_bin {
        score += 0.2 * (mean_residual - post_residual as f64).max(0.0);
    }

    // Late-stream consolidation: prefer filling existing bins near the end
    if total_items > 0 && step_index as f64 / total_items as f64 > 0.8 && !is_new_bin {
        score -= 8.0;
    }

    score
}

