pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit_norm = item_size as f64 / cap;

    // Base: quadratic penalty on post-residual (dead space), non-linearly
    // coupled with stream progress so waste matters more late in the stream.
    let mut score = pr * (1.0 + 0.9 * progress * progress);

    // Smooth non-linear coupling: reward tight fits (small post_residual)
    // with a saturating polynomial in normalized residual.
    score -= 12.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 + 0.5 * progress);

    // Penalize leaving a residual that is too small for typical future items
    // (smooth term, no hard threshold): residual slightly above zero is worst.
    let small_gap = (norm_pr * (1.0 - norm_pr)).max(0.0);
    score += 8.0 * small_gap * (1.0 + 0.3 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 + progress);
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && next_item_size as f64 <= pr {
        score -= 6.0 * (1.0 - (next_item_size as f64 / cap));
    } else if next_item_size > 0 {
        score += 4.0 * progress;
    }

    // Prefer filling bins with large residuals when many bins are open
    // (smooth coupling with mean residual).
    score -= 3.0 * ((bin_residual as f64 - mean_residual) / cap) * (1.0 + progress);

    // Mild penalty for proliferating open bins, growing smoothly over time.
    score += open_bins_count as f64 * 0.4 * (0.5 + 0.5 * progress);

    // New-bin candidate: make empty bins attractive only when the item is
    // large relative to capacity (poor fit elsewhere is likely).
    if bin_residual == bin_capacity {
        score += 10.0 - 14.0 * fit_norm * (1.0 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

