    // class boundaries (multiples of common small sizes) are less dead.
    let capacity_frac = post_residual as f64 / bin_capacity as f64;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Integer-division thresholds on post_residual: classify residual into
        // harmonic slots of 10 (typical small item granularity).
        let slot = post_residual / 10;
        let slot_rem = post_residual % 10;
        // Reward residuals that are exact multiples of 10 (likely reusable).
        if slot_rem == 0 {
            score -= 12.0;
        } else if slot_rem <= 3 {
            score += 6.0; // tiny sliver, near-dead space
        }
        // Larger usable slots are better than small ones, with diminishing returns.
        score -= (slot as f64).min(6.0) * 2.0;

        // Coupling with next item lookahead: if next item fits exactly into
        // post_residual, strongly reward; if it fits, mild reward.
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 200.0;
            } else if next_item_size <= post_residual {
                let nxt_rem = post_residual - next_item_size;
                score -= 20.0;
                if nxt_rem % 10 == 0 {
