                }
                score += nxt_rem as f64 * 0.15;
            } else {
                // Next item won't fit here: residual likely becomes dead space.
                score += 8.0;
            }
        }

        // Dead-space penalty grows non-linearly as residual fraction shrinks.
        if capacity_frac < 0.1 {
            score += (0.1 - capacity_frac) * 120.0;
        }

        // Last-chance bin: strongly prefer using it over opening a new bin.
        if fitting_bins_count == 1 && bin_residual != bin_capacity {
            score -= 60.0;
