        // New-bin candidate: penalize opening new bins unless existing fits are bad.
        if bin_residual == bin_capacity {
            score += 45.0
                + (open_bins_count as f64) * 2.0
                + mean_residual * 0.3;
            // Early in stream, new bins are cheaper to open.
            let progress = step_index as f64 / (total_items.max(1) as f64);
            score -= (1.0 - progress) * 20.0;
        }
    }

    // Mean-residual coupling: prefer bins whose residual deviates favorably
    // from the mean (larger-than-mean residual keeps flexibility).
    let dev = post_residual as f64 - mean_residual;
    score -= dev * 0.1;

    // Modulo-20 harmonic bonus: residuals of 20/40/60/80 pair well with
    // mid-size items.
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    score
}

