            score -= (post_residual - next_item_size) as f64 * 0.2;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin when open bins exist,
    // scaled by open_bins_count pressure (prefer filling existing bins).
    if bin_residual == bin_capacity {
        score += 60.0 + 10.0 * open_bins_count as f64;
