            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Compare against mean residual: bins tighter than average are good targets.
    score += (post_residual as f64 - mean_residual) * 0.6;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when no good fit exists
    // (i.e., current bin leaves large unusable waste).
    if bin_residual == bin_capacity {
        let waste_penalty = if post_residual > 0 && post_residual < 10 { 120.0 } else { 0.0 };
        let lookahead_bonus = if next_item_size > 0 && post_residual >= next_item_size { -80.0 } else { 0.0 };
