    let smallest = 1u32;
    if post_residual > 0 && post_residual < smallest + 5 {
        score += 30.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            score -= 60.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty proportional to leftover
            score += 15.0;
        }
    }

    // Prefer tighter fits among many candidates
    let tightness = 1.0 - post_residual as f64 / bin_residual.max(1) as f64;
    score -= 50.0 * tightness;

    // Global state coupling: when many bins open, discourage spreading; when few, allow
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += 0.5 * pressure * (1.0 - progress);

    // New-bin candidate handling: make empty bin moderately attractive only when
    // nothing fits well (high mean residual waste) or late in stream with few bins
    if bin_residual == bin_capacity {
        let waste = mean_residual - item_size as f64;
        if waste > 0.0 {
