pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post-residual, smoothly warped
    let mut score = pr_norm.powf(1.5) * cap;

    // Non-linear coupling of post_residual with stream progress:
    // later in the stream, dead space becomes more costly (convex penalty)
    let progress_coupling = pr_norm * pr_norm * (0.5 + progress) * cap;
    score += progress_coupling * 8.0;

    // Reward tight fits more strongly as stream progresses (smooth interaction)
    let fit_bonus = (1.0 - pr_norm).powi(3) * (1.0 + progress) * 30.0;
    score -= fit_bonus;

    // Perfect fill: near-zero residual gets strong reward, amplified over time
    if post_residual == 0 {
        score -= 40.0 + 40.0 * progress;
    }

    // Last-chance bin: strong reward, smoothly scaled by how full the bin is
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - bin_residual as f64 / cap).powi(2);
    }

    // Lookahead: if next item fits exactly into post_residual, reward smoothly
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        let lookahead_fit = (1.0 - diff / cap).max(0.0);
        score -= lookahead_fit * lookahead_fit * 20.0;
        // Penalize post-residual too small for the next item (dead space risk)
        if pr < next_item_size as f64 {
            score += (next_item_size as f64 - pr) * (0.3 + 0.7 * progress);
        }
    }

    // Penalize bins far below mean residual (smooth deviation penalty)
    let dev = (mean_residual - pr).abs();
    score += dev * dev / cap * 0.05;

    // Mild penalty when many bins are open: encourage consolidation
    score += open_bins_count as f64 * 0.1 * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how well does the leftover decompose?
    // Residuals that are multiples of 10 (harmonic with capacity) are "usable" classes.
    let post_mod10 = post_residual % 10;
    if post_mod10 == 0 {
        score -= 4.0; // perfectly harmonic leftover
    } else if post_mod10 <= 3 {
        score += 2.0 + 2.0 * post_mod10 as f64; // tiny slivers -> dead space
    } else {
        score += 0.5 * post_mod10 as f64;
    }

    // Integer-division threshold: does the leftover fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // reward couplings: leftover that chains nicely into next item
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 12.0; // perfect two-item fill
            } else if slack <= 10 {
                score -= 6.0;
            } else {
                score -= 2.0 * (10.0 - (slack as f64 / 10.0).min(10.0)) / 10.0;
            }
        } else {
            // leftover cannot host next item -> penalize, worse if next item is large
            score += 3.0 + (next_item_size as f64) * 0.05;
        }
    }

    // Capacity-fraction classes of the fill ratio
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    let quarter = (fill * 4.0).floor(); // 0..=3 class
    score -= quarter * 1.5; // deeper-filled bins are more attractive

    // Last-chance bin logic: strongly prefer using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is terrible
    if bin_residual == bin_capacity {
        let crowded = mean_residual < 15.0 || open_bins_count == 0;
        let poor_fit = post_residual < 10;
        if crowded || poor_fit {
            score -= 5.0;
        } else {
            score += 8.0 + mean_residual * 0.1; // discourage waste of open space
        }
    }

    // Stream progression: later in stream, tighten packing (prefer tight fits harder)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.02;

    // Mean-residual coupling: penalize creating residuals far below mean (fragmentation)
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score += 0.03 * dev;
    }

    // Modulo coupling between item and capacity thirds
    if (item_size % 25) == 0 {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold the smallest plausible
    // future item are pure waste; penalize them heavily (non-linearly).
    let dead_threshold = 10u32.min(bin_capacity / 10);
    if post_residual < dead_threshold && post_residual > 0 {
        score += 60.0 * (1.0 - post_residual as f64 / dead_threshold as f64);
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Tight-fit reward: small leftover relative to capacity is good.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 25.0 * (1.0 - tightness).max(0.0) * (1.0 - tightness).max(0.0);

    // Last chance: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: prefer it only when it enables a better future fit.
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized more when many bins are already open.
        score += 20.0 + 2.0 * open_bins_count as f64;
        // But if the next item fits exactly in a fresh bin and current fits are poor, encourage it.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0;
        }
        // Late in the stream, avoid spreading items across new bins.
        score += 15.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // If next item exactly fits the post residual, strongly favor this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
