    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 40.0;

    // Lookahead: if next item fits into post residual, reward this bin
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0 + 0.3 * next_item_size as f64;
        } else {
