            let dead = post_residual as f64;
            if dead < 10.0 {
                score += 15.0; // tiny dead space is fine (near full)
            } else {
                score += dead * 0.4;
            }
        }
    }

    // Last chance: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New bin candidate: penalize opening a new bin unless existing bins are fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        // base penalty, reduced if open bins have high mean residual (they're full-ish)
        let mut new_bin_penalty = 120.0 - 0.5 * mean_residual;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            new_bin_penalty -= 10.0;
