    if bin_residual == bin_capacity {
        let newbin_penalty = 20.0 * (1.0 - progress) + 5.0 * (mean_residual / cap);
        score += newbin_penalty + (open_bins_count as f64).sqrt();
        // Favor new bin if it fits next item too
