    if post_residual > 0 && next_item_size as f64 <= post {
        let dev = (post - mean_residual).abs();
        if dev > cap * 0.3 { score += 4.0 * (dev / cap); }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: which "slot" of capacity it falls in.
    let q = post_residual / (bin_capacity / 4); // 0..=4 harmonic quarter class
    match q {
        0 => score -= 14.0,            // near-perfect fill
        1 => score -= 6.0,             // good fill
        2 => score += 3.0,             // half-full, mediocre
        3 => score += 9.0,             // wasteful
        _ => score += 2.0,             // empty-ish (new bin candidate)
    }

    // Fine-grained modulo bonus: post_residual divisible by common item sizes
    // suggests a future item can exactly fill the leftover space.
    if post_residual > 0 {
        let r = post_residual as usize;
        if r % 10 == 0 { score -= 5.0; }
        else if r % 5 == 0 { score -= 2.5; }
        if r <= 9 { score -= 20.0; } // dead space too small for any item (min size 1..10 range)
    } else {
        score -= 30.0; // perfect closure
    }

    // Lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 4.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are tight.
    if bin_residual == bin_capacity {
        score += 18.0;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if mean_residual > 0.6 * bin_capacity as f64 {
            score += 10.0 * mean_residual / bin_capacity as f64;
        }
        if open_bins_count == 0 { score -= 40.0; }
        let _ = progress;
    }

    // Prefer bins that are already partially loaded (consolidation).
    let used = (bin_capacity - bin_residual) as f64;
    score -= 0.05 * used;

    // Slight preference for bins below mean residual (balance fill levels).
    score += 0.03 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
