pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest possible item (size 1) are already counted via post_residual,
    // but gaps that cannot fit the NEXT item are effectively dead space.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // This bin becomes unusable for the lookahead item -> penalty.
            score += (next_item_size - post_residual) as f64 * 1.5;
        } else {
            // Reward bins that still fit the next item.
            score -= 6.0;
        }
    }

    // Penalize small-but-nonzero dead gaps harder than large leftovers:
    // gaps in (0, 10) are nearly worthless; gaps in (10, 30) are risky.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 30 {
        score += 8.0;
    } else if post_residual == 0 {
        // Perfect closure of the bin is ideal.
        score -= 40.0;
    }

    // Tight fit reward: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 10.0;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (penalize the new-bin candidate more when open_bins_count is high).
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 3.0;
        // Early in the stream a fresh bin is cheaper to accept.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 10.0;
    } else {
        // Slight preference for bins whose residual is close to the item
        // (minimal waste relative to bin state).
        score -= (bin_residual - item_size) as f64 * 0.05;
    }

    // Deviation from mean residual: prefer bins that reduce residual variance
    // (keeps a portfolio of medium gaps for future items).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

