pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 60.0 * (1.0 - tightness) * (1.0 - tightness);

    // Aggressive 2-step lookahead: reward when post_residual can host next item
    if next_item_size > 0 && post_residual >= next_item_size {
        // bonus grows as post_residual approaches next_item_size (chain potential)
        let gap = (post_residual - next_item_size) as f64;
        score -= 45.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 {
        // penalize creating dead space that next item cannot use
        score += 35.0;
        // extra penalty if dead space is small-but-unusable (worst waste)
        if post_residual < 10 {
            score += 25.0;
        }
    }

    // Exact fit: near-perfect closure of the bin
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual < 5 {
        score -= 80.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate handling: only attractive when no good open option exists
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 120.0;
        // cheaper to open a new bin early in the stream / few open bins
        score -= 30.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
        if open_bins_count == 0 {
            score -= 150.0;
        }
        // if the next item is large, a fresh bin preserves flexibility
        if next_item_size >= item_size {
            score -= 40.0;
        }
        // discourage new bin if this bin would already fit the next item too
        if next_item_size > 0 && bin_residual >= item_size + next_item_size {
            score += 90.0;
        }
    }

    // Mild preference for bins with residual below mean (consolidate emptier bins)
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0 * ((res - mean_residual) / bin_capacity as f64);
    }

    score
}

