    let progress = step_index as f64 / (total_items.max(1) as f64);
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * (0.5 + progress);

    // Penalize dead space: post residual that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Lookahead: bonus if next item fits in the post residual (chain packing).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0;
        } else if next_item_size >= item_size && post_residual < next_item_size {
            // prefer bins leaving room for a bigger next item elsewhere; slight penalty
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Many open bins: prefer consolidating into bins with low residual (large mean gap).
    let gap = mean_residual - bin_residual as f64;
    score += 0.15 * gap;

    // Penalize bins whose residual deviates far above mean when many bins are open.
    if open_bins_count > 4 {
        score += 0.05 * (bin_residual as f64 - mean_residual).abs();
    }

    // New-bin candidate handling: empty bin gets a baseline penalty so we only
    // open a new bin when no decent fit exists.
    if bin_residual == bin_capacity {
        score += 55.0 - 20.0 * progress;
        // If next item is large and this item leaves lots of room, new bin is fine.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Mild preference for filling nearly-full bins late in the stream.
    if progress > 0.7 && post_residual < item_size {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
