    if fitting_bins_count > 4 && bin_residual != bin_capacity && post_residual > 30 { score += 3.0; }

    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_bonus = 40.0 * (1.0 - progress);
    if bin_residual == bin_capacity {
        score -= new_bin_bonus;
        if next_item_size > 0 && post_residual >= next_item_size { score -= 8.0; }
        if fitting_bins_count > 2 && post_residual >= next_item_size { score += 14.0; }
        // refine: penalize opening a new bin when some open bin would end nearly perfect
        if next_item_size > 0 && next_item_size == bin_residual {
            score += 90.0;
        }
        if next_item_size > 0 && open_bins_count > 0 && next_item_size >= 5 && next_item_size <= 10 {
            score += 10.0;
        }
    }

    let dead = post / cap;
    if post_residual > 0 && next_item_size as f64 <= post && next_item_size as f64 > post * 0.6 && post_residual <= 25 {
