    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, mildly non-linear (quadratic) — prefer tight fits
    let mut score = pr - 12.0 * norm_pr * (1.0 - norm_pr) * cap * 0.1;

    // Smooth polynomial coupling of post_residual with stream progress
    let prog_poly = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 8.0 * (pr * pr) / cap * (1.0 - prog_poly);
    score -= 10.0 * pr * prog_poly;

    // Lookahead: reward if next item fits post-residual (smooth cubic term)
    if next_item_size > 0 {
        let fits = (post_residual >= next_item_size) as f64;
        let tight = (next_item_size as f64 - pr).abs() / cap;
        score -= fits * 15.0 * (1.0 - tight * tight);
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Penalize waste relative to mean residual across open bins
    score += 0.15 * (pr - mean_residual).abs();

    // New-bin candidate: mild penalty so it's chosen only when fits are bad
    if bin_residual == bin_capacity {
        score += 6.0 + 4.0 * prog_poly;
