        if post_residual == 0 {
            score -= 25.0;
        } else if post_residual <= 5 {
            score -= 12.0;
        }
    }

    // Lookahead synergy: if the next item fits exactly into the post residual,
    // strongly favor this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 18.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        score -= 2.0; // bin remains usable for lookahead
    }

    // Tightness reward: fraction of the bin actually consumed.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * tightness;

    // Last-chance pressure: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual >= min_useful {
        score -= 8.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into them,
    // few open bins -> opening a new bin is relatively cheap.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    score += 2.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: placing into a bin far below mean residual
    // keeps the bin population balanced (avoid many near-full stragglers).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // New-bin candidate: empty bin must look attractive only when the item
    // is large relative to capacity or no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        if item_size >= 70 || post_residual == 0 {
            score -= 5.0;
        } else {
            score += 12.0; // discourage wasting a fresh bin on small items
        }
    }

