        if post_residual < 30 { score += 7.5 * (30 - post_residual) as f64 / 18.0; }
    }

    if post > 0.0 && post < 0.25 * cap {
        score += 30.0 * (1.0 - post / (0.25 * cap));
    }

    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let chain_tight = 1.0 - (post - nxt) / cap;
            score -= 52.0 * chain_tight;
            if post == nxt { score -= 68.0; }
            if post >= nxt + mean_residual { score -= 10.0; }
            if (post - nxt) <= mean_residual * 0.5 { score -= 8.0; }
            let gap = post - nxt;
            if gap >= 1.0 && gap <= 4.0 { score -= 12.0; }
            if gap < 6.0 { score -= 18.0; }
            if gap as u32 == mean_residual as u32 { score -= 9.0; }
            // refined: penalize leaving a gap that equals a "wasted" dead-space band
            if gap > 12.0 && gap < 25.0 && post_residual < (bin_capacity / 2) {
                score += 3.0 * (gap - 12.0) / 13.0;
            }
        } else if post + 10.0 >= nxt {
            score += 6.0;
        } else {
            score += 0.06 * (nxt - post);
        }
        if nxt > post && post_residual < 10 { score += 60.0; }
        if nxt > post && (nxt - post) as u32 <= 2 && fitting_bins_count > 1 { score += 15.0; }
        if nxt > post && (nxt - post) as u32 > 20 && post_residual > 0 && post_residual < 20 { score += 12.0; }
    } else {
        score += post * 2.2;
    }

    if post_residual > 0 && post_residual < 8 && next_item_size > post_residual { score += 26.0; }
    if post_residual > 0 && post_residual < 16 && next_item_size > post_residual && (mean_residual as u32) > post_residual {
        score += 9.0 * (16 - post_residual) as f64 / 8.0;
    }

    let mean_diff = (bin_residual as f64) - mean_residual;
    score += 0.3 * mean_diff;

