    // post-residual, this is a perfect pairing — strongly favor it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            // Next item fits: penalize leftover after the hypothetical pairing.
            let second_post = post_residual - next_item_size;
            score -= 100.0 - second_post as f64 * 2.0;
        } else {
            // Next item won't fit here: dead space risk scales with gap.
            let gap = next_item_size - post_residual;
            score += gap as f64 * 1.5;
        }
