    if post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }

    // Compare against mean residual: prefer bins whose post-residual stays
    // near the fleet mean to preserve balanced flexibility.
    score += (post_residual as f64 - mean_residual).abs() * 0.5;

