        1 => score -= 6.0,           // 10..19: still good
        2 => score -= 2.0,
        3 | 4 => score += 1.0,
        _ => score += 3.0,           // large leftover: wasteful
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic bonus if next item's class complements post_residual
            let combo = post_residual - next_item_size;
            score -= 6.0 + (combo % 10) as f64 * 0.4;
        } else {
            score += 5.0;
        }
