pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let residual = bin_residual as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post * post / cap;

    // Perfect / near-perfect fit rewards.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 330.0 / post;
    } else if post_residual < 12 {
        score += 90.0 + (12 - post_residual) as f64 * 6.0;
    } else {
        score -= 15.0 * (post / cap);
        if post_residual >= 40 { score -= 9.0; }
        if post_residual < 30 { score += 7.5 * (30 - post_residual) as f64 / 18.0; }
    }

    // Tightness coupling.
    let fill_ratio = item / residual.max(1.0);
    score -= 24.0 * fill_ratio;

    // Fragmentation penalty for small residuals.
    if post > 0.0 && post < 0.25 * cap {
        score += 30.0 * (1.0 - post / (0.25 * cap));
    }

    // Lookahead chain-fit bonus with combined gap anticipation.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let chain_tight = 1.0 - (post - nxt) / cap;
            score -= 52.0 * chain_tight;
            if post == nxt { score -= 68.0; }
            if post >= nxt + mean_residual { score -= 10.0; }
            if (post - nxt) <= mean_residual * 0.5 { score -= 8.0; }
            let gap = post - nxt;
            if gap >= 1.0 && gap <= 4.0 { score -= 12.0; }
            if gap < 6.0 { score -= 18.0; }
            if gap as u32 == mean_residual as u32 { score -= 9.0; }
            // Two-step lookahead: gap after next item stays reusable.
            if gap > 0.0 && gap < mean_residual {
                score += 10.0 * (1.0 - gap / mean_residual.max(1.0));
            }
            if gap >= mean_residual { score -= 6.0; }
        } else if post + 10.0 >= nxt {
            score += 6.0;
        } else {
            score += 0.06 * (nxt - post);
        }
        if nxt > post && post_residual < 10 { score += 60.0; }
        if nxt > post && (nxt - post) as u32 <= 2 && fitting_bins_count > 1 { score += 15.0; }
        if nxt > post && (nxt - post) as u32 > 20 && post_residual > 0 && post_residual < 20 { score += 12.0; }
    } else {
        score += post * 2.2;
    }

    // Dead-space penalty: residual too small for the next item.
    if post_residual > 0 && post_residual < 8 && next_item_size > post_residual { score += 26.0; }
    if post_residual > 0 && post_residual < 16 && next_item_size > post_residual && (mean_residual as u32) > post_residual {
        score += 9.0 * (16 - post_residual) as f64 / 8.0;
    }

    // Mean-residual coupling (borrowed from best: linear residual tilt).
    let mean_diff = (bin_residual as f64) - mean_residual;
    score += 0.3 * mean_diff;

    // Last-chance pressure.
    if fitting_bins_count == 1 && bin_residual != bin_capacity { score -= 120.0; }
    else if fitting_bins_count <= 1 && bin_residual != bin_capacity { score -= 6.0; }
    if fitting_bins_count > 4 && bin_residual != bin_capacity && post_residual > 30 { score += 3.0; }

    // Consolidation pressure.
    score += (open_bins_count as f64) * 1.5;

    // Semi-fit lookahead.
    if post_residual > 0 && next_item_size as f64 <= post && next_item_size as f64 > post * 0.6 && post_residual <= 25 {
        score -= 13.0 * (1.0 - post_residual as f64 / 25.0);
    }
    if post_residual > 0 && post_residual < item_size && next_item_size as f64 > post && open_bins_count > 3 { score += 8.0; }
    if post_residual > 0 && next_item_size as f64 > post && post_residual < (next_item_size / 2).max(1) {
        score += 6.0 * (1.0 - post_residual as f64 / (next_item_size / 2).max(1) as f64);
    }
    if post_residual > 0 && post_residual % 10 == 0 && next_item_size as f64 <= post { score -= 5.0; }
    let dead = post / cap;
    if post_residual > 0 && next_item_size as f64 > post && dead > 0.35 && post_residual as f64 > mean_residual * 1.5 && fitting_bins_count > 3 {
        score += 10.0 * (dead - 0.35);
    }
    if post_residual > 0 && next_item_size as f64 <= post && (post - next_item_size as f64) <= 2.0 && dead > 0.4 { score -= 9.0; }
    if post_residual > 0 && next_item_size as f64 <= post {
        let gap = post - next_item_size as f64;
        if gap <= 12.0 && gap <= mean_residual * 1.2 { score -= 7.0 * (1.0 - gap / 12.0); }
    }
    if post_residual > 0 && next_item_size > post_residual && post_residual >= (next_item_size * 3 / 4) && post_residual < next_item_size {
        score += 5.0 * (post_residual as f64 - next_item_size as f64 * 0.75) / (next_item_size as f64 * 0.25).max(1.0);
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score += 120.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 100.0 * progress;
        score += 10.0 * (open_bins_count as f64);
        if fitting_bins_count > 1 {
            score += 100.0 * (fitting_bins_count as f64 - 1.0);
        }
        score += 0.5 * mean_residual;
        if item_size < (bin_capacity / 2) {
            score += 12.0;
            if next_item_size > 0 && (next_item_size as f64) <= post {
                score += 20.0;
            }
        }
        // Huge items deserve fresh bins when residuals are small.
        if item > 0.8 * cap && mean_residual < item * 0.9 {
            score -= 200.0;
        }
        // Medium-large items late in stream when no open bin fits the next item.
        if item > 0.5 * cap && next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 120.0;
        }
        // Fresh bin for medium items when all open residuals are nearly dead.
        if item <= 0.5 * cap && open_bins_count > 2 && mean_residual < item * 0.55 && fitting_bins_count > 0 {
            score -= 45.0;
        }
        // NEW: fresh bin early when next item also large and current item huge.
        if item > 0.7 * cap && next_item_size > (bin_capacity / 3) && progress > 0.3 {
            score -= 60.0;
        }
    } else if open_bins_count > 3 && residual > 2.0 * mean_residual {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress in the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (small post_residual) with a non-linear emphasis
    score = score * (1.0 + 0.05 * (1.0 - progress));

    // Reward placements that leave a residual matching the next item's size
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        score += 0.6 * gap;
        // Perfect lookahead match bonus
        if post_residual as u32 == next_item_size {
            score -= 25.0;
        }
    }

    // Penalize creating dead space that is too small for the minimum item (unusable)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward filling bins nearly completely
    let fill_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * fill_ratio * fill_ratio;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize spreading across many open bins; encourage consolidation
    score += 0.15 * open_bins_count as f64 * (1.0 - fill_ratio);

    // Penalize bins whose residual deviates far from the mean residual (fragmentation)
    score += 0.1 * (bin_residual as f64 - mean_residual).abs();

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized, but less when no good fits exist
        let mut new_bin_score = 60.0 + post_residual as f64;
        // If item is small relative to capacity, new bin wastes more space
        new_bin_score += 0.5 * (bin_capacity as f64 - item_size as f64);
        // Early in stream, new bins are cheaper; late, prefer consolidation
        new_bin_score *= (0.5 + progress);
        // If many bins already fit the item, opening a new bin is bad
        if fitting_bins_count > 0 {
            new_bin_score += 25.0 * fitting_bins_count as f64;
        }
        // If next item is large and would need a fresh bin anyway, opening now is fine
        if next_item_size > 0 && next_item_size >= item_size {
            new_bin_score -= 15.0;
        }
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post * post / cap;

    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0 / post;
    } else if post_residual < 12 {
        score += 80.0 + (12 - post_residual) as f64 * 5.0;
    } else {
        score -= 12.0 * (post / cap);
        if post_residual >= 40 { score -= 8.0; }
        if post_residual < 30 { score += 6.0 * (30 - post_residual) as f64 / 18.0; }
    }

    // Lookahead: strongly reward exact next-item fit, mildly reward close fits.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let gap = post - nxt;
            score -= 55.0 * (1.0 - gap / cap);
            if gap == 0.0 { score -= 70.0; }
            if gap >= 1.0 && gap <= 4.0 { score -= 12.0; }
            if gap as u32 == mean_residual as u32 { score -= 8.0; }
            if post_residual <= 25 && nxt >= post * 0.6 {
                score -= 13.0 * (1.0 - post_residual as f64 / 25.0);
            }
        } else {
            let miss = nxt - post;
            if post_residual < 10 { score += 60.0; }
            if miss <= 2.0 && fitting_bins_count > 1 { score += 15.0; }
            if miss > 20.0 && post_residual > 0 && post_residual < 20 { score += 12.0; }
            if post_residual > 0 && post_residual < (next_item_size / 2).max(1) {
                score += 6.0 * (1.0 - post_residual as f64 / (next_item_size / 2).max(1) as f64);
            }
        }
    } else {
        score += post * 2.0;
    }

    // Mean-residual comparison: prefer tighter bins.
    let mean_diff = (bin_residual as f64) - mean_residual;
    score += 0.3 * mean_diff;

    // Last-chance fitting bin: avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }
    if fitting_bins_count > 4 && bin_residual != bin_capacity && post_residual > 30 {
        score += 3.0;
    }

    // Consolidation pressure.
    score += 0.05 * open_bins_count as f64;

    // New-bin candidate handling with progress-scaled bonus.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_bonus = 40.0 * (1.0 - progress);
    if bin_residual == bin_capacity {
        score -= new_bin_bonus;
        if next_item_size > 0 && post_residual >= next_item_size { score -= 8.0; }
        if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
            score += 14.0;
        }
    }

    // Waste-guard: penalize residuals too small to ever be useful.
    if post_residual > 0 && post_residual < 8 && next_item_size > post_residual {
        score += 26.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // smooth non-linear coupling of post_residual with stream progress
    score += 30.0 * norm_pr * norm_pr * (0.5 + progress);
    score -= 12.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;
    // lookahead: reward residual that fits next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            score -= 8.0 * (1.0 - ns / cap) * (0.5 + progress);
        } else {
            score += 6.0 * (ns - pr) / cap;
        }
    }
    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }
    // penalize opening new bins when open bins fit well
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 5.0 + 10.0 * (1.0 - progress);
    }
    // tie-break toward bins near mean residual
    score += 0.05 * (pr - mean_residual).abs();
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity-fraction band does it fall in?
    let frac = post_residual as f64 / bin_capacity as f64;
    // Class index via capacity/8 octants (harmonic division of the bin)
    let class = post_residual / (bin_capacity / 8).max(1);

    // Reward residuals that are "usable" harmonic slots (>= ~20% of bin)
    if post_residual >= bin_capacity / 5 {
        score -= 12.0 * frac;
    } else if post_residual > 0 {
        // dead space penalty grows sharply for tiny unusable slivers
        score += 15.0 * (1.0 - frac * 5.0);
    }

    // Perfect-ish fits: post_residual divisible into small harmonic units
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Lookahead coupling: can next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0; // chain fit is excellent
            // harmonic bonus if next item exactly matches a residual class
            if post_residual % next_item_size.max(1) == 0 {
                score -= 8.0;
            }
        } else if next_item_size <= bin_residual && post_residual < next_item_size {
            // we consumed the slot the next item could have used
            score += 6.0;
        }
    } else {
        // last item: just minimize leftover
        score -= 5.0 * frac;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // competition: prefer bins with tighter fits
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate handling: opening a bin is only good when no open bin
    // offers a decent fit or the stream is young
    let is_new_bin = bin_residual == bin_capacity && item_size > 0;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // penalize new bins mildly; worse late in stream when consolidation matters
        score += 10.0 + 15.0 * progress;
        // but if mean residual across open bins is tiny, a fresh bin is attractive
        if mean_residual < item_size as f64 {
            score -= 14.0;
        }
        if fitting_bins_count == 0 {
            score -= 25.0; // nothing else fits
        }
    }

    // Prefer filling bins that are already relatively full (small residual)
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Slight preference to keep number of open bins low late in the stream
    score += 0.02 * open_bins_count as f64 * (0.5 + step_index as f64 / total_items.max(1) as f64);

    score
}

