pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // future item (items are 1..=100, but small gaps < 10 are near-useless)
    // are heavily penalized; large leftovers are mild.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // unusable sliver
        } else if post_residual < 25 {
            score += 25.0; // hard-to-fill gap
        } else if post_residual < 50 {
            score += 8.0;
        } else {
            score -= 5.0; // roomy leftover is fine
        }
    } else {
        // Perfect fill: strong reward
        score -= 40.0;
    }

    // Reward tight fits: fraction of bin consumed by this item.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * tightness;

    // Open-bin pressure: with many bins open, prefer reusing existing bins
    // rather than spreading; makes opening new bins costly implicitly.
    score += (open_bins_count as f64).sqrt() * 1.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when the item fits poorly everywhere.
    // An empty bin has residual == capacity => post_residual == capacity - item,
    // which is large; add a fixed surcharge so reuse is preferred unless
    // dead-space penalty elsewhere dominates.
    if bin_residual == bin_capacity {
        score += 35.0;
        // But if no open bin fits well (mean residual small), new bin is fine.
        if mean_residual < item_size as f64 * 0.5 {
            score -= 25.0;
        }
    }

    // Lookahead: if the next item exactly matches the post residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; slight penalty for blocking.
        score += 3.0;
    }

    // Late in stream, be greedier about tight packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * tightness;

    // Align with mean residual: bins below mean residual are already tight;
    // prefer to fill those further.
    if (bin_residual as f64) < mean_residual {
