        score -= 330.0 / post;
    } else if post_residual < 12 {
        score += 90.0 + (12 - post_residual) as f64 * 6.0;
    } else {
        score -= 15.0 * (post / cap);
        if post_residual >= 40 { score -= 9.0; }
        if post_residual < 30 { score += 7.5 * (30 - post_residual) as f64 / 18.0; }
    }

    if post > 0.0 && post < 0.25 * cap {
        score += 30.0 * (1.0 - post / (0.25 * cap));
    }

    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let chain_tight = 1.0 - (post - nxt) / cap;
            score -= 52.0 * chain_tight;
            if post == nxt { score -= 68.0; }
            if post >= nxt + mean_residual { score -= 10.0; }
            if (post - nxt) <= mean_residual * 0.5 { score -= 8.0; }
            let gap = post - nxt;
            if gap >= 1.0 && gap <= 4.0 { score -= 12.0; }
            if gap < 6.0 { score -= 18.0; }
            if gap as u32 == mean_residual as u32 { score -= 9.0; }
            // dead-space ratio refinement: prefer leaving gaps the next item nearly fills
            if gap > 0.0 && gap / nxt > 0.5 { score += 5.0 * (gap / nxt - 0.5); }
        } else if post + 10.0 >= nxt {
            score += 6.0;
        } else {
            score += 0.06 * (nxt - post);
        }
        if nxt > post && post_residual < 10 { score += 60.0; }
        if nxt > post && (nxt - post) as u32 <= 2 && fitting_bins_count > 1 { score += 15.0; }
        if nxt > post && (nxt - post) as u32 > 20 && post_residual > 0 && post_residual < 20 { score += 12.0; }
    } else {
        score += post * 2.2;
    }

    if post_residual > 0 && post_residual < 8 && next_item_size > post_residual { score += 26.0; }
    if post_residual > 0 && post_residual < 16 && next_item_size > post_residual && (mean_residual as u32) > post_residual {
        score += 9.0 * (16 - post_residual) as f64 / 8.0;
    }

    let mean_diff = (bin_residual as f64) - mean_residual;
    score += 0.3 * mean_diff;

    if fitting_bins_count == 1 && bin_residual != bin_capacity { score -= 120.0; }
    if fitting_bins_count > 4 && bin_residual != bin_capacity && post_residual > 30 { score += 3.0; }

    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_bonus = 40.0 * (1.0 - progress);
    if bin_residual == bin_capacity {
        score -= new_bin_bonus;
        if next_item_size > 0 && post_residual >= next_item_size { score -= 8.0; }
        if fitting_bins_count > 2 && post_residual >= next_item_size { score += 14.0; }
        // open a fresh bin only when it leaves a cleaner residual than the best open fit would
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 * 1.4 { score -= 4.0; }
    }

    let dead = post / cap;
    if post_residual > 0 && next_item_size as f64 <= post && next_item_size as f64 > post * 0.6 && post_residual <= 25 {
        score -= 13.0 * (1.0 - post_residual as f64 / 25.0);
    }
    if post_residual > 0 && post_residual < item_size && next_item_size as f64 > post && open_bins_count > 3 { score += 8.0; }
    if post_residual > 0 && next_item_size as f64 > post && post_residual < (next_item_size / 2).max(1) {
        score += 6.0 * (1.0 - post_residual as f64 / (next_item_size / 2).max(1) as f64);
    }
