pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: prefer tight fits (low post_residual), with non-linear penalty on awkward leftovers.
    let mut score = post;

    // Dead-space penalty: residuals that are small-but-unusable are the worst.
    // A leftover that can't hold even the minimum item (1) is fine (perfect fit),
    // but leftovers in the "awkward zone" (1..=12) waste space.
    if post > 0.0 && post < 13.0 {
        score += (13.0 - post) * 2.5;
    }

    // Reward near-perfect packing strongly.
    if post == 0.0 {
        score -= 40.0;
    } else if post <= 3.0 {
        score -= 15.0;
    }

    // Fit ratio coupling: how much of the bin the item consumes.
    let fill_ratio = item / cap;
    score -= fill_ratio * 12.0;

    // Lookahead: if next item fits into the post residual, reward this placement;
    // if next item would be blocked by a barely-too-small residual, penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 8.0 + 0.1 * nxt;
        } else if post > 0.0 && nxt > post && nxt - post <= 10.0 {
            score += 6.0 + (nxt - post);
        }
    }

    // Global state: mean residual across open bins. If this bin's residual is far
    // below the mean, it's a "junk bin" — placing here preserves fatter bins.
    let residual_gap = mean_residual - residual;
    score += 0.15 * residual_gap;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is expensive early and when
    // other bins fit, but attractive when it enables pairing with the next item.
    if bin_residual == bin_capacity {
        let mut nb = 55.0;
        // Cheaper to open bins as stream progresses (commitment already sunk).
        nb -= 30.0 * progress;
        // If many bins are open with lots of slack, discourage proliferation.
        nb += 0.5 * open_bins_count as f64;
        // If the next item is large and no current bin pairing looks likely,
        // a fresh bin gives a clean slate — but we can't know fits, so use mean residual.
        if next_item_size as f64 >= mean_residual {
            nb -= 12.0;
        }
        // If this is the only chance and nothing fits elsewhere, new bin is fine.
        if fitting_bins_count == 0 {
            nb -= 60.0;
        }
        score += nb;
    }

    // Time-horizon modulation: late in the stream, be more conservative —
    // reward compacting into existing bins rather than spreading.
    score += 5.0 * progress * (post / cap);

    // Mild exploration term: slight preference for bins whose residual differs
    // from the mean (diversity of residual shapes helps future fits).
    score -= 0.05 * (residual_gap * residual_gap).sqrt() * (1.0 - progress);

    score
}

