pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let norm_pr = pr / capacity;

    // Base: prefer tight fits (small post_residual), with polynomial shaping.
    let mut score = norm_pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth coupling with stream progress: late in the stream, dead space matters more.
    score *= 1.0 + 0.5 * progress * norm_pr;

    // Reward bins whose post-residual is far from the mean residual (diversity of gaps).
    let gap = pr - mean_residual;
    score += 0.3 * (gap / capacity) * (gap / capacity);

    // Last-chance bonus: only one bin fits the item.
    if fitting_bins_count == 1 {
        score -= 2.5;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let fill = nx / pr.max(1.0);
            score -= 1.5 * fill * fill;
        } else {
            // Penalize post-residuals that cannot host the next item.
            score += 0.5 * (nx - pr) / capacity;
        }
    }

    // Mild penalty for spreading across too many open bins early.
    score += 0.02 * (open_bins_count as f64) * progress;

    score
}

