    let mut score = post_residual as f64;

    // Harmonic class of the item: which capacity fraction band it occupies
    let item_class = (item_size * 5) / bin_capacity; // 0..4 harmonic class
    let post_class = (post_residual * 5) / bin_capacity;

    // Reward tight fits: small post_residual gets strong discount
    if post_residual == 0 {
