            score += 60.0; // sliver: nearly unusable
        } else if post_residual <= 30 {
            score -= 15.0; // usable small-item slot
        } else if post_residual <= 50 {
            score -= 5.0;
        }
    }

    // Harmonic pairing: does next_item_size fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0; // perfect harmonic pair
        } else if next_item_size <= post_residual {
            let pair_waste = post_residual - next_item_size;
            score -= 40.0 * (1.0 - pair_waste as f64 / cap);
