    }

    // Prefer filling bins as stream progresses (close-out pressure)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0 * (bin_residual as f64 / cap);

    // Mild preference for bins with below-mean residual (consolidate emptier space)
    score += 0.1 * (mean_residual - bin_residual as f64);

    // Integer-division threshold: residual class granularity
    score += (post_class as f64) * 2.0 - (item_class as f64);

    score
}

