    let post = post_residual as f64;
    let mut score = post * post / cap;

    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 330.0 / post;
    } else if post_residual < 12 {
        score += 90.0 + (12 - post_residual) as f64 * 6.0;
    } else {
        score -= 15.0 * (post / cap);
        if post_residual >= 40 {
            score -= 9.0;
        }
        if post_residual < 30 {
            score += 7.5 * (30 - post_residual) as f64 / 18.0;
        }
    }

    let dead = post / cap;
    if dead > 0.45 && post_residual > 0 {
        score += 14.0 * (dead - 0.45);
    }

    // Lookahead on next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let gap = post - nxt;
            let chain_tight = 1.0 - gap / cap;
            score -= 52.0 * chain_tight;
            if gap == 0.0 {
                score -= 68.0;
            }
            if gap >= 1.0 && gap <= 4.0 {
                score -= 12.0;
            }
            if gap < 6.0 {
                score -= 18.0;
            }
            if gap <= 12.0 && gap <= mean_residual * 1.2 {
                score -= 7.0 * (1.0 - gap / 12.0);
            }
            if post_residual <= mean_residual as u32 {
                score -= 6.0;
            }
        } else {
            if post + 10.0 >= nxt {
                score += 6.0;
            } else {
                score += 0.06 * (nxt - post);
            }
            if post_residual < 10 {
                score += 60.0;
            }
            if (nxt - post) as u32 <= 2 && fitting_bins_count > 1 {
                score += 15.0;
            }
            if (nxt - post) as u32 > 20 && post_residual > 0 && post_residual < 20 {
                score += 12.0;
            }
        }
    } else {
        score += post * 2.2;
    }

