    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_bonus = 40.0 * (1.0 - progress);
    if bin_residual == bin_capacity {
        score -= new_bin_bonus;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
        if fitting_bins_count > 2 && post_residual >= next_item_size {
            score += 14.0;
        }
        if progress > 0.5 {
            score += 18.0 * (progress - 0.5);
        }
        if dead > 0.5 && open_bins_count > 2 {
            score += 20.0 * (dead - 0.5);
        }
    }

    // Reward near-perfect chain fits in small residuals.
    if post_residual > 0 && next_item_size as f64 <= post && next_item_size as f64 > post * 0.6 && post_residual <= 25 {
        score -= 13.0 * (1.0 - post_residual as f64 / 25.0);
    }

