pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post * post / cap; // quadratic leftover pressure

    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 330.0 / post; // near-perfect fill: strong reward
    } else if post_residual < 12 {
        score += 90.0 + (12 - post_residual) as f64 * 6.0; // dead sliver
    } else {
        score -= 15.0 * (post / cap);
        if post_residual >= 40 { score -= 9.0; }
        if post_residual < 30 { score += 7.5 * (30 - post_residual) as f64 / 18.0; }
    }

    // dead-space band under 25% of capacity
    if post > 0.0 && post < 0.25 * cap {
        score += 30.0 * (1.0 - post / (0.25 * cap));
    }
    let dead = post / cap;
    if dead > 0.45 && post_residual > 0 {
        score += 14.0 * (dead - 0.45);
    }

    // Lookahead: reward if next item chains into the leftover
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let chain_tight = 1.0 - (post - nxt) / cap;
            score -= 52.0 * chain_tight;
            if post == nxt { score -= 68.0; } // exact chain fill
            if post >= nxt + mean_residual { score -= 10.0; }
            let gap = post - nxt;
            if gap <= mean_residual * 0.5 { score -= 8.0; }
            if gap >= 1.0 && gap <= 4.0 { score -= 12.0; } // near-perfect chain
            if gap < 6.0 { score -= 18.0; }
            if gap as u32 == mean_residual as u32 { score -= 9.0; }
            if gap <= 1.0 { score -= 6.0; }
            if gap <= 2.0 && dead > 0.5 { score -= 6.0; }
            // harmonic chain: leftover divisible by next item
            if post_residual % next_item_size == 0 { score -= 14.0; }
            // mid-range chain bonus scaled by dead-space ratio
            if gap <= 12.0 && gap <= mean_residual * 1.2 {
                score -= 7.0 * (1.0 - gap / 12.0);
            }
            // near-exact chain with few alternatives
            if gap <= 3.0 && fitting_bins_count <= 2 { score -= 10.0; }
            if post_residual <= mean_residual as u32 { score -= 6.0; }
        } else {
            // next item won't fit here
            if post_residual > 0 && post_residual < 10 { score += 26.0; }
            if nxt - post <= 2.0 && fitting_bins_count > 1 { score += 15.0; }
            if nxt - post > 20.0 && post_residual > 0 && post_residual < 20 { score += 12.0; }
            // near-miss penalty scaled by closeness
            if post_residual > 0 && nxt - post <= 10.0 {
                score += 4.0 * (1.0 - (nxt - post) / 10.0);
            }
            // residual just under next item (wasted near-fit)
            if post_residual >= (next_item_size * 3 / 4) && post_residual < next_item_size {
                score += 5.0 * (post_residual as f64 - next_item_size as f64 * 0.75)
                    / (next_item_size as f64 * 0.25).max(1.0);
            }
            // deep dead space with few fitting bins: strong penalty
            if dead > 0.5 && fitting_bins_count <= 2 { score += 14.0 * (dead - 0.5); }
            // near-miss within half mean residual
            if post_residual > 0 && (nxt - post) < 0.5 * mean_residual.max(1.0) { score += 4.0; }
            // near-miss within a few units: penalize wasting this bin
            if post_residual > 0 && (nxt - post) as u32 <= 4 && fitting_bins_count > 2 {
                score += 11.0 * (dead - 0.3).max(0.0);
            }
        }
    } else {
        score += post * 2.2;
    }

