        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - slack / 50.0).max(0.0);
    }

    // Next item does NOT fit in the leftover: penalize dead space
    if next_item_size > 0 && next_item_size > post_residual {
        score += 0.35 * (next_item_size - post_residual) as f64;
    }

    // Penalize leaving unusable tiny dead space (no next item to fill it)
    if next_item_size == 0 {
        score += 0.5 * post_residual as f64;
    } else if post_residual < 10 && post_residual > 0 {
        score += 15.0; // dead space too small for any item (min size 1..100 case: small waste)
    }

    // Relative-to-mean coupling: prefer bins that stay near the mean residual,
    // avoid creating extreme outliers
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are tight
    if bin_residual == bin_capacity {
        let open_pressure = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 1.0 };
        // If open bins still have lots of room (high mean residual), discourage new bin
        score += 30.0 + 60.0 * open_pressure;
        // But if this item is huge and next item is large too, a fresh bin is fine
        if item_size >= 70 && next_item_size >= 50 {
            score -= 70.0;
        }
    }

    // Mild stream-progression term: later in the stream, consolidation matters more
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: square the post-residual so small leftovers dominate.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Lookahead: if the next item fits exactly (or well) in the post-residual, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 100.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot follow here; penalize bins whose residual is too small to matter.
            let dead = post_residual as f64;
            if dead < 10.0 {
                score += 50.0; // tiny dead space is fine but slightly discouraged
            } else if dead < next_item_size as f64 {
                score += 0.3 * dead; // medium dead space unusable by next item
            }
        }
    }

    // Last-chance bin: strongly prefer using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: neutral baseline; open a new bin only when
    // no open bin offers a decent fit (post_residual small relative to capacity).
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin: proportional to wasted capacity potential.
        score = bin_capacity as f64 * 0.55 + open_bins_count as f64 * 2.0;
        // Late in the stream, slightly prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
    }

    // Prefer bins whose residual is close to the item (minimize fragmentation).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.2 * gap;

    // Global state: if mean residual across open bins is high, we have slack;
    // be pickier (penalize loose fits) to encourage consolidation elsewhere.
    score += 0.1 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
