    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_ratio = item_size as f64 / cap;

    // Non-linear waste penalty: quadratic in post_residual, scaled by stream progress
    let waste = (post / cap).powi(2) * cap * (0.5 + 0.9 * progress);
    score += waste;

    // Reward tight fits (small post_residual relative to item size)
    let tightness = (1.0 - post / cap).powi(3);
    score -= 12.0 * tightness * fit_ratio;

    // Penalize leaving residuals that no typical item can use (dead space)
    let dead_zone = (post / cap - 0.2).powi(2);
    score += 8.0 * dead_zone * (1.0 - fit_ratio);

    // Lookahead coupling: favor bins whose post_residual pairs well with next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        score += 0.35 * (gap / cap) * cap * (1.0 - progress);
        if post >= nxt {
            score -= 0.25 * nxt * (1.0 - progress);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0 + 8.0 * progress;
    }

    // New-bin candidate: penalize opening a bin unless current fit is poor
    if bin_residual == bin_capacity {
        let poor_fit = (fitting_bins_count == 0) as i32 as f64;
        let bad_post = (post_residual > bin_capacity / 2) as i32 as f64;
        score += 18.0 - 14.0 * poor_fit - 6.0 * bad_post * (1.0 - progress);
        score += 3.0 * (open_bins_count as f64).sqrt();
