        // many fitting bins means this choice matters less; slight penalty for sloppy fits
        if fitting_bins_count > 4 && post_residual > 30 {
            score += 3.0;
        }
        // penalize leaving dead space when next item is much larger than residual
        if post_residual > 0 && next_item_size as f64 > post && post_residual as f64 > mean_residual * 1.5 && fitting_bins_count > 3 {
            score += 8.0;
        }
        // near-miss within a couple units of next item with several options
        if post_residual > 0 && next_item_size as f64 > post && (next_item_size as f64 - post) <= 4.0 && fitting_bins_count > 2 {
            let dead = post / cap;
            if dead > 0.3 {
                score += 11.0 * (dead - 0.3);
            }
        }
        // NEW: reward placing into bins whose post-residual stays above mean residual (keeps bins reusable)
        if post_residual > 0 && post >= mean_residual && fitting_bins_count > 1 {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Reward fitting the next item too (chain fits).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }

    // Open-bin pressure: more open bins -> prefer reusing existing bins,
    // penalize opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when existing bins are crowded.
        score += 25.0 + 15.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // new bin can host the next big item too
        }
    } else {
        // Reuse bonus, stronger late in the stream.
        score -= 8.0 + 10.0 * progress;
        // Last-chance bin: strongly favor using it before it dies.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // Slight preference for bins below mean residual (balances loads).
    score += 0.05 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
