    }

    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let chain_tight = 1.0 - (post - nxt) / cap;
            score -= 52.0 * chain_tight;
            if post_residual == next_item_size { score -= 68.0; }
            if post_residual % next_item_size == 0 { score -= 18.0; }
            if (post_residual - next_item_size) % 10 == 0 { score -= 6.0; }
            let gap = post - nxt;
            if gap >= 1.0 && gap <= 4.0 { score -= 12.0; }
            if post >= nxt + mean_residual { score -= 10.0; }
            if gap <= mean_residual * 0.5 { score -= 8.0; }
            if gap < 6.0 { score -= 18.0; }
            if (post_residual as f64 - nxt) as u32 == mean_residual as u32 { score -= 9.0; }
            if post_residual <= 25 && nxt > post_residual as f64 * 0.6 {
                score -= 13.0 * (1.0 - post_residual as f64 / 25.0);
            }
            if gap <= 12.0 && gap <= mean_residual * 1.2 {
                score -= 7.0 * (1.0 - gap / 12.0);
            }
            if gap <= 2.0 && post > 0.4 * cap { score -= 9.0; }
            if gap <= 2.0 && dead > 0.5 { score -= 6.0; }
            if gap <= 3.0 && fitting_bins_count <= 2 { score -= 10.0; }
            if post_residual <= mean_residual as u32 { score -= 6.0; }
            if fitting_bins_count <= 2 { score -= 5.0 * (1.0 - gap / cap); }
        } else {
            if post_residual > 0 && post_residual < 10 { score += 60.0; }
            if nxt - post <= 2.0 && fitting_bins_count > 1 { score += 15.0; }
            if nxt - post > 20.0 && post_residual < 20 { score += 12.0; }
            if post_residual < next_item_size / 2 {
                score += 6.0 * (1.0 - post_residual as f64 / (next_item_size / 2).max(1) as f64);
            }
            if post_residual > 0 && post_residual < item_size && open_bins_count > 3 { score += 8.0; }
            if post_residual > 0 && nxt - post <= 10.0 {
                score += 4.0 * (1.0 - (nxt - post) / 10.0);
            }
            if dead > 0.35 && post_residual as f64 > mean_residual * 1.5 && fitting_bins_count > 3 {
                score += 10.0 * (dead - 0.35);
            }
            if post_residual >= (next_item_size * 3 / 4) && post_residual < next_item_size {
                score += 5.0 * (post_residual as f64 - next_item_size as f64 * 0.75) / (next_item_size as f64 * 0.25).max(1.0);
            }
            if dead > 0.5 && fitting_bins_count <= 2 {
                score += 14.0 * (dead - 0.5);
            }
            if post_residual > 0 && (nxt - post) < 0.5 * mean_residual.max(1.0) {
                score += 4.0;
            }
            if dead > 0.55 && open_bins_count > 4 {
                score += 16.0 * (dead - 0.55);
            }
        }
    } else {
        score += post * 2.2;
    }

    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 40.0 * (1.0 - progress);
        if mean_residual < item_size as f64 && open_bins_count > 2 {
            score += 10.0;
        }
        if open_bins_count > 5 && mean_residual > 0.4 * cap {
            score += 12.0;
        }
        if progress > 0.5 {
            score += 18.0 * (progress - 0.5);
        }
        if open_bins_count > 3 && progress > 0.6 {
            score += 8.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
        if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
            score += 14.0;
        }
        if next_item_size > 0 && next_item_size as f64 <= bin_residual as f64 && open_bins_count > 1 {
            score += 6.0;
        }
        if dead > 0.5 && open_bins_count > 2 {
            score += 20.0 * (dead - 0.5);
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 12.0;
        }
        // new bin that nearly exactly fits next item is attractive
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 4 {
            score -= 20.0;
        }
    } else {
        let tightness = 1.0 - (bin_residual as f64 / cap);
        score -= 10.0 * tightness;
        if fitting_bins_count > 4 && post_residual > 30 {
            score += 3.0;
        }
        if post_residual > 0 && next_item_size as f64 > post && post_residual as f64 > mean_residual * 1.5 && fitting_bins_count > 3 {
            score += 8.0;
        }
        if post_residual > 0 && next_item_size as f64 > post && (next_item_size as f64 - post) <= 4.0 && fitting_bins_count > 2 {
            if dead > 0.3 {
                score += 11.0 * (dead - 0.3);
            }
        }
        if post_residual > 0 && next_item_size as f64 <= post && (post - next_item_size as f64) <= 2.0 && dead > 0.4 {
            score -= 9.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space into capacity fractions
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1
    // Integer-division thresholds on post_residual (harmonic bands)
    let band = (post_residual / 25) as f64; // 0..4 harmonic class

    // Reward near-perfect fits strongly (non-linear)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 400.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    }

    // Penalize dead space that cannot fit typical small items (harmonic class >= 2)
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 350.0;
        } else if next_item_size < post_residual {
            score -= 60.0 - band * 5.0;
        } else {
            score += 30.0; // next item won't fit here; residual becomes dead space
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate handling: only open a new bin when current fits are poor
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so new bins are opened only when justified
        score += 120.0;
        // If no existing bin fits (we are the only candidate), open freely
        if fitting_bins_count <= 1 {
            score -= 400.0;
        }
        // If next item is large and mean residual is small, new bin is attractive
        if next_item_size as f64 > 0.6 * cap && mean_residual < 0.25 * cap {
            score -= 100.0;
        }
    }

    // Prefer filling bins with high residual when many bins are open (bin consolidation)
    score -= (bin_residual as f64 / cap) * 20.0;

    // Progress-based mild adaptation: later in stream, tighten fits more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (100.0 - frac * 100.0).min(50.0);

    // Mean-residual coupling: placing into bins far below mean residual is wasteful
    score += ((mean_residual - pr) * 0.3).max(0.0);

    // Harmonic modulo bonus: post_residual divisible classes
    if post_residual % 50 == 0 && post_residual > 0 {
        score -= 40.0;
    }
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // hold another item (min item size 1, but practically small gaps)
    // are wasted space. Penalize "unusable" small gaps quadratically.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 12.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tightness reward: fill bins as fully as possible.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill * 25.0;

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }
    // Many fitting bins: mild penalty to encourage spreading decisions carefully.
    if fitting_bins_count > 1 {
        score += 4.0 * (fitting_bins_count as f64 - 1.0).min(8.0);
    }

    // Lookahead: reward leaving room for the next item, penalize if
    // post_residual cannot hold next_item_size while bin_residual could.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            score += 18.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over opening new ones.
    score += 2.0 * open_bins_count as f64;

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is a poor candidate (it's already tight); slight penalty.
    let diff = mean_residual - bin_residual as f64;
    score += 0.15 * diff.max(-30.0).min(30.0);

    // New-bin candidate: only attractive when existing fits are bad
    // (handled above via bonuses) — otherwise penalize opening new bins,
    // scaled by stream progression (late in stream, keep bins tight).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 + 25.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward for near-perfect pairing of the lookahead item.
        score -= 60.0 * (1.0 - diff / (bin_capacity as f64)).powi(6);

        // Penalize leaving residual that neither fits next item nor is tight.
        if post_residual as i64 - next_item_size as i64 > 0 {
            score += 0.5 * diff;
        }

        // If next item could fit exactly into this residual, big bonus.
        if next_item_size <= post_residual {
            score -= 10.0;
        }
    }

    // Tight fits are good: small post_residual preferred.
    score += 0.3 * (post_residual as f64 / bin_capacity as f64).powi(2) * 20.0;

    // Relative to mean residual: prefer bins whose residual is above average
    // (consume the "loosest" space first, preserving tight bins).
    score -= 0.4 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: prefer opening a fresh bin when the fit here
    // would leave a large awkward residual and no lookahead pairing exists.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Neutral baseline; penalize opening new bins when many are open and
        // residual is still usable, but allow it when current fit is terrible.
        score += 8.0;
        if open_bins_count as f64 > 0.0 {
            let usable = mean_residual / bin_capacity as f64;
            score += 30.0 * usable;
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 5.0; // fresh bin can still host the next item
        }
    }

    // Late in the stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize large post_residual quadratically.
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // Next item fits but leaves slack: mild reward scaled by how well it packs.
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item cannot use the remaining space: penalize proportionally to dead space.
            let dead = post_residual.min(next_item_size.saturating_sub(1)) as f64;
            score += 0.25 * dead;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer bins with low residual relative to mean (compact bins first).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Time horizon: late in stream, be more conservative (favor tighter packing,
    // avoid opening bins unnecessarily).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.4 * progress;

    // New-bin candidate: only attractive when current bins are crowded or fit is bad.
    if bin_residual == bin_capacity {
        let crowding = if open_bins_count == 0 { 1.0 } else { 1.0 - mean_residual / bin_capacity as f64 };
        let bad_fit = (post_residual as f64 / bin_capacity as f64);
        let base = 55.0 - 45.0 * crowding;
        // Penalize opening new bin, less so when item is large and would leave small post_residual.
        score = base + 40.0 * bad_fit - 0.2 * item_size as f64;
        if fitting_bins_count == 1 {
            // Don't open a new bin when an existing one is a last chance.
            score += 25.0;
        }
    }

    // Slight penalty for spreading across many bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap; // normalized post residual

    // Base: minimize wasted space, with non-linear (quadratic) waste penalty
    let mut score = pr + 40.0 * norm_pr * norm_pr * cap;

    // Smooth stream-progress coupling: later in the stream, waste matters more
    let progress_gain = 1.0 + 2.0 * progress * progress;
    score *= progress_gain;

    // Interaction: post_residual vs mean residual — prefer bins whose leftover
    // is below the mean (concentrating waste in few bins)
    let mean_term = (mean_residual - pr) / cap;
    score -= 15.0 * mean_term * mean_term * cap.signum() * (mean_term.signum() + 1.0);

    // Lookahead coupling: smooth reward if the next item could fit the post residual
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs() / cap;
        score += 10.0 * gap * gap * cap;
        // smooth bonus when next item fits exactly-ish
        score -= 12.0 * (1.0 - (gap * 8.0).min(1.0)).powi(2);
    }

    // Last-chance bin: strongly favor using it (smooth, not piecewise)
    let last_chance = ((fitting_bins_count as f64) - 1.0).max(0.0);
    score -= 25.0 / (1.0 + last_chance * last_chance);

    // New-bin candidate: penalize opening a new bin smoothly, less so early in stream
    let is_new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    score += is_new_bin * (30.0 + 40.0 * progress) * (1.0 + (open_bins_count as f64).powf(0.5) * 0.1);

    // Mild penalty for leaving very large residuals unusable by typical items
    score += 8.0 * (norm_pr - 0.2).max(0.0).powi(2) * cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: minimal post_residual is good.
    score -= 2.5 * (1.0 - post_residual as f64 / bin_capacity as f64) * (bin_capacity as f64);

    // Harmonic class of post_residual: residuals divisible into useful chunks
    // (multiples of 10) are more reusable than odd dead space.
    let class = post_residual % 10;
    if class != 0 {
        score += class as f64 * 1.5; // penalize non-harmonic dead space
    }

    // Big bonus when post_residual is zero (perfect packing).
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        score -= 15.0 * (1.0 - gap as f64 / bin_capacity as f64);
        if gap == 0 {
            score -= 25.0;
        }
    }
    // If next item cannot fit in this bin anyway, mild penalty for wasting it here
    else if next_item_size > post_residual && post_residual > 0 {
        score += (next_item_size as f64 - post_residual as f64).min(30.0) * 0.4;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are bad.
    if bin_residual == bin_capacity {
        score += 30.0 + 3.0 * open_bins_count as f64;
        // But if the item is large relative to capacity and mean residual is low,
        // opening fresh may be better: reduce the penalty.
        let frac = item_size as f64 / bin_capacity as f64;
        if frac > 0.5 && mean_residual < item_size as f64 {
            score -= 45.0;
        }
    }

    // Harmonic threshold on residual via integer division: bins with residual in
    // "useful" buckets (>= 40) are worth keeping tight; small residuals are near-dead.
    if post_residual < 10 && post_residual > 0 {
        score += 8.0; // small dead space is useless
    }

    // Mild stream-progression adaptation: later in the stream, prefer consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable" band (1..=9)
    // are pure waste; penalize them super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 3.0;
    }
    // Perfect fit is golden.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving room for the lookahead item if it can still fit.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // Dead space relative to the next item's need.
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Open-bin pressure: with many bins open, prefer packing into existing
    // bins (especially the last fitting bin) rather than spreading out.
    let open_pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += open_pressure * 0.5;

    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // Last-chance bin: strongly favor using it to avoid opening a new bin.
        score -= 15.0;
    }

    // New-bin candidate: only attractive when item is large and no good fit exists.
    if bin_residual == bin_capacity {
        let tightness = (item_size as f64 / bin_capacity as f64);
        score += 10.0 - 20.0 * tightness; // cheap for big items, expensive for small ones
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0; // fresh bin accommodates lookahead
        }
    }

    // Mild stream-progression term: later in the stream, consolidate harder.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= progress * (bin_residual - item_size) as f64 * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight fit reward: prefer bins with small post_residual.
    score -= 2.0 * (cap - post_residual as f64) / cap;

    // Aggressive 2-step lookahead: if the next item fits exactly in the
    // post-residual, heavily reward this bin.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64) >= next {
            let slack_after_next = post_residual as f64 - next;
            if slack_after_next == 0.0 {
                score -= 60.0; // perfect pair match
            } else if slack_after_next <= 10.0 {
                score -= 30.0; // near-perfect pair
            } else {
                score -= 15.0 * (1.0 - slack_after_next / cap);
            }
        } else {
            // Next item cannot follow here; penalize residual that likely
            // becomes dead space (small leftovers < 10 unusable).
            if post_residual < 10 {
                score += 25.0;
            }
        }
    } else {
        // Last item: only the immediate tightness matters.
        if post_residual == 0 {
            score -= 50.0;
        }
    }

    // Relative-to-mean coupling: bins below mean residual are already
    // "well used"; filling them further is good, but keep some spread.
    let dev = mean_residual - post_residual as f64;
    score += 0.35 * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a bin should only win when the
    // item fits poorly everywhere else (large item, big post_residual need).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 12.0;
        // Large items with no good home justify a fresh bin.
        if item_size > 50 && post_residual >= item_size {
            score -= 10.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
        // Many open bins already: discourage another.
        score += 0.8 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual as fraction of capacity
    let tight = post_residual as f64 / cap;
    score += tight * 20.0;

    // Reward filling the bin deeply (item large relative to residual)
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 15.0;

    // Lookahead: if next item fits exactly-ish in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let waste = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - waste / cap);
        } else {
            // next item won't fit here: penalize leaving awkward gaps
            let gap = post_residual as f64;
            if gap > 0.0 && gap < next_item_size as f64 {
                score += gap * 0.3;
            }
        }
    } else {
        // last item: minimize leftover hard
        score += post_residual as f64 * 2.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Many open bins: prefer consolidating into emptier bins to close them
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 3 {
        let below_mean = (mean_residual - bin_residual as f64) / cap;
        score -= below_mean * 10.0 * (open_bins_count as f64).ln();
    }

    // Early stream: be less greedy, keep flexibility (penalize very small residuals less)
    let flexibility = 1.0 - progress;
    if post_residual > 0 && post_residual < 10 {
        score -= flexibility * 8.0; // tiny dead space tolerated early? no—reward closing
    }

    // New-bin candidate: only open new bin if no open bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base cost of opening a new bin
        let mut new_cost = 35.0 + post_residual as f64;
        // cheaper to open a new bin when few bins open and stream is early
        new_cost -= progress * 15.0;
        new_cost -= (open_bins_count as f64) * 2.0;
        // if this bin would be the only fitting bin, opening new bin is wasteful
        if fitting_bins_count <= 1 {
            new_cost += 60.0;
        }
        // if next item is large and current bins are full-ish, new bin attractive
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            new_cost -= 10.0;
        }
        score += new_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr_norm = pr / cap;
    let poly = pr_norm * pr_norm * (1.0 - pr_norm);
    score += 18.0 * poly * (0.5 + t);

    // Reward tight fits (small post_residual) more strongly as stream progresses
    let tight = (1.0 - pr_norm).powi(3);
    score -= 12.0 * tight * (0.3 + t);

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let unusable = ((nx - pr) / cap).max(0.0);
        score += 15.0 * unusable * unusable;
        // Reward leaving exactly enough room for the next item
        let gap = (pr - nx).abs() / cap;
        score -= 8.0 * (1.0 - gap).powi(2) * (1.0 - t);
    } else {
        score += 5.0 * pr_norm * pr_norm;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Mild penalty for spreading across many bins
    score += 0.15 * open_bins_count as f64 * pr_norm;

    // Deviation from mean residual: prefer bins near mean (balanced packing)
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins partitioned by capacity fractions.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;

    // Dead-space penalty via integer division thresholds on post_residual.
    // Residuals below 10 are unusable (min item size) -> heavy penalty.
    if post_residual < 10 {
        score += 40.0;
    } else {
        // Harmonic class: which item sizes (1..=100) can still fit.
        // Reward residuals in "useful" classes (>=25 fits half of sizes).
        if post_residual >= 50 {
            score -= 12.0;
        } else if post_residual >= 25 {
            score -= 4.0;
        }
        // Modulo-arithmetic coupling: residuals near multiples of common
        // item sizes (10, 20, 25, 50) are more reusable.
        let r = post_residual;
        if r % 10 == 0 { score -= 3.0; }
        if r % 20 == 0 { score -= 2.0; }
        if r % 25 == 0 { score -= 2.0; }
        if r % 50 == 0 { score -= 2.0; }
    }

    // Next-item fit lookahead (harmonic pairing of residuals with next item).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Exact or near-exact pairing reward.
            let gap = post_residual - next_item_size;
            if gap == 0 { score -= 25.0; }
            else if gap <= 5 { score -= 12.0; }
            else { score -= (gap as f64).min(10.0); }
        } else {
            // Next item cannot fit here: penalize mildly.
            score += 6.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Tight fit reward: item fills most of the bin.
    let tight = item_size as f64 / bin_residual as f64;
    if tight > 0.9 { score -= 10.0; }
    else if tight > 0.7 { score -= 4.0; }

    // New-bin candidate: penalize opening a new bin, unless current fit is bad
    // (large post_residual waste on a nearly-full bin or unusable remainder).
    if bin_residual == bin_capacity {
        // Base penalty keeps open bins preferred for decent fits.
        score += 8.0;
        // But if this item is huge relative to mean residual, new bin is fine.
        let mean_gap = mean_residual - item_size as f64;
        if mean_gap < 0.0 {
            score -= 10.0;
        }
        // Late in stream, prefer compacting into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 5.0 * progress;
        // Small items should not open new bins.
        if item_size <= 30 { score += 10.0; }
    }

    // Mild pressure toward filling bins with low mean residual.
    score += 0.05 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (< next item size) are unusable.
    if next_item_size > 0 && post_residual < next_item_size {
        // Dead space that cannot host the next item: penalize quadratically.
        let dead = (next_item_size - post_residual) as f64;
        score += 3.0 * dead * dead / 100.0;
        // Extra penalty if the gap is so small it's likely unusable by anything (<= 10).
        if post_residual < 10 {
            score += 25.0;
        }
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward gaps that can still host the lookahead item.
        score -= 4.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 10.0; // near-perfect fit, effectively sealed
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        score += 8.0 * (open_bins_count as f64).sqrt();
        // But if the current item fits poorly everywhere else, new bin is fine:
        // approximate poor fit by large item relative to mean residual.
        if (item_size as f64) > mean_residual + 20.0 {
            score -= 15.0;
        }
    }

    // Mild progress term: late in the stream, consolidate rather than fragment.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if !new_bin {
        score -= 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
