        if post < 0.25 * cap {
            score += 30.0 * (1.0 - post / (0.25 * cap));
        }
    }

    let dead = post / cap;
    if dead > 0.45 && post_residual > 0 {
        score += 14.0 * (dead - 0.45);
    }

    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let chain_tight = 1.0 - (post - nxt) / cap;
            score -= 52.0 * chain_tight;
            if post == nxt { score -= 68.0; }
            if post_residual % next_item_size == 0 { score -= 18.0; }
            if (post_residual - next_item_size) % 10 == 0 { score -= 6.0; }
            if post >= nxt + mean_residual { score -= 10.0; }
            if (post - nxt) <= mean_residual * 0.5 { score -= 8.0; }
