            if gap <= 12.0 && gap <= mean_residual * 1.2 {
                score -= 7.0 * (1.0 - gap / 12.0);
            }
            if gap <= 2.0 && dead > 0.4 { score -= 9.0; }
            if post_residual <= mean_residual as u32 { score -= 6.0; }
            // lookahead two-step: residual left after chaining should fit mean residual
            if gap as u32 >= 1 && (gap as u32) <= mean_residual as u32 { score -= 5.0; }
        } else {
