}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of next item into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0; // perfect chaining: this bin becomes exactly filled next step
        } else if post_residual >= next_item_size {
            // next item fits; reward tighter leftovers after that hypothetical placement
            let post2 = post_residual - next_item_size;
            score -= 8.0 + 12.0 * (1.0 - post2 as f64 / bin_capacity as f64);
        } else {
            // next item does NOT fit here -> dead space risk proportional to gap
            let gap = (next_item_size - post_residual) as f64;
            score += 4.0 + 0.35 * gap;
        }
    } else {
        // last item: prefer minimal final residual
        score += 0.0;
    }

    // Penalize large leftover space that likely becomes dead space
    let cap = bin_capacity as f64;
    if post_residual > 0 && post_residual < 10 {
        score -= 6.0; // nearly full bin is excellent
    } else if post_residual > 0 {
        // small residuals below typical item sizes are worthless
        let waste = 10.0_f64.min(post_residual as f64);
        score += 0.15 * (10.0 - waste);
    }

    // Relative-to-mean coupling: bins below mean residual are "tighter" -> prefer them
    score -= 0.25 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current fits are bad
    if bin_residual == bin_capacity {
        score += 30.0;
        // but if lookahead shows next item pairs perfectly with this item in a fresh bin, soften
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 12.0;
        }
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * (1.0 - post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
