    }

    // New-bin candidate: only attractive when the fit is poor or stream is early.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > bin_capacity as f64 * 0.55;
        if poor_fit || (next_item_size > 0 && post_residual < next_item_size) {
