    score += 40.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - progress);

    // Interaction: tight fits rewarded more early, dead space punished more late
    let fit_quality = 1.0 - (norm_pr * 2.0 - 1.0) * (norm_pr * 2.0 - 1.0);
    score -= 25.0 * fit_quality * norm_item;

