    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Prefer bins with residual near mean (balance), smooth quadratic coupling
    score += 5.0 * (pr - mean_residual) * (pr - mean_residual) / cap;

    // New-bin candidate: penalize mildly, less so late when open bins are fragmented
    if bin_residual == bin_capacity {
        score += 30.0 - 20.0 * progress;
    }

    // Slight crowding pressure: more open bins -> favor filling existing ones
    score += (open_bins_count as f64).ln() * 2.0;

    score
}

