            if gap <= 2.0 && post > 0.4 * cap { score -= 9.0; }
            if post_residual <= mean_residual as u32 { score -= 6.0; }
            if gap <= 3.0 && fitting_bins_count <= 2 { score -= 10.0; }
            if post >= nxt + mean_residual { score -= 10.0; }
        } else {
            // next item won't fit here
            if post_residual > 0 && post_residual < 8 { score += 60.0; }
            else if post_residual > 0 && post_residual < 10 { score += 26.0; }
            if nxt - post <= 2.0 && fitting_bins_count > 1 { score += 15.0; }
            if nxt - post > 20.0 && post_residual > 0 && post_residual < 20 { score += 12.0; }
            if post_residual > 0 && post_residual < next_item_size / 2 {
                score += 6.0 * (1.0 - post_residual as f64 / (next_item_size / 2).max(1) as f64);
            }
            if post_residual > 0 && post_residual < item_size && open_bins_count > 3 { score += 8.0; }
            // near-miss penalty scaled by how close next item is
            if post_residual > 0 && nxt - post <= 10.0 {
                score += 4.0 * (1.0 - (nxt - post) / 10.0);
            }
            // residual just under next item (wasted near-fit)
            if post_residual >= (next_item_size * 3 / 4) && post_residual < next_item_size {
                score += 5.0 * (post_residual as f64 - next_item_size as f64 * 0.75) / (next_item_size as f64 * 0.25).max(1.0);
            }
            // deep dead space with few fitting bins: strong penalty
            if dead > 0.5 && fitting_bins_count <= 2 {
                score += 14.0 * (dead - 0.5);
            }
            // near-miss within half mean residual
            if post_residual > 0 && (nxt - post) < 0.5 * mean_residual.max(1.0) {
                score += 4.0;
            }
            // near-miss within a few units: strongly penalize wasting this bin
            if post_residual > 0 && (nxt - post) as u32 <= 4 && fitting_bins_count > 2 {
                score += 11.0 * (post / cap - 0.3).max(0.0);
            }
            // small residual with mean residual larger: likely stranded
            if post_residual > 0 && post_residual < 16 && next_item_size > post_residual && (mean_residual as u32) > post_residual {
                score += 9.0 * (16 - post_residual) as f64 / 8.0;
            }
        }
    } else {
        score += post * 2.2;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 40.0 * (1.0 - progress); // early: bins cheap; late: consolidate
        if mean_residual < item_size as f64 && open_bins_count > 2 {
            score += 10.0;
        }
        if open_bins_count > 5 && mean_residual > 0.4 * cap {
            score += 12.0;
        }
        if progress > 0.5 {
            score += 18.0 * (progress - 0.5);
        }
        if open_bins_count > 3 && progress > 0.6 {
            score += 8.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
        if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
            score += 14.0;
        }
        if next_item_size > 0 && next_item_size as f64 <= bin_residual as f64 && open_bins_count > 1 {
            score += 6.0;
        }
        if open_bins_count > 2 && mean_residual > 0.5 * cap {
            score += 20.0 * (mean_residual / cap - 0.5);
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 12.0;
        }
        // exact chain into fresh bin with near-zero gap: cheap new bin
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 4 {
            score -= 20.0;
        }
    } else {
        // tightness pressure toward fuller bins
        let tightness = 1.0 - (bin_residual as f64 / cap);
        score -= 10.0 * tightness;
        if fitting_bins_count > 4 && post_residual > 30 {
            score += 3.0;
        }
        if post_residual > 0 && next_item_size as f64 > post && post_residual as f64 > mean_residual * 1.5 && fitting_bins_count > 3 {
            score += 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0) are ideal; small dead
    // space (1..=5) is nearly as bad as wasting a whole bin.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score += 60.0 * (6 - post_residual) as f64;
    }

    // Harmonic class via integer division: classify residual into bands of 10.
    let band = post_residual / 10;
    score += band as f64 * 2.0;

    // Reward tight fits: item occupies a large fraction of the bin.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= fill_frac * 40.0;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 30.0;
        // Harmonic bonus if next item also lands on a clean boundary.
        if post_residual % next_item_size == 0 {
            score -= 15.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize leaving awkward gaps.
        score += 10.0;
    }

    // Prefer filling bins when many are open (reduce bin count pressure).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * (10.0 + 20.0 * progress);

    // New-bin candidate: only attractive when residuals are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        if fitting_bins_count > 0 && mean_residual > 40.0 {
            score += 80.0; // keep using existing space
        } else if fragmentation < 15.0 {
            score -= 20.0;
        }
    }

    // Mean-residual alignment: bins far from the mean get slight penalty.
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
