#[inline]
fn chain_gap_fits(gap: f64) -> bool {
    gap <= 3.0
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that are too small to ever
    // hold a future item (min item size 1, but practically small gaps < 10
    // are nearly unusable) are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += (11 - post_residual as f64) * 12.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize wasting a large residual on a small item (poor utilization).
    if item_size < bin_residual / 2 {
        score += (bin_residual - item_size) as f64 * 0.4;
    }

    // Pressure from number of open bins: discourage opening extra bins when
    // many are already open; encourage consolidation.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward this placement (creates a perfect follow-up fit).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }
    // If next item cannot fit in the post residual, mild penalty since
    // this bin becomes dead for the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // New-bin candidate handling: a fresh bin should only win when existing
    // bins would leave bad dead space. Give it a moderate baseline score
    // (its post_residual = capacity - item_size, already large), plus a
    // small fixed cost so it loses to good fits but beats terrible ones.
    if bin_residual == bin_capacity {
        score += 8.0;
        // Opening a new bin is more acceptable early in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
    }

    // Slight preference for bins below mean residual (balance load).
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Primary: exact or near-exact fit is excellent.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: strongly reward bins where the NEXT item also fits
    // into the post residual (chained packing), penalize otherwise.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // chainable: reward proportionally to how tightly next item fits
            let slack_after_next = post_residual as f64 - next_item_size as f64;
            score -= 150.0 - slack_after_next; // tight chain preferred
            if slack_after_next == 0.0 {
                score -= 300.0; // perfect 2-item fill
            }
        } else {
            // next item won't fit here: penalize leftover dead space
            score += 0.5 * post_residual as f64;
            // if next item is large, dead space is more costly
            if next_item_size > 50 {
                score += 0.3 * post_residual as f64;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when many bins
    // are open and mean residual is high (fragmentation exists).
    if bin_residual == bin_capacity {
        score += 120.0;
        score += 5.0 * open_bins_count as f64;
        score += 2.0 * mean_residual.max(0.0);
        // late in stream, prefer filling existing bins even harder
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 60.0 * progress;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong fit reward: tight packing preferred.
    score -= 40.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Dead-space penalty for very small leftover slivers that few items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; mild penalty if we leave a large gap it can't use
            score += 5.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin is expensive unless the item is huge
    // or the fit in existing bins is terrible.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = mean_residual / bin_capacity as f64;
        // Penalize new bins more when open bins have plenty of room and stream is late.
        score += 60.0 + 40.0 * pressure + 30.0 * progress;
        // But if item is large relative to capacity, new bin is more acceptable.
        score -= 0.4 * item_size as f64;
    }

    // Mild preference for filling bins that are already partially loaded (fewer bins overall).
    if bin_residual < bin_capacity {
        score -= 8.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);
    }

    // Slight penalty for bins with residuals far from the mean (encourage balanced usage),
    // damped early in the stream.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * dev * (1.0 - step_index as f64 / (total_items.max(1) as f64));

    // Late-stream consolidation: prefer existing bins even more as stream ends.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= 15.0 * t * (bin_residual < bin_capacity) as u8 as f64;

    score
}

