                score += 4.0 * (1.0 - (nxt - post) / 10.0);
            }
            // penalize large dead space when next item overshoots badly
            if dead > 0.35 && post_residual as f64 > mean_residual * 1.5 && fitting_bins_count > 3 {
                score += 10.0 * (dead - 0.35);
            }
            // residual just under next item (wasted near-fit)
            if post_residual >= (next_item_size * 3 / 4) && post_residual < next_item_size {
                score += 5.0 * (post_residual as f64 - next_item_size as f64 * 0.75) / (next_item_size as f64 * 0.25).max(1.0);
            }
            // deep dead space with few fitting bins: strong penalty
            if dead > 0.5 && fitting_bins_count <= 2 {
                score += 14.0 * (dead - 0.5);
            }
            // near-miss within half mean residual
            if post_residual > 0 && (nxt - post) < 0.5 * mean_residual.max(1.0) {
                score += 4.0;
            }
        }
    } else {
        score += post * 2.2;
    }

    // small sliver that no future item likely fills
    if post_residual > 0 && post_residual < 8 && next_item_size > post_residual {
        score += 26.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let new_bin_bonus = 40.0 * (1.0 - progress);
        score -= new_bin_bonus; // early: bins cheap; late: consolidate
        if mean_residual < item_size as f64 && open_bins_count > 2 {
            score += 10.0;
        }
        // many open bins with slack: prefer consolidating instead of new bin
        if open_bins_count > 5 && mean_residual > 0.4 * cap {
            score += 12.0;
        }
        // late stream: opening new bins is expensive, tighten further
        if progress > 0.5 {
            score += 18.0 * (progress - 0.5);
        }
        if open_bins_count > 3 && progress > 0.6 {
            score += 8.0;
        }
        // if some open bin already fits next item, opening is less attractive
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
        if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
            score += 14.0;
        }
        if next_item_size > 0 && next_item_size as f64 <= bin_residual as f64 && open_bins_count > 1 {
            score += 6.0;
        }
        // a fresh bin that exactly chains the next item is attractive
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 12.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 4 {
            score -= 20.0;
        }
    } else {
        // tightness pressure toward fuller bins
        let tightness = 1.0 - (bin_residual as f64 / cap);
        score -= 10.0 * tightness;
        // many fitting bins means this choice matters less; slight penalty for sloppy fits
        if fitting_bins_count > 4 && post_residual > 30 {
            score += 3.0;
        }
        // penalize leaving dead space when next item is much larger than residual
        if post_residual > 0 && next_item_size as f64 > post && post_residual as f64 > mean_residual * 1.5 && fitting_bins_count > 3 {
            score += 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post_f = post_residual as f64;
    let norm_post = post_f / cap;

    // Non-linear polynomial coupling: waste grows quadratically with normalized
    // post-residual, amplified as the stream progresses (less slack for error).
    let progress_amp = 1.0 + 2.0 * progress;
    score += 2.0 * norm_post * norm_post * cap * progress_amp;

    // Cubic dead-space term: heavily penalize residuals too small to be useful
    // for any plausible future item (smooth, no piecewise constants).
    let dead = 1.0 - norm_post;
    score += 0.5 * dead * dead * dead * cap * (1.0 - progress);

    // Tight-fit reward: subtract proportionally to how well the item fills the bin.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * fill * fill * progress_amp;

    // Lookahead coupling: reward if the next item fits the resulting residual,
    // penalize if it nearly fits but not quite (smooth interaction).
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= post_f {
            let slack = (post_f - n) / cap;
            score -= 3.0 * (1.0 - slack) * (1.0 + progress);
        } else {
            let miss = (n - post_f) / cap;
            score += 4.0 * miss * miss * cap;
        }
    }

    // Last-chance bin: strongly reward using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate calibration: opening a new bin should only win when
    // existing residuals are poor; couple with mean residual and progress.
    if bin_residual == bin_capacity {
        score = mean_residual * (1.0 + progress) + 5.0 * norm_post * cap * progress_amp;
        if fitting_bins_count == 0 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 classes
    let r = post_residual;
    let class = (r % 10) as f64;
    let decade = (r / 10) as f64;

    // Penalize residuals in awkward classes (1..=9 mod 10 are hard to fill)
    if r > 0 && r % 10 != 0 {
        score += 8.0 - class * 0.5; // small awkward slivers penalized more
    }

    // Reward residual sizes that are "harmonic": divisible by common item sizes
    if r % 20 == 0 || r % 25 == 0 || r % 50 == 0 {
        score -= 6.0;
    }

    // Perfect fit
    if r == 0 {
        score -= 50.0;
    }

    // Next-item lookahead: check if next item fits exactly in post_residual
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 40.0;
        } else if next_item_size < r {
            let nr = r - next_item_size;
            if nr % 10 == 0 || nr % 5 == 0 {
                score -= 12.0;
            }
            score += (nr % 10) as f64 * 0.8;
        } else {
            // next item can't use this residual: mild penalty scaled by decade
            score += 2.0 + decade * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 30.0;
        // but if mean residual is tiny (bins nearly full), opening fresh is fine
        score -= (mean_residual / cap) * 10.0;
        // early in stream, prefer consolidation into existing bins less strictly
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 5.0;
    }

    // Prefer fuller bins overall: reward small post_residual relative to mean
    score -= (1.0 - post_residual as f64 / cap) * 5.0;
    score += (mean_residual - post_residual as f64).max(0.0) * 0.05;

    // Slight preference to spread load when many bins open
    score += open_bins_count as f64 * 0.01;

    score
}

