pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize small unusable gaps hard.
    let dead_threshold = 12.0f64;
    if (post_residual as f64) > 0.0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Open bins pressure: penalize adding items to bins when many bins are open,
    // to encourage consolidation into fewer bins when possible.
    score += open_bins_count as f64 * 0.3;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive if current bin fit is poor (large post_residual).
    if bin_residual == bin_capacity {
        // Base penalty so new bins aren't opened frivolously.
        score += 30.0;
        // But if the item barely fits anywhere else, opening fresh is fine.
        if bin_residual < item_size {
            score += 0.0;
        }
        // Lookahead: if next item is large, a fresh bin is more valuable.
        if next_item_size > 0 {
            let gap = (bin_capacity as f64 - next_item_size as f64).max(0.0);
            if gap < (post_residual as f64) {
                score -= 10.0;
            }
        }
    }

    // Lookahead synergy: reward leaving space compatible with next item.
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) >= 0 {
        score -= 8.0;
    }

    // Mean residual coupling: prefer bins with residual close to mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // Stream progression: late in stream, be more conservative about new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // ---- 2-step lookahead: reward exact / near matches with next item ----
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;

        // Perfect match: next item exactly fills the bin afterwards
        if (post - nxt).abs() < 0.5 {
            score -= 60.0 + 20.0 * progress;
        } else if post >= next_item_size {
            // Next item still fits: reward proportional to how snug the leftover would be
            let leftover_after_next = post - nxt;
            score -= 25.0 * (1.0 - leftover_after_next / bin_capacity as f64);
            // Extra bonus if the pair nearly fills the bin completely
            if leftover_after_next as u32 <= 5 {
                score -= 15.0;
            }
        } else {
            // Next item would NOT fit here afterwards: penalize dead space
            let gap = nxt - post;
            score += 10.0 + 0.15 * gap;
        }
    } else {
        // Last item: just minimize waste
        score += 0.5 * post_residual as f64;
    }

    // ---- Mean-residual relative positioning ----
    // Bins with residual close to the mean are neutral; below-mean residual
    // (tight bins) are preferred targets; above-mean are penalized mildly.
    let dev = post_residual as f64 - mean_residual;
    score += 0.08 * dev;

    // ---- Last-chance bin: strongly favor using it to avoid opening a new bin ----
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // ---- Many open bins: prefer consolidation into existing bins ----
    if open_bins_count > 4 {
        score -= 2.0 * (open_bins_count.min(20) as f64 - 4.0).ln().max(0.0);
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Fresh bin: baseline cost of consuming a whole new bin.
        // Attractive only if the item is large or the lookahead suggests
        // the item + next item pair needs a big space.
        let pair_need = item_size as f64 + next_item_size as f64;
        let pair_fits_new = pair_need <= bin_capacity as f64;
        let pair_fits_here = (bin_residual as f64 - item_size as f64) >= next_item_size as f64 && next_item_size > 0;

        let mut new_bin_score = bin_capacity as f64 * 0.55 + 20.0;

        if pair_fits_new && !pair_fits_here && next_item_size > 0 {
            // Opening a new bin lets both items pack together cleanly
            new_bin_score -= 45.0;
        }
        if item_size > bin_capacity / 2 {
            new_bin_score -= 10.0; // large items do well in fresh bins
        }
        if fitting_bins_count > 2 {
            new_bin_score += 15.0; // plenty of alternatives exist, avoid spreading
        }
        // Late in the stream, prefer closing out existing bins
        new_bin_score += 10.0 * progress;

        score = new_bin_score;
    }

    // Small tie-breaker toward tighter bins
    score += 0.01 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
