        if open_bins_count > 3 && progress > 0.6 { score += 8.0; }
        if next_item_size > 0 && post_residual >= next_item_size { score -= 8.0; }
        if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size { score += 14.0; }
        if next_item_size > 0 && next_item_size as f64 <= bin_residual as f64 && open_bins_count > 1 { score += 6.0; }
        if open_bins_count > 2 && mean_residual > 0.5 * cap {
            score += 20.0 * (mean_residual / cap - 0.5);
        }
        if next_item_size > 0 && post_residual == next_item_size { score -= 12.0; }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 4 { score -= 20.0; }
    } else {
        let tightness = 1.0 - (bin_residual as f64 / cap);
        score -= 10.0 * tightness;
        if fitting_bins_count > 4 && post_residual > 30 { score += 3.0; }
        if post_residual > 0 && next_item_size as f64 > post && post_residual as f64 > mean_residual * 1.5 && fitting_bins_count > 3 { score += 8.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: exact or near-exact packing is highly desirable.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Penalize dead space that is too small to hold typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly favor this bin (chains items together).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size && (post_residual - next_item_size) <= 10 {
            score -= 12.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 8.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // When many bins are open, prefer consolidation into existing bins.
    let congestion = open_bins_count as f64 / (1.0 + total_items as f64 / 10.0);
    score += congestion * 3.0;

    // Prefer bins with residual below the mean (pack the tighter bins first).
    let residual_gap = bin_residual as f64 - mean_residual;
    score += 0.15 * residual_gap;

    // Time horizon: early in the stream, be more selective (penalize loose fits);
    // late in the stream, just fill whatever fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * (post_residual as f64) * 0.25;
    score -= progress * 10.0;

    // New-bin candidate: only attractive when the item is large relative to a
    // fresh bin and no good fits exist; otherwise penalize opening a new bin.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio > 0.7 {
            score -= 5.0;
        } else {
            score += 25.0 + 40.0 * (1.0 - fill_ratio);
        }
    }

    // Slight preference for bins whose residual is an exact multiple of
    // common item sizes (10-80 granularity), improving future fit odds.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear coupling: quadratic waste pressure growing with stream progress.
    let norm_pr = pr / cap;
    score += 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits increasingly as the stream matures.
    score -= 25.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;

    // Lookahead synergy: if next item fits into post-residual, reward strongly (smoothly scaled by how well it fits).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack = (pr - nx) / cap;
            score -= 30.0 * (1.0 - slack * slack);
        } else {
            // Penalize leaving a residual that the next item cannot use.
            score += 10.0 * (1.0 - pr / nx.max(1.0)).abs() * (0.5 + progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // Mild preference for fuller bins among many candidates.
        score -= 5.0 * (1.0 - norm_pr);
    }

    // New-bin candidate (empty bin): penalize opening a new bin unless residual
    // landscape is badly fragmented (high mean residual among few bins).
    if bin_residual == bin_capacity {
        let fragmentation = if open_bins_count > 0 { mean_residual / cap } else { 0.0 };
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score += 45.0 - 30.0 * fragmentation * fragmentation - 8.0 * open_pressure * progress;
    } else {
        // Slight bonus to keep existing bins busy when many are open.
        score -= 3.0 * (open_bins_count as f64).min(10.0) / 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into capacity-fraction buckets.
    let post_f = post_residual as f64 / cap;
    let class = (post_f * 10.0).floor(); // 0..10 harmonic class

    // Reward residuals that form "complementary" classes (small dead space)
    score -= 12.0 * (1.0 - post_f);

    // Modulo arithmetic on post_residual: perfect-fit harmonics (residual divisible
    // by common item sizes) are valuable.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 8.0; }
        if post_residual % 20 == 0 { score -= 4.0; }
        if post_residual % 25 == 0 { score -= 4.0; }
    } else {
        // Perfect closure: best possible outcome.
        score -= 60.0;
    }

    // Lookahead coupling: does next_item_size fit harmonically in post_residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
        // extra reward if next item exactly matches a modulo class of post_residual
        if post_residual % next_item_size.max(1) == 0 { score -= 10.0; }
    } else if next_item_size > post_residual && post_residual > 0 {
        // dead space that next item cannot use
        score += 10.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): only attractive if current fit is bad
    // and many bins are open (fragmentation guard).
    if bin_residual == bin_capacity {
        let tight_fit = (post_residual as f64) < 15.0;
        if tight_fit {
            score -= 20.0; // item nearly fills a fresh bin
        } else {
            score += 30.0 + 2.0 * open_bins_count as f64; // discourage waste
        }
    }

    // Progress-aware mild regularization toward mean residual alignment.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.1 * (post_residual as f64 - mean_residual) * (0.5 + 0.5 * progress);

    // Integer-division threshold: penalize residuals in "awkward" small bands.
    let q = post_residual / 15;
    if q == 0 && post_residual > 0 { score += 12.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
