pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder than large ones.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny dead space is nearly worthless
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Reward exact fills.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0; // blocking the next item creates dead space
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to number of open bins.
        score += 15.0 + open_bins_count as f64 * 5.0;
        // But if no open bin fits well, opening is acceptable.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    } else {
        // Last-chance bin: strongly favor using the only bin that fits.
        if fitting_bins_count == 1 {
            score -= 25.0;
        }
        // Mild reward for consolidating into bins already open.
        score -= 5.0;
    }

    // Progression: early in stream, be more willing to open bins; later, pack tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: prefer bins whose residual is below mean (more filled bins).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    score
}

