                score -= 4.0 * (1.0 - gap / 10.0);
            }
        } else {
            if post_residual > 0 && post_residual < 10 { score += 60.0; }
            if nxt - post <= 2.0 && fitting_bins_count > 1 { score += 15.0; }
            if nxt - post > 20.0 && post_residual < 20 { score += 12.0; }
            if post_residual < next_item_size / 2 {
                score += 6.0 * (1.0 - post_residual as f64 / (next_item_size / 2).max(1) as f64);
            }
            if post_residual > 0 && post_residual < item_size && open_bins_count > 3 { score += 8.0; }
            if post_residual > 0 && nxt - post <= 10.0 {
                score += 4.0 * (1.0 - (nxt - post) / 10.0);
            }
            let dead = post / cap;
            if dead > 0.35 && post_residual as f64 > mean_residual * 1.5 && fitting_bins_count > 3 {
                score += 10.0 * (dead - 0.35);
            }
            if post_residual >= (next_item_size * 3 / 4) && post_residual < next_item_size {
                score += 5.0 * (post_residual as f64 - next_item_size as f64 * 0.75) / (next_item_size as f64 * 0.25).max(1.0);
            }
            if dead > 0.5 && fitting_bins_count <= 2 {
                score += 14.0 * (dead - 0.5);
            }
            if post_residual > 0 && (nxt - post) < 0.5 * mean_residual.max(1.0) {
                score += 4.0;
            }
            if dead > 0.55 && open_bins_count > 4 {
                score += 16.0 * (dead - 0.55);
            }
            // near-miss: residual just under next item wastes capacity
            if post_residual > 0 && nxt - post <= 4.0 {
                score += 8.0 * (1.0 - (nxt - post) / 4.0);
            }
        }
    } else {
        score += post * 2.2;
    }

    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 40.0 * (1.0 - progress);
        if mean_residual < item_size as f64 && open_bins_count > 2 {
            score += 10.0;
        }
        if open_bins_count > 5 && mean_residual > 0.4 * cap {
            score += 12.0;
        }
        if progress > 0.5 {
            score += 18.0 * (progress - 0.5);
        }
        if open_bins_count > 3 && progress > 0.6 {
            score += 8.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
        if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
            score += 14.0;
        }
        if next_item_size > 0 && next_item_size as f64 <= bin_residual as f64 && open_bins_count > 1 {
            score += 6.0;
        }
        let dead = post / cap;
        if dead > 0.5 && open_bins_count > 2 {
            score += 20.0 * (dead - 0.5);
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 12.0;
        }
        // new bin fits next item tightly: attractive
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 4 {
            score -= 20.0;
        }
        // late stream: opening new bins is expensive
        if open_bins_count > 6 && progress > 0.4 {
            score += 10.0;
        }
    } else {
        let tightness = 1.0 - (bin_residual as f64 / cap);
        score -= 10.0 * tightness;
        if fitting_bins_count > 4 && post_residual > 30 {
            score += 3.0;
        }
        if post_residual > 0 && next_item_size as f64 > post && post_residual as f64 > mean_residual * 1.5 && fitting_bins_count > 3 {
            score += 8.0;
        }
        if post_residual > 0 && next_item_size as f64 > post && (next_item_size as f64 - post) <= 4.0 && fitting_bins_count > 2 {
            let dead = post / cap;
            if dead > 0.3 {
                score += 11.0 * (dead - 0.3);
            }
        }
        // prefer the bin whose residual after placement stays largest-usable
        if post_residual >= 20 && fitting_bins_count > 1 {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small dead space gets quadratic bonus).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Aggressive 2-step lookahead: strongly reward when the NEXT item
    // exactly matches the post_residual (perfect chaining).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if next <= post {
            let gap = post - next;
            if gap == 0.0 {
                score -= 60.0; // perfect chain: next item fills bin completely
            } else {
                // proportional reward for near-chaining, decaying with gap
                score -= 30.0 * (1.0 - gap / (bin_capacity as f64)).max(0.0);
            }
        } else {
            // Next item cannot use post_residual: penalize wasted space
            score += 0.35 * (next - post).min(post as f64);
        }
    }

    // Compare post_residual against mean residual across open bins:
    // leaving less than average residual is good (bin well-utilized).
    score -= 0.25 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a brand-new bin when decent fits exist,
    // unless the item is large and a fresh bin is genuinely useful.
    if bin_residual == bin_capacity {
        score += 20.0;
        if next_item_size > 0 && next_item_size as f64 >= 0.9 * (bin_capacity as f64) {
            score -= 30.0; // large current item benefits from a fresh bin
        }
    }

    // Mild early-stream preference to consolidate (fewer bins early),
    // relaxing slightly as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * (1.0 - progress) * (open_bins_count as f64).sqrt();

    score
}

