pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fill_ratio * fill_ratio;

    // Penalize large dead space quadratically (unusable gaps).
    if post_residual > 0 {
        let dead = post_residual as f64;
        score += 0.05 * dead * dead / bin_capacity as f64;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post-residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 6.0;
        }
        // Chain fit: post residual exactly matches next item => great pairing.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Fragmentation pressure: when mean residual is low, be greedy with space.
    let t = step_index as f64 / (total_items.max(1) as f64);
    if (bin_residual as f64) < mean_residual {
        score -= 8.0 * (1.0 - t);
    } else {
        score += 4.0 * t;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // (i.e., many bins but poor fit) or stream is early with few bins open.
    if bin_residual == bin_capacity {
        let poor_fit = if fitting_bins_count == 0 { 0.0 } else {
            (item_size as f64 / bin_capacity as f64).min(1.0)
        };
        score += 30.0 * poor_fit;          // penalize opening new bin when one fits decently
        score -= 10.0 * (1.0 - t) * (1.0 - t); // early stream: opening bins is cheap
        score += 2.0 * open_bins_count as f64 * t; // late stream: prefer consolidation
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = 1.0 + 2.0 * progress - 3.0 * progress * progress + 2.0 * progress * progress * progress;
    score *= poly;

    // Penalize small post_residuals that create dead space, more late in the stream
    let dead = if pr > 0.0 { (cap - pr) / cap } else { 1.0 };
    score -= dead * (1.0 + progress) * 8.0;

    // Reward tight fits: post_residual near zero
    score -= (1.0 - norm_pr).powi(3) * 12.0;

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 * (1.0 - progress);
    } else if next_item_size > 0 {
        score += 3.0 * (1.0 - norm_pr);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Mild penalty for spreading across many open bins late in stream
    score += (open_bins_count as f64).ln().max(0.0) * progress * 2.0;

    // Deviation from mean residual: prefer bins whose residual is below mean (denser bins)
    let dev = mean_residual - pr;
    score += dev * 0.05 * (1.0 + progress);

    // New-bin candidate: discourage opening a new bin unless current fit is bad
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) + 5.0;
        if item_size as f64 / cap > 0.8 {
            score -= 20.0;
        }
    }

    score
}

