                score += 10.0 * (dead - 0.35);
            }
            if post_residual >= (next_item_size * 3 / 4) && post_residual < next_item_size {
                score += 5.0 * (post_residual as f64 - next_item_size as f64 * 0.75) / (next_item_size as f64 * 0.25).max(1.0);
            }
            if dead > 0.5 && fitting_bins_count <= 2 {
                score += 14.0 * (dead - 0.5);
            }
            if post_residual > 0 && (nxt - post) < 0.5 * mean_residual.max(1.0) {
                score += 4.0;
            }
            if post_residual > 0 && (nxt - post) as u32 <= 4 && fitting_bins_count > 2 {
                score += 11.0 * (post / cap - 0.3).max(0.0);
            }
            // near-miss penalty scaled by closeness (encourage waiting elsewhere)
            if post_residual > 0 && nxt - post <= 5.0 {
                score += 6.0 * (1.0 - (nxt - post) / 5.0);
            }
        }
    } else {
        score += post * 2.2;
    }

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let new_bin_bonus = 40.0 * (1.0 - progress);
        score -= new_bin_bonus;
        if mean_residual < item_size as f64 && open_bins_count > 2 {
            score += 10.0;
        }
        if open_bins_count > 5 && mean_residual > 0.4 * cap {
            score += 12.0;
        }
        if progress > 0.5 {
            score += 18.0 * (progress - 0.5);
        }
        if open_bins_count > 3 && progress > 0.6 {
            score += 8.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
            if post_residual - next_item_size <= 4 { score -= 20.0; }
        }
        if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
            score += 14.0;
        }
        if next_item_size > 0 && next_item_size as f64 <= bin_residual as f64 && open_bins_count > 1 {
            score += 6.0;
        }
        if open_bins_count > 2 && mean_residual > 0.5 * cap {
            score += 20.0 * (mean_residual / cap - 0.5);
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 12.0;
        }
        // prefer consolidation late when an open bin leaves a residual close to next item
        if progress > 0.4 && next_item_size > 0 && fitting_bins_count > 0 {
            let near = (mean_residual - next_item_size as f64).abs();
            if near <= 5.0 { score += 10.0; }
        }
        // discourage opening new bins when an existing bin's post-residual is a tight chain
        if fitting_bins_count > 0 && next_item_size > 0 {
            let best_gap = mean_residual.min(post);
            if best_gap as f64 >= next_item_size as f64 { score += 6.0; }
        }
    } else {
        let tightness = 1.0 - (bin_residual as f64 / cap);
        score -= 10.0 * tightness;
        if fitting_bins_count > 4 && post_residual > 30 {
            score += 3.0;
        }
        if post_residual > 0 && next_item_size as f64 > post && post_residual as f64 > mean_residual * 1.5 && fitting_bins_count > 3 {
            score += 8.0;
        }
        // strong consolidation pressure when many bins compete and this fit is tight
        if fitting_bins_count > 3 && post_residual < 15 {
            score -= 6.0;
        }
        // reward very tight fits among many competitors
        if post_residual < 8 && post_residual > 0 && fitting_bins_count > 2 {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64 * 1.0;

    // Reward placements that still accommodate the lookahead item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + (post_residual - next_item_size) as f64 * 0.05;
    } else if next_item_size > 0 {
        // Penalize dead space the next item cannot use
        score += (next_item_size - post_residual) as f64 * 0.15;
    }

    // Last chance: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Opening a fresh bin wastes open_bins_count * mean_residual potential
        score = bin_capacity as f64 * 0.9 + open_bins_count as f64 * mean_residual * 0.05 - progress * 5.0;
        // If the new bin could host the next item too, slightly less bad
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0;
        }
        // If no open bin fits well (post_residual large elsewhere), new bin ok
        if post_residual_wrapped(item_size, bin_capacity) < 10 {
            score -= 12.0;
        }
    }

    // Harmonic class penalty: dead space in awkward residue classes is less reusable
    let pr = post_residual;
    if pr > 0 {
        // residue classes mod 10: small remainders are near-unusable
        let r = pr % 10;
        if r > 0 && pr < 10 {
            score += 6.0; // tiny unusable sliver
        }
        // integer division threshold: post_residual in (0,10] is dead space
        if pr <= 10 {
            score += 4.0;
        }
        // divisible-by-25 residuals are highly reusable
        if pr % 25 == 0 && pr > 0 {
            score -= 5.0;
        }
    }

    // Slight preference to fill bins with larger residual (consolidate)
    score -= bin_residual as f64 * 0.02;

    score
}

#[inline]
fn post_residual_wrapped(item_size: u32, capacity: u32) -> u32 {
    capacity % item_size.max(1)
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: perfect placement, strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: small nonzero gaps are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead zone penalty
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward leaving room for the lookahead item (good coupling).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
        // Bonus if lookahead exactly fills the new residual.
        if post_residual == next_item_size {
            score -= 40.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 20.0; // residual too small for the known next item
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: mildly discourage spreading across many bins.
    score += open_bins_count as f64 * 0.5;

    // Slight preference for tighter bins (small residual before placement).
    score += (bin_residual as f64) * 0.05;

    // New-bin candidate: neutral-ish default so it wins only when fits are bad.
    if bin_residual == bin_capacity {
        score = 45.0 + open_bins_count as f64 * 0.3;
        // If the only alternative is a poor fit, allow new bin.
        if fitting_bins_count == 1 {
            score += 100.0; // prefer using the existing last-chance bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: zero post residual is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // 2-step lookahead: reward if next item fits the post residual exactly or closely.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let gap = (post - nxt).abs();
        if nxt <= post {
            // next item fits: reward tightness of the chained fit
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
            if gap == 0.0 {
                score -= 30.0; // perfect 2-chain
            }
        } else {
            // next item won't fit here: penalize large dead space relative to next item
            score += 0.15 * (post - nxt).max(0.0);
        }
    }

    // Favor bins whose residual is below mean (tighter bins get filled first),
    // keeping loose bins available for larger future items.
    score += 0.35 * (mean_residual - bin_residual as f64).max(0.0);
    score -= 0.10 * (bin_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Mild penalty for opening a new bin when many bins are already open and fit exists.
    if bin_residual == bin_capacity {
        score += 20.0 + 2.0 * open_bins_count as f64;
        // But allow new bin if it enables a perfect 2-chain with next item
        if next_item_size > 0 && (bin_capacity - item_size) == next_item_size {
            score -= 55.0;
        }
    }

    // Late-stream pressure: consolidate more aggressively as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness of fit: reward small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead: if the next item fits into the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_next = post_residual - next_item_size;
        let pair_fit = 1.0 - (slack_after_next as f64) / (bin_capacity as f64);
        score -= 8.0 * pair_fit;
    } else if next_item_size > 0 {
        // Next item won't fit here: mild penalty proportional to how much we'd strand.
        score += 0.05 * (next_item_size as f64).min(post_residual as f64);
    }

    // Last-chance bin: strongly favor using the final fitting bin to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // When several bins fit, prefer ones that keep flexibility: penalize very low residual.
        score += 0.02 * (post_residual as f64);
    }

    // Global pressure: when many bins are open relative to progress, discourage opening new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let open_pressure = open_bins_count as f64 / (1.0 + 20.0 * progress + 1.0);
    score += 0.3 * open_pressure;

    // Mean residual coupling: if this bin's residual is far below the mean, it's a good "garbage collector".
    let residual_gap = mean_residual - post_residual as f64;
    score += 0.08 * residual_gap;

    // Late stream: prefer consolidating into existing bins rather than opening new ones.
    if progress > 0.7 && bin_residual != bin_capacity {
        score -= 3.0 * progress;
    }

    // New-bin candidate: only attractive when no open bin is a decent fit or residual is very tight.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 40.0 } else { 0.0 };
        let poor_fits = if post_residual > 50 { 10.0 } else { 0.0 };
        score += 18.0 - desperation - poor_fits + 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_frac = item_size as f64 / cap;

    // Non-linear waste penalty: squared post-residual scaled by stream progress
    score += (pr * pr) / cap * (0.5 + t);

    // Reward tight fits (small post_residual relative to item size)
    score -= fit_frac * fit_frac * 20.0 * (1.0 - t);

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 20.0 * t;
    }

    // New-bin candidate handling: prefer opening a new bin when the item fits
    // poorly in existing bins, but discourage hoarding bins early in the stream
    if bin_residual == bin_capacity {
        let open_penalty = (open_bins_count as f64).ln().max(0.0) * 8.0 * (1.0 - t);
        score += 10.0 + open_penalty - 25.0 * fit_frac;
        // If the next item could use this bin's post-residual, encourage opening
        if (next_item_size as f64) <= pr && next_item_size > 0 {
            score -= 15.0;
        }
    }

    // Encourage bins whose residual is close to the next item (lookahead pairing)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 12.0 * (1.0 - gap / cap).max(0.0) * (1.0 - t);
    }

    // Slight preference for bins with residual near the mean (balance residuals)
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post * post / cap;

    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        // tiny leftover: near-perfect fit, small residual is cheap
        score -= 330.0 / post;
    } else if post_residual < 12 {
        score += 90.0 + (12 - post_residual) as f64 * 6.0;
    } else {
        score -= 15.0 * (post / cap);
        if post_residual >= 40 {
            score -= 9.0;
        }
        if post_residual < 30 {
            score += 7.5 * (30 - post_residual) as f64 / 18.0;
        }
        if post_residual % 25 == 0 {
            score -= 8.0;
        }
        if post_residual % 50 == 0 {
            score -= 6.0;
        }
    }

    if post > 0.0 && post < 0.25 * cap {
        score += 30.0 * (1.0 - post / (0.25 * cap));
    }
    let dead = post / cap;
    if dead > 0.45 && post_residual > 0 {
        score += 14.0 * (dead - 0.45);
    }

    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let chain_tight = 1.0 - (post - nxt) / cap;
            score -= 52.0 * chain_tight;
            if post == nxt {
                score -= 68.0;
            }
            if post_residual % next_item_size == 0 {
                score -= 18.0;
            }
            if post >= nxt + mean_residual {
                score -= 10.0;
            }
            let gap = post - nxt;
            if gap <= mean_residual * 0.5 {
                score -= 8.0;
            }
            if gap >= 1.0 && gap <= 4.0 {
                score -= 12.0;
            }
            if gap < 6.0 {
                score -= 18.0;
            }
            if gap as u32 == mean_residual as u32 {
                score -= 9.0;
            }
            if gap <= 1.0 {
                score -= 6.0;
            }
            if gap <= 2.0 && dead > 0.5 {
                score -= 6.0;
            }
            if gap <= 12.0 && gap <= mean_residual * 1.2 {
                score -= 7.0 * (1.0 - gap / 12.0);
            }
            if gap <= 3.0 && fitting_bins_count <= 2 {
                score -= 10.0;
            }
            if post_residual <= 25 && nxt > post_residual as f64 * 0.6 {
                score -= 13.0 * (1.0 - post_residual as f64 / 25.0);
            }
        } else {
            if post + 10.0 >= nxt {
                score += 6.0;
            } else {
                score += 0.06 * (nxt - post);
            }
            if post_residual < 10 {
                score += 60.0;
            }
            if (nxt - post) as u32 <= 2 && fitting_bins_count > 1 {
                score += 15.0;
            }
            if (nxt - post) as u32 > 20 && post_residual > 0 && post_residual < 20 {
                score += 12.0;
            }
            if post_residual >= (next_item_size * 3 / 4) && post_residual < next_item_size {
                score += 5.0 * (post_residual as f64 - nxt * 0.75) / (nxt * 0.25).max(1.0);
            }
            if (nxt - post) < 0.5 * mean_residual.max(1.0) {
                score += 4.0;
            }
            if dead > 0.5 && fitting_bins_count <= 2 {
                score += 14.0 * (dead - 0.5);
            }
            if (nxt - post) as u32 <= 4 && fitting_bins_count > 2 {
                score += 11.0 * (dead - 0.3).max(0.0);
            }
        }
    } else {
        score += post * 2.2;
    }

    if post_residual > 0 && post_residual < 16 && next_item_size > post_residual && (mean_residual as u32) > post_residual {
        score += 9.0 * (16 - post_residual) as f64 / 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    let progress = step_index as f64 / (total_items.max(1) as f64);

    if bin_residual == bin_capacity {
        // New-bin candidate
        score -= 40.0 * (1.0 - progress);
        if progress > 0.5 {
            score += 18.0 * (progress - 0.5);
        }
        if open_bins_count > 3 && progress > 0.6 {
            score += 8.0;
        }
        if mean_residual < item_size as f64 && open_bins_count > 2 {
            score += 10.0;
        }
        if open_bins_count > 5 && mean_residual > 0.4 * cap {
            score += 12.0;
        }
        if open_bins_count > 2 && mean_residual > 0.5 * cap {
            score += 20.0 * (mean_residual / cap - 0.5);
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
            if post_residual - next_item_size <= 4 {
                score -= 20.0;
            }
            if fitting_bins_count > 2 {
                score += 14.0;
            }
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 12.0;
        }
        if next_item_size > 0 && next_item_size as f64 <= bin_residual as f64 && open_bins_count > 1 {
            score += 6.0;
        }
    } else {
        let tightness = 1.0 - (bin_residual as f64 / cap);
        score -= 10.0 * tightness;
        if fitting_bins_count > 4 && post_residual > 30 {
            score += 3.0;
        }
        if post_residual > 0 && next_item_size as f64 > post && post_residual as f64 > mean_residual * 1.5 && fitting_bins_count > 3 {
            score += 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Harmonic class logic: quantize post_residual into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    let q = (frac * 4.0).floor() / 4.0; // quarter-capacity class
    score -= 12.0 * q;

    // Penalize dead space that no plausible item can use (items >= 1).
    if post_residual == 0 {
        score -= 50.0; // perfect pack
    } else if post_residual < 10 {
        score -= 20.0; // near-perfect
    }

    // Modulo arithmetic on post_residual vs common item sizes.
    if post_residual > 0 {
        let mut best_mod = u32::MAX;
        for s in [1u32, 5, 10, 15, 20, 25, 30, 40, 50, 60, 75, 80, 100] {
            if s <= post_residual {
                best_mod = best_mod.min(post_residual % s);
            }
        }
        if best_mod != u32::MAX {
            score += 0.15 * best_mod as f64; // residue mod common sizes = wasted potential
        }
    }

    // Lookahead coupling: reward bins whose post_residual can host next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0;
        } else {
            score += 0.3 * (next_item_size - post_residual.min(next_item_size)) as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: make opening a new bin costly unless current bins are bad fits.
    if bin_residual == bin_capacity {
        score += 40.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // forced new bin
        }
    }

    // Stream progression: as stream advances, be greedier with tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * fit_ratio;

    // Mean residual coupling: penalize bins far below mean residual (fragmented bins).
    score += 0.2 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are pure waste.
    if post_residual < 10 {
        score -= 60.0; // perfect fit, no dead space at all -> strongly favored
    } else if post_residual <= 20 {
        // gap too small for most items (min size 1..100 unknown, but small gaps
        // are unlikely to be reused): penalize relative to its size
        score += (20 - post_residual) as f64 * 3.0;
    }

    // Reward filling the bin deeply (low post_residual relative to capacity)
    score += (post_residual as f64 / bin_capacity as f64) * 40.0;

    // Reward when this bin is the ONLY one that fits (last-chance pressure)
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        score += (fitting_bins_count as f64 - 1.0) * 2.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; prefer tight fits
    // and discourage opening new bins when a decent fit exists.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (1.0 + progress);
    score += pressure * 0.5;

    // New-bin candidate (empty bin): only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced when many items remain
        // and mean residual across open bins is large (poor reuse potential).
        let reuse_potential = mean_residual / bin_capacity as f64;
        score = 30.0 + open_bins_count as f64 * 2.0 - reuse_potential * 10.0;
        // If the next item could pair with this item in a fresh bin, slight bonus
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 5.0;
        }
        // Late in the stream, opening new bins is cheaper than fragmentation
        score -= progress * 8.0;
    }

    // Lookahead: if the residual left behind exactly accommodates the next item,
    // this placement is excellent (chains fits together).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size + 10 {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
