pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let tightness = (next_item_size as f64 / post_residual as f64).min(1.0);
            score -= 30.0 + 40.0 * tightness;
        } else {
            // Penalize residual that next item cannot use, scaled by dead space
            let dead = post_residual as f64;
            score += dead * 0.5;
            // Extra penalty if next item would have fit a slightly larger residual bin
            if next_item_size > post_residual && next_item_size <= bin_residual {
                score += 15.0;
            }
        }
    }

    // Compare against mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: usually penalize, but accept it when no open bin fits well
    if bin_residual == bin_capacity {
        let base_penalty = 45.0 + 0.15 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // opening a fresh bin guarantees a fit for the next item
            score += base_penalty - 10.0;
        } else {
            score += base_penalty;
        }
        // Late in stream, prefer closing out existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Mild preference to fill larger-residual bins when many are open
    score += 0.05 * (bin_residual as f64 / bin_capacity as f64) * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward bins whose leftover could host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a bin unless it is the only option
    // or the fit in open bins is poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_penalty = 55.0;
        if fitting_bins_count == 0 {
            new_bin_penalty = 0.0;
        } else if fitting_bins_count == 1 {
            new_bin_penalty = 25.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        new_bin_penalty += 20.0 * progress;
        // Many open bins with slack: discourage opening more.
        if mean_residual > item_size as f64 {
            new_bin_penalty += 10.0;
        }
        score += new_bin_penalty;
    }

    // Mild penalty for spreading across many open bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post * post / cap; // quadratic pressure

    if post_residual == 0 {
        score -= 1000.0; // perfect fit dominates
    } else {
        // Harmony bonuses for round leftovers
        if post % 10 == 0 { score -= 12.0; }
        if post % 20 == 0 { score -= 8.0; }
        if post % 25 == 0 { score -= 8.0; }
        if post % 50 == 0 { score -= 6.0; }
        // Borrowed from best: strong sliver penalty
        if post_residual <= 5 {
            score -= 330.0 / post;
        } else if post_residual < 12 {
            score += 90.0 + (12 - post_residual) as f64 * 6.0;
        } else {
            score -= 15.0 * (post / cap);
            if post_residual >= 40 { score -= 9.0; }
            if post_residual < 30 { score += 7.5 * (30 - post_residual) as f64 / 18.0; }
        }
        // dead-space band under 25% of capacity
        if post < 0.25 * cap {
            score += 30.0 * (1.0 - post / (0.25 * cap));
        }
        // deep dead-space pressure
        let dead0 = post / cap;
        if dead0 > 0.45 {
            score += 14.0 * (dead0 - 0.45);
        }
    }

    let dead = post / cap;

    // Lookahead: reward if next item chains into the leftover
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let chain_tight = 1.0 - (post - nxt) / cap;
            score -= 52.0 * chain_tight;
            if post == nxt { score -= 68.0; } // exact chain fill
            if post_residual % next_item_size == 0 { score -= 18.0; } // harmonic chain
            if (post_residual - next_item_size) % 10 == 0 { score -= 6.0; }
            let gap = post - nxt;
            if gap >= 1.0 && gap <= 4.0 { score -= 12.0; } // near-perfect chain
            if post >= nxt + mean_residual { score -= 10.0; }
            if gap <= mean_residual * 0.5 { score -= 8.0; }
            if gap < 6.0 { score -= 18.0; }
            if gap as u32 == mean_residual as u32 { score -= 9.0; }
            if gap <= 1.0 { score -= 6.0; }
            if gap <= 2.0 && dead > 0.5 { score -= 6.0; }
            if post_residual <= 25 && nxt > post_residual as f64 * 0.6 {
                score -= 13.0 * (1.0 - post_residual as f64 / 25.0);
            }
            if gap <= 12.0 && gap <= mean_residual * 1.2 {
                score -= 7.0 * (1.0 - gap / 12.0);
            }
            if gap <= 3.0 && fitting_bins_count <= 2 {
                score -= 10.0;
            }
            if post_residual <= mean_residual as u32 { score -= 6.0; }
        } else {
            // next item won't fit here
            if post_residual > 0 && post_residual < 10 { score += 60.0; }
            if nxt - post <= 2.0 && fitting_bins_count > 1 { score += 15.0; }
            if nxt - post > 20.0 && post_residual > 0 && post_residual < 20 { score += 12.0; }
            if post_residual < next_item_size / 2 {
                score += 6.0 * (1.0 - post_residual as f64 / (next_item_size / 2).max(1) as f64);
            }
            if post_residual > 0 && post_residual < item_size && open_bins_count > 3 { score += 8.0; }
            // near-miss penalty scaled by closeness
            if post_residual > 0 && nxt - post <= 10.0 {
                score += 4.0 * (1.0 - (nxt - post) / 10.0);
            }
            // large dead space with next item overshooting badly
            if dead > 0.35 && post_residual as f64 > mean_residual * 1.5 && fitting_bins_count > 3 {
                score += 10.0 * (dead - 0.35);
            }
            // residual just under next item (wasted near-fit)
            if post_residual >= (next_item_size * 3 / 4) && post_residual < next_item_size {
                score += 5.0 * (post_residual as f64 - next_item_size as f64 * 0.75) / (next_item_size as f64 * 0.25).max(1.0);
            }
            // deep dead space with few fitting bins
            if dead > 0.5 && fitting_bins_count <= 2 {
                score += 14.0 * (dead - 0.5);
            }
            // near-miss within half mean residual
            if post_residual > 0 && (nxt - post) < 0.5 * mean_residual.max(1.0) {
                score += 4.0;
            }
            // near-miss within a few units
            if post_residual > 0 && (nxt - post) as u32 <= 4 && fitting_bins_count > 2 {
                score += 11.0 * (post / cap - 0.3).max(0.0);
            }
        }
    } else {
        score += post * 2.2;
    }

    // Sliver guard even when next item fits elsewhere
    if post_residual > 0 && post_residual < 8 && next_item_size > post_residual {
        score += 26.0;
    }
    if post_residual > 0 && post_residual < 16 && next_item_size > post_residual && (mean_residual as u32) > post_residual {
        score += 9.0 * (16 - post_residual) as f64 / 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    let progress = step_index as f64 / (total_items.max(1) as f64);

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        score -= 40.0 * (1.0 - progress); // early: bins cheap; late: consolidate
        if mean_residual < item_size as f64 && open_bins_count > 2 {
            score += 10.0;
        }
        if open_bins_count > 5 && mean_residual > 0.4 * cap {
            score += 12.0;
        }
        if progress > 0.5 {
            score += 18.0 * (progress - 0.5);
        }
        if open_bins_count > 3 && progress > 0.6 {
            score += 8.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
        if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
            score += 14.0;
        }
        if next_item_size > 0 && next_item_size as f64 <= bin_residual as f64 && open_bins_count > 1 {
            score += 6.0;
        }
        // many open bins with deep dead space: new bin is expensive
        if open_bins_count > 2 && mean_residual > 0.5 * cap {
            score += 20.0 * (mean_residual / cap - 0.5);
        }
        // exact chain into fresh bin: cheap new bin
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 12.0;
        }
        // near-exact chain into fresh bin
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 4 {
            score -= 20.0;
        }
    } else {
        // tightness pressure toward fuller bins
        let tightness = 1.0 - (bin_residual as f64 / cap);
        score -= 10.0 * tightness;
        if fitting_bins_count > 4 && post_residual > 30 {
            score += 3.0;
        }
        if post_residual > 0 && next_item_size as f64 > post && post_residual as f64 > mean_residual * 1.5 && fitting_bins_count > 3 {
            score += 8.0;
        }
    }

    // Cross-cutting lookahead couplings
    if post_residual > 0 && next_item_size as f64 <= post && next_item_size as f64 > post_residual as f64 * 0.6 && post_residual <= 25 {
        score -= 13.0 * (1.0 - post_residual as f64 / 25.0);
    }
    if post_residual > 0 && post_residual < item_size && next_item_size as f64 > post && open_bins_count > 3 {
        score += 8.0;
    }
    if post_residual > 0 && post_residual % 10 == 0 && next_item_size as f64 <= post {
        score -= 5.0;
    }
    if post_residual > 0 && next_item_size as f64 <= post && (post - next_item_size as f64) <= 2.0 && dead > 0.4 {
        score -= 9.0;
    }
    if post_residual > 0 && next_item_size as f64 <= post && fitting_bins_count <= 2 {
        score -= 5.0 * (1.0 - (post - next_item_size as f64) / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // smooth polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += 25.0 * norm_pr * (0.5 + progress) - 30.0 * norm_pr * norm_pr * (1.0 - 0.5 * p2);
    // reward tight fits more strongly as stream advances
    score -= 40.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.6 + 0.4 * p3);
    // penalize dead space relative to mean residual
    score += 0.3 * (pr - mean_residual).abs() * (0.5 + p2);
    // last-chance bin bonus
    if fitting_bins_count == 1 { score -= 15.0 * (1.0 - norm_pr); }
    // lookahead: reward leaving space compatible with next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= pr { score -= 8.0 * (1.0 - (ns / cap - norm_pr).abs()); }
        else { score += 5.0 * (ns - pr) / cap; }
    }
    // new-bin candidate: keep neutral-ish, slightly penalized so good fits win
    if bin_residual == bin_capacity {
        score = 55.0 + 20.0 * progress - 10.0 * norm_pr;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction band does it land in?
    let post_class = (post_residual * 4) / bin_capacity; // 0..4 integer division classes
    match post_class {
        0 => score -= 40.0,            // near-perfect fit: strongly reward
        1 => score -= 12.0,            // small leftover, still usable
        2 => score += 8.0,             // half-ish leftover: mediocre
        _ => score += 4.0,             // large leftover
    }

    // Modulo arithmetic on post_residual: dead-space penalties at awkward residues
    if post_residual % 10 == 0 {
        score -= 5.0; // round residual tends to admit future round items
    }
    if post_residual % 3 == 0 {
        score -= 2.0;
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits exactly or with small slack -> reward
            let slack = post_residual - next_item_size;
            score -= 15.0 + (slack as f64) * 0.15;
        } else {
            // next item won't fit here: penalize proportional to overshoot
            let over = next_item_size - post_residual;
            score += (over as f64) * 0.25;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 35.0 + mean_residual * 0.3;
        // opening a fresh bin is more attractive late in the stream or with many open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 20.0 + open_bins_count.min(20) as f64;
    }

    // Tightness reward: fraction of bin consumed by this item
    let tightness = item_size as f64 / cap;
    score -= tightness * 20.0;

    // Mean residual alignment: prefer bins whose residual is close to mean (balanced packing)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold the
    // minimum item size (1..=10) are wasted forever -> heavy penalty.
    if post_residual >= 1 && post_residual <= 10 {
        score += 40.0;
    } else if post_residual <= 20 {
        // Small-but-usable gaps are risky: only very small items can use them.
        score += 12.0 * (1.0 - (post_residual as f64) / 20.0);
    } else {
        // Larger usable residuals are mildly rewarded relative to base.
        score -= 3.0;
    }

    // Tight fit reward: fill ratio of the bin after placement.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 15.0 * fill;

    // Open-bin pressure: discourage spreading across many bins; encourage
    // closing bins down (low residual) when the fleet is large.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += 2.0 * pressure;
    if post_residual == 0 {
        score -= 25.0; // perfectly closed bin is excellent
    }

    // Lookahead: if the next item fits exactly into the resulting residual,
    // strongly favor this placement; penalize if next item barely misses.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 20.0;
            } else if slack <= 10 {
                score += 8.0; // leaves a fresh dead gap for the future item
            } else {
                score -= 4.0;
            }
        } else {
            score += 5.0; // next item cannot use this bin's remainder anyway
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: an empty bin is attractive early when few
    // bins are open, but expensive once a fleet exists with usable space.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 18.0 + 10.0 * progress + 1.5 * open_bins_count as f64;
        // If no open bin truly fits, opening fresh is more acceptable.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match: large reward.
        if diff == 0.0 {
            score -= 60.0;
        } else if diff <= 5.0 {
            score -= 25.0 - 3.0 * diff;
        } else {
            // Penalize residuals that neither fit next item well nor stay small.
            score += 0.35 * diff;
        }
        // If next item can't fit here at all, mild penalty unless this bin is nearly full.
        if next_item_size > post_residual {
            score += 8.0;
        }
    } else {
        // Last item: just minimize wasted space strongly.
        score *= 1.5;
    }

    // Reward tight fits relative to current item.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness;

    // Compare against mean residual: bins with below-mean residual are more "valuable" to fill.
    score -= 0.25 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no open bin
    // offers a decent fit (i.e., all residuals far from item size).
    if bin_residual == bin_capacity {
        let poor_alternatives = if next_item_size > 0 {
            (post_residual as i64 - next_item_size as i64).abs() as f64
        } else {
            0.0
        };
        // Base cost of a fresh bin, discounted when existing fits are poor.
        score = 45.0 - 0.4 * poor_alternatives;
        if fitting_bins_count == 0 {
            score -= 100.0; // forced new bin anyway
        }
    }

    // Slight late-stream tightening: waste matters more as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

