pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for very tight fits (small dead space).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual <= 10 {
        score -= 8.0;
    }

    // Fractional waste term: normalized residual squared, penalizes leaving
    // awkward mid-size gaps.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 15.0 * frac * frac;

    // Lookahead: reward placements whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Bonus scaled by how well the next item fills the leftover.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 12.0 * fill;
        } else if post_residual > 0 && post_residual < next_item_size {
            // Leftover too small for next item: dead space penalty, worse
            // when the gap is tiny (unusable).
            score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bin: if this is the ONLY bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Crowding: with many open bins, prefer consolidating into existing bins
    // (avoid bin proliferation).
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0);

    // Prefer bins whose residual is below the mean (use up the emptier bins'
    // space less; keep large residuals for future big items).
    let diff = bin_residual as f64 - mean_residual;
    score += 0.15 * diff;

    // Time horizon: early in the stream, be more conservative (keep bins
    // flexible); late in the stream, prioritize immediate tight packing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - frac);

    // New-bin candidate handling: an empty bin is a valuable resource; only
    // prefer it when the item is large relative to capacity and no good fit
    // exists (large post_residual on an empty bin is naturally penalized by
    // the base term, but add a mild penalty to discourage casual openings).
    if bin_residual == bin_capacity {
        score += 18.0;
        if item_size >= 70 {
            score -= 15.0; // big items justify a fresh bin
        }
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative: must open
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let next_ratio = next_item_size as f64 / cap;

    // Base: waste left behind, smoothed by progress
    let mut score = pr * (1.0 + 0.5 * progress);

    // Non-linear coupling: quadratic penalty on post_residual scaled by fit ratio
    score += 0.8 * pr * pr / cap * fit_ratio;

    // Reward tight fits (small post_residual) more strongly later in the stream
    score -= 2.0 * (1.0 - fit_ratio) * (1.0 - progress) * (cap - pr);

    // Lookahead coupling: penalize if post_residual is just below next item (dead space)
    if next_item_size > 0 {
        let gap = pr - next_ratio * cap;
        if gap < 0.0 {
            score += 0.6 * (-gap) * (0.5 + progress);
        } else {
            score -= 0.3 * gap * (1.0 - gap / cap) * (1.0 - progress);
        }
    }

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // New-bin candidate: prefer it only when open-bin residuals are large and item is big
    if bin_residual == bin_capacity {
        score += 1.0 + 3.0 * (1.0 - fit_ratio) - 2.0 * mean_residual / cap;
        score -= 2.0 * progress;
    }

    // Congestion: many open bins -> favor consolidating (penalize new bins implicitly via pr term)
    score += 0.05 * (open_bins_count as f64) * (pr / cap);

    score
}
